        #region material

        List<PrintGroupMaterialTotal> GetPrintGroupMaterialTotal(int month, int year) {
            var model = new List<PrintGroupMaterialTotal>();
            try {
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;

                    var importSx1 = (from id in vfi.ImportFormSX1Detail
                                     where id.ImportFormSX1.ImportDate.Month == month &&
                                           id.ImportFormSX1.ImportDate.Year == year &&
                                           id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                           id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                           id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                             .Transaction.Status ==
                                           (byte)MyUtilities.Transaction.Status.Approved
                                     orderby id.ImportFormSX1.MaterialUseDate
                                     select new {
                                         id.ImportFormSX1.MaterialUseDate,
                                         MaterialUse = (id.MaterialUse1) + (id.MaterialUse2),
                                         id.MaterialInvId
                                     }).ToList();
                    if (!importSx1.Any()) {
                        throw new AggregateException("Không có gì để báo cáo!");
                    }
                    var startMonth = importSx1.FirstOrDefault().MaterialUseDate.AddDays(1);
                    var endMonth = importSx1.LastOrDefault().MaterialUseDate;
                    var groupMaterials = (from mt in vfi.MaterialTypes
                                          where mt.Active && mt.MaterialClassifiedId == 1
                                          orderby mt.IdentityCode
                                          //&& mt.MaterialTypeId == 3
                                          select new {
                                              mt.MaterialTypeName,
                                              mt.MaterialTypeId,
                                          }).ToList();
                    var groupIds = groupMaterials.Select(g => g.MaterialTypeId).ToList();
                    var materials = (from m in vfi.Materials
                                     where m.Active && groupIds.Contains(m.MaterialTypeId)
                                     select new {
                                         m.MaterialId,
                                         m.MaterialName,
                                         m.Shape,
                                         m.InDiameter,
                                         m.OutDiameter,
                                         m.DiameterType,
                                         m.MaterialTypeId
                                     }).ToList();
                    var materialIds = materials.Select(m => m.MaterialId).ToList();
                    var materialInvs = (from mi in vfi.MaterialInventories
                                        where materialIds.Contains(mi.MaterialId)
                                        //&& mi.MaterialInventoryId == 1264
                                        select new {
                                            mi.MaterialId,
                                            mi.MaterialInventoryId,
                                            mi.LotNumber,
                                            mi.Vendor.VendorCode,
                                            mi.UnitWeight,
                                            mi.UnitPrice,
                                            mi.ImportDate,
                                            mi.Length,
                                            mi.StoreCode,
                                            mi.FirstUseDate,
                                            mi.EndDate,
                                            mi.ImportQuantity,
                                            mi.ImportQuantityKg
                                        }).ToList();
                    var materialInvIds = materialInvs.Select(mi => mi.MaterialInventoryId).ToList();
                    var mip = (from period in vfi.MaterialInventoryPeriods
                               where
                               period.PeriodDate <= endMonth &&
                               materialInvIds.Contains(period.MaterialInventoryId)
                               select new {
                                   period.MaterialInventoryId,
                                   period.PeriodDate,
                                   period.EarlyPeriodQuantity,
                                   period.LastPeriodQuantity,
                                   PeriodQuantity = period.LastPeriodQuantity - period.EarlyPeriodQuantity,
                                   period.Quantity,
                                   IsDestroyed = period.IsDestroyed ?? false
                               }).ToList();
                    var mimp = (from period in vfi.MaterialInvOnMachinePeriods
                                where
                                    period.PeriodDate <= endMonth
                                select new {
                                    period.MaterialInvId,
                                    period.PeriodDate,
                                    period.EarlyQuantity,
                                    period.LastQuantity,
                                    period.Quantity,
                                    PeriodQuantity = period.LastQuantity - period.EarlyQuantity,
                                }).ToList();
                    var emDestroyInMonth = (from em in vfi.ExportMaterialDetails
                                            where
                                                em.ExportMaterial.ExportDate >= startMonth &&
                                                em.ExportMaterial.ExportDate <= endMonth &&
                                                em.ExportMaterial.Transaction.Status ==
                                                (byte)MyUtilities.Transaction.Status.Approved &&
                                                em.MachineId == null
                                            select new {
                                                em.MachineId,
                                                em.Machine.MachineName,
                                                em.MaterialInvId,
                                                Quantity = em.Quantity,
                                                em.ExportMaterial.ExportDate,
                                            }).ToList();
                    var retrieveInMonth = (from ms in vfi.MaterialUseDetails
                                           where ms.MaterialUseInShift.Type == (int)MyUtilities.Material.UseType.SendBack &&
                                                ms.MaterialUseInShift.Status ==
                                                (byte)MyUtilities.Transaction.Status.Approved &&
                                                ms.MaterialUseInShift.UsedDate >= startMonth &&
                                                ms.MaterialUseInShift.UsedDate <= endMonth
                                           select new {
                                               ms.MaterialInvId,
                                               Quantity = ms.EditQuantity + ms.EditQuantity2,
                                           }).ToList();
                    var useInMonth = (from ms in vfi.MaterialUseDetails
                                      where ms.MaterialUseInShift.Type == 1 &&
                                            ms.MaterialUseInShift.Status ==
                                            (byte)MyUtilities.Transaction.Status.Approved &&
                                            ms.MaterialUseInShift.UsedDate >= startMonth &&
                                            ms.MaterialUseInShift.UsedDate <= endMonth
                                      select new {
                                          ms.MaterialInvId,
                                          Quantity = ms.EditQuantity + ms.EditQuantity2,
                                      }).ToList();
                    foreach (var group in groupMaterials) {
                        var printGroup = new PrintGroupMaterialTotal {
                            GroupName = group.MaterialTypeName,
                            MaterialTyleId = group.MaterialTypeId,
                            ReportDate = endMonth,
                            LastPeriodDateString = endMonth.ToString("dd/MM/yyyy")
                        };
                        var materialsByGroup =
                            materials.Where(m => m.MaterialTypeId == group.MaterialTypeId)
                                     .OrderBy(l => l.MaterialName)
                                     .ThenBy(l => l.Shape)
                                     .ThenBy(l => l.OutDiameter)
                                     .ThenBy(l => l.InDiameter)
                                     .ThenBy(l => l.DiameterType)
                                     .ToList();
                        foreach (var material in materialsByGroup) {
                            var entity =
                                printGroup.List.FirstOrDefault(
                                    l =>
                                    l.MaterialName.Equals(material.MaterialName) &&
                                    l.OutDiameter == material.OutDiameter &&
                                    l.InDiameter == material.InDiameter &&
                                    l.Shape.Equals(material.Shape) &&
                                    l.DiameterType.Equals(material.DiameterType));
                            if (entity == null) {
                                entity = new PrintGroupMaterialDesign {
                                    MaterialName = material.MaterialName,
                                    Shape = material.Shape,
                                    InDiameter = material.InDiameter,
                                    OutDiameter = material.OutDiameter,
                                    DiameterType = material.DiameterType,
                                };
                                printGroup.List.Add(entity);
                            }
                            var materialInvsById =
                                materialInvs.Where(mi => mi.MaterialId == material.MaterialId)
                                            .OrderBy(m => m.LotNumber)
                                            .ToList();
                            foreach (var materialInv in materialInvsById) {
                                var detail = new PrintMaterialTotal {
                                    VendorCode = materialInv.VendorCode,
                                    MaterialName = entity.MaterialName,
                                    Shape = entity.Shape,
                                    InDiameter = entity.InDiameter,
                                    OutDiameter = entity.OutDiameter,
                                    Length = materialInv.Length,
                                    DiameterType = material.DiameterType,
                                    MaterialLot = materialInv.LotNumber,
                                    MaterialUnitPrice = materialInv.UnitPrice,
                                    MaterialUnitWeight = materialInv.UnitWeight,
                                    ImportDateString =
                                        materialInv.ImportDate != null
                                            ? materialInv.ImportDate.ToString("dd/MM/yyyy")
                                            : "",
                                    StoreCode = materialInv.StoreCode,
                                    Show = true,
                                    FirstImport =
                                        materialInv.ImportQuantity != 0
                                            ? string.Format("{0:n2}", materialInv.ImportQuantity)
                                            : "",
                                    FirstImportKg =
                                        materialInv.ImportQuantityKg != 0
                                            ? string.Format("{0:n2}", materialInv.ImportQuantityKg)
                                            : "",
                                    FirstUseDateString =
                                        materialInv.FirstUseDate != null
                                            ? materialInv.FirstUseDate.Value.ToString("dd/MM/yyyy")
                                            : "",
                                    EndUseDateString =
                                        materialInv.EndDate != null
                                            ? materialInv.EndDate.Value.ToString("dd/MM/yyyy")
                                            : "",
                                };
                                var periodById =
                                    mip.Where(p => p.MaterialInventoryId == materialInv.MaterialInventoryId).ToList();
                                detail.LastQuantity = Math.Round(periodById.Sum(p => p.PeriodQuantity), 2);
                                var onMachineById =
                                    mimp.Where(p => p.MaterialInvId == materialInv.MaterialInventoryId).ToList();
                                detail.MaterialOnMachine = Math.Round(onMachineById.Sum(p => p.PeriodQuantity), 2);
                                detail.LastQuantity += detail.MaterialOnMachine;

                                periodById = periodById.Where(p => p.PeriodDate < startMonth).ToList();
                                detail.EarlyQuantity = Math.Round(periodById.Sum(p => p.PeriodQuantity), 2);
                                onMachineById = onMachineById.Where(p => p.PeriodDate < startMonth).ToList();
                                detail.EarlyQuantity += Math.Round(onMachineById.Sum(p => p.PeriodQuantity), 2);

                                var importInMonth =
                                    mip.Where(
                                        period =>
                                            period.MaterialInventoryId == materialInv.MaterialInventoryId &&
                                            period.PeriodDate >= startMonth &&
                                            period.LastPeriodQuantity > period.EarlyPeriodQuantity);
                                if (importInMonth.Any()) {
                                    detail.Import = Math.Round(importInMonth.Sum(period => period.Quantity), 2);
                                    var retrieve =
                                        retrieveInMonth.Where(
                                            ms => ms.MaterialInvId == materialInv.MaterialInventoryId);
                                    if (retrieve.Any()) {
                                        detail.Import -= Math.Round(retrieve.Sum(period => period.Quantity), 2);
                                    }
                                }
                                var materialUse =
                                    importSx1.Where(em => em.MaterialInvId == materialInv.MaterialInventoryId);
                                if (materialUse.Any()) {
                                    detail.Export = Math.Round(materialUse.Sum(e => e.MaterialUse), 2);
                                }
                                var emDestroyById =
                                    emDestroyInMonth.Where(
                                        em =>
                                        em.MaterialInvId == materialInv.MaterialInventoryId);
                                if (emDestroyById.Any()) {
                                    detail.ExportDestroyed = Math.Round(emDestroyById.Sum(e => e.Quantity), 2);
                                }
                                if (detail.EarlyQuantity == 0 && detail.Import == 0 && detail.Export == 0 &&
                                    detail.MaterialOnMachine == 0 && detail.ExportDestroyed == 0) {
                                    //detail.Show = false;
                                }
                                else {
                                    entity.Details.Add(detail);
                                }
                            }
                        }
                        printGroup.List.RemoveAll(l => !l.Details.Any());
                        model.Add(printGroup);
                    }
                }
            }
            catch (Exception ex) {
                throw ex;
            }
            return model;
        }

        [HttpPost]
        public ActionResult PrintMaterialInvTotalInMonth(int materialTypeId, int vendor, string fromDate, string toDate) {
            var model = new List<MaterialGroupModel>();
            try {
                //model = GetPrintGroupMaterialTotal(month, year);
                var list = GetMaterialDailyPeriod("", materialTypeId, vendor, fromDate, toDate, (int)MyUtilities.Report.Calculate.All);
                if (!list.Any())
                    return PartialView("PageMaterialTotal", model);

                var first = list.FirstOrDefault();
                var types = (from t in list
                             select new { t.MaterialTypeId, t.MaterialTypeCode, t.MaterialTypeName }).Distinct().ToList();
                var listExports = new List<MaterialInjectReportModel>();
                foreach (var type in types) {
                    var entity = new MaterialGroupModel {
                        MaterialTypeId = type.MaterialTypeId,
                        MaterialTypeCode = type.MaterialTypeCode,
                        MaterialTypeName = type.MaterialTypeName,
                        ToDate = first.ToDate,
                        ToDateString = first.ToDate.ToString("dd/MM")
                    };
                    var materials = (from l in list
                                     where l.MaterialTypeId == entity.MaterialTypeId
                                     select new {
                                         l.MaterialId,
                                         l.MaterialCode,
                                         l.MaterialName,
                                         l.OutDiameter,
                                         l.InDiameter,
                                         l.Shape,
                                         l.DiameterType,
                                     }).Distinct().ToList();
                    foreach (var material in materials) {
                        var detail = new MaterialPeriodModel {
                            MaterialId = material.MaterialId,
                            MaterialCode = material.MaterialCode,
                            MaterialName = material.MaterialName,
                            OutDiameter = material.OutDiameter,
                            InDiameter = material.InDiameter,
                            Shape = material.Shape,
                            DiameterType = material.DiameterType,
                        };
                        detail.Invs = list.Where(l => l.MaterialId == detail.MaterialId).ToList();
                        entity.Materials.Add(detail);
                    }

                    listExports.Add(new MaterialInjectReportModel {
                        MaterialTypeName = entity.MaterialTypeName,
                        Destroy = entity.Destroy + entity.DestroyOnMachine,
                        DestroyWeight = entity.DestroyKg,
                        DestroyPrice = entity.DestroyPrice,
                        ExportInternal = entity.ExportInternal,
                        ExportInternalWeight = entity.ExportInternalWeight,
                        ExportInternalPrice = entity.ExportInternalPrice,
                    });
                    model.Add(entity);
                }
                model[0].InjectExports = listExports;
            }
            catch (Exception ex) {
                return Json(ex.Message);
            }
            return PartialView("PageMaterialTotal", model);
        }

        [GridAction]
        public ActionResult SelectMaterialInvDetailPeriodModel(int materialInvId, string fromDate, string toDate) {
            var model = new List<MaterialPeriodDetailModel>();
            if (materialInvId == 0)
                return View(new GridModel(model));
            try {
                var ci = new CultureInfo("vi-VN");
                var fdate = string.IsNullOrWhiteSpace(fromDate)
                    ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                    : Convert.ToDateTime(fromDate, ci);
                var tdate = string.IsNullOrWhiteSpace(toDate)
                    ? DateTime.Now
                    : Convert.ToDateTime(toDate, ci).AddDays(1).AddSeconds(-1);
                using (var vfi = new tammaContext()) {
                    var materialInv =
                        vfi.MaterialInventories.FirstOrDefault(mi => mi.MaterialInventoryId == materialInvId);
                    if (materialInv == null)
                        return View(new GridModel(model));
                    var importSx1 = (from id in vfi.ImportFormSX1Detail
                                     where id.ImportFormSX1.ImportDate >= fdate &&
                                           id.ImportFormSX1.ImportDate <= tdate &&
                                           id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                           id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                           id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                               .Transaction.Status ==
                                           (byte)MyUtilities.Transaction.Status.Approved &&
                                           id.MaterialInvId == materialInvId
                                     orderby id.ImportFormSX1.MaterialUseDate
                                     select id).ToList();
                    if (!importSx1.Any())
                        throw new AggregateException("Không có báo cáo mới ! ");
                    var startMonth = importSx1.FirstOrDefault().ImportFormSX1.MaterialUseDate;
                    var endMonth = importSx1.LastOrDefault().ImportFormSX1.MaterialUseDate;
                    var useInMonth = (from ms in vfi.MaterialUseDetails
                                      where ms.MaterialUseInShift.Status ==
                                            (byte)MyUtilities.Transaction.Status.Approved &&
                                            ms.MaterialUseInShift.UsedDate >= startMonth &&
                                            ms.MaterialUseInShift.UsedDate <= endMonth &&
                                            ms.MaterialInvId == materialInvId
                                      select ms);
                    foreach (var use in useInMonth) {
                        var entity = new MaterialPeriodDetailModel {
                            PeriodDate = use.MaterialUseInShift.UsedDate,
                            ModifiedDate = use.MaterialUseInShift.ModifiedDate,
                            ModifiedUser = use.MaterialUseInShift.ModifiedUser,
                            Quantity = use.EditQuantity + use.EditQuantity2,
                            Note = use.Machine.MachineName + "| " + use.Note,
                            TransactionCode = use.MaterialUseInShift.UsedCode,
                            Type = use.MaterialUseInShift.Type,
                            TransactionId = use.UseId
                        };
                        entity.QuantityKg = entity.Quantity * materialInv.UnitWeight;
                        if (use.MaterialUseInShift.Type == (int)MyUtilities.Material.UseType.Using) {
                            entity.TypeName = "Sử dụng";
                        }
                        else if (use.MaterialUseInShift.Type == (int)MyUtilities.Material.UseType.SendBack && use.IsDetroy)
                            entity.TypeName = "Huỷ trên máy";
                        else if (use.MaterialUseInShift.Type == (int)MyUtilities.Material.UseType.SendBack && !use.IsDetroy)
                            entity.TypeName = "Thu hồi";
                        model.Add(entity);
                    }
                    var emDestroyInMonth = (from em in vfi.ExportMaterialDetails
                                            where
                                            em.ExportMaterial.ExportDate >= startMonth &&
                                            em.ExportMaterial.ExportDate <= endMonth &&
                                            em.ExportMaterial.Transaction.Status ==
                                            (byte)MyUtilities.Transaction.Status.Approved &&
                                            em.MachineId == null &&
                                            em.MaterialInvId == materialInvId
                                            select em).ToList();
                    foreach (var export in emDestroyInMonth) {
                        var entity = new MaterialPeriodDetailModel {
                            ModifiedDate = export.ExportMaterial.ModifiedDate,
                            ModifiedUser = export.ExportMaterial.ModifiedUser,

                            PeriodDate = export.ExportMaterial.ExportDate,
                            Quantity = export.Quantity,

                            TransactionId = export.ExportMaterial.TransactionId ?? 0,
                            TransactionCode = export.ExportMaterial.Transaction.TransactionCode,

                            TypeName = "Huỷ kho",
                            Note = "",
                        };
                        entity.QuantityKg = entity.Quantity * materialInv.UnitWeight;
                        model.Add(entity);
                    }
                    //var mip = (from period in vfi.MaterialInventoryPeriods
                    //           where
                    //           period.PeriodDate <= endMonth &&
                    //           period.MaterialInventoryId == materialInvId
                    //           select period).ToList();
                    //var mimp = (from period in vfi.MaterialInvOnMachinePeriods
                    //            where
                    //            period.PeriodDate <= endMonth &&
                    //            period.MaterialInvId == materialInvId
                    //            select period).ToList();
                    model = model.OrderBy(x => x.PeriodDate).ToList();
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectMaterialInvDetailPeriodModel", ex.Message);
            }
            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult SelectMaterialYearlyDetailReport(int materialId, int year) {
            var model = new List<MaterialYearlyDetailReportModel>();
            try {

                using (var vfi = new tammaContext()) {
                    var approvedProductions = vfi.SelectApprovedProductions.Where(ap => ap.MaterialId == materialId &&
                        ap.MaterialUseDate.Year == year).ToList();
                    var products = approvedProductions.Select(ap => new { ap.ProductId, ap.ProductCode })
                        .Distinct().OrderBy(p => p.ProductCode).ToList();
                    foreach (var product in products) {
                        var entity = new MaterialYearlyDetailReportModel {
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,

                        };
                        var approvedProductionsById = approvedProductions.Where(ap => ap.ProductId == entity.ProductId &&
                            ap.MaterialId == materialId);
                        entity.ProductWeight = approvedProductionsById.Max(ap => ap.ProductWeight);
                        //var dates = approvedProductionsById.Select(ap => new { ap.MaterialUseDate.Month, ap.MaterialUseDate.Year })
                        //    .Distinct().ToList();
                        for (var month = 1; month <= 12; month++) {
                            var detail = new MaterialProductionModel {
                                Month = month,
                                Year = year
                            };
                            var approvedProductionsByDate = approvedProductionsById.Where(ap => ap.MaterialUseDate.Month == month &&
                                ap.MaterialUseDate.Year == year).ToList();
                            if (approvedProductionsByDate.Any()) {
                                detail.MaterialUse = approvedProductionsByDate.Sum(ap => ap.MaterialUse.Value * ap.MaterialWeight);
                                detail.Production = approvedProductionsByDate.Sum(ap => ap.Number.Value);
                                detail.Processing = approvedProductionsByDate.Sum(ap => ap.Processing.Value);
                                detail.Defect = approvedProductionsByDate.Sum(ap => ap.Defect.Value);
                            }
                            entity.Productions.Add(detail);

                        }
                        model.Add(entity);
                    }
                }

            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectMaterialYearlyDetailReport", ex.Message);
            }

            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult SelectMaterialYearlyReport(string materialCode, int materialTypeId, int year) {
            var model = new List<MaterialYearlyReportModel>();
            if (year == 0)
                return View(new GridModel(model));
            try {
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var materials = from m in vfi.Materials
                                    where m.Active &&
                                    (materialTypeId == 0 || m.MaterialTypeId == materialTypeId)
                                    select new {
                                        m.MaterialId,
                                        m.MaterialCode,
                                        m.MaterialTypeId,
                                        m.MaterialType.MaterialTypeName,
                                    };
                    if (!string.IsNullOrWhiteSpace(materialCode))
                        materials = materials.Where(m => m.MaterialCode.Contains(materialCode));
                    var materialIds = materials.Select(m => m.MaterialId);
                    var periods = from mp in vfi.MaterialInventoryPeriods
                                  where materialIds.Contains(mp.MaterialId) && mp.PeriodDate.Year == year &&
                                        mp.LastPeriodQuantity > mp.EarlyPeriodQuantity
                                  select new {
                                      mp.MaterialId,
                                      mp.PeriodDate.Month,
                                      QuantityKg =
                                      (mp.LastPeriodQuantity - mp.EarlyPeriodQuantity) * mp.MaterialInventory.UnitWeight,
                                      Type = mp.Transaction.ImportPurchaseOrders.Any()
                                  };
                    //var machinePeriods = (from mp in vfi.MaterialInvOnMachinePeriods
                    //    where materialIds.Contains(mp.MaterialInventory.MaterialId) &&
                    //          mp.PeriodDate.Year == year
                    //    select new
                    //    {
                    //        mp.PeriodDate.Month,
                    //        mp.MaterialInventory.MaterialId,
                    //    }).ToList();

                    var emDestroyInMonth = (from em in vfi.ExportMaterialDetails
                                            where em.ExportMaterial.ExportDate.Year == year &&
                                                  em.ExportMaterial.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                  em.MachineId == null &&
                                                  materialIds.Contains(em.MaterialId)
                                            select new {
                                                em.MaterialId,
                                                em.ExportMaterial.ExportDate.Month,
                                                QuantityKg = em.MaterialInventory.UnitWeight * em.Quantity,
                                            }).ToList();

                    var useInYear = (from ms in vfi.MaterialUseDetails
                                     where ms.MaterialUseInShift.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                           ms.MaterialUseInShift.UsedDate.Year == year &&
                                           materialIds.Contains(ms.MaterialInventory.MaterialId)
                                     select new {
                                         ms.MaterialInventory.MaterialId,
                                         ms.MaterialUseInShift.UsedDate.Month,
                                         ms.MaterialUseInShift.Type,
                                         ms.IsDetroy,
                                         QuantityKg = ms.MaterialInventory.UnitWeight * (ms.EditQuantity + ms.EditQuantity2),
                                     }).ToList();
                    var totalInvs = from mi in vfi.MaterialInventories
                                    where materialIds.Contains(mi.MaterialId) && mi.TotalQty > 0
                                    select new {
                                        mi.MaterialId,
                                        QuantityKg = mi.TotalQty * mi.UnitWeight
                                    };
                    foreach (var material in materials) {
                        var entity = new MaterialYearlyReportModel {
                            MaterialId = material.MaterialId,
                            MaterialCode = material.MaterialCode,
                            MaterialTypeId = material.MaterialTypeId,
                            MaterialTypeName = material.MaterialTypeName,
                            Months = new List<MaterialMonthlyReportModel>(),
                            Year = year
                        };
                        var periodsById = periods.Where(p => p.MaterialId == material.MaterialId).ToList();
                        var useById = useInYear.Where(p => p.MaterialId == entity.MaterialId).ToList();
                        var emDestroyById = emDestroyInMonth.Where(em => em.MaterialId == entity.MaterialId).ToList();
                        if (!periodsById.Any() && !useById.Any() && !emDestroyById.Any()) continue;
                        var months = new List<MaterialMonthlyReportModel>();
                        for (int month = 1; month <= 12; month++) {
                            var byMonth = new MaterialMonthlyReportModel {
                                MaterialId = material.MaterialId,
                                Import = 0,
                                ImportMore = 0,
                                ExportUse = 0,
                                ExportDestroy = 0
                            };
                            months.Add(byMonth);
                            periodsById =
                                periods.Where(p => p.MaterialId == material.MaterialId && p.Month == month).ToList();
                            var periodsByParam = periodsById.Where(p => p.Type).ToList();
                            byMonth.Import = Math.Round(periodsByParam.Sum(period => period.QuantityKg), 2);
                            periodsByParam = periodsById.Where(p => !p.Type).ToList();
                            byMonth.ImportMore = Math.Round(periodsByParam.Sum(period => period.QuantityKg), 2);

                            useById =
                                useInYear.Where(p => p.MaterialId == entity.MaterialId && p.Month == month).ToList();
                            var useByParam = useById.Where(p => p.Type == 1).ToList();
                            byMonth.ExportUse = Math.Round(useByParam.Sum(e => e.QuantityKg), 2);

                            useByParam = useById.Where(p => p.Type == (int)MyUtilities.Material.UseType.SendBack && p.IsDetroy).ToList();
                            byMonth.ExportDestroy = Math.Round(useByParam.Sum(e => e.QuantityKg), 2);

                            useByParam = useById.Where(p => p.Type == (int)MyUtilities.Material.UseType.SendBack && !p.IsDetroy).ToList();
                            byMonth.ImportMore -= Math.Round(useByParam.Sum(e => e.QuantityKg), 2);
                            if (byMonth.ImportMore < 0) byMonth.ImportMore = 0;

                            emDestroyById =
                                emDestroyInMonth.Where(em => em.MaterialId == entity.MaterialId && em.Month == month)
                                    .ToList();
                            byMonth.ExportDestroy += Math.Round(emDestroyById.Sum(e => e.QuantityKg), 2);
                        }

                        var total = new MaterialMonthlyReportModel {
                            Import = months.Sum(m => m.Import),
                            ImportMore = months.Sum(m => m.ImportMore),
                            ExportUse = months.Sum(m => m.ExportUse),
                            ExportDestroy = months.Sum(m => m.ExportDestroy)
                        };
                        var totalInvsById = totalInvs.Where(mi => mi.MaterialId == entity.MaterialId).ToList();
                        entity.TotalInv = totalInvsById.Sum(mi => mi.QuantityKg);
                        if (total.Import + total.ImportMore +
                            total.ExportUse + total.ExportDestroy + entity.TotalInv > 0) {
                            var monthCount = months.Where(m => m.ExportUse > 0).ToList().Count();
                            if (monthCount > 0)
                                entity.Avg = total.ExportUse / monthCount;
                            entity.Months.Add(total);
                            entity.Months.AddRange(months);
                            model.Add(entity);
                        }
                    }
                }

            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectMaterialYearlyReport", ex.Message);
            }
            return View(new GridModel(model.OrderBy(m => m.MaterialTypeName).ThenBy(m => m.MaterialCode)));
        }

        [GridAction]
        public ActionResult SelectMaterialProductionReport(string materialCode, int materialTypeId, string fromDate, string toDate) {
            var model = new List<MaterialProductionReport>();
            if (string.IsNullOrWhiteSpace(toDate))
                return View(new GridModel(model));
            try {
                model = GetMaterialProductionReport(materialCode, materialTypeId, fromDate, toDate);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectMaterialProductionReport", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<MaterialProductionReport> GetMaterialProductionReport(string materialCode, int materialTypeId, string fromDate, string toDate) {
            var model = new List<MaterialProductionReport>();
            if (string.IsNullOrWhiteSpace(toDate))
                return model;
            var ci = new CultureInfo("vi-VN");
            var tdate = Convert.ToDateTime(toDate, ci);
            var fdate = Convert.ToDateTime(fromDate, ci);
            //var fdate = new DateTime(tdate.Year, tdate.Month, 1);
            using (var vfi = new tammaContext()) {
                var importSx1 = (from id in vfi.ImportFormSX1
                                 where id.MaterialUseDate >= fdate &&
                          id.ImportWorkpieceMaterials.Any() &&
                          id.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                          id.ImportWorkpieceMaterials.FirstOrDefault().Transaction.Status ==
                          (byte)MyUtilities.Transaction.Status.Approved
                                 orderby id.MaterialUseDate
                                 select id).FirstOrDefault();
                if (importSx1 != null)
                    fdate = importSx1.MaterialUseDate;

                var importDetailsSx1 = (from id in vfi.ImportFormSX1Detail
                                        where id.ImportFormSX1.MaterialUseDate >= fdate &&
                                              id.ImportFormSX1.MaterialUseDate <= tdate &&
                                              id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                              id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                              id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault().Transaction.Status ==
                                              (byte)MyUtilities.Transaction.Status.Approved
                                        orderby id.ImportFormSX1.MaterialUseDate descending
                                        select new {
                                            id.MaterialInventory.MaterialId,
                                            MachineId = id.MachineId ?? 0,
                                            id.Machine1.MachineName,
                                            id.ProductId,
                                            Forecasts = id.Product.ForecastsQuality ?? 0,
                                            Productivity = id.Product.Productivity ?? 0,
                                            id.ImportFormSX1.MaterialUseDate,
                                            id.Product.ProductCode,
                                            Quantity = id.Number1 + id.Number2 +
                                                       id.Processing1 + id.Processing2 +
                                                       id.DefectProduct1 + id.DefectProduct2,
                                            MaterialUse = (id.MaterialUse1 + id.MaterialUse2) * id.MaterialInventory.UnitWeight,
                                        }).ToList();
                var productionIds = importDetailsSx1.Select(id => id.ProductId).Distinct().ToList();
                var products = from p in vfi.Products
                               where p.Active
                               select new {
                                   p.ProductId,
                                   p.ProductCode,
                                   Forecasts = p.ForecastsQuality ?? 0,
                                   Productivity = p.Productivity ?? 0,
                                   p.MaterialId,
                               };
                var productIds = products.Select(id => id.ProductId).ToList();

                var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                var productInvs = from pi in vfi.ProductInventories
                                  where productIds.Contains(pi.ProductId) &&
                                        warehouses.Contains(pi.WarehouseId) &&
                                        pi.TotalQty > 0
                                  select new {
                                      pi.ProductId,
                                      pi.TotalQty,
                                  };
                var materials = (from m in vfi.Materials
                                 where m.Active &&
                                       (materialTypeId == 0 || m.MaterialTypeId == materialTypeId) &&
                                       m.MaterialCode.Contains(materialCode)
                                 select m).ToList();
                var materialIds = materials.Select(m => m.MaterialId).ToList();
                var productionMaterials = from pm in vfi.ProductionMaterials
                                          where productIds.Contains(pm.ProductId) &&
                                                materialIds.Contains(pm.MaterialId) &&
                                                pm.Active
                                          select new {
                                              pm.MaterialId,
                                              pm.ProductId,
                                              pm.UnitWeightByMaterial
                                          };
                var periods = (from p in vfi.MaterialInventoryPeriods
                               where p.PeriodDate <= tdate &&
                                     materialIds.Contains(p.MaterialId)
                               select new {
                                   p.MaterialId,
                                   QuantityKg = (p.LastPeriodQuantity - p.EarlyPeriodQuantity) * p.MaterialInventory.UnitWeight,
                                   p.EarlyPeriodQuantity,
                                   p.LastPeriodQuantity,
                                   p.Quantity,
                                   p.MaterialInventory.UnitWeight,
                                   p.PeriodDate,
                                   IsPurchase = p.Transaction.ImportPurchaseOrders.Any()
                               }).ToList();
                var mimp = (from p in vfi.MaterialInvOnMachinePeriods
                            where p.PeriodDate <= tdate &&
                                  materialIds.Contains(p.MaterialInventory.MaterialId)
                            select new {
                                p.MaterialInventory.MaterialId,
                                p.PeriodDate,
                                QuantityKg = (p.LastQuantity - p.EarlyQuantity) * p.MaterialInventory.UnitWeight
                            }).ToList();
                var useInMonth = from ms in vfi.MaterialUseDetails
                                 where ms.MaterialUseInShift.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                     //ms.MaterialUseInShift.UsedDate >= fdate &&
                                       ms.MaterialUseInShift.UsedDate <= tdate &&
                                       materialIds.Contains(ms.MaterialInventory.MaterialId) &&
                                       ms.MaterialUseInShift.Type == 1
                                 select new {
                                     ms.MachineId,
                                     ms.MaterialInventory.MaterialId,
                                     ms.MaterialUseInShift.UsedDate,
                                     QuantityKg = (ms.EditQuantity + ms.EditQuantity2) * ms.MaterialInventory.UnitWeight,
                                     //ms.MaterialUseInShift.Type,
                                 };
                var poDetails = from pd in vfi.PurchaseOrderDetails
                                where (pd.PurchaseOrder.Status == (byte)MyUtilities.Sales.Status.InProcess ||
                                      pd.PurchaseOrder.Status == (byte)MyUtilities.Sales.Status.Waiting) &&
                                      pd.PurchaseOrder.MaterialClassifiedId == 1 &&
                                      pd.ReceivedQty < pd.OrderQty
                                select new {
                                    pd.ReferenceId,
                                    pd.PurchaseOrder.OrderDate,
                                    Quanity = pd.OrderQty - pd.ReceivedQty
                                };
                var lastMonth = new DateTime(fdate.Year, fdate.Month, 1).AddDays(-1);
                var next6Month = lastMonth.AddMonths(5);
                var forecasts = from f in vfi.ForecastOrders
                                where f.Status == (byte)MyUtilities.Sales.Status.Completed &&
                                      f.ForecastDate >= lastMonth && f.ForecastDate <= next6Month
                                select new {
                                    f.ProductId,
                                    f.Quantity,
                                    f.ForecastDate
                                };

                var lastMonth2 = lastMonth.AddMonths(1);
                var orderDetailsAll = (from od in vfi.OrderDetails
                                       where od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                                             od.Order.DueDate != null &&
                                             od.Order.DueDate.Value.Year == tdate.Year &&
                                             od.Order.DueDate <= lastMonth2 &&
                                             od.Order.DueDate > MyUtilities.Sales.StartOrderDate
                                       select new {
                                           od.ProductId,
                                           od.Order.DueDate,
                                           od.OrderQty,
                                           od.RequiedNumber,
                                       }).ToList();
                var orderDetailRequires = (from od in vfi.OrderDetails
                                           where (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                  od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                 od.Order.DueDate != null &&
                                                 od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                                 od.Order.DueDate <= lastMonth2 &&
                                                 od.RequiedNumber > 0
                                           select new {
                                               od.ProductId,
                                               od.Order.DueDate,
                                               od.OrderQty,
                                               od.RequiedNumber,
                                           }).ToList();

                var exports = from id in vfi.InvoiceDetails
                              where id.Active &&
                                    id.Invoice.ShipmentDate.Value.Month == fdate.Month &&
                                    id.Invoice.ShipmentDate.Value.Year == fdate.Year &&
                                    productIds.Contains(id.ProductId.Value)
                              //(customerId == 0 || id.Invoice.CustomerId == customerId)
                              select new {
                                  id.Piece,
                                  id.ProductId
                              };
                foreach (var material in materials) {
                    var entity = new MaterialProductionReport() {
                        FromDate = fdate,
                        ToDate = tdate,
                        FromDateString = fdate.ToString("dd/MM/yyyy"),
                        ToDateString = tdate.ToString("dd/MM/yyyy"),
                        MaterialTypeId = material.MaterialTypeId,
                        MaterialTypeCode = material.MaterialType.IdentityCode,

                        MaterialId = material.MaterialId,
                        MaterialName = material.MaterialName,
                        MaterialCode = material.MaterialCode,
                        OutDiameter = material.OutDiameter,
                        InDiameter = material.InDiameter,
                        Shape = material.Shape.Trim(),
                        DiameterType = material.DiameterType.Trim(),
                    };
                    var periodsById = periods.Where(p => p.MaterialId == entity.MaterialId).ToList();
                    entity.LastQuantity = Math.Round(periodsById.Sum(p => p.QuantityKg), 2);

                    var onMachineById = mimp.Where(p => p.MaterialId == entity.MaterialId).ToList();
                    entity.LastQuantity += Math.Round(onMachineById.Sum(p => p.QuantityKg), 2);

                    var periodsByParam = periodsById.Where(p => p.PeriodDate < fdate).ToList();
                    entity.EarlyQuantity = Math.Round(periodsByParam.Sum(p => p.QuantityKg), 2);

                    onMachineById = onMachineById.Where(p => p.PeriodDate < fdate).ToList();
                    entity.EarlyQuantity += Math.Round(onMachineById.Sum(p => p.QuantityKg), 2);

                    periodsByParam =
                        periodsById.Where(
                            p =>
                                p.PeriodDate >= fdate &&
                                p.LastPeriodQuantity > p.EarlyPeriodQuantity
                                && p.IsPurchase).ToList();
                    entity.Import = Math.Round(periodsByParam.Sum(p => p.Quantity * p.UnitWeight), 2);

                    var useById = useInMonth.Where(u => u.MaterialId == entity.MaterialId).ToList();
                    var count = useById.Select(u => u.UsedDate.Month).Distinct().Count();
                    if (count > 0) {
                        entity.AvgExport = Math.Round((useById.Sum(e => e.QuantityKg) / count) / 2, 2);
                        useById = useById.Where(u => u.UsedDate >= fdate).ToList();
                        entity.Export = Math.Round(useById.Sum(e => e.QuantityKg), 2);
                        // ?
                        count = useById.Select(u => u.UsedDate.Day).Distinct().Count();
                    }

                    var productionIdsByMaterial =
                         importDetailsSx1.Where(id => id.MaterialId == entity.MaterialId)
                             .Select(id => id.ProductId)
                             .Distinct().ToList();
                    var productIdsByMaterial =
                        products.Where(
                                p => p.MaterialId == entity.MaterialId && !productionIds.Contains(p.ProductId))
                            .Select(p => p.ProductId)
                            .ToList();
                    productIds = productionIdsByMaterial.Union(productIdsByMaterial).Distinct().ToList();
                    var forcastsById = forecasts.Where(f => productIds.Contains(f.ProductId)).ToList();
                    var orderDetailsById = orderDetailRequires.Where(od => productIds.Contains(od.ProductId)).ToList();
                    if (entity.Import + entity.Export == 0 &&
                        !productIds.Any() && !forcastsById.Any() && !orderDetailsById.Any())
                        continue;
                    var poById = poDetails.Where(pd => pd.ReferenceId == entity.MaterialId);
                    if (poById.Any()) {
                        entity.PoQuantity = poById.Sum(pd => pd.Quanity);
                        entity.PoDate = poById.FirstOrDefault().OrderDate.ToString("dd/MM");
                    }
                    foreach (var productId in productIds) {
                        entity.ProductId = productId;
                        var productExport = exports.Where(e => e.ProductId == productId).ToList();
                        entity.ProductExport = productExport.Sum(e => e.Piece);
                        var productionMaterialById =
                            productionMaterials.FirstOrDefault(
                                pm => pm.MaterialId == entity.MaterialId && pm.ProductId == productId);
                        if (productionMaterialById != null)
                            entity.ProductionWeight = productionMaterialById.UnitWeightByMaterial;
                        var productInvsById = productInvs.Where(pi => pi.ProductId == productId).ToList();
                        entity.ProductInv = productInvsById.Sum(pi => pi.TotalQty);
                        var foreastById = forcastsById.Where(f => f.ProductId == productId).ToList();
                        entity.OrderForecast = foreastById.Sum(f => f.Quantity);
                        entity.AvgForecast = 0;
                        if (foreastById.Any()) {
                            count = foreastById.Select(f => f.ForecastDate.Month).Distinct().Count();
                            entity.AvgForecast = Math.Round(entity.OrderForecast / count, 0);
                        }
                        var orderDetailById = orderDetailsById.Where(f => f.ProductId == productId).ToList();
                        entity.OrderQuantity = orderDetailById.Sum(f => f.RequiedNumber);
                        orderDetailById = orderDetailsAll.Where(f => f.ProductId == productId).ToList();
                        if (orderDetailById.Any()) {
                            count = orderDetailById.Select(f => f.DueDate.Value.Month).Distinct().Count();
                            entity.AvgOrder = Math.Round((double)orderDetailById.Sum(od => od.OrderQty.Value) / count,
                                0);
                        }

                        //var machineIds2 = useById.Select(u => u.MachineId).Distinct().ToList();
                        var machineIds =
                            importDetailsSx1.Where(
                                    id =>
                                        id.ProductId == productId && id.MaterialId == entity.MaterialId)
                                .OrderBy(id => id.MachineName)
                                .Select(id => id.MachineId)
                                .Distinct()
                                .ToList();
                        //if (machineIds2.Any())
                        //    machineIds = machineIds.Union(machineIds2).Distinct().ToList();
                        //entity.MaterialUse = productionsById.Sum(id => id.MaterialUse);
                        foreach (var machineId in machineIds) {
                            var productionsById = importDetailsSx1.Where(
                                    id =>
                                        id.ProductId == productId &&
                                        id.MaterialId == entity.MaterialId &&
                                        id.MachineId == machineId)
                                .ToList();
                            var p = productionsById.FirstOrDefault();
                            //var entity2 =
                            //    model.FirstOrDefault(
                            //        m =>
                            //            m.ProductId == p.ProductId && 
                            //            m.MachineId == p.MachineId &&
                            //            m.MaterialId == p.MaterialId);
                            //if (entity2 != null) continue;
                            var entity2 = new MaterialProductionReport(entity);
                            var productbydate = productionsById.Where(id => id.MaterialUseDate == tdate);
                            if (productbydate.Any()) {
                                entity2.ProductionQuantity = productbydate.Sum(id => id.Quantity);
                                entity2.MaterialUse = productbydate.Sum(id => id.MaterialUse);
                            }
                            var useByMachine = useById.Where(ud => ud.MachineId == machineId).ToList();
                            //entity2.MaterialUse = useByMachine.Sum(id => id.QuantityKg);
                            //entity2.MaterialUse = productionsById.Sum(id=> id.MaterialUse);
                            entity2.MachineId = p.MachineId;
                            entity2.MachineName = p.MachineName;
                            entity2.ProductCode = p.ProductCode;
                            entity2.Productivity = p.Productivity;
                            //entity2.ProductForecast = p.Forecasts;
                            var lastTrack =
                                MyUtilities.Machine.LastTrackUpMachine(
                                entity2.MachineId,
                                entity2.MaterialId,
                                entity2.ProductId,
                                tdate);
                            //var lastTrack =
                            //    (from t in vfi.TrackUpMachines
                            //     where
                            //     t.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                            //     t.MachineId == entity2.MachineId &&
                            //     t.MaterialId == entity2.MaterialId &&
                            //     t.ProductId == entity2.ProductId &&
                            //     ((t.DeliveryDate != null ? t.DeliveryDate.Value <= tdate : t.StartDate <= tdate) ||
                            //      (t.StartDate <= tdate))
                            //     select new {
                            //         t.MachineId,
                            //         t.ProductId,
                            //         t.Quantity,
                            //         t.Product.ProductCode,
                            //         t.RealProductivity,
                            //         t.RealRate,
                            //         t.TrackUpMaterials,
                            //         t.MaterialId,
                            //         t.Material,
                            //         t.WorkPiece,
                            //         t.KnifeCut,
                            //         Length = t.Product.Length ?? 0,
                            //         Date = t.DeliveryDate != null ? t.DeliveryDate.Value : t.StartDate
                            //     })
                            //    .OrderByDescending(t => t.Date)
                            //    .FirstOrDefault();
                            if (lastTrack != null) {
                                entity2.Productivity = lastTrack.RealProductivity;
                                //
                                var importDetailsSx1ByTrack = (from id in vfi.ImportFormSX1Detail
                                                               where
                                                               id.ImportFormSX1.MaterialUseDate >= lastTrack.ReportDate &&
                                                               id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                               id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                               id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault().Transaction.Status ==
                                                               (byte)MyUtilities.Transaction.Status.Approved &&
                                                               id.ProductId == entity2.ProductId &&
                                                               id.MachineId == entity2.MachineId &&
                                                               id.MaterialInventory.MaterialId == entity2.MaterialId
                                                               select new {
                                                                   //id.MaterialInventory.MaterialId,
                                                                   //MachineId = id.MachineId ?? 0,
                                                                   //id.Machine1.MachineName,
                                                                   //id.ProductId,
                                                                   //Forecasts = id.Product.ForecastsQuality ?? 0,
                                                                   //Productivity = id.Product.Productivity ?? 0,
                                                                   //id.ImportFormSX1.MaterialUseDate,
                                                                   //id.Product.ProductCode,
                                                                   Quantity = id.Number1 + id.Number2 +
                                                                              id.Processing1 + id.Processing2 +
                                                                              id.DefectProduct1 + id.DefectProduct2,
                                                                   MaterialUseKg = (id.MaterialUse1 + id.MaterialUse2) *
                                                                   id.MaterialInventory.UnitWeight,
                                                               }).ToList();
                                entity2.ProductForecast = lastTrack.Quantity;
                                entity2.ProductionQuantityByTrack = importDetailsSx1ByTrack.Sum(id => id.Quantity);
                                entity2.MaterialUseKgByTrack = importDetailsSx1ByTrack.Sum(id => id.MaterialUseKg);
                            }
                            model.Add(entity2);
                        }

                        if (!machineIds.Any()) {
                            var entity2 = new MaterialProductionReport(entity);
                            var productionById =
                                products.FirstOrDefault(p => p.MaterialId == entity.MaterialId &&
                                                             !productionIds.Contains(entity.ProductId) &&
                                                             p.ProductId == entity.ProductId);
                            if (productionById == null) continue;
                            //entity2.ProductForecast = productionById.Forecasts;
                            //if (!entity2.Check)
                            //    continue;
                            entity2.ProductCode = productionById.ProductCode;
                            entity2.Productivity = productionById.Productivity == 0 ? 1 : productionById.Productivity;
                            model.Add(entity2);
                        }

                    }

                }
            }
            return
                model.OrderBy(m => m.MaterialTypeCode)
                    .ThenBy(m => m.MaterialName)
                    .ThenBy(m => m.Shape)
                    .ThenBy(m => m.DiameterType)
                    .ThenBy(m => m.OutDiameter)
                    .ThenBy(m => m.InDiameter).ToList();
        }

        [GridAction]
        public ActionResult SelectMaterialInvPeriodModel(string materialCode, int materialTypeId, int vendor,
            string fromDate, string toDate) {
            var model = new List<MaterialInvPeriodModel>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                model = GetMaterialDailyPeriod(materialCode, materialTypeId, vendor, fromDate, toDate, (int)MyUtilities.Report.Calculate.InPeriod);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectMaterialInvPeriodModel", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<MaterialInvPeriodModel> GetMaterialDailyPeriod(string materialCode, int materialTypeId, int vendor,
            string fromDate, string toDate, int calculateMode) {
            var model = new List<MaterialInvPeriodModel>();
            if (string.IsNullOrWhiteSpace(toDate))
                return model;
            //var ci = new CultureInfo("vi-VN");
            //var fdate = string.IsNullOrWhiteSpace(fromDate)
            //    ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
            //    : Convert.ToDateTime(fromDate, ci);
            var fdate = MyUtilities.Function.ParseDate(fromDate);
            //var tdate = string.IsNullOrWhiteSpace(toDate)
            //    ? DateTime.Now
            //    : Convert.ToDateTime(toDate, ci).AddDays(-1);
            var tdate = MyUtilities.Function.ParseDate(toDate).AddDays(1).AddSeconds(-1);
            var purchaseManager = MyUtilities.UserRole.CheckRole(HttpContext.User.Identity.Name, MyUtilities.UserRole.PurchasingManagement);
            var invManagementLv1 = MyUtilities.UserRole.CheckRole(HttpContext.User.Identity.Name, MyUtilities.UserRole.InvManagement);
            var invManagementLv2 = MyUtilities.UserRole.CheckRole(HttpContext.User.Identity.Name, MyUtilities.UserRole.InvManagementLv2);
            using (var vfi = new tammaContext()) {
                vfi.Configuration.LazyLoadingEnabled = false;
                //var importSx1 = (from id in vfi.ImportFormSX1Detail
                //                 where id.ImportFormSX1.ImportDate >= fdate &&
                //                       id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                //                       id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                //                       id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                //                           .Transaction.Status ==
                //                       (byte)MyUtilities.Transaction.Status.Approved
                //                 orderby id.ImportFormSX1.MaterialUseDate
                //                 select id).FirstOrDefault();

                //var importSx1 = (from id in vfi.ImportFormSX1
                //                 where id.ImportDate >= fdate &&
                //                       id.ImportWorkpieceMaterials.Any() &&
                //                       id.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                //                       id.ImportWorkpieceMaterials.FirstOrDefault().Transaction.Status ==
                //                       (byte)MyUtilities.Transaction.Status.Approved
                //                 orderby id.MaterialUseDate
                //                 select id).FirstOrDefault();
                //if (importSx1 != null)
                //    fdate = importSx1.MaterialUseDate;
                //var importSx1 = (from id in vfi.ImportFormSX1
                //                 where id.ImportDate <= tdate &&
                //                       id.ImportWorkpieceMaterials.Any() &&
                //                       id.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                //                       id.ImportWorkpieceMaterials.FirstOrDefault().Transaction.Status ==
                //                       (byte)MyUtilities.Transaction.Status.Approved
                //                 orderby id.MaterialUseDate descending
                //                 select id).FirstOrDefault();
                //if (importSx1 != null)
                //    tdate = importSx1.MaterialUseDate;
                //var groupMaterials = (from mt in vfi.MaterialTypes
                //                      where mt.Active && mt.MaterialClassifiedId == 1
                //                            && (materialTypeId == 0 || mt.MaterialTypeId == materialTypeId)
                //                      orderby mt.IdentityCode
                //                      select new {
                //                          mt.MaterialTypeId
                //                      }).ToList();
                //var groupIds = groupMaterials.Select(g => g.MaterialTypeId).ToList();
                //var materials = (from m in vfi.Materials
                //                 where m.Active &&
                //                       groupIds.Contains(m.MaterialTypeId) &&
                //                       m.MaterialCode.Contains(materialCode)
                //                 select m).ToList();
                //var materialIds = materials.Select(m => m.MaterialId).ToList();
                var materialInvs = (from x in vfi.MaterialInventories
                                    where x.Material.MaterialType.Active &&
                                          x.Material.MaterialType.MaterialClassifiedId == 1 &&
                                          (materialTypeId == 0 || x.Material.MaterialType.MaterialTypeId == materialTypeId) &&
                                          x.Material.Active &&
                                          x.Material.MaterialCode.Contains(materialCode) &&
                                          (vendor == 0 || x.VendorId == vendor) &&
                                          (x.EndDate == null || x.EndDate > fdate)
                                    select new {
                                        x.Material.MaterialTypeId,
                                        x.Material.MaterialType.IdentityCode,
                                        x.Material.MaterialType.MaterialTypeName,

                                        x.MaterialId,
                                        x.Material.MaterialName,
                                        x.Material.MaterialCode,
                                        x.Material.OutDiameter,
                                        x.Material.InDiameter,
                                        x.Material.Shape,
                                        x.Material.DiameterType,

                                        VendorId = x.VendorId.Value,
                                        VendorCode = x.Vendor.VendorCode,

                                        x.MaterialInventoryId,
                                        x.Length,
                                        x.LotNumber,
                                        x.UnitWeight,
                                        x.UnitPrice,
                                        x.ImportDate,
                                        x.FirstUseDate,
                                        x.EndDate,
                                        x.ImportQuantity,
                                        x.ImportQuantityKg,
                                        x.StoreCode,
                                        x.InfoImg,
                                        x.InfoImg2,
                                        x.ModifiedDate,
                                        x.TotalQty,
                                    }).ToList();
                var materialInvIds = materialInvs.Select(mi => mi.MaterialInventoryId).ToList();
                var onShelves = vfi.OnShelves.Where(x => x.Active && materialInvIds.Contains(x.ReferenceInvId))
                    .Select(x => new InventoryDrawerModel {
                        ShelfName = x.InventoryDrawer.InventoryShelf.ShelfName,
                        ColumnName = x.InventoryDrawer.ColumnName,
                        RowName = x.InventoryDrawer.RowName,
                        AdditionName = x.InventoryDrawer.AdditionName,
                        ReferenceInvId = x.ReferenceInvId
                    }).ToList();
                var mip = (from x in vfi.MaterialInventoryPeriods
                           where x.PeriodDate <= tdate &&
                                 materialInvIds.Contains(x.MaterialInventoryId)
                           select new {
                               x.EarlyPeriodQuantity,
                               x.LastPeriodQuantity,
                               x.Quantity,
                               x.PeriodDate,
                               x.MaterialId,
                               x.MaterialInventoryId,
                               IsInternal = x.Transaction.IsInternal ?? false,
                               IsPurchase = x.Transaction.ImportPurchaseOrders.Any(ipo => ipo.PurchaseOrder != null)
                           }).ToList();
                var mimp = (from x in vfi.MaterialInvOnMachinePeriods
                            where x.PeriodDate <= tdate &&
                                  materialInvIds.Contains(x.MaterialInvId.Value)
                            select new {
                                x.LastQuantity,
                                x.EarlyQuantity,
                                x.Quantity,
                                x.PeriodDate,
                                x.MaterialInvId,
                            }).ToList();

                //if (calculateMode == (int)MyUtilities.Report.Calculate.InPeriod) {
                //    var inPeriods = mip.Where(x => x.PeriodDate >= fdate).ToList();
                //    var inPeriods2 = mimp.Where(x => x.PeriodDate >= fdate).ToList();
                //    if (!inPeriods.Any() && !inPeriods2.Any()) {
                //        return model;
                //    }
                //    materialInvIds = inPeriods.Select(x => x.MaterialInventoryId).ToList();
                //    materialInvIds.AddRange(inPeriods2.Select(x => x.MaterialInvId.Value));
                //    materialInvIds = materialInvIds.Distinct().ToList();
                //    materialInvs = materialInvs.Where(x => materialInvIds.Contains(x.MaterialInventoryId)).ToList();
                //}
                var emDestroyInMonth = (from em in vfi.ExportMaterialDetails
                                        where
                                        em.ExportMaterial.ExportDate >= fdate &&
                                        em.ExportMaterial.ExportDate <= tdate &&
                                        em.ExportMaterial.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                        em.MachineId == null &&
                                        materialInvIds.Contains(em.MaterialInvId)
                                        select new {
                                            em.MaterialInvId,
                                            em.Quantity,
                                            IsInternal = em.ExportMaterial.Transaction.IsInternal ?? false
                                        }).ToList();
                var useInMonth = from ms in vfi.MaterialUseDetails
                                 where ms.MaterialUseInShift.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                       ms.MaterialUseInShift.UsedDate >= fdate &&
                                       ms.MaterialUseInShift.UsedDate <= tdate &&
                                       materialInvIds.Contains(ms.MaterialInvId)
                                 select new {
                                     ms.MaterialInvId,
                                     Quantity = ms.EditQuantity + ms.EditQuantity2,
                                     ms.MaterialUseInShift.Type,
                                     ms.IsDetroy,
                                 };
                // the hien cac nguyen lieu tren may
                var materialInvOnMachines =
                    vfi.MaterialInvOnMachines.Where(mi => mi.TotalQuantity > 0)
                        .Select(mi => mi.MaterialInvId)
                        .Distinct()
                        .ToList();
                foreach (var materialInv in materialInvs) {
                    var entity = new MaterialInvPeriodModel() {
                        FromDate = fdate,
                        ToDate = tdate,
                        FromDateString = fdate.ToString("dd/MM/yyyy"),
                        ToDateString = tdate.AddDays(1).ToString("dd/MM/yyyy"),
                        MaterialTypeId = materialInv.MaterialTypeId,
                        MaterialTypeCode = materialInv.IdentityCode,
                        MaterialTypeName = materialInv.MaterialTypeName,

                        MaterialId = materialInv.MaterialId,
                        MaterialName = materialInv.MaterialName,
                        MaterialCode = materialInv.MaterialCode,
                        OutDiameter = materialInv.OutDiameter,
                        InDiameter = materialInv.InDiameter,
                        Shape = materialInv.Shape.Trim(),
                        DiameterType = materialInv.DiameterType.Trim(),

                        VendorId = materialInv.VendorId,
                        VendorCode = materialInv.VendorCode,

                        MaterialInvId = materialInv.MaterialInventoryId,
                        Length = materialInv.Length,
                        MaterialLot = materialInv.LotNumber,
                        MaterialUnitWeight = materialInv.UnitWeight,
                        MaterialUnitPrice = materialInv.UnitPrice,
                        ImportDateString =
                            materialInv.ImportDate != null
                                ? materialInv.ImportDate.ToString("dd/MM/yyyy")
                                : "",
                        FirstUseDateString =
                            materialInv.FirstUseDate != null
                                ? materialInv.FirstUseDate.Value.ToString("dd/MM/yyyy")
                                : "",
                        EndUseDateString =
                            materialInv.EndDate != null
                                ? materialInv.EndDate.Value.ToString("dd/MM/yyyy")
                                : "",
                        FirstImport = string.Format("{0:n2}", materialInv.ImportQuantity),
                        FirstImportKg = string.Format("{0:n2}", materialInv.ImportQuantityKg),
                        //StoreCode = materialInv.StoreCode,
                        Show = true,
                        Active = false,
                        InfoImg = materialInv.InfoImg,
                        InfoImg2 = materialInv.InfoImg2,
                        UploadDate = materialInv.ModifiedDate.ToString("yyyyMMddhhmmss"),
                        CanEdit = invManagementLv2,
                        CanUpload = invManagementLv1,
                    };
                    var onShelvesById = onShelves.Where(x => x.ReferenceInvId == materialInv.MaterialInventoryId).ToList();
                    if (onShelvesById.Any()) {
                        entity.StoreCode = string.Join("+", onShelvesById.Distinct().OrderBy(x => x.DrawerCode).Select(x => x.DrawerCode).ToList());
                    }
                    else if (materialInv.TotalQty > 0) {
                        entity.StoreCode = "Ngoài kệ";
                    }
                    if (string.IsNullOrWhiteSpace(entity.InfoImg))
                        entity.InfoImg = "askquestion.jpg";
                    if (string.IsNullOrWhiteSpace(entity.InfoImg2))
                        entity.InfoImg2 = "askquestion.jpg";

                    // ton trong KHO
                    var periodById = mip.Where(p => p.MaterialInventoryId == entity.MaterialInvId).ToList();
                    entity.LastQuantity = Math.Round(periodById.Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity), 2);

                    var periodByParam = periodById.Where(p => p.PeriodDate < fdate).ToList();
                    entity.EarlyQuantity = Math.Round(periodByParam.Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity), 2);

                    // dien bien ton KHO
                    periodById = periodById.Where(p => p.PeriodDate >= fdate &&
                                                        p.LastPeriodQuantity > p.EarlyPeriodQuantity)
                                            .ToList();
                    if (periodById.Any()) {
                        entity.DiffImport = Math.Round(periodById.Sum(period => period.Quantity), 2);
                        periodByParam = periodById.Where(p => p.IsPurchase).ToList();
                        entity.Import = Math.Round(periodByParam.Sum(period => period.Quantity), 2);

                        periodByParam = periodById.Where(p => !p.IsPurchase && !p.IsInternal).ToList();
                        entity.ImportMore = Math.Round(periodByParam.Sum(period => period.Quantity), 2);

                        periodByParam = periodById.Where(p => !p.IsPurchase && p.IsInternal).ToList();
                        entity.ImportInternal = Math.Round(periodByParam.Sum(period => period.Quantity), 2);
                    }

                    // ton tren MAY
                    var onMachineById = mimp.Where(p => p.MaterialInvId == entity.MaterialInvId).ToList();
                    if (onMachineById.Any()) {
                        entity.LastOnMachine = Math.Round(onMachineById.Sum(p => p.LastQuantity - p.EarlyQuantity), 2);
                        onMachineById = onMachineById.Where(p => p.PeriodDate < fdate).ToList();
                        entity.EarlyOnMachine = Math.Round(onMachineById.Sum(p => p.LastQuantity - p.EarlyQuantity), 2);
                    }

                    // dien bien ton MAY
                    var useById = useInMonth.Where(u => u.MaterialInvId == entity.MaterialInvId).ToList();
                    if (useById.Any()) {
                        var useByParam = useById.Where(u => u.Type == (int)MyUtilities.Material.UseType.Using).ToList();
                        entity.Export = Math.Round(useByParam.Sum(e => e.Quantity), 2);

                        useByParam = useById.Where(u => u.IsDetroy && u.Type == (int)MyUtilities.Material.UseType.SendBack).ToList();
                        entity.DestroyOnMachine = Math.Round(useByParam.Sum(e => e.Quantity), 2);
                        entity.DiffExport = entity.Export + entity.DestroyOnMachine;
                        useByParam = useById.Where(u => !u.IsDetroy && u.Type == (int)MyUtilities.Material.UseType.SendBack).ToList();
                        entity.ImportOnMachine = Math.Round(useByParam.Sum(e => e.Quantity), 2);
                    }
                    if (entity.ImportOnMachine > 0) {
                        entity.DiffImport -= entity.ImportOnMachine;
                        if (entity.ImportOnMachine >= entity.ImportMore) {
                            entity.ImportOnMachine -= entity.ImportMore;
                            entity.ImportMore = 0;
                        }
                        else {
                            entity.ImportMore -= entity.ImportOnMachine;
                            entity.ImportOnMachine = 0;
                        }
                    }

                    var exportsById = emDestroyInMonth.Where(em => em.MaterialInvId == entity.MaterialInvId).ToList();
                    if (exportsById.Any()) {
                        entity.DiffExport += Math.Round(exportsById.Sum(e => e.Quantity));
                        var emById = exportsById.Where(x => !x.IsInternal).ToList();
                        entity.Destroy = Math.Round(emById.Sum(e => e.Quantity), 2);
                        emById = exportsById.Where(x => x.IsInternal).ToList();
                        entity.ExportInternal = Math.Round(emById.Sum(e => e.Quantity), 2);
                    }
                    entity.DiffImport -= entity.TotalImport;
                    // the hien cac nguyen lieu tren may
                    var checkActive = materialInvOnMachines.FirstOrDefault(mi => mi == entity.MaterialInvId);
                    if (checkActive != null) {
                        entity.Active = true;
                    }

                    if (entity.Check) {
                        model.Add(entity);
                    }
                }
            }
            return
                model.OrderBy(m => m.MaterialTypeCode)
                    .ThenBy(m => m.MaterialName)
                    .ThenBy(m => m.Shape)
                    .ThenBy(m => m.DiameterType)
                    .ThenBy(m => m.OutDiameter)
                    .ThenBy(m => m.InDiameter)
                    .ThenBy(m => m.MaterialLot).ToList();
        }

        public ActionResult CheckUploadImage(string upload) {
            //if (date.DayOfWeek == DayOfWeek.Monday)
            //    date = date.AddDays(-2);
            //else
            //    date = date.AddDays(-1);
            try {

                using (var vfi = new tammaContext()) {
                    var msg = "";
                    var materialInvs = vfi.MaterialInventories.Where(p => p.InfoImg.Equals(upload)|| p.InfoImg2.Equals(upload));
                    if (materialInvs.Any()) {
                        foreach (var materialInv in materialInvs) {
                            msg += materialInv.Material.MaterialCode + materialInv.LotNumber +
                                            (materialInv.Length / 3000) + "|/n";
                        }
                        return Json("9! " + msg);
                    }
                }
            }
            catch (Exception ex) {
                return Json("0! " + ex.Message);
            }
            return Json("");
        }

        [HttpPost]
        public ActionResult SaveCertificate(IEnumerable<HttpPostedFileBase> CertificateMaterial) {
            // The Name of the Upload component is "attachments"       
            try {
                var attachments = new List<HttpPostedFileBase>();
                if (CertificateMaterial != null && CertificateMaterial.Any()) {
                    attachments.AddRange(CertificateMaterial.ToList());
                }
                if (attachments.Any()) {
                    foreach (var file in attachments) {
                        // Some browsers send file names with full path. We only care about the file name.
                        var fileName = Path.GetFileName(file.FileName);
                        if (fileName == null) continue;
                        var destinationPath = Path.Combine(Server.MapPath("~/Content/FileUpload/CertificateMaterial"), fileName);
                        // giam kich thuoc
                        Image bm = Image.FromStream(file.InputStream);
                        var designWidth = 3000.0;
                        var designHeight = 1500.0;
                        var ratioW = designWidth / (double)bm.Width;
                        var ratioH = designHeight / (double)bm.Height;
                        var ratio = ratioH < ratioW ? ratioH : ratioW;
                        var newWidth = Convert.ToInt32(bm.Width * ratio);
                        var newHeight = Convert.ToInt32(bm.Height * ratio);
                        bm = ResizeBitmap((Bitmap)bm, newWidth, newHeight);
                        bm.Save(destinationPath, bm.RawFormat);
                        //bm.Save(destinationPath);
                    }
                    return Json("Upload thành công !");
                }
                else {
                    throw new AggregateException("attachments null");
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("UploadSave", ex.Message);
                return Json(ex.Message);
            }
            // Redirect to a view showing the result of the form submissSaveion.    
            //return Json("False");
        }

