        private Bitmap ResizeBitmap(Bitmap b, int nWidth, int nHeight) {
            Bitmap result = new Bitmap(nWidth, nHeight);
            using (Graphics g = Graphics.FromImage((Image)result))
                g.DrawImage(b, 0, 0, nWidth, nHeight);
            return result;
        }
        List<PrintMaterialTotal> GetMaterialTotal(string materialCode, int materialTypeId, string fromDate, string toDate) {
            var model = new List<PrintMaterialTotal>();
            var ci = new CultureInfo("vi-VN");
            var fdate = string.IsNullOrWhiteSpace(fromDate)
                            ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                            : Convert.ToDateTime(fromDate, ci);
            var tdate = string.IsNullOrWhiteSpace(toDate)
                            ? DateTime.Now
                            : Convert.ToDateTime(toDate, ci).AddDays(1).AddSeconds(-1);
            using (var vfi = new tammaContext()) {
                vfi.Configuration.LazyLoadingEnabled = false;

                var importSx1 = (from id in vfi.ImportFormSX1Detail
                                 where id.ImportFormSX1.ImportDate >= fdate &&
                                       id.ImportFormSX1.ImportDate <= tdate &&
                                       id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                       id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                       id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                         .Transaction.Status ==
                                       (byte)MyUtilities.Transaction.Status.Approved
                                 orderby id.ImportFormSX1.MaterialUseDate
                                 select new {
                                     id.ImportFormSX1.MaterialUseDate,
                                     MaterialUse = (id.MaterialUse1) + (id.MaterialUse2),
                                     id.MaterialInvId
                                 }).ToList();
                if (!importSx1.Any())
                    throw new AggregateException("Không có báo cáo mới ! ");
                var startMonth = importSx1.FirstOrDefault().MaterialUseDate;
                var endMonth = importSx1.LastOrDefault().MaterialUseDate;
                var materialInvs =
                    string.IsNullOrWhiteSpace(materialCode) ?

                    (from mi in vfi.MaterialInventories
                     where //materialIds.Contains(mi.MaterialId)
                         mi.Material.MaterialType.Active
                         && mi.Material.MaterialType.MaterialClassifiedId == 1
                         && mi.Material.Active
                     //&& (mi.ModifiedDate > deathMonth || mi.TotalQty > 0)
                     //&& mi.MaterialInventoryId == 618
                     select new {
                         mi.Material.MaterialType.IdentityCode,
                         mi.Material.MaterialType.MaterialTypeName,
                         mi.Material.MaterialType.MaterialTypeId,
                         mi.Material.MaterialName,
                         mi.Material.MaterialCode,
                         mi.Material.Shape,
                         mi.Material.InDiameter,
                         mi.Material.OutDiameter,
                         mi.Material.DiameterType,
                         mi.MaterialId,
                         mi.Length,
                         mi.MaterialInventoryId,
                         mi.LotNumber,
                         mi.Vendor.VendorCode,
                         mi.UnitWeight,
                         mi.UnitPrice,
                         mi.StoreCode,
                         mi.ImportQuantity,
                         mi.ImportQuantityKg,
                         mi.ImportDate,
                         mi.FirstUseDate,
                         mi.EndDate,
                         mi.VendorId,
                     }).ToList()
                    :
                    (from mi in vfi.MaterialInventories
                     where //materialIds.Contains(mi.MaterialId)
                         mi.Material.MaterialType.Active
                         && mi.Material.MaterialType.MaterialClassifiedId == 1
                         && mi.Material.Active
                         && mi.Material.MaterialCode.Contains(materialCode)
                     //&& (mi.ModifiedDate > deathMonth || mi.TotalQty > 0)
                     //&& mi.MaterialInventoryId == 618
                     select new {
                         mi.Material.MaterialType.IdentityCode,
                         mi.Material.MaterialType.MaterialTypeName,
                         mi.Material.MaterialType.MaterialTypeId,
                         mi.Material.MaterialName,
                         mi.Material.MaterialCode,
                         mi.Material.Shape,
                         mi.Material.InDiameter,
                         mi.Material.OutDiameter,
                         mi.Material.DiameterType,
                         mi.MaterialId,
                         mi.Length,
                         mi.MaterialInventoryId,
                         mi.LotNumber,
                         mi.Vendor.VendorCode,
                         mi.UnitWeight,
                         mi.UnitPrice,
                         mi.StoreCode,
                         mi.ImportQuantity,
                         mi.ImportQuantityKg,
                         mi.ImportDate,
                         mi.FirstUseDate,
                         mi.EndDate,
                         mi.VendorId,
                     }).ToList();
                if (!materialInvs.Any())
                    return model;
                //importSx1 = importSx1.Where(id => id.MaterialInvId == 618).ToList();
                //if (string.IsNullOrWhiteSpace(materialCode))
                //{
                //    materialInvs = materialInvs.Where(mi => mi.MaterialCode.Contains(materialCode));
                //}
                var materialInvIds = materialInvs.Select(mi => mi.MaterialInventoryId).ToList();
                var mip = (from period in vfi.MaterialInventoryPeriods
                           where
                               period.PeriodDate <= tdate &&
                               materialInvIds.Contains(period.MaterialInventoryId)
                           select new {
                               period.MaterialInventoryId,
                               period.PeriodDate,
                               period.EarlyPeriodQuantity,
                               period.LastPeriodQuantity,
                               period.Quantity,
                               IsDestroyed = period.IsDestroyed ?? false,
                           }).ToList();
                var mipStartMonth = (from period in mip
                                     where period.PeriodDate < startMonth
                                     select period).ToList();
                var mipInMonth = (from period in mip
                                  where period.PeriodDate >= startMonth
                                  orderby period.PeriodDate
                                  select period).ToList();
                var mimp = (from period in vfi.MaterialInvOnMachinePeriods
                            where
                                period.PeriodDate <= tdate
                            select new {
                                period.MaterialInvId,
                                period.PeriodDate,
                                period.EarlyQuantity,
                                period.LastQuantity,
                                period.Quantity,
                            }).ToList();
                var mimpStartMonth = (from period in mimp
                                      where period.PeriodDate < startMonth
                                      select period).ToList();
                //var mimpInMonth = (from period in mimp
                //                      where period.PeriodDate >= startMonth
                //                      select period).ToList();
                var emDestroyInMonth = (from em in vfi.ExportMaterialDetails
                                        where
                                            em.ExportMaterial.ExportDate >= startMonth &&
                                            em.ExportMaterial.ExportDate <= tdate &&
                                            em.ExportMaterial.Transaction.Status ==
                                            (byte)MyUtilities.Transaction.Status.Approved &&
                                            em.MachineId == null
                                        select new {
                                            em.MachineId,
                                            em.Machine.MachineName,
                                            em.MaterialInvId,
                                            Quantity = em.Quantity,
                                            em.ExportMaterial.ExportDate,
                                        }).ToList();
                var retrieveInMonth = from ms in vfi.MaterialUseDetails
                                      where ms.MaterialUseInShift.Type == (int)MyUtilities.Material.UseType.SendBack &&
                                            ms.MaterialUseInShift.Status ==
                                            (byte)MyUtilities.Transaction.Status.Approved &&
                                            ms.MaterialUseInShift.UsedDate >= startMonth &&
                                            ms.MaterialUseInShift.UsedDate <= tdate
                                      select new {
                                          ms.MaterialInvId,
                                          Quantity = ms.EditQuantity + ms.EditQuantity2,
                                          ms.IsDetroy
                                      };
                //var imInMonth = (from ipo in vfi.ImportPurchaseOrderDetails
                //                 where
                //                     ipo.ImportPurchaseOrder.ImportDate.Value >= startMonth &&
                //                     ipo.ImportPurchaseOrder.ImportDate.Value <= endMonth &&
                //                     ipo.ImportPurchaseOrder.Transaction.Status ==
                //                     (byte) MyUtilities.Transaction.Status.Approved
                //                 select new
                //                     {
                //                         ipo.MaterialId,
                //                         ipo.LotNumber,
                //                         //UnitWeight = ipo.UnitWeight.Value,
                //                         Quantity = ipo.Quantity.Value,
                //                         ImportDate = ipo.ImportPurchaseOrder.ImportDate.Value
                //                     }).ToList();
                foreach (var materialInv in materialInvs) {
                    var entity = new PrintMaterialTotal {
                        MaterialTypeId = materialInv.MaterialTypeId,
                        MaterialTypeCode = materialInv.IdentityCode,
                        VendorCode = materialInv.VendorCode,
                        MaterialName = materialInv.MaterialName,
                        MaterialCode = materialInv.MaterialCode,
                        Shape = materialInv.Shape,
                        InDiameter = materialInv.InDiameter,
                        OutDiameter = materialInv.OutDiameter,
                        Length = materialInv.Length,
                        DiameterType = materialInv.DiameterType,
                        MaterialLot = materialInv.LotNumber,
                        MaterialUnitPrice = materialInv.UnitPrice,
                        MaterialUnitWeight = materialInv.UnitWeight,
                        EarlyQuantity = 0,
                        Import = 0,
                        Export = 0,
                        LastQuantity = 0,
                        MaterialOnMachine = 0,
                        ExportDestroyed = 0,
                        Show = true,
                        StoreCode = materialInv.StoreCode,
                        ImportDateString =
                            materialInv.ImportDate != null
                                ? materialInv.ImportDate.ToString("dd/MM/yyyy")
                                : "",
                        FirstUseDateString =
                            materialInv.FirstUseDate != null
                                ? materialInv.FirstUseDate.Value.ToString("dd/MM/yyyy")
                                : "",
                        EndUseDateString =
                            materialInv.EndDate != null
                                ? materialInv.EndDate.Value.ToString("dd/MM/yyyy")
                                : "",
                        FirstImport = string.Format("{0:n2}", materialInv.ImportQuantity),
                        FirstImportKg = string.Format("{0:n2}", materialInv.ImportQuantityKg),
                        MaterialInvId = materialInv.MaterialInventoryId,
                        MaterialId = materialInv.MaterialId,
                        VendorId = materialInv.VendorId.Value,
                    };
                    var startPeriod =
                        mipStartMonth.Where(
                            period => period.MaterialInventoryId == materialInv.MaterialInventoryId);
                    if (startPeriod.Any()) {
                        entity.EarlyQuantity =
                            Math.Round(startPeriod.Sum(
                                period => period.LastPeriodQuantity - period.EarlyPeriodQuantity),
                                       2);
                    }
                    var startOnMachine = mimpStartMonth.Where(
                        period => period.MaterialInvId == materialInv.MaterialInventoryId);
                    if (startOnMachine.Any()) {
                        entity.EarlyQuantity +=
                            Math.Round(startOnMachine.Sum(
                                period => period.LastQuantity - period.EarlyQuantity), 2);
                    }
                    var endPeriod =
                        mip.Where(
                            period => period.MaterialInventoryId == materialInv.MaterialInventoryId);
                    if (endPeriod.Any()) {
                        entity.LastQuantity =
                            Math.Round(endPeriod.Sum(
                                period => period.LastPeriodQuantity - period.EarlyPeriodQuantity), 2);
                    }
                    var materialOnMachines =
                        mimp.Where(
                            period => period.MaterialInvId == materialInv.MaterialInventoryId);
                    if (materialOnMachines.Any()) {
                        entity.MaterialOnMachine =
                            Math.Round(materialOnMachines.Sum(
                                period => period.LastQuantity - period.EarlyQuantity), 2);
                        entity.LastQuantity += entity.MaterialOnMachine;
                    }
                    var importInMonth =
                        mipInMonth.Where(
                            period =>
                            period.MaterialInventoryId == materialInv.MaterialInventoryId &&
                            period.LastPeriodQuantity > period.EarlyPeriodQuantity);
                    if (importInMonth.Any()) {
                        entity.Import = Math.Round(importInMonth.Sum(period => period.Quantity), 2);
                    }
                    var retrieve =
                        retrieveInMonth.Where(
                            ms => ms.MaterialInvId == materialInv.MaterialInventoryId && !ms.IsDetroy);
                    if (retrieve.Any()) {
                        entity.SendBack = Math.Round(retrieve.Sum(period => period.Quantity), 2);
                        entity.Import -= entity.SendBack;
                    }
                    var materialUse =
                        importSx1.Where(em => em.MaterialInvId == materialInv.MaterialInventoryId);
                    if (materialUse.Any()) {
                        entity.Export = Math.Round(materialUse.Sum(e => e.MaterialUse), 2);
                    }
                    var emDestroyById =
                        emDestroyInMonth.Where(
                            em =>
                            em.MaterialInvId == materialInv.MaterialInventoryId);
                    if (emDestroyById.Any()) {
                        entity.ExportDestroyed = Math.Round(emDestroyById.Sum(e => e.Quantity), 2);
                    }
                    var emDestroyOnMachineById =
                        retrieveInMonth.Where(
                            ms => ms.MaterialInvId == materialInv.MaterialInventoryId && ms.IsDetroy);
                    if (emDestroyOnMachineById.Any()) {
                        entity.ExportDestroyedOnMachine = Math.Round(emDestroyOnMachineById.Sum(period => period.Quantity), 2);
                    }
                    if (entity.Print) {
                        model.Add(entity);
                    }
                }
            }
            return model
                                          .OrderBy(l => l.MaterialTypeCode)
                                          .ThenBy(l => l.MaterialName)
                                          .ThenBy(l => l.Shape)
                                          .ThenBy(l => l.OutDiameter)
                                          .ThenBy(l => l.InDiameter)
                                          .ThenBy(l => l.DiameterType)
                                          .ThenBy(l => l.Length)
                                          .ThenBy(l => l.MaterialLot).ToList();
        }

        [GridAction]
        public ActionResult SelectMaterialInventoryTotal(
            string materialCode, int materialTypeId, string fromDate, string toDate
            ) {
            var model = new List<PrintMaterialTotal>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                model = GetMaterialTotal(materialCode, materialTypeId, fromDate, toDate);
            }
            catch (Exception ex) {
                ModelState.AddModelError("MaterialInvTotal", ex.Message);
            }
            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult UpdateMaterialInventoryTotal(MaterialInvPeriodModel update) {
            try {
                using (var vfi = new tammaContext()) {
                    var materialInv =
                        vfi.MaterialInventories.FirstOrDefault(mi => mi.MaterialInventoryId == update.MaterialInvId);
                    materialInv.StoreCode = update.StoreCode;
                    if (update.CanUpload) {
                        if (!string.IsNullOrWhiteSpace(update.InfoImg)) {
                            materialInv.InfoImg = update.InfoImg;
                        }
                        if (!string.IsNullOrWhiteSpace(update.InfoImg2)) {
                            materialInv.InfoImg2 = update.InfoImg2;
                        }
                    }
                    if (update.CanEdit) {
                        materialInv.UnitPrice = update.MaterialUnitPrice;
                        materialInv.UnitWeight = update.MaterialUnitWeight;
                        materialInv.EndDate = !string.IsNullOrWhiteSpace(update.EndUseDateString)
                            ? MyUtilities.Function.ParseDate(update.EndUseDateString)
                            : DateTime.Now;
                    }
                    vfi.SaveChanges();
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("UpdateMaterialInventoryTotal", ex.Message);
            }
            return
                View(new GridModel(GetMaterialDailyPeriod("", 0, 0, "", "", (int)MyUtilities.Report.Calculate.InPeriod)));
        }

        [GridAction]
        public ActionResult SelectMaterialDailyReport(string materialCode, int materialTypeId, string date) {
            var model = new List<PrintMaterialDailyReportModel>();
            var ci = new CultureInfo("vi-VN");
            var reportDate = string.IsNullOrWhiteSpace(date)
                              ? DateTime.Today
                              : Convert.ToDateTime(date, ci);
            reportDate = reportDate.AddDays(1).AddSeconds(-1);
            //var lastReportDate = reportDate.AddDays(-1);
            var startMonth = new DateTime(reportDate.Year, reportDate.Month, 1);
            try {
                using (var vfi = new tammaContext()) {
                    var importSx1Details = from id in vfi.ImportFormSX1Detail
                                           where
                                               id.ImportFormSX1.MaterialUseDate < reportDate &&
                                               id.ImportFormSX1.MaterialUseDate > startMonth &&
                                               id.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                               id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                               id.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                 .Transaction.Status ==
                                               (byte)MyUtilities.Transaction.Status.Approved
                                           select new {
                                               MaterialInvId = id.MaterialInvId.Value,
                                               id.Product,
                                               MaterialUse = (id.MaterialUse1) + (id.MaterialUse2),
                                               Production = (id.Number1) + (id.Number2) +
                                                            (id.Processing1) + (id.Processing2),
                                               MaterialUseDate = id.ImportFormSX1.MaterialUseDate,
                                           };
                    var identityCodes = MaterialIdentityCode.GetMaterialIdentityCodes(0);
                    foreach (var importDetail in importSx1Details) {
                        var materialInv =
                            vfi.MaterialInventories.FirstOrDefault(
                                mi => mi.MaterialInventoryId == importDetail.MaterialInvId);
                        if (materialInv == null)
                            throw new AggregateException("Lỗi!");
                        var entity =
                            model.FirstOrDefault(
                                m =>
                                m.MaterialInvId == importDetail.MaterialInvId
                            //&&m.ProductId == importDetail.Product.ProductId
                                );
                        if (entity == null) {
                            entity = new PrintMaterialDailyReportModel {
                                MaterialTypeId = materialInv.Material.MaterialTypeId,
                                MaterialInvId = importDetail.MaterialInvId,
                                MaterialId = materialInv.MaterialId,
                                Shape = materialInv.Material.Shape,
                                OutDiameter = materialInv.Material.OutDiameter,
                                InDiameter = materialInv.Material.InDiameter,
                                DiameterType = materialInv.Material.DiameterType,
                                MaterialLot = materialInv.LotNumber,
                                VendorCode = materialInv.Vendor.VendorCode,
                                MaterialName = materialInv.Material.MaterialName,
                                MaterialWeight = materialInv.UnitWeight,
                                //ProductId = importDetail.Product.ProductId,
                                //ProductCode = importDetail.Product.ProductCode,
                                //ProductionRate = importDetail.Product.ProductionRate ?? 0,
                                //ProductWeight = importDetail.Product.Weight ?? 0,
                                Production = 0,
                                ProductionInMonth = 0,
                                MaterialUse = 0,
                                MaterialUseInMonth = 0,
                                WorkpieceMaterial = 0,
                                WorkpieceMaterialInMonth = 0,
                                DifferenceStandard = 0,
                                DifferenceStandardInMonth = 0
                            };
                            entity.DesignNo = MyUtilities.Material.GetMaterialDesignNo(
                                entity.OutDiameter,
                                entity.InDiameter,
                                entity.DiameterType,
                                entity.Shape);
                            model.Add(entity);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("WorkpieceMaterialReport", ex.Message);
            }
            return View(new GridModel(model
                                          .OrderBy(m => m.MaterialTypeId)
                                          .ThenBy(m => m.MaterialName)
                                          .ThenBy(l => l.Shape)
                                          .ThenBy(l => l.OutDiameter)
                                          .ThenBy(l => l.InDiameter)
                                          .ThenBy(l => l.DiameterType)
                                          .ThenBy(l => l.Length)
                                          .ThenBy(l => l.MaterialLot)
                            ));
        }

