        [GridAction]
        public ActionResult SelectWorkpieceMaterialReport(int materialType, string fromDate, string toDate) {
            var model = new List<WorkpieceMaterialPeriodModel>();
            try {
                if (!string.IsNullOrWhiteSpace(fromDate)) {
                    model = GetWorkPriceMaterialModel(materialType, fromDate, toDate);
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("WorkpieceMaterialReport", ex.Message);
            }
            return View(new GridModel(model.OrderBy(m => m.IdentityCode).ThenBy(m => m.Type)));
        }

        [HttpPost]
        public ActionResult PrintWorkpieceMaterial(string fromDate, string toDate) {
            var model = new List<WorkpieceMaterialPeriodModel>();
            try {
                model = GetWorkPriceMaterialModel(0, fromDate, toDate);
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintWorkpieceMaterial", ex.Message);
            }
            return PartialView("PageWorkpieceMaterial", model.OrderBy(m => m.IdentityCode).ThenBy(m => m.Type).ToList());
        }

        public List<WorkpieceMaterialPeriodModel> GetWorkPriceMaterialModel(int materialType, string fromDate, string toDate) {
            var model = new List<WorkpieceMaterialPeriodModel>();
            var ci = new CultureInfo("vi-VN");
            var fromD = string.IsNullOrWhiteSpace(fromDate)
                              ? DateTime.Today
                              : Convert.ToDateTime(fromDate, ci);
            var toD = string.IsNullOrWhiteSpace(toDate)
                              ? DateTime.Today
                              : Convert.ToDateTime(toDate, ci);
            try {
                using (var vfi = new tammaContext()) {
                    var periods = vfi.WorkpieceMaterialPeriods.ToList();
                    if (!string.IsNullOrWhiteSpace(fromDate) && !string.IsNullOrWhiteSpace(toDate))
                        periods = periods.Where(wmp => wmp.PeriodDate <= toD).ToList();
                    var importSx1Details = (from sxd in vfi.ImportFormSX1Detail
                                            where
                                            sxd.ImportFormSX1.MaterialUseDate.Month == toD.Month &&
                                            sxd.ImportFormSX1.MaterialUseDate.Year == toD.Year &&
                                            sxd.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                            sxd.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                            sxd.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                .Transaction.Status ==
                                            (byte)MyUtilities.Transaction.Status.Approved &&
                                            sxd.MaterialUse1 + sxd.MaterialUse2 > 0
                                            && (materialType == 0 || sxd.MaterialInventory.Material.MaterialTypeId == materialType)
                                            orderby sxd.ImportFormSX1.MaterialUseDate
                                            select new {
                                                MaterialUse = sxd.MaterialUse1 + sxd.MaterialUse2,
                                                MaterialUnitPrice = sxd.MaterialInventory.UnitPrice,
                                                MaterialUnitWeight = sxd.MaterialInventory.UnitWeight,
                                                IdentityCode = sxd.MaterialInventory.Material.MaterialType.IdentityCode,
                                            }).ToList();
                    var identityCodes = MaterialIdentityCode.GetMaterialIdentityCodes(materialType);
                    foreach (var identity in identityCodes) {
                        var avgPrice = 0;
                        var sx1s = importSx1Details.Where(id => id.IdentityCode.Equals(identity.IdentityCode));
                        if (sx1s.Any()) {
                            var totalWeight = sx1s.Sum(sx => sx.MaterialUse * sx.MaterialUnitWeight);
                            var totalPrice = sx1s.Sum(sx => sx.MaterialUse * sx.MaterialUnitWeight * sx.MaterialUnitPrice);
                            avgPrice = MyUtilities.Function.RoundUp(totalPrice / totalWeight);
                        }
                        foreach (var type in MyUtilities.Material.GetMaterialIdentityType()) {
                            var entity = new WorkpieceMaterialPeriodModel {
                                IdentityCode = identity.IdentityCode.Trim(),
                                MaterialTypeName = identity.MaterialTypeShortName,
                                Type = type,
                                Weight = 0,
                                EoI = (int)MyUtilities.Transaction.EoIEnum.Import,
                                IsDestroy = false,
                                FromDate = fromDate,
                                ToDate = toDate,
                                AvgMaterialUnitPrice = avgPrice
                            };
                            var periodByTypes =
                                periods.Where(wmp => wmp.IdentityCode.Equals(identity.IdentityCode) && wmp.Type == type)
                                       .ToList();
                            if (!string.IsNullOrWhiteSpace(fromDate) && !string.IsNullOrWhiteSpace(toDate)) {
                                var periodByDates = periodByTypes.Where(wmp => wmp.PeriodDate < fromD).ToList();
                                entity.EarlyQuantity = periodByDates.Sum(wmp => wmp.LastQuantity - wmp.EarlyQuantity);
                                entity.LastQuantity = periodByTypes.Sum(wmp => wmp.LastQuantity - wmp.EarlyQuantity);

                                periodByDates =
                                    periodByTypes.Where(
                                        wmp =>
                                        wmp.PeriodDate >= fromD &&
                                        wmp.EoI == (byte)MyUtilities.Transaction.EoIEnum.Import).ToList();
                                entity.Import =
                                    periodByDates.Where(wmp => wmp.ImportWorkpieceMaterial.TransactionId != null)
                                                 .Sum(wmp => wmp.Weight);
                                if (entity.Import > 0) {

                                }
                                entity.ImportVirtual =
                                    periodByDates.Where(wmp => wmp.ImportWorkpieceMaterial.TransactionId == null)
                                                 .Sum(wmp => wmp.Weight);

                                periodByDates =
                                    periodByTypes.Where(
                                        wmp =>
                                        wmp.PeriodDate >= fromD &&
                                        wmp.EoI == (byte)MyUtilities.Transaction.EoIEnum.Export).ToList();
                                entity.Export = periodByDates.Where(wmp => wmp.ExportType == (byte)MyUtilities.Material.WorkpieceExport.Sales)
                                                             .Sum(wmp => wmp.Weight);
                                entity.Destroy = periodByDates.Where(wmp => wmp.ExportType == (byte)MyUtilities.Material.WorkpieceExport.Destroy)
                                                             .Sum(wmp => wmp.Weight);
                                entity.Process = periodByDates.Where(wmp => wmp.ExportType == (byte)MyUtilities.Material.WorkpieceExport.Process)
                                                             .Sum(wmp => wmp.Weight);
                            }
                            model.Add(entity);
                        }

                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintWorkpieceMaterial", ex.Message);
            }
            return model;
        }

        [GridAction]
        public ActionResult SelectProductionImportWorkpiece(string identityCode, int type, string fromDate,
                                                                  string toDate) {

            var model = new List<WorkpieceImportExportModel>();
            var ci = new CultureInfo("vi-VN");
            var from = string.IsNullOrWhiteSpace(fromDate)
                              ? DateTime.Today
                              : Convert.ToDateTime(fromDate, ci);
            var to = string.IsNullOrWhiteSpace(toDate)
                              ? DateTime.Today
                              : Convert.ToDateTime(toDate, ci);
            try {
                using (var vfi = new tammaContext()) {
                    var periods =
                        vfi.WorkpieceMaterialPeriods.Where(
                            wmp =>
                            wmp.PeriodDate >= from && wmp.PeriodDate <= to &&
                            wmp.IdentityCode.Equals(identityCode) &&
                            wmp.Type == type).ToList();
                    if (!periods.Any())
                        return View(new GridModel(model));
                    var ids = periods.Where(x => x.EoI == (int)MyUtilities.Transaction.EoIEnum.Import).Select(x => x.EoIId.Value).ToList();
                    var imports = vfi.ImportWorkpieceMaterials.Where(x => ids.Contains(x.ImportId)).ToList();
                    var transactionIds = imports.Where(x => x.TransactionId != null).Select(x => x.TransactionId.Value).ToList();
                    var transactions = vfi.Transactions.Where(x => transactionIds.Contains(x.TransactionId)).ToList();
                    ids = periods.Where(x => x.EoI == (int)MyUtilities.Transaction.EoIEnum.Export).Select(x => x.EoIId.Value).ToList();
                    var exports = vfi.ExportWorkpieceMaterials.Where(x => ids.Contains(x.ExportId)).ToList();
                    foreach (var period in periods) {
                        var entity = new WorkpieceImportExportModel {
                            EoIId = period.EoIId.Value,
                            PeriodId = period.PeriodId,
                            Weight = period.Weight
                        };
                        if (period.EoI == (int)MyUtilities.Transaction.EoIEnum.Import) {
                            var import = imports.FirstOrDefault(iwm => iwm.ImportId == period.EoIId.Value);
                            entity.Date = import.ImportDate.Value;
                            entity.ImportExport = "Nhập";
                            if (import.TransactionId == null && import.ImportSx1Id == null) {
                                entity.ImportExport += " thêm";
                            }
                            else {
                                entity.TransactionId = import.TransactionId.Value;
                                var transaction = transactions.FirstOrDefault(x => x.TransactionId == import.TransactionId.Value);
                                if (transaction != null) {
                                    entity.TransactionCode = transaction.TransactionCode;
                                    if (transaction.WarehouseIssueId != null)
                                        entity.WarehouseName = transaction.Warehouse.WarehouseName;
                                }
                                if (import.ImportSx1Id != null) {
                                    entity.WarehouseName = "SX 1";
                                }
                            }
                        }
                        else if (period.EoI == (int)MyUtilities.Transaction.EoIEnum.Export) {
                            var export = exports.FirstOrDefault(ewm => ewm.ExportId == period.EoIId.Value);
                            entity.Date = export.ExportDate.Value;
                            entity.ImportExport = "Xuất";
                            if (period.IsDestroy)
                                entity.ImportExport += " hủy";
                            else entity.ImportExport += " bán";
                        }
                        model.Add(entity);
                    }

                }
            }
            catch (Exception ex) {

                ModelState.AddModelError("SelectProductionImportWorkpiece", ex.Message);
            }
            return View(new GridModel(model.OrderByDescending(m => m.Date).ThenBy(m => m.ImportExport)));
        }

        [GridAction]
        public ActionResult SelectProductionImportWorkpieceDetail(string identityCode, int type, string fromDate, string toDate) {
            var model = new List<WorkpieceMaterialDetailModel>();
            var ci = new CultureInfo("vi-VN");
            var from = string.IsNullOrWhiteSpace(fromDate)
                              ? DateTime.Today
                              : Convert.ToDateTime(fromDate, ci);
            var to = string.IsNullOrWhiteSpace(toDate)
                              ? DateTime.Today
                              : Convert.ToDateTime(toDate, ci);
            try {
                using (var vfi = new tammaContext()) {
                    var importSx1Details =
                        vfi.ImportFormSX1Detail.Where(
                            id => id.ImportFormSX1.MaterialUseDate >= from &&
                                  id.ImportFormSX1.MaterialUseDate <= to &&
                                  id.MaterialInventory.Material.MaterialType.IdentityCode.Equals(identityCode))
                           .ToList();

                    foreach (var importSx1Detail in importSx1Details) {
                        var entity =
                            model.FirstOrDefault(
                                m =>
                                m.ProductId == importSx1Detail.ProductId &&
                                m.MachineId == importSx1Detail.MachineId &&
                                m.MaterialInvId == importSx1Detail.MaterialInvId);
                        if (entity == null) {
                            entity = new WorkpieceMaterialDetailModel {
                                MaterialInvId = importSx1Detail.MaterialInvId.Value,
                                MaterialCode = importSx1Detail.MaterialInventory.Material.MaterialCode,
                                LotNumber = importSx1Detail.MaterialInventory.LotNumber,
                                VendorCode = importSx1Detail.MaterialInventory.Vendor.VendorCode,
                                MachineId = importSx1Detail.MachineId.Value,
                                MachineName = importSx1Detail.Machine1.MachineName,
                                ProductId = importSx1Detail.ProductId,
                                ProductCode = importSx1Detail.Product.ProductCode,
                                MaterialUse = (importSx1Detail.MaterialUse1 + importSx1Detail.MaterialUse2),
                                MaterialWeight = importSx1Detail.MaterialInventory.UnitWeight,
                                Production =
                                    (importSx1Detail.Number1 + importSx1Detail.Number2 + importSx1Detail.Processing1 +
                                     importSx1Detail.Processing2),
                                ProductWeight = importSx1Detail.ProductWeight,
                            };

                            if (type == 3) {
                                entity.Production =
                                    (importSx1Detail.DefectProduct1 + importSx1Detail.DefectProduct2);
                                entity.Workpiece = entity.Production * entity.ProductWeight / 1000;
                            }
                            else {

                                entity.Workpiece = (entity.MaterialUse * entity.MaterialWeight) -
                                                   ((importSx1Detail.Number1 + importSx1Detail.Number2 +
                                                     importSx1Detail.Processing1 + importSx1Detail.Processing2 +
                                                     importSx1Detail.DefectProduct1 + importSx1Detail.DefectProduct2)
                                                    * entity.ProductWeight / 1000);
                            }
                            if (entity.Production == 0)
                                continue;
                            model.Add(entity);
                        }
                        else {
                            entity.MaterialUse += (importSx1Detail.MaterialUse1 + importSx1Detail.MaterialUse2);
                            if (type == 3) {
                                entity.Production +=
                                    (importSx1Detail.DefectProduct1 + importSx1Detail.DefectProduct2);
                                entity.Workpiece = entity.Production * entity.ProductWeight / 1000;
                            }
                            else {

                                entity.Production +=
                                   (importSx1Detail.Number1 + importSx1Detail.Number2 + importSx1Detail.Processing1 +
                                         importSx1Detail.Processing2);
                                entity.Workpiece = (entity.MaterialUse * entity.MaterialWeight) -
                                                   ((importSx1Detail.Number1 + importSx1Detail.Number2 +
                                                     importSx1Detail.Processing1 + importSx1Detail.Processing2 +
                                                     importSx1Detail.DefectProduct1 + importSx1Detail.DefectProduct2)
                                                    * entity.ProductWeight / 1000);
                            }
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectWorkpieceDetail", ex.Message);
            }
            return
                View(
                    new GridModel(
                        model.OrderBy(m => m.MachineName).ThenBy(m => m.MaterialCode).ThenBy(m => m.ProductCode)));
        }


        [GridAction]
        public ActionResult SelectToolYearlyReport(string toolName, int toolType, int year, int exportType) {
            var model = new List<MaterialYearlyReportModel>();
            if (year == 0)
                return View(new GridModel(model));
            try {
                using (var vfi = new tammaContext()) {
                    var tools = (from t in vfi.Tools
                                 where t.Active &&
                                       (toolType == 0 || t.MaterialTypeId == toolType)
                                 select new {
                                     t.ToolId,
                                     t.ToolCode,
                                     t.ToolFullCode,
                                     t.ToolDesignNo,
                                     t.ToolMaterial,
                                     t.ToolProduction,
                                     t.ToolTypeId,
                                     t.MaterialType.MaterialTypeName
                                 }).ToList();
                    if (!string.IsNullOrWhiteSpace(toolName)) {
                        tools = tools.Where(t => t.ToolFullCode.Contains(toolName)).ToList();
                    }
                    var toolIds = tools.Select(t => t.ToolId);
                    var imports = (from tip in vfi.ToolInventoryPeriods
                                   where toolIds.Contains(tip.ToolId)
                                         && tip.PeriodDate.Year == year &&
                                         tip.LastQuantity > tip.EarlyQuantity
                                   select new {
                                       tip.ToolId,
                                       IsPurchase = tip.TransactionFpt.PoId != null,
                                       tip.PeriodDate.Month,
                                       tip.Quantity,
                                       tip.TransactionFpt.Type,
                                       IsInternal = tip.TransactionFpt.IsInternal ?? false
                                   }).ToList();
                    var exports = (from tip in vfi.ToolInventoryPeriods
                                   where toolIds.Contains(tip.ToolId)
                                         && tip.PeriodDate.Year == year &&
                                         tip.LastQuantity < tip.EarlyQuantity
                                   select new {
                                       tip.ToolId,
                                       IsPurchase = tip.TransactionFpt.PoId != null,
                                       tip.PeriodDate.Month,
                                       tip.Quantity,
                                       tip.TransactionFpt.Type,
                                       IsInternal = tip.TransactionFpt.IsInternal ?? false
                                   }).ToList();
                    var toolInvs = (from ti in vfi.ToolInventories
                                    where toolIds.Contains(ti.ToolId) &&
                                          ti.TotalQuantity > 0
                                    select ti).ToList();
                    //var exports = (from ed in vfi.ExportToolDetails
                    //               where ed.ExportTool.ExportDate.Value.Year == year &&
                    //                     toolIds.Contains(ed.ToolInventory.ToolId) &&
                    //                     ed.ExportTool.TransactionFpt.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                    //                     (exportType == 0 || ed.ExportTool.TransactionFpt.Type == exportType)
                    //               select new {
                    //                   ed.ToolInventory.ToolId,
                    //                   ed.ExportTool.ExportDate.Value.Month,
                    //                   ed.ExportTool.TransactionFpt.Type,
                    //                   ed.Quantity,
                    //                   IsInternal = ed.TransactionFptDetail.IsInternal ?? false
                    //               }).ToList();
                    var todayMonth = DateTime.Now.Month;
                    var threeMonthBefore = DateTime.Now.AddMonths(-3).Month;
                    foreach (var tool in tools) {
                        var entity = new MaterialYearlyReportModel {
                            MaterialId = tool.ToolId,
                            MaterialName = tool.ToolCode,
                            //MaterialCode = tool.ToolFullCode,
                            MaterialCode = MyUtilities.Tool.GetFullToolDesign(tool.ToolDesignNo, tool.ToolMaterial, tool.ToolProduction),
                            MaterialTypeId = tool.ToolTypeId,
                            MaterialTypeName = tool.MaterialTypeName,
                            Months = new List<MaterialMonthlyReportModel>()
                        };
                        var importsById = imports.Where(p => p.ToolId == entity.MaterialId).ToList();
                        var exportsById = exports.Where(p => p.ToolId == entity.MaterialId).ToList();
                        var toolInvsById = toolInvs.Where(ti => ti.ToolId == entity.MaterialId).ToList();
                        entity.TotalInv = toolInvsById.Sum(ti => ti.TotalQuantity);
                        //var emDestroyById = emDestroyInMonth.Where(em => em.MaterialId == entity.MaterialId).ToList();
                        if (!importsById.Any() && !exportsById.Any()) continue;
                        var months = new List<MaterialMonthlyReportModel>();
                        for (int month = 1; month <= 12; month++) {
                            var byMonth = new MaterialMonthlyReportModel {
                                MaterialId = entity.MaterialId,
                                Import = 0,
                                ImportMore = 0,
                                ExportUse = 0,
                                ExportDestroy = 0,
                                Export3MonthUsed = 0,
                            };
                            months.Add(byMonth);

                            var importsInMonth = importsById.Where(p => p.Month == month).ToList();
                            if (importsInMonth.Any()) {
                                var periodsByParam = importsInMonth.Where(p => p.IsPurchase).ToList();
                                byMonth.Import = Math.Round(periodsByParam.Sum(period => period.Quantity), 1);
                                periodsByParam = importsInMonth.Where(p => !p.IsPurchase).ToList();
                                byMonth.ImportMore = Math.Round(periodsByParam.Sum(period => period.Quantity), 1);
                            }

                            var exportsInMonth = exports.Where(p => p.ToolId == entity.MaterialId && p.Month == month).ToList();
                            if (exportsInMonth.Any()) {
                                var exportsParam = exportsInMonth.Where(p => p.Type != (int)MyUtilities.Tool.ExportType.Destroy).ToList();
                                byMonth.ExportUse = Math.Round(exportsParam.Sum(e => e.Quantity), 1);

                                exportsParam = exportsInMonth.Where(p => p.Type == (int)MyUtilities.Tool.ExportType.Destroy).ToList();
                                byMonth.ExportDestroy = Math.Round(exportsParam.Sum(e => e.Quantity), 1);
                            }

                            if (month < todayMonth && month >= threeMonthBefore) {
                                if (exportsInMonth.Any()) {
                                    var exportsParam = exportsInMonth.Where(p => p.Type != (int)MyUtilities.Tool.ExportType.Destroy).ToList();
                                    byMonth.Export3MonthUsed = Math.Round(exportsParam.Sum(e => e.Quantity), 1);
                                }
                            }
                        }
                        var total = new MaterialMonthlyReportModel {
                            Import = months.Sum(m => m.Import),
                            ImportMore = months.Sum(m => m.ImportMore),
                            ExportUse = months.Sum(m => m.ExportUse),
                            ExportDestroy = months.Sum(m => m.ExportDestroy),
                            Export3MonthUsed = months.Sum(t => t.Export3MonthUsed),
                        };
                        if (total.Import + total.ImportMore + total.ExportUse + total.ExportDestroy > 0) {
                            entity.Months.Add(total);
                            entity.Months.AddRange(months);
                            entity.TotalExport3MonthUsed = total.Export3MonthUsed;
                            model.Add(entity);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectToolYearlyReport", ex.Message);
            }
            return View(new GridModel(model));
        }


