        #region product
        [GridAction]
        public ActionResult SelectAccountingReport(int customerId, string productCode, string fromDate, string toDate) {
            var model = new List<AccountingReportModel>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                var ci = new CultureInfo("vi-VN");
                var tDate = Convert.ToDateTime(toDate, ci);
                var fDate = Convert.ToDateTime(fromDate, ci);
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var products = from p in vfi.Products
                                   where p.Active && (customerId == 0 || p.CustomerId == customerId)
                                   orderby p.Customer.CustomerCode, p.ProductCode
                                   select new {
                                       p.ProductId,
                                       p.ProductCode,
                                       p.DesignNo,
                                       p.Customer.CustomerCode,
                                       p.MaterialId,
                                       p.Material
                                   };
                    if (!string.IsNullOrWhiteSpace(productCode)) {
                        products = products.Where(p => p.ProductCode.Contains(productCode));
                    }
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var sumWarehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();


                    var importProduction = (from sx in vfi.ImportFormSX1Detail
                                            where sx.ImportFormSX1.ImportDate >= fDate &&
                                                  sx.ImportFormSX1.ImportDate <= tDate &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                      .Transaction.Status ==
                                                  (byte)MyUtilities.Transaction.Status.Approved &&
                                                  productIds.Contains(sx.ProductId)
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                            select new {
                                                sx.ProductId,
                                                MaterialId = sx.MaterialInventory.MaterialId,
                                                MaterialCode = sx.MaterialInventory.Material.MaterialCode,
                                                MaterialInvId = sx.MaterialInvId.Value,
                                                sx.MaterialInventory.UnitPrice,
                                                MaterialWeight = sx.MaterialInventory.UnitWeight,
                                                Quantity = (sx.Number1 + sx.Number2) + (sx.Processing1 + sx.Processing2),
                                                MaterialUse = (sx.MaterialUse1 + sx.MaterialUse2),
                                            }).ToList();
                    var periods = from pip in vfi.ProductInventoryPeriods
                                  where pip.PeriodDate <= tDate &&
                                        productIds.Contains(pip.ProductId)
                                  select new {
                                      pip.ProductId,
                                      pip.PeriodDate,
                                      pip.WarehouseId,
                                      pip.EarlyPeriodQuantity,
                                      pip.LastPeriodQuantity,
                                      pip.Transaction,
                                      pip.Quantity,
                                      pip.ProductInventory.MaterialInvId,
                                      pip.Transaction.WarehouseIssueId,
                                      pip.Transaction.WarehouseReceiptId
                                  };
                    var periodsInv = periods.Where(pip => sumWarehouses.Contains(pip.WarehouseId));
                    var periodsInMonth = periods.Where(pip => pip.PeriodDate >= fDate).ToList();
                    var periodsMore = from pip in periodsInMonth
                                      where pip.Transaction.WarehouseIssueId == null &&
                                            sumWarehouses.Contains(pip.WarehouseReceiptId.Value)
                                      select pip;
                    var periodsDefect = (from pip in periodsInMonth
                                         where pip.WarehouseId == MyUtilities.Warehouse.Defect &&
                                               pip.WarehouseIssueId != null &&
                                               pip.WarehouseReceiptId == MyUtilities.Warehouse.Defect
                                         select pip).ToList();
                    var periodsDestroy = (from pip in periodsInMonth
                                          where pip.WarehouseId == MyUtilities.Warehouse.Destroy &&
                                                sumWarehouses.Contains(pip.WarehouseIssueId.Value) &&
                                                pip.WarehouseReceiptId == MyUtilities.Warehouse.Destroy
                                          select pip).ToList();
                    var periodsFinish = (from pip in periodsInMonth
                                         where pip.WarehouseIssueId == MyUtilities.Warehouse.Packing &&
                                               pip.WarehouseReceiptId == MyUtilities.Warehouse.Finish &&
                                               pip.WarehouseId == MyUtilities.Warehouse.Finish
                                         select pip).ToList();
                    var periodsSales = (from pip in periodsInMonth
                                        where pip.WarehouseId == MyUtilities.Warehouse.Business &&
                                              pip.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                              pip.WarehouseReceiptId == MyUtilities.Warehouse.Business
                                        select pip).ToList();
                    var taxInvoiceProducts = from tip in vfi.TaxInvoiceProducts
                                             where productIds.Contains(tip.ProductId) &&
                                                   tip.TaxInvoice.SetupDate >= fDate &&
                                                   tip.TaxInvoice.SetupDate <= tDate &&
                                                   tip.TaxInvoice.Status != (byte)MyUtilities.Sales.Status.Cancel
                                             select tip;

                    foreach (var product in products) {
                        var entity = new AccountingReportModel() {
                            CustomerCode = product.CustomerCode,
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            ProductCustomerCode = product.DesignNo,
                        };
                        var materialInvIds = new List<int>();
                        var productionsById = importProduction.Where(id => id.ProductId == entity.ProductId);
                        if (productionsById.Any()) {
                            entity.ProductionQuantity = productionsById.Sum(id => id.Quantity);
                            entity.MaterialUseQuantity = productionsById.Sum(x => x.MaterialUse);
                            entity.MaterialUseWeight = productionsById.Sum(x => x.MaterialUse * x.MaterialWeight);
                            materialInvIds = productionsById.Select(id => id.MaterialInvId).Distinct().ToList();
                            foreach (var materialInvId in materialInvIds) {
                                var first = productionsById.FirstOrDefault(id => id.MaterialInvId == materialInvId);
                                if (first == null) continue;
                                var detail = new AccountingReportDetail() {
                                    MaterialInvId = materialInvId,
                                    MaterialCost = first.UnitPrice,
                                };
                                var dElse = entity.Details.FirstOrDefault(d => d.MaterialId == first.MaterialId);
                                if (dElse == null) {
                                    detail.MaterialId = first.MaterialId;
                                    detail.MaterialProductionCode = first.MaterialCode;
                                }
                                entity.Details.Add(detail);
                            }
                        }
                        else {
                            if (product.MaterialId != null) {
                                var detail = new AccountingReportDetail() {
                                    MaterialId = product.MaterialId.Value,
                                    MaterialProductionCode = product.Material.MaterialCode
                                };
                                var lastMaterialInv =
                                    vfi.MaterialInventories.Where(mi => mi.MaterialId == detail.MaterialId)
                                        .OrderByDescending(mi => mi.ImportDate)
                                        .FirstOrDefault();
                                if (lastMaterialInv != null) {
                                    detail.MaterialInvId = lastMaterialInv.MaterialInventoryId;
                                    detail.MaterialCost = lastMaterialInv.UnitPrice;
                                }
                                entity.Details.Add(detail);
                            }
                        }
                        var taxInvoiceProductsById = taxInvoiceProducts.Where(tip => tip.ProductId == entity.ProductId).ToList();
                        entity.TaxInvoiceQuantity = taxInvoiceProductsById.Sum(id => id.Quantity);
                        var periodsById = periodsInMonth.Where(p => p.ProductId == entity.ProductId).ToList();
                        if (periodsById.Any()) {
                            var materialInvIds2 =
                                periodsById.Where(pip => pip.MaterialInvId != null &&
                                                         !materialInvIds.Contains(pip.MaterialInvId.Value))
                                    .Select(pip => pip.MaterialInvId.Value)
                                    .Distinct()
                                    .ToList();
                            foreach (var materialInvId in materialInvIds2) {
                                var first = (from mi in vfi.MaterialInventories
                                             where mi.MaterialInventoryId == materialInvId
                                             select new {
                                                 mi.UnitPrice,
                                                 mi.MaterialId,
                                                 mi.Material.MaterialCode
                                             }).FirstOrDefault();
                                if (first == null) continue;
                                var detail = new AccountingReportDetail() {
                                    MaterialInvId = materialInvId,
                                    MaterialCost = first.UnitPrice,
                                };
                                var dElse = entity.Details.FirstOrDefault(d => d.MaterialId == first.MaterialId);
                                if (dElse == null) {
                                    detail.MaterialId = first.MaterialId;
                                    detail.MaterialProductionCode = first.MaterialCode;
                                }
                                entity.Details.Add(detail);
                            }
                            periodsById = periodsInv.Where(p => p.ProductId == entity.ProductId).ToList();
                            entity.ProductInv = periodsById.Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);

                            periodsById = periodsMore.Where(p => p.ProductId == entity.ProductId).ToList();
                            entity.ImportQuantity = periodsById.Sum(p => p.Quantity);

                            periodsById = periodsDefect.Where(p => p.ProductId == entity.ProductId).ToList();
                            entity.DefectQuantity = periodsById.Sum(p => p.Quantity);

                            periodsById = periodsDestroy.Where(p => p.ProductId == entity.ProductId).ToList();
                            entity.DestroyQuantity = periodsById.Sum(p => p.Quantity);

                            periodsById = periodsFinish.Where(p => p.ProductId == entity.ProductId).ToList();
                            entity.ImportFinish = periodsById.Sum(p => p.Quantity);

                            periodsById = periodsSales.Where(p => p.ProductId == entity.ProductId).ToList();
                            entity.ExportSales = periodsById.Sum(p => p.Quantity);
                            model.Add(entity);
                        }
                        else if (entity.ProductionQuantity + entity.TaxInvoiceQuantity > 0)
                            model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectAccountingReport", ex.Message);
            }

            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult SelectExportByProductId(int productId, int month, int year) {
            var model = new List<ExportFormTP_KDModel>();
            try {
                var monthly = new DateTime(year, month, 1).AddMonths(1).AddSeconds(-1);
                var lastMonth = new DateTime(year, month, 1).AddSeconds(-1);
                using (var vfi = new tammaContext()) {
                    var exportDetails = from ed in vfi.ExportFormTP_KDDetail
                                        where ed.ProductId == productId &&
                                              ed.ExportFormTP_KD.DateCreate > lastMonth &&
                                              ed.ExportFormTP_KD.DateCreate < monthly
                                        select new {
                                            ed.ExportFormTP_KD.TransactionCode,
                                            ed.ExportFormTP_KD.CarNumber,
                                            ed.ExportFormTP_KD.CompanyTransporter,
                                            ed.ExportFormTP_KD.Customer.CustomerCode,
                                            ed.ExportFormTP_KD.DateCreate,
                                            ed.ExportFormTP_KD.Transporter,
                                            ed.ExportFormTP_KD.ModifiedDate,
                                            ed.ExportFormTP_KD.ModifiedUser,
                                            ed.Note,
                                            ed.Quality,
                                        };
                    if (!exportDetails.Any())
                        return View(new GridModel(model));
                    foreach (var exportDetail in exportDetails) {
                        var transaction =
                            vfi.Transactions.FirstOrDefault(t => t.TransactionCode.Equals(exportDetail.TransactionCode));
                        if (transaction == null || transaction.Status != (byte)MyUtilities.Transaction.Status.Approved)
                            continue;
                        var entity = new ExportFormTP_KDModel {
                            CustomerCode = exportDetail.CustomerCode,
                            CarNumber = exportDetail.CarNumber,
                            CompanyTransporter = exportDetail.CompanyTransporter,
                            DateCreate = exportDetail.DateCreate.Value,
                            ModifiedDate = exportDetail.ModifiedDate.Value,
                            ModifiedUser = exportDetail.ModifiedUser,
                            TotalQuality = exportDetail.Quality,
                            Transporter = exportDetail.Transporter,
                            TransactionCode = exportDetail.TransactionCode,
                        };
                        model.Add(entity);
                    }


                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<ImportExportProductionModel> GetFinishedProductionReport(
            int customerId, string productName,
            string fromDate, string toDate,
            int type, int calculateMode) {
            var model = new List<ImportExportProductionModel>();
            var warehouseId = MyUtilities.Warehouse.Finish;
            using (var vfi = new tammaContext()) {
                var fDate = MyUtilities.Function.ParseDate(fromDate);
                var tDate = MyUtilities.Function.ParseLastDateTime(toDate);
                var products = (from pi in vfi.ProductInventories
                                where
                                    pi.Warehouse.IsFinish == true &&
                                    (customerId == 0 || pi.Product.CustomerId == customerId)
                                select new {
                                    pi.ProductId,
                                    pi.Product.ProductCode,
                                    pi.Product.ProductName,
                                    pi.Product.DesignNo,
                                    pi.Product.QcWeight,
                                    pi.Product.CustomerId,
                                    pi.Product.Customer.CustomerCode,
                                    UnitPrice = pi.Product.UnitPrice ?? 0,
                                }).Distinct().ToList();
                if (!string.IsNullOrWhiteSpace(productName)) {
                    products = products.Where(p => p.ProductCode.Contains(productName)).ToList();
                }
                var productIds = products.Select(p => p.ProductId).Distinct().ToList();

                var productInvPeriods = (from pip in vfi.ProductInventoryPeriods
                                         where
                                             pip.PeriodDate <= tDate &&
                                             //pip.WarehouseId == warehouseId &&
                                             pip.Warehouse.IsFinish == true &&
                                             productIds.Contains(pip.ProductId)
                                         select new {
                                             pip.ProductId,
                                             Quantity = pip.Quantity,
                                             LastPeriodQuantity = pip.LastPeriodQuantity,
                                             EarlyPeriodQuantity = pip.EarlyPeriodQuantity,
                                             PeriodQuantity = pip.LastPeriodQuantity - pip.EarlyPeriodQuantity,
                                             pip.PeriodDate,
                                             pip.WarehouseId,
                                             pip.Transaction,
                                             pip.Transaction.WarehouseIssueId,
                                             pip.Transaction.WarehouseReceiptId,
                                             IsInternal = pip.Transaction.IsInternal ?? false
                                         }).ToList();

                if (calculateMode == (int)MyUtilities.Report.Calculate.InPeriod) {
                    var inPeriods = productInvPeriods.Where(x => x.PeriodDate >= fDate).ToList();
                    if (!inPeriods.Any()) {
                        return model;
                    }
                    productIds = inPeriods.Select(x => x.ProductId).Distinct().ToList();
                    products = products.Where(x => productIds.Contains(x.ProductId)).ToList();
                }

                var importPeriodInMonths =
                    productInvPeriods.Where(pip => pip.WarehouseReceiptId == warehouseId &&
                                                    pip.PeriodDate >= fDate)
                                     .ToList();
                var exportPeriodInMonths =
                    productInvPeriods.Where(pip => pip.WarehouseIssueId == warehouseId &&
                                                    pip.PeriodDate >= fDate)
                                     .ToList();

                var processingIds = MyUtilities.Warehouse.GetWarehouseId_ReProcessing();

                var customers = from c in vfi.Customers
                                where (customerId == 0 || c.CustomerId == customerId)
                                orderby c.CustomerCode
                                select new {
                                    c.CustomerId,
                                    c.CustomerName,
                                    c.CustomerCode
                                };
                var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                var inventoryRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseInventoryPriceRate);
                foreach (var customer in customers) {
                    var entity = new ImportExportProductionModel {
                        CustomerCode = customer.CustomerCode,
                        CustomerName = customer.CustomerName,
                        ReportDate = tDate,
                        Details = new List<ImportExportProductionDetailModel>(),
                    };
                    var list = new List<ImportExportProductionDetailModel>();
                    var productsById = products.Where(p => p.CustomerId == customer.CustomerId)
                        .OrderBy(p => p.ProductCode)
                        .ToList();
                    foreach (var product in productsById) {
                        var detail = new ImportExportProductionDetailModel {
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            ProductName = product.ProductName,
                            ProductCustomerName = product.DesignNo,
                            ProductCustomerCode = customer.CustomerCode,
                            ProductPrice = 0,
                            ImportQuantity = 0,
                            ExportQuantity = 0,
                            EarlyQuantity = 0,
                            LastQuantity = 0,
                            Month = tDate.Month,
                            Year = tDate.Year,
                            //Show = false,
                        };

                        detail.EarlyQuantity = productInvPeriods.Where(
                            pip => pip.PeriodDate < fDate && pip.ProductId == detail.ProductId)
                                                                 .Sum(pip => pip.PeriodQuantity);
                        detail.LastQuantity = productInvPeriods.Where(
                            pip => pip.ProductId == detail.ProductId)
                                                                .Sum(pip => pip.PeriodQuantity);
                        //

                        detail.ImportQuantity = importPeriodInMonths
                                             .Where(pip => pip.ProductId == detail.ProductId &&
                                                           pip.WarehouseIssueId == MyUtilities.Warehouse.Packing)
                                             .Sum(pip => pip.Quantity);
                        detail.ImportReturn = importPeriodInMonths
                                             .Where(pip => pip.ProductId == detail.ProductId &&
                                                           pip.WarehouseIssueId == MyUtilities.Warehouse.Business)
                                             .Sum(pip => pip.Quantity);
                        detail.ImportMore = importPeriodInMonths
                                            .Where(pip => pip.ProductId == detail.ProductId &&
                                                         !pip.IsInternal &&
                                                          (pip.WarehouseIssueId == null ||
                                                          pip.WarehouseIssueId == MyUtilities.Warehouse.Tranfer))
                                            .Sum(pip => pip.Quantity);
                        detail.ImportInternal = importPeriodInMonths
                                            .Where(pip => pip.ProductId == detail.ProductId &&
                                                          pip.IsInternal &&
                                                          pip.WarehouseIssueId == null)
                                            .Sum(pip => pip.Quantity);

                        //detail.DiffImport = importPeriodInMonths
                        //     .Where(x => x.ProductId == detail.ProductId &&
                        //                 !x.IsInternal && x.WarehouseIssueId != null && // nhap them + NB
                        //                 x.WarehouseIssueId != MyUtilities.Warehouse.Packing && // nhap dong goi
                        //                 x.WarehouseIssueId != MyUtilities.Warehouse.Business && // nhap tra hang
                        //                 x.WarehouseIssueId != MyUtilities.Warehouse.Tranfer) // nhap trung chuyen
                        //     .Sum(pip => pip.Quantity);
                        detail.TotalImport = importPeriodInMonths.Where(x => x.ProductId == product.ProductId)
                                                                .Sum(x => x.Quantity);
                        //detail.DiffImport -= detail.TotalImport;
                        //
                        detail.ExportQuantity = exportPeriodInMonths
                             .Where(pip => pip.ProductId == detail.ProductId &&
                                           pip.WarehouseReceiptId == MyUtilities.Warehouse.Business)
                             .Sum(pip => pip.Quantity);
                        detail.ExportDestroy = exportPeriodInMonths
                            .Where(pip => pip.ProductId == detail.ProductId &&
                                            pip.WarehouseReceiptId != null &&
                                            !pip.IsInternal &&
                                          (processingIds.Contains(pip.WarehouseReceiptId.Value) ||
                                           pip.WarehouseReceiptId == MyUtilities.Warehouse.Tranfer ||
                                           pip.WarehouseReceiptId == MyUtilities.Warehouse.Destroy ||
                                           pip.WarehouseReceiptId == MyUtilities.Warehouse.Defect))
                            .Sum(pip => pip.Quantity);
                        detail.ExportInternal = exportPeriodInMonths
                            .Where(pip => pip.ProductId == detail.ProductId &&
                                            pip.WarehouseReceiptId == null &&
                                            pip.IsInternal)
                            .Sum(pip => pip.Quantity);

                        //detail.DiffExport = exportPeriodInMonths
                        //     .Where(x => x.ProductId == detail.ProductId &&
                        //                 !x.IsInternal && x.WarehouseReceiptId != null &&// xuat nb
                        //                 x.WarehouseReceiptId != MyUtilities.Warehouse.Tranfer && // xuat trung chuyen
                        //                 x.WarehouseReceiptId != MyUtilities.Warehouse.Destroy && // xuat huy
                        //                 x.WarehouseReceiptId != MyUtilities.Warehouse.Defect &&// xuat phe pham
                        //                 x.WarehouseReceiptId != MyUtilities.Warehouse.Business  // xuat thanh pham
                        //                 )
                        //     .Sum(pip => pip.Quantity);
                        //detail.DiffExport -= detail.TotalExport;

                        detail.TotalExport = exportPeriodInMonths.Where(x => x.ProductId == product.ProductId)
                                                                .Sum(x => x.Quantity);
                        detail.ProductPrice = MyUtilities.Product.ProductVndPrice(product.UnitPrice, inventoryRate, exchangeRate);

                        list.Add(detail);
                    }
                    if (list.Any()) {
                        entity.Details.AddRange(list.Where(l => l.Show).OrderBy(l => l.ProductCode));
                        model.Add(entity);
                    }
                }
            }

            return model;
        }

        [GridAction]
        public ActionResult SelectFinishedProductionReport(
            int type, int customerId, string productName,
            string fromDate, string toDate) {
            var model = new List<ImportExportProductionDetailModel>();
            if (string.IsNullOrWhiteSpace(toDate))
                return View(new GridModel(model));
            try {
                var customers = GetFinishedProductionReport(customerId, productName, fromDate, toDate, type, type);
                foreach (var customer in customers) {
                    model.AddRange(customer.Details);
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectIEProduction", ex.Message);
            }
            return View(new GridModel(model));
        }

        public ActionResult PrintExportProductionInMonth(int type, int month, int year) {

            var model = new List<ImportExportProductionDetailModel>();
            try {
                using (var vfi = new tammaContext()) {
                    var exports = from pip in vfi.ProductInventoryPeriods
                                  where pip.WarehouseId == MyUtilities.Warehouse.Finish &&
                                        pip.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                        pip.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Business &&
                                        pip.PeriodDate.Month == month && pip.PeriodDate.Year == year
                                  select pip;
                    var productIds = exports.Select(e => e.ProductId).Distinct().ToList();
                    foreach (var productId in productIds) {
                        var product = vfi.Products.FirstOrDefault(p => p.ProductId == productId);
                        var entity = new ImportExportProductionDetailModel {
                            ProductCustomerCode = product.Customer.CustomerCode,
                            ProductCode = product.ProductCode,
                            ProductId = productId,
                            Month = month,
                            Year = year,
                        };
                        var exportById = exports.Where(e => e.ProductId == entity.ProductId).ToList();
                        foreach (var period in exportById) {
                            entity.ExportInMonth[period.PeriodDate.Day - 1] += period.Quantity;
                        }
                        model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintFinishedProducts", ex.Message);
            }
            return PartialView("PageExportProductionInMonthReport",
                               model.OrderBy(m => m.ProductCustomerCode).ThenBy(m => m.ProductCode).ToList());
        }


        public ActionResult PrintFinishedProductionReport(
            int customerId, string productCode, int type,
            string fromDate, string toDate) {
            var model = new List<ImportExportProductionModel>();
            try {
                model = GetFinishedProductionReport(customerId, productCode,
                    fromDate, toDate,
                    type, (int)MyUtilities.Report.Calculate.All);
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintFinishedProducts", ex.Message);
            }
            return PartialView("PageFinishedProductionReport", model);
        }

        [GridAction]
        public ActionResult SelectProductStatusReport(int customerId, string productCode) {
            var model = new List<ProductStatusModel>();
            if (customerId < 0)
                return View(new GridModel(model));
            try {
                using (var vfi = new tammaContext()) {
                    var products = (from p in vfi.Products
                                    where p.Active &&
                                    (customerId == 0 || p.CustomerId == customerId)
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        p.ProductId,
                                        p.ProductCode,
                                        p.MaterialId,
                                        p.Material,
                                        ProductionMaterials = p.ProductionMaterials.Where(x => x.Active),
                                        UnitPrice = p.UnitPrice ?? 0,
                                        p.ModifiedDate
                                    }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode)) {
                        products = products.Where(p => p.ProductCode.Contains(productCode)).ToList();
                    }
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity2();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where productIds.Contains(pi.ProductId) &&
                                       warehouses.Contains(pi.WarehouseId) &&
                                       pi.TotalQty > 0
                                       select new {
                                           pi.WarehouseId,
                                           pi.ProductId,
                                           pi.TotalQty
                                       }).ToList();
                    //var exports = (from ex in vfi.ExportFormTP_KDDetail
                    //               where productIds.Contains(ex.ProductId.Value)
                    //               group ex by new { ex.ProductId }
                    //                   into exg
                    //                   select new {
                    //                       ProductId = exg.Key.ProductId.Value,
                    //                       Date = exg.Max(gd => gd.ExportFormTP_KD.DateTransporter.Value),
                    //                   }).ToList();
                    var exports = (from x in vfi.InvoiceDetails
                                   where productIds.Contains(x.ProductId.Value) &&
                                        x.Invoice.Status != (byte)MyUtilities.Transaction.Status.Cancel
                                   group x by new { x.ProductId.Value }
                                       into exg
                                       select new {
                                           ProductId = exg.Key.Value,
                                           Date = exg.Max(gd => gd.Invoice.ShipmentDate.Value),
                                       }).ToList();
                    var periods = (from pip in vfi.ProductInventoryPeriods
                                   where productIds.Contains(pip.ProductId)
                                   group pip by new { pip.ProductId }
                                       into pipg
                                       select new {
                                           ProductId = pipg.Key.ProductId,
                                           Date = pipg.Max(gd => gd.PeriodDate),
                                       }).ToList();

                    var finishPeriods = (from pip in vfi.ProductInventoryPeriods
                                         where productIds.Contains(pip.ProductId)
                                         && pip.WarehouseId == MyUtilities.Warehouse.Finish
                                         group pip by new { pip.ProductId }
                                             into pipg
                                             select new {
                                                 ProductId = pipg.Key.ProductId,
                                                 Date = pipg.Max(gd => gd.PeriodDate),
                                             }).ToList();
                    var productions = (from sx in vfi.ImportFormSX1Detail
                                       where productIds.Contains(sx.ProductId) &&
                                             sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                       group sx by new { sx.ProductId }
                                           into sxg
                                           select new {
                                               ProductId = sxg.Key.ProductId,
                                               Date = sxg.Max(gd => gd.ImportFormSX1.ImportDate),
                                           }).ToList();
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    var inventoryRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseInventoryPriceRate);
                    foreach (var product in products) {
                        var entity = new ProductStatusModel {
                            CustomerId = product.CustomerId,
                            CustomerCode = product.CustomerCode,
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            UnitPrice = MyUtilities.Product.ProductVndPrice(product.UnitPrice, inventoryRate, exchangeRate),
                            ModifiedDate = product.ModifiedDate
                        };
                        if (product.MaterialId != null) {
                            entity.MaterialId = product.MaterialId.Value;
                            entity.MaterialCode = product.Material.MaterialCode;
                            entity.MaterialPrice = product.Material.UnitPrice;
                        }
                        if (product.ProductionMaterials.Any()) {
                            var productionMaterial = product.ProductionMaterials.OrderBy(x => x.Priority).FirstOrDefault();
                            entity.MaterialUnitWeight = productionMaterial.UnitWeightByMaterial;
                        }
                        var productInvsById = productInvs.Where(p => p.ProductId == entity.ProductId);
                        if (productInvsById.Any()) {
                            entity.TotalInv = productInvsById.Sum(pi => pi.TotalQty);
                        }
                        productInvsById = productInvsById.Where(p => p.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (productInvsById.Any()) {
                            entity.FinishInv = productInvsById.Sum(pi => pi.TotalQty);
                        }
                        var exportById = exports.FirstOrDefault(p => p.ProductId == entity.ProductId);
                        if (exportById != null) {
                            entity.LastExportDate = exportById.Date;
                        }
                        var periodById = periods.FirstOrDefault(p => p.ProductId == entity.ProductId);
                        if (periodById != null) {
                            entity.LastRotateDate = periodById.Date;
                        }
                        periodById = finishPeriods.FirstOrDefault(p => p.ProductId == entity.ProductId);
                        if (periodById != null) {
                            entity.LastFinishInvDate = periodById.Date;
                        }
                        var productionById = productions.FirstOrDefault(p => p.ProductId == entity.ProductId);
                        if (productionById != null) {
                            entity.LastProductionDate = productionById.Date;
                        }
                        model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductStatusReport", ex.Message);
            }
            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult SelectAllProductsReport(int type, int customerId, string productName,
            string fromDate, string toDate) {
            var model = new List<ImportExportProductionDetailModel>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                var list = GetAllProductImportExport(customerId, productName,
                    fromDate, toDate,
                    type, type);
                foreach (var l in list) {
                    model.AddRange(l.Details);
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectIEProduction", ex.Message);
            }
            return View(new GridModel(model));
        }

        public ActionResult PrintAllProductsReport(int customerId, int type, string fromDate, string toDate) {

            var model = new List<ImportExportProductionModel>();
            try {
                model = GetAllProductImportExport(customerId, "",
                    fromDate, toDate,
                    type, (byte)MyUtilities.Report.Calculate.All);
            }
            catch (Exception ex) {
                return Json(ex.Message);
            }
            return PartialView("PageAllProductsReport", model);
        }

        List<ImportExportProductionModel> GetAllProductImportExport(int customerId, string productCode,
            string fromDate, string toDate,
            int type, int caculateModel) {
            var model = new List<ImportExportProductionModel>();
            try {
                //var overWatch = System.Diagnostics.Stopwatch.StartNew();
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var fDate = MyUtilities.Function.ParseDate(fromDate);
                    var tDate = MyUtilities.Function.ParseLastDateTime(toDate);
                    var customers = (from c in vfi.Customers
                                     where c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                           && (customerId == 0 || c.CustomerId == customerId)
                                     orderby c.CustomerCode
                                     select new {
                                         c.CustomerId,
                                         c.CustomerCode,
                                         c.CustomerName,
                                         //Products = c.Products.Where(p => p.Active).ToList(),
                                     }).ToList();
                    var customerIds = customers.Select(c => c.CustomerId).ToList();
                    var products = (from p in vfi.Products
                                    where customerIds.Contains(p.CustomerId) &&
                                          p.ProductCode.Contains(productCode) &&
                                          p.Active
                                    orderby p.ProductCode
                                    select new {
                                        p.CustomerId,
                                        p.ProductId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        UnitPrice = p.UnitPrice ?? 0,
                                        p.Length,
                                        p.KnifeCut,
                                        ProductionMaterial = p.ProductionMaterials.FirstOrDefault(pm => pm.Active) != null
                                            ? p.ProductionMaterials.FirstOrDefault(pm => pm.Active).Material
                                            : null,
                                        MaterialType = p.ProductionMaterials.FirstOrDefault(pm => pm.Active) != null
                                            ? p.ProductionMaterials.FirstOrDefault(pm => pm.Active)
                                                .Material.MaterialType.IdentityCode
                                            : null,
                                    }).ToList();
                    var productIds = products.Select(p => p.ProductId).ToList();
                    //var watch = System.Diagnostics.Stopwatch.StartNew();
                    var allProductionPeriods = (from pip in vfi.ProductInventoryPeriods
                                                where pip.PeriodDate <= tDate && productIds.Contains(pip.ProductId)
                                                select new {
                                                    pip.ProductInventoryPeriodId,
                                                    pip.ProductId,
                                                    Quantity = pip.Quantity,
                                                    //PeriodQuantity = Math.Round(pip.LastPeriodQuantity - pip.EarlyPeriodQuantity),
                                                    LastPeriodQuantity = pip.LastPeriodQuantity,
                                                    EarlyPeriodQuantity = pip.EarlyPeriodQuantity,
                                                    pip.PeriodDate,
                                                    pip.WarehouseId,
                                                    //pip.Transaction,
                                                    pip.Transaction.WarehouseIssueId,
                                                    pip.Transaction.WarehouseReceiptId,
                                                    IsInternal = pip.Transaction.IsInternal ?? false,
                                                    IsPurchase = pip.Transaction.PoId != null && pip.Transaction.PoId > 0
                                                }).ToList();
                    //watch.Stop();
                    //MyUtilities.Function.SaveLog("allProductionPeriods", watch.ElapsedMilliseconds + " ms");
                    //return model;
                    if (caculateModel == (int)MyUtilities.Report.Calculate.InPeriod) {
                        var onPeriods = allProductionPeriods.Where(x => x.PeriodDate >= fDate).ToList();
                        if (!onPeriods.Any()) {
                            return model;
                        }
                        productIds = onPeriods.Select(x => x.ProductId).Distinct().ToList();
                        products = products.Where(x => productIds.Contains(x.ProductId)).ToList();
                        customerIds = products.Select(x => x.CustomerId).Distinct().ToList();
                        customers = customers.Where(x => customerIds.Contains(x.CustomerId)).ToList();
                    }
                    //watch = System.Diagnostics.Stopwatch.StartNew();
                    var importProductions = (from sx in vfi.ImportFormSX1Detail
                                             where
                                                 sx.ImportFormSX1.ImportDate >= fDate &&
                                                 sx.ImportFormSX1.ImportDate <= tDate &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                   .Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                                 && productIds.Contains(sx.ProductId) &&
                                                 sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                             orderby sx.ImportFormSX1.MaterialUseDate
                                             group sx by sx.ProductId into sxx
                                             select new {
                                                 ProductId = sxx.Key,
                                                 //sx.ImportFormSX1.ImportDate,
                                                 Quantity = sxx.Sum(x => x.Number1 + x.Number2 + x.Processing1 + x.Processing2),
                                                 //sx.ImportFormSX1.MaterialUseDate,
                                             }
                                            ).ToList();
                    //watch.Stop();
                    //MyUtilities.Function.SaveLog("importSx1Details", watch.ElapsedMilliseconds + " ms");
                    //watch.Start();
                    var earlyProduction = (from p in allProductionPeriods
                                           where
                                               p.PeriodDate < fDate
                                           select p).ToList();
                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    //
                    var importsPeriod = allProductionPeriods.Where(x => x.WarehouseReceiptId != null
                                                                    && warehouses.Contains(x.WarehouseReceiptId.Value)
                        //&& (x.WarehouseIssueId == null
                        //    || !warehouses.Contains(x.WarehouseIssueId.Value))
                        //&& x.WarehouseIssueId != MyUtilities.Warehouse.Production1 // sx1
                        //&& x.WarehouseReceiptId != MyUtilities.Warehouse.Production1 // sx1
                        //&& x.WarehouseIssueId != MyUtilities.Warehouse.Business // tra hang
                        //&& x.WarehouseIssueId != MyUtilities.Warehouse.Defect // phe pham
                                                                    && x.LastPeriodQuantity > x.EarlyPeriodQuantity
                                                                    && x.PeriodDate >= fDate).ToList();

                    var importsMore = (from p in importsPeriod
                                       where p.WarehouseIssueId == null &&
                                             p.WarehouseReceiptId != MyUtilities.Warehouse.Production1 &&
                                             !p.IsInternal && !p.IsPurchase
                                       select p).ToList();
                    var importsPurchase = (from p in importsPeriod
                                           where p.WarehouseIssueId == null &&
                                                 p.IsPurchase
                                           select p).ToList();
                    var importsInternal = (from p in importsPeriod
                                           where p.WarehouseIssueId == null &&
                                                 p.IsInternal
                                           select p).ToList();
                    var importsTransfer = (from p in importsPeriod
                                           where p.WarehouseIssueId == MyUtilities.Warehouse.Tranfer
                                           select p).ToList();
                    var listHangTra = (from ond in vfi.OrderNoteDetails
                                       where ond.OrderNote.CreatedDate >= fDate &&
                                             ond.OrderNote.CreatedDate <= tDate &&
                                             ond.OrderNote.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                             productIds.Contains(ond.ProductId.Value)
                                       group ond by ond.ProductId into x
                                       select new {
                                           ProductId = x.Key,
                                           Quantity = x.Sum(y => y.Quantity)
                                       }).ToList();
                    //watch.Stop();
                    //MyUtilities.Function.SaveLog("import query", watch.ElapsedMilliseconds + " ms");
                    //watch.Start();
                    //var importsElse = (from p in importsPeriod
                    //                   where p.WarehouseIssueId != null &&
                    //                         !warehouses.Contains(p.WarehouseIssueId.Value) &&
                    //                         p.WarehouseIssueId != MyUtilities.Warehouse.Production1 && // sx1
                    //                         p.WarehouseIssueId != MyUtilities.Warehouse.Tranfer && // trung chuyen
                    //                         p.WarehouseIssueId != MyUtilities.Warehouse.Business // tra hang
                    //                   select p).ToList();
                    //
                    var exportsPeriod = allProductionPeriods.Where(x => x.WarehouseIssueId != null
                        //&& warehouses.Contains(x.WarehouseIssueId.Value)
                        //&& (x.WarehouseReceiptId == null
                        //    || !warehouses.Contains(x.WarehouseReceiptId.Value))
                                                                    && x.LastPeriodQuantity < x.EarlyPeriodQuantity
                                                                    && x.PeriodDate >= fDate).ToList();
                    var exportsTransfer = (from p in exportsPeriod
                                           where p.WarehouseReceiptId == MyUtilities.Warehouse.Tranfer
                                           select p).ToList();
                    var exportsDestroy = (from p in exportsPeriod
                                          where p.WarehouseReceiptId == MyUtilities.Warehouse.Destroy
                                          select p).ToList();
                    var exportsInternal = (from p in exportsPeriod
                                           where p.WarehouseReceiptId == null &&
                                                 p.IsInternal
                                           select p).ToList();
                    var exportsProduction = (from p in exportsPeriod
                                             where
                                                 p.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                                 p.WarehouseReceiptId == MyUtilities.Warehouse.Business
                                             select p).ToList();
                    var exportsDefect = (from p in exportsPeriod
                                         where
                                             p.WarehouseReceiptId == MyUtilities.Warehouse.Defect
                                         select p).ToList();
                    //var exportsElse = (from p in exportsPeriod
                    //                   where (p.IsInternal || 
                    //                            (p.WarehouseReceiptId != null && !warehouses.Contains(p.WarehouseReceiptId.Value))) &&
                    //                        p.WarehouseReceiptId != MyUtilities.Warehouse.Defect &&
                    //                        p.WarehouseReceiptId != MyUtilities.Warehouse.Business &&
                    //                        p.WarehouseReceiptId != MyUtilities.Warehouse.Destroy &&
                    //                        p.WarehouseReceiptId != MyUtilities.Warehouse.Tranfer &&
                    //                        p.EarlyPeriodQuantity > p.LastPeriodQuantity
                    //                   select p).ToList();
                    //watch.Stop();
                    //MyUtilities.Function.SaveLog("export query", watch.ElapsedMilliseconds + " ms");
                    var inventoryRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseInventoryPriceRate);
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    //watch.Start();
                    foreach (var customer in customers) {
                        var entity = new ImportExportProductionModel {
                            CustomerCode = customer.CustomerCode,
                            CustomerName = customer.CustomerName,
                            ReportDate = tDate,
                            Details = new List<ImportExportProductionDetailModel>(),
                        };
                        var list = new List<ImportExportProductionDetailModel>();
                        var productsById = products.Where(p => p.CustomerId == customer.CustomerId);
                        foreach (var product in productsById) {
                            var detail = new ImportExportProductionDetailModel {
                                ProductId = product.ProductId,
                                ProductCode = product.ProductCode,
                                ProductName = product.ProductName,
                                ProductCustomerName = product.DesignNo,
                                ProductCustomerCode = entity.CustomerCode,
                                ProductPrice = 0,
                                ImportQuantity = 0,
                                ExportQuantity = 0,
                                EarlyQuantity = 0,
                                LastQuantity = 0,
                                //Show = true,
                                DifferenceQuantity = 0,
                                ProductionWeight = 0,
                                MaterialPrice = 0,
                            };
                            detail.EarlyQuantity =
                                earlyProduction.Where(
                                    p => p.ProductId == product.ProductId && warehouses.Contains(p.WarehouseId))
                                               .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                            detail.LastQuantity =
                                allProductionPeriods.Where(
                                    p => p.ProductId == product.ProductId && warehouses.Contains(p.WarehouseId))
                                               .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                            detail.TranferInv = 
                                allProductionPeriods.Where(p => p.ProductId == product.ProductId &&
                                                                p.WarehouseId == MyUtilities.Warehouse.Tranfer)
                                                    .Sum(p => Math.Round(p.LastPeriodQuantity - p.EarlyPeriodQuantity, 0));

                            detail.ImportQuantity = importProductions.Where(p => p.ProductId == product.ProductId)
                                                                    .Sum(p => p.Quantity);
                            detail.ImportPurchase = importsPurchase.Where(pip => pip.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);
                            detail.ImportMore = importsMore.Where(pip => pip.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);
                            detail.ImportInternal = importsInternal.Where(pip => pip.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);
                            detail.ImportReturn = listHangTra.Where(ond => ond.ProductId == product.ProductId)
                                                            .Sum(ond => ond.Quantity.Value);
                            detail.ImportTransfer = importsTransfer.Where(p => p.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);

                            detail.ExportQuantity = exportsProduction.Where(p => p.ProductId == product.ProductId)
                                                                    .Sum(p => p.Quantity);
                            detail.ExportDefect = exportsDefect.Where(p => p.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);
                            detail.ExportInternal = exportsInternal.Where(p => p.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);
                            detail.ExportDestroy = exportsDestroy.Where(pip => pip.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);
                            detail.ExportTransfer = exportsTransfer.Where(p => p.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);

                            detail.TotalImport = importsPeriod.Where(x => x.ProductId == detail.ProductId
                                                                    && (x.WarehouseIssueId == null
                                                                        || !warehouses.Contains(x.WarehouseIssueId.Value)))
                                                                .ToList().Sum(x => x.Quantity);
                            if (detail.DiffImport < 0) {
                                detail.ImportQuantity += detail.DiffImport;
                                //detail.DiffImport = 0;
                            }
                            //detail.TotalImport += detail.ImportQuantity; // loi workoder: sx1 chua hoan thanh khong tinh ton
                            //detail.ImportElse = detail.TotalImport - detail.ImportPurchase - detail.ImportReturn
                            //                    - detail.ImportInternal - detail.ImportMore - detail.ImportTransfer;
                            detail.TotalExport = exportsPeriod.Where(x => x.ProductId == detail.ProductId
                                                                    && (x.WarehouseReceiptId == null
                                                                        || !warehouses.Contains(x.WarehouseReceiptId.Value)))
                                                                .ToList().Sum(x => x.Quantity);
                            //detail.ExportElse = detail.TotalExport - detail.ExportQuantity - detail.ExportDefect
                            //                    - detail.ExportInternal - detail.ExportDestroy - detail.ExportTransfer;
                            if (detail.ImportTransfer > 0 && detail.ExportTransfer > 0) {
                                if (detail.ImportTransfer >= detail.ExportTransfer) {
                                    detail.ImportTransfer -= detail.ExportTransfer;
                                    detail.TotalImport -= detail.ExportTransfer;
                                    detail.TotalExport -= detail.ExportTransfer;
                                    detail.ExportTransfer = 0;
                                }
                                else {
                                    detail.ExportTransfer -= detail.ImportTransfer;
                                    detail.TotalImport -= detail.ImportTransfer;
                                    detail.TotalExport -= detail.ImportTransfer;
                                    detail.ExportTransfer = 0;
                                }
                            }
                            detail.DifferenceQuantity = detail.EarlyQuantity
                                                        + detail.TotalImport
                                                        - detail.TotalExport
                                                        - detail.LastQuantity;
                            //detail.DiffImport = importsPeriod.Where(x => x.ProductId == detail.ProductId 
                            //                                        && (x.WarehouseIssueId == null 
                            //                                            || !warehouses.Contains(x.WarehouseIssueId.Value)
                            //                                        && x.LastPeriodQuantity > x.EarlyPeriodQuantity)
                            //                                .Sum(x => x.Quantity);
                            //detail.DiffImport -= detail.TotalImport;

                            //detail.DiffExport = exportsPeriod.Where(x => x.ProductId == detail.ProductId 
                            //                                        && (x.WarehouseReceiptId != MyUtilities.Warehouse.Business
                            //                                            || x.WarehouseReceiptId != MyUtilities.Warehouse.Defect
                            //                                            || x.WarehouseReceiptId != MyUtilities.Warehouse.Destroy
                            //                                            || x.WarehouseReceiptId != MyUtilities.Warehouse.Tranfer)
                            //                                        && x.IsInternal != true
                            //                                        && x.LastPeriodQuantity < x.EarlyPeriodQuantity)
                            //                                .Sum(x => x.Quantity);
                            //detail.DiffExport -= detail.TotalExport;

                            //detail.ProductPrice = MyUtilities.Product.ProductPrice(product.UnitPrice);
                            detail.ProductPrice = MyUtilities.Product.ProductVndPrice(product.UnitPrice, inventoryRate, exchangeRate);

                            var lastExport = (from p in allProductionPeriods
                                              where
                                              p.WarehouseId == MyUtilities.Warehouse.Business &&
                                              p.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                              p.WarehouseReceiptId == MyUtilities.Warehouse.Business &&
                                              p.ProductId == product.ProductId
                                              orderby p.PeriodDate descending
                                              select p).FirstOrDefault();
                            if (lastExport != null)
                                detail.LastExportDate = lastExport.PeriodDate;

                            if (product.ProductionMaterial != null) {
                                detail.ProductionWeight =
                                    MyUtilities.Product.GetProductWeight(
                                        product.ProductionMaterial.MaterialName.Trim(),
                                        product.ProductionMaterial.OutDiameter,
                                        product.ProductionMaterial.InDiameter,
                                        product.Length ?? 0, product.KnifeCut ?? 0,
                                        product.ProductionMaterial.Shape.Trim());
                                detail.MaterialCode = product.ProductionMaterial.MaterialCode;
                                detail.MaterialPrice = product.ProductionMaterial.UnitPrice;
                                detail.MaterialType = product.MaterialType;
                            }
                            list.Add(detail);
                        }
                        if (list.Any()) {
                            entity.Details.AddRange(list.Where(l => l.Show).OrderBy(l => l.ProductCode));
                            model.Add(entity);
                        }
                        //watch.Stop();
                        //MyUtilities.Function.SaveLog("foreach data", watch.ElapsedMilliseconds + " ms");
                    }
                }
                //overWatch.Stop();
                //MyUtilities.Function.SaveLog("GetAllProductImportExport on try", overWatch.ElapsedMilliseconds + " ms");
            }
            catch (Exception ex) {
                ModelState.AddModelError("GetAllProductImportExport", MyUtilities.MySystem.FetchExceptionMessage(ex));
            }
            return model;
        }

        public ActionResult PrintAllProductsReport2(int type, int month, int year) {
            var model = new List<ImportExportProductionDetailModel>();
            try {
                using (var vfi = new tammaContext()) {
                    var importSx1Details = (from sx in vfi.ImportFormSX1Detail
                                            where
                                                sx.ImportFormSX1.ImportDate.Month == month &&
                                                sx.ImportFormSX1.ImportDate.Year == year &&
                                                sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                  .Transaction.Status ==
                                                (byte)MyUtilities.Transaction.Status.Approved
                                                && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                            orderby sx.ImportFormSX1.MaterialUseDate
                                            select new {
                                                sx.ProductId,
                                                sx.ImportFormSX1.ImportDate,
                                                Quantity =
                                            (sx.Number1 + sx.Number2 + sx.Processing1 + sx.Processing2),
                                                sx.ImportFormSX1.MaterialUseDate,
                                                sx.MachineId,
                                            }).ToList();
                    var exportProduction = (from p in vfi.ProductInventoryPeriods
                                            where
                                                p.PeriodDate.Month == month &&
                                                p.PeriodDate.Year == year &&
                                                p.WarehouseId == MyUtilities.Warehouse.Business &&
                                                p.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                                p.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Business
                                            select p).ToList();
                    var productIds =
                        importSx1Details.Select(id => id.ProductId)
                                        .Union(exportProduction.Select(pip => pip.ProductId))
                                        .Distinct()
                                        .ToList();
                    var listHangTra = (from ond in vfi.OrderNoteDetails
                                       where ond.OrderNote.CreatedDate.Month == month &&
                                             ond.OrderNote.CreatedDate.Year == year &&
                                             ond.OrderNote.Transaction.Status ==
                                             (byte)MyUtilities.Transaction.Status.Approved
                                       select new {
                                           ond.ProductId,
                                           ond.Quantity
                                       }).ToList();
                    //var i = 0;
                    var lastMonthReport = new DateTime(year, month, 1).AddMonths(1).AddDays(-1);
                    foreach (var productId in productIds) {
                        var product = vfi.Products.FirstOrDefault(p => p.ProductId == productId);
                        var detail = new ImportExportProductionDetailModel {
                            ProductCode = product.ProductCode,
                            ProductName = product.ProductName,
                            ProductCustomerName = product.DesignNo,
                            ProductCustomerCode = product.Customer.CustomerCode,
                            DesignProductivity = product.Productivity ?? 0,
                            ExportWeight = product.QcWeight ?? 0,
                            ReportDate = new DateTime(year, month, 1),
                            ProductPrice = 0,
                            ImportQuantity = 0,
                            ExportQuantity = 0,
                            EarlyQuantity = 0,
                            LastQuantity = 0,
                            //Show = true
                        };
                        if (product.ProductionMaterials.Any(pm => pm.Active)) {
                            var material = product.ProductionMaterials.FirstOrDefault(pm => pm.Active).Material;
                            detail.ImportWeight = MyUtilities.Product.GetProductWeight(material.MaterialName,
                                                                                 material.OutDiameter,
                                                                                 material.InDiameter,
                                                                                 product.Length ?? 0,
                                                                                 product.KnifeCut ?? 0,
                                                                                 material.Shape + "");
                        }
                        detail.ExportQuantity =
                            exportProduction.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity);
                        var hangTra =
                            listHangTra.Where(ond => ond.ProductId == product.ProductId).Sum(ond => ond.Quantity);
                        detail.ExportQuantity -= hangTra.Value;
                        var importSx1DetailById = importSx1Details.Where(p => p.ProductId == product.ProductId).ToList();
                        if (importSx1DetailById.Any()) {
                            detail.ImportQuantity = importSx1DetailById.Sum(id => id.Quantity);
                            var machineIds = importSx1DetailById.Select(id => id.MachineId).Distinct();
                            var total = 0.0;
                            foreach (var machineId in machineIds) {
                                var importSx1ById = importSx1DetailById.Where(id => id.MachineId == machineId);
                                var lastTrack = MyUtilities.Machine.LastTrackUpMachine(machineId.Value, null, productId, lastMonthReport);
                                if (lastTrack != null) {
                                    total += (importSx1ById.Count() * lastTrack.RealProductivity);
                                }
                                else {
                                    total += (importSx1ById.Count() * detail.DesignProductivity);
                                }
                            }
                            detail.ProductivityInMonth = total / importSx1DetailById.Count();
                        }
                        model.Add(detail);
                    }

                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintAllProductsReport2", ex.Message);
            }
            return PartialView("PageProductionMonthlyImportExportReport",
                               model.OrderBy(m => m.ProductCustomerCode).ThenBy(m => m.ProductCode).ToList());
        }


        public ActionResult PrintAllProductsReport3(int year) {
            var model = new List<PrintSalesReport>();
            try {
                using (var vfi = new tammaContext()) {
                    var importSx1Details = (from sx in vfi.ImportFormSX1Detail
