                                                  //sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                  //sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                  //sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                  //    .Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                                  //    && 
                                                      sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                            //&& sx.ProductId == 961
                                            orderby sx.ImportFormSX1.MaterialUseDate
                                            select new {
                                                sx.ProductId,
                                                sx.ImportFormSX1.ImportDate,
                                                Quantity =  (sx.Number1 + sx.Number2 + sx.Processing1 + sx.Processing2),
                                                sx.ImportFormSX1.MaterialUseDate,
                                                sx.MachineId,
                                            }).ToList();
                    var productIds1 = importSx1Details.Select(od => od.ProductId).Distinct().ToList();
                    var orderDetails = (from od in vfi.OrderDetails
                                        where
                                            (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.Completed) &&
                                            od.Order.DueDate != null &&
                                            od.Order.DueDate.Value.Year == year
                                        select new {
                                            od.ProductId,
                                            OrderQty = od.OrderQty.Value,
                                            od.Order.DueDate
                                        }).ToList();
                    var productIds2 = orderDetails.Select(od => od.ProductId).Distinct().ToList();
                    var exportProduction = (from p in vfi.ProductInventoryPeriods
                                            where
                                                p.PeriodDate.Year == year &&
                                                p.WarehouseId == MyUtilities.Warehouse.Business &&
                                                p.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                                p.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Business
                                            select p).ToList();
                    var productIds3 = exportProduction.Select(od => od.ProductId).Distinct().ToList();
                    var listHangTra = (from ond in vfi.OrderNoteDetails
                                       where ond.OrderNote.CreatedDate.Year == year &&
                                             ond.OrderNote.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                       select new {
                                           ond.ProductId,
                                           ond.Quantity,
                                           ond.OrderNote.CreatedDate,
                                       }).ToList();
                    var forecasts = from f in vfi.ForecastOrders
                                    where f.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                          f.ForecastDate.Year == year
                                    select f;
                    var productIds4 = forecasts.Select(f => f.ProductId).Distinct().ToList();
                    //var productIds =
                    //    orderDetails.Select(id => id.ProductId)
                    //                    .Union(exportProduction.Select(pip => pip.ProductId))
                    //    //.Union(listHangTra.Select(pip => pip.ProductId.Value))
                    //                    .Distinct()
                    //                    .ToList();
                    productIds1.AddRange(productIds2);
                    productIds1.AddRange(productIds3);
                    productIds1.AddRange(productIds4);
                    productIds1.Distinct().ToList();
                    //var i = 0;
                    var products = (from p in vfi.Products
                                    where productIds1.Contains(p.ProductId)
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.ProductCode,
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        p.ProductionMaterials,
                                        Diameter = p.Diameter ?? 0,
                                        Length = p.Length ?? 0,
                                        KnifeCut = p.KnifeCut ?? 0,
                                        //p.RealProductions,
                                        Productivity = p.Productivity ?? 0,
                                        ProductionRate = p.ProductionRate ?? 0,
                                        p.ProductionSections
                                    }).ToList();
                    foreach (var product in products) {
                        //var product = vfi.Products.FirstOrDefault(p => p.ProductId == productId);
                        var entity = new PrintSalesReport {
                            CustomerId = product.CustomerId,
                            CustomerCode = product.CustomerCode,
                            ProductCode = product.ProductCode,
                            ReportDate = new DateTime(year, 1, 1),
                            ProductDesign = product.Diameter + " x " + product.Length,
                            ProductMaterialWeight = 0,
                            ProductionRate = product.ProductionRate,
                            Productivity = product.Productivity
                        };
                        var orderDetailById = orderDetails.Where(od => od.ProductId == product.ProductId).ToList();
                        var exportDetailById = exportProduction.Where(ed => ed.ProductId == product.ProductId).ToList();
                        if (product.ProductionMaterials.Any(pm => pm.Active)) {
                            var first = product.ProductionMaterials.FirstOrDefault(pm => pm.Active);
                            entity.MaterialCode = first.Material.MaterialCode;
                            entity.ProductMaterialWeight =
                                MyUtilities.Product.GetProductWeight(first.Material.MaterialName,
                                                                     first.Material.OutDiameter,
                                                                     first.Material.InDiameter,
                                                                     product.Length,
                                                                     product.KnifeCut,
                                                                     first.Material.Shape);
                        }
                        if (product.ProductionSections.Any(ps => ps.Active == true)) {
                            entity.Section = product.ProductionSections.Count(ps => ps.Active == true);
                            entity.Productivity2 = (from ps in product.ProductionSections
                                                    orderby ps.Productivity descending
                                                    where ps.Active == true
                                                    select ps.Productivity).FirstOrDefault();
                        }
                        for (int month = 1; month <= 12; month++) {
                            var detail = new SalesReport {
                                Month = month,
                            };
                            var orderInMonth = orderDetailById.Where(od => od.DueDate.Value.Month == month &&
                                                                           od.ProductId == product.ProductId).ToList();
                            detail.OrderQuantity = orderInMonth.Sum(od => od.OrderQty);
                            var exportInMonth = exportDetailById.Where(ed => ed.PeriodDate.Month == month &&
                                                                             ed.ProductId == product.ProductId).ToList();
                            detail.ExportQuantity = exportInMonth.Sum(od => od.Quantity);
                            var returnInMonth = listHangTra.Where(ond => ond.CreatedDate.Month == month &&
                                                                         ond.ProductId == product.ProductId).ToList();
                            detail.ExportQuantity -= returnInMonth.Sum(od => od.Quantity.Value);
                            var productionInMonth =
                                importSx1Details.Where(
                                    id => id.ImportDate.Month == month && id.ProductId == product.ProductId)
                                                .ToList();
                            detail.ProductionQuantity = productionInMonth.Sum(od => od.Quantity);
                            var forecastInMonth =
                                forecasts.Where(f => f.ProductId == product.ProductId && f.ForecastDate.Month == month)
                                         .ToList();
                            detail.ForecastQuantity = forecastInMonth.Sum(f => f.Quantity);
                            entity.List.Add(detail);
                        }
                        model.Add(entity);
                    }

                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintAllProductsReport3", ex.Message);
            }
            return PartialView("PageSalesYearlyReport",
                               model.OrderBy(m => m.CustomerCode).ThenBy(m => m.ProductCode).ToList());
        }


        public ActionResult PrintNotFinishInvProduct(int customerId, string productCode,
            string fromDate, string toDate,
            int caculateModel) {
            var model = new List<ImportExportProductionModel>();
            try {
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var fDate = MyUtilities.Function.ParseDate(fromDate);
                    var tDate = MyUtilities.Function.ParseLastDateTime(toDate);
                    var customers = (from c in vfi.Customers
                                     where c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                           && (customerId == 0 || c.CustomerId == customerId)
                                     orderby c.CustomerCode
                                     select new {
                                         c.CustomerId,
                                         c.CustomerCode,
                                         c.CustomerName,
                                         //Products = c.Products.Where(p => p.Active).ToList(),
                                     }).ToList();
                    var customerIds = customers.Select(c => c.CustomerId).ToList();
                    var products = (from p in vfi.Products
                                    where customerIds.Contains(p.CustomerId) &&
                                          p.ProductCode.Contains(productCode) &&
                                          p.Active
                                    orderby p.ProductCode
                                    select new {
                                        p.CustomerId,
                                        p.ProductId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        UnitPrice = p.UnitPrice ?? 0,
                                        p.Length,
                                        p.KnifeCut,
                                        ProductionMaterial = p.ProductionMaterials.FirstOrDefault(pm => pm.Active) != null
                                            ? p.ProductionMaterials.FirstOrDefault(pm => pm.Active).Material
                                            : null,
                                        MaterialType = p.ProductionMaterials.FirstOrDefault(pm => pm.Active) != null
                                            ? p.ProductionMaterials.FirstOrDefault(pm => pm.Active)
                                                .Material.MaterialType.IdentityCode
                                            : null,
                                    }).ToList();
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var allProductionPeriods = (from pip in vfi.ProductInventoryPeriods
                                                where pip.PeriodDate <= tDate && productIds.Contains(pip.ProductId)
                                                && !pip.Warehouse.IsFinish
                                                select new {
                                                    pip.ProductInventoryPeriodId,
                                                    pip.ProductId,
                                                    Quantity = pip.Quantity,
                                                    //PeriodQuantity = Math.Round(pip.LastPeriodQuantity - pip.EarlyPeriodQuantity),
                                                    LastPeriodQuantity = pip.LastPeriodQuantity,
                                                    EarlyPeriodQuantity = pip.EarlyPeriodQuantity,
                                                    pip.PeriodDate,
                                                    pip.WarehouseId,
                                                    //pip.Transaction,
                                                    WarehouseIssue = pip.Transaction.Warehouse,
                                                    WarehouseReceipt = pip.Transaction.Warehouse1,
                                                    pip.Transaction.WarehouseIssueId,
                                                    pip.Transaction.WarehouseReceiptId,
                                                    IsInternal = pip.Transaction.IsInternal ?? false,
                                                    IsPurchase = pip.Transaction.PoId != null && pip.Transaction.PoId > 0
                                                }).ToList();
                    if (caculateModel == (int)MyUtilities.Report.Calculate.InPeriod) {
                        var onPeriods = allProductionPeriods.Where(x => x.PeriodDate >= fDate).ToList();
                        if (!onPeriods.Any()) {
                            return PartialView("PageNotFinishInvProductReport",
                                               model.OrderBy(m => m.CustomerCode).ToList());
                        }
                        productIds = onPeriods.Select(x => x.ProductId).Distinct().ToList();
                        products = products.Where(x => productIds.Contains(x.ProductId)).ToList();
                        customerIds = products.Select(x => x.CustomerId).Distinct().ToList();
                        customers = customers.Where(x => customerIds.Contains(x.CustomerId)).ToList();
                    }
                    //watch = System.Diagnostics.Stopwatch.StartNew();
                    var importProductions = (from sx in vfi.ImportFormSX1Detail
                                             where
                                                 sx.ImportFormSX1.ImportDate >= fDate &&
                                                 sx.ImportFormSX1.ImportDate <= tDate &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                   .Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                                 && productIds.Contains(sx.ProductId) &&
                                                 sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                             orderby sx.ImportFormSX1.MaterialUseDate
                                             group sx by sx.ProductId into sxx
                                             select new {
                                                 ProductId = sxx.Key,
                                                 //sx.ImportFormSX1.ImportDate,
                                                 Quantity = sxx.Sum(x => x.Number1 + x.Number2 + x.Processing1 + x.Processing2),
                                                 //sx.ImportFormSX1.MaterialUseDate,
                                             }
                                            ).ToList();
                    var earlyProduction = (from p in allProductionPeriods
                                           where
                                               p.PeriodDate < fDate
                                           select p).ToList();
                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    warehouses.Remove(MyUtilities.Warehouse.Finish);
                    //
                    var importsPeriod = allProductionPeriods.Where(x => x.WarehouseReceiptId != null
                                                                    && warehouses.Contains(x.WarehouseReceiptId.Value)
                        //&& (x.WarehouseIssueId == null
                        //    || !warehouses.Contains(x.WarehouseIssueId.Value))
                        //&& x.WarehouseIssueId != MyUtilities.Warehouse.Production1 // sx1
                        //&& x.WarehouseReceiptId != MyUtilities.Warehouse.Production1 // sx1
                        //&& x.WarehouseIssueId != MyUtilities.Warehouse.Business // tra hang
                        //&& x.WarehouseIssueId != MyUtilities.Warehouse.Defect // phe pham
                                                                    && x.LastPeriodQuantity > x.EarlyPeriodQuantity
                                                                    && x.PeriodDate >= fDate).ToList();

                    var importsMore = (from p in importsPeriod
                                       where p.WarehouseIssueId == null &&
                                             !p.WarehouseReceipt.IsProduction &&
                                             !p.IsInternal && !p.IsPurchase
                                       select p).ToList();
                    var importsPurchase = (from p in importsPeriod
                                           where p.WarehouseIssueId == null &&
                                                 p.IsPurchase
                                           select p).ToList();
                    var importsInternal = (from p in importsPeriod
                                           where p.WarehouseIssueId == null &&
                                                 p.IsInternal
                                           select p).ToList();
                    var importsTransfer = (from p in importsPeriod
                                           where p.WarehouseIssueId == MyUtilities.Warehouse.Tranfer
                                           select p).ToList();
                    var listHangTra = (from ond in vfi.OrderNoteDetails
                                       where ond.OrderNote.CreatedDate >= fDate &&
                                             ond.OrderNote.CreatedDate <= tDate &&
                                             ond.OrderNote.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                             productIds.Contains(ond.ProductId.Value)
                                       group ond by ond.ProductId into x
                                       select new {
                                           ProductId = x.Key,
                                           Quantity = x.Sum(y => y.Quantity)
                                       }).ToList();
                    var exportsPeriod = allProductionPeriods.Where(x => x.WarehouseIssueId != null
                                                                    && x.LastPeriodQuantity < x.EarlyPeriodQuantity
                                                                    && x.PeriodDate >= fDate).ToList();
                    var exportsTransfer = (from p in exportsPeriod
                                           where p.WarehouseReceiptId == MyUtilities.Warehouse.Tranfer
                                           select p).ToList();
                    var exportsDestroy = (from p in exportsPeriod
                                          where p.WarehouseReceiptId != null
                                          && p.WarehouseReceipt.IsDestroy == true
                                          select p).ToList();
                    var exportsInternal = (from p in exportsPeriod
                                           where p.WarehouseReceiptId == null &&
                                                 p.IsInternal
                                           select p).ToList();
                    var exportsProduction = (from p in exportsPeriod
                                             where
                                                 p.WarehouseIssueId != null &&
                                                 p.WarehouseReceiptId != null &&
                                                 p.WarehouseIssue.IsPacking &&
                                                 p.WarehouseReceipt.IsFinish
                                             select p).ToList();
                    var exportsDefect = (from p in exportsPeriod
                                         where
                                                 p.WarehouseReceiptId != null &&
                                             p.WarehouseReceipt.IsDefect == true
                                         select p).ToList();
                    var inventoryRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseInventoryPriceRate);
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    foreach (var customer in customers) {
                        var entity = new ImportExportProductionModel {
                            CustomerCode = customer.CustomerCode,
                            CustomerName = customer.CustomerName,
                            ReportDate = tDate,
                            Details = new List<ImportExportProductionDetailModel>(),
                        };
                        var list = new List<ImportExportProductionDetailModel>();
                        var productsById = products.Where(p => p.CustomerId == customer.CustomerId).ToList();
                        foreach (var product in productsById) {
                            var detail = new ImportExportProductionDetailModel {
                                ProductId = product.ProductId,
                                ProductCode = product.ProductCode,
                                ProductName = product.ProductName,
                                ProductCustomerName = product.DesignNo,
                                ProductCustomerCode = entity.CustomerCode,
                                ImportQuantity = 0,
                                ExportQuantity = 0,
                                EarlyQuantity = 0,
                                LastQuantity = 0,
                                //Show = true,
                                DifferenceQuantity = 0,
                                ProductionWeight = 0,
                                MaterialPrice = 0,
                                //ProductPrice = 0,
                                ProductPrice = MyUtilities.Product.ProductVndPrice(product.UnitPrice, inventoryRate, exchangeRate),
                            };
                            detail.EarlyQuantity =
                                earlyProduction.Where(
                                    p => p.ProductId == product.ProductId && warehouses.Contains(p.WarehouseId))
                                               .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                            detail.LastQuantity =
                                allProductionPeriods.Where(
                                    p => p.ProductId == product.ProductId && warehouses.Contains(p.WarehouseId))
                                               .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                            detail.TranferInv =
                                allProductionPeriods.Where(p => p.ProductId == product.ProductId &&
                                                                p.WarehouseId == MyUtilities.Warehouse.Tranfer)
                                                    .Sum(p => Math.Round(p.LastPeriodQuantity - p.EarlyPeriodQuantity, 0));

                            detail.ImportQuantity = importProductions.Where(p => p.ProductId == product.ProductId)
                                                                    .Sum(p => p.Quantity);
                            detail.ImportPurchase = importsPurchase.Where(pip => pip.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);
                            detail.ImportMore = importsMore.Where(pip => pip.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);
                            detail.ImportInternal = importsInternal.Where(pip => pip.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);
                            detail.ImportReturn = listHangTra.Where(ond => ond.ProductId == product.ProductId)
                                                            .Sum(ond => ond.Quantity.Value);
                            detail.ImportTransfer = importsTransfer.Where(p => p.ProductId == product.ProductId)
                                                            .Sum(p => p.Quantity);

                            detail.ExportQuantity = exportsProduction.Where(p => p.ProductId == product.ProductId)
                                                                    .Sum(p => p.Quantity);
                            detail.ExportDefect = exportsDefect.Where(p => p.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);
                            detail.ExportInternal = exportsInternal.Where(p => p.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);
                            detail.ExportDestroy = exportsDestroy.Where(pip => pip.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);
                            detail.ExportTransfer = exportsTransfer.Where(p => p.ProductId == product.ProductId)
                                                                .Sum(p => p.Quantity);

                            detail.TotalImport = importsPeriod.Where(x => x.ProductId == detail.ProductId
                                                                    && (x.WarehouseIssueId == null
                                                                        || !warehouses.Contains(x.WarehouseIssueId.Value)))
                                                                .ToList().Sum(x => x.Quantity);
                            if (detail.DiffImport < 0) {
                                detail.ImportQuantity += detail.DiffImport;
                            }
                            detail.TotalExport = exportsPeriod.Where(x => x.ProductId == detail.ProductId
                                                                    && (x.WarehouseReceiptId == null
                                                                        || !warehouses.Contains(x.WarehouseReceiptId.Value)))
                                                                .ToList().Sum(x => x.Quantity);
                            if (detail.ImportTransfer > 0 && detail.ExportTransfer > 0) {
                                if (detail.ImportTransfer >= detail.ExportTransfer) {
                                    detail.ImportTransfer -= detail.ExportTransfer;
                                    detail.TotalImport -= detail.ExportTransfer;
                                    detail.TotalExport -= detail.ExportTransfer;
                                    detail.ExportTransfer = 0;
                                }
                                else {
                                    detail.ExportTransfer -= detail.ImportTransfer;
                                    detail.TotalImport -= detail.ImportTransfer;
                                    detail.TotalExport -= detail.ImportTransfer;
                                    detail.ExportTransfer = 0;
                                }
                            }
                            detail.DifferenceQuantity = detail.EarlyQuantity
                                                        + detail.TotalImport
                                                        - detail.TotalExport
                                                        - detail.LastQuantity;
                            
                            if (product.ProductionMaterial != null) {
                                detail.ProductionWeight =
                                    MyUtilities.Product.GetProductWeight(
                                        product.ProductionMaterial.MaterialName.Trim(),
                                        product.ProductionMaterial.OutDiameter,
                                        product.ProductionMaterial.InDiameter,
                                        product.Length ?? 0, product.KnifeCut ?? 0,
                                        product.ProductionMaterial.Shape.Trim());
                                detail.MaterialCode = product.ProductionMaterial.MaterialCode;
                                detail.MaterialPrice = product.ProductionMaterial.UnitPrice;
                                detail.MaterialType = product.MaterialType;
                            }
                            list.Add(detail);
                        }
                        if (list.Any()) {
                            entity.Details.AddRange(list.Where(l => l.Show).OrderBy(l => l.ProductCode));
                            model.Add(entity);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintNotFinishInvProduct", ex.Message);
            }
            return PartialView("PageNotFinishInvProductReport",
                               model.OrderBy(m => m.CustomerCode).ToList());
        }

        private List<SoLieuTongHopSanPham> GetProductCurrentReportTotal(
            bool chkOrder, bool chkInventory,
            int customerId, string productCode, string monthlyDate) {
            var model = new List<SoLieuTongHopSanPham>();
            try {
                //var ci = new CultureInfo("vi-VN");
                //var monthly = string.IsNullOrWhiteSpace(monthlyDate)
                //                  ? DateTime.Today
                //                  : Convert.ToDateTime(monthlyDate, ci);
                var monthly = DateTime.Today;
                using (var vfi = new tammaContext()) {
                    var products = (from p in vfi.Products
                                    where p.Active && (customerId == 0 || p.CustomerId == customerId)
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.ProductCode,
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        ForecastsQuality = p.ForecastsQuality ?? 0,
                                        DayOfStartSx1 = "",
                                    }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode)) {
                        products = products.Where(p => p.ProductCode.Contains(productCode)).ToList();
                    }
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where productIds.Contains(pi.ProductId) &&
                                           warehouseIds.Contains(pi.WarehouseId) &&
                                           pi.TotalQty > 0
                                       select new {
                                           pi.ProductId,
                                           pi.WarehouseId,
                                           pi.TotalQty,
                                           pi.Warehouse.IsProduction,
                                           pi.Warehouse.IsCncMilling,
                                           pi.Warehouse.IsProduction2,
                                           pi.Warehouse.IsHeatTreatment,
                                           pi.Warehouse.IsPolish,
                                           //pi.Warehouse.IsPlating,
                                           pi.Warehouse.IsPacking,
                                           pi.Warehouse.IsFinish,
                                           //pi.Warehouse.IsQC,
                                           //pi.Warehouse.IsReprocessing,
                                       }).ToList();

                    var lastMonth = new DateTime(monthly.Year, monthly.Month, 1).AddSeconds(-1);
                    var nextMonth = new DateTime(monthly.Year, monthly.Month, 1).AddMonths(1);
                    var orderDetails = (from od in vfi.OrderDetails
                                        where (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                               od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess ||
                                               od.Order.Status == (byte)MyUtilities.Sales.Status.Completed) &&
                                              od.Order.DueDate > MyUtilities.Sales.StartOrderReportDate &&
                                              od.Order.DueDate != null &&
                                             productIds.Contains(od.ProductId) &&
                                             od.RequiedNumber > 0
                                        select new {
                                            od.ProductId,
                                            od.Order.DueDate,
                                            od.Order.Status,
                                            od.OrderQty,
                                            od.RequiedNumber,
                                            od.IsAlert
                                        }).ToList();

                    var orderDetailLastMonth = (from od in orderDetails
                                                where od.DueDate < lastMonth &&
                                                od.Status != (byte)MyUtilities.Sales.Status.Completed
                                                select od).ToList();
                    var orderDetailInMonth = (from od in orderDetails
                                              where od.DueDate.Value.Month == monthly.Month &&
                                                    od.DueDate.Value.Year == monthly.Year
                                              select od).ToList();
                    var orderDetailNextMonth = (from od in orderDetails
                                                where
                                                    od.DueDate.Value.Month == nextMonth.Month &&
                                                    od.DueDate.Value.Year == nextMonth.Year
                                                select od).ToList();

                    var forecastOrdersInMonth = (from fo in vfi.ForecastOrders
                                                 where fo.ForecastDate.Month == monthly.Month &&
                                                       fo.ForecastDate.Year == monthly.Year &&
                                                       fo.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                       productIds.Contains(fo.ProductId)
                                                 select new {
                                                     fo.ProductId,
                                                     fo.Quantity,
                                                 }).ToList();
                    var forecastOrdersNextMonth = (from fo in vfi.ForecastOrders
                                                   where fo.ForecastDate.Month == nextMonth.Month &&
                                                         fo.ForecastDate.Year == nextMonth.Year &&
                                                         fo.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                         productIds.Contains(fo.ProductId)
                                                   select new {
                                                       fo.ProductId,
                                                       fo.Quantity,
                                                   }).ToList();
                    var warehousesProduction2 = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    var warehousesPlating = MyUtilities.Warehouse.GetWarehouseIds_Plating();
                    var warehousesReProcessing = MyUtilities.Warehouse.GetWarehouseId_ReProcessing();
                    foreach (var product in products) {
                        var entity = new SoLieuTongHopSanPham {
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            CustomerCode = product.CustomerCode,
                            ToDate = monthly,
                            InMonthString = monthly.ToString("MM/yyyy"),
                            NextMonthString = nextMonth.ToString("MM/yyyy"),
                            UseForecast = true,
                            Title = "Thông tin tồn kho tổng hợp " + monthly.ToString("dd/MM/yyyy"),
                            HienThi = false
                        };
                        var productInvsById = productInvs.Where(x => x.ProductId == entity.ProductId).ToList();
                        entity.TonKhoSX2CNC = productInvsById.Where(x => x.IsCncMilling).Sum(x => x.TotalQty);
                        entity.TonKhoSX2SX2 = productInvsById.Where(x => x.IsProduction2).Sum(x => x.TotalQty);
                        entity.TonKhoNhietLuyen = productInvsById.Where(x => x.IsHeatTreatment).Sum(x => x.TotalQty);
                        entity.TonKhoRungBong = productInvsById.Where(x => x.IsPolish).Sum(x => x.TotalQty);
                        entity.TonKhoGCN = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.WaitingPlating).Sum(x => x.TotalQty);
                        entity.TonKhoNCU = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.Plating).Sum(x => x.TotalQty);
                        entity.TonKhoNCUKiemTra = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.PlatingTest).Sum(x => x.TotalQty);
                        entity.TonKhoQCA = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.QcA).Sum(x => x.TotalQty);
                        entity.TonKhoQCB = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.QcB).Sum(x => x.TotalQty);
                        entity.TonKhoQCC = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.QcC).Sum(x => x.TotalQty);
                        entity.Packing = productInvsById.Where(x => x.IsPacking).Sum(x => x.TotalQty);
                        entity.TonKhoTPA = productInvsById.Where(x => x.IsFinish).Sum(x => x.TotalQty);
                        entity.TonKhoCXL = productInvsById.Where(x => x.WarehouseId == MyUtilities.Warehouse.Processing).Sum(x => x.TotalQty);
                        entity.ReProcessing = productInvsById.Where(x => warehousesReProcessing.Contains(x.WarehouseId)).Sum(x => x.TotalQty);


                        entity.DonHangThangTruoc = orderDetailLastMonth.Where(x => x.ProductId == entity.ProductId).Sum(x => x.RequiedNumber);
                        entity.DonHangTrongThang = orderDetailInMonth.Where(x => x.ProductId == entity.ProductId).Sum(x => x.RequiedNumber);
                        entity.DonHangThangKe = orderDetailNextMonth.Where(x => x.ProductId == entity.ProductId).Sum(x => x.RequiedNumber);
                        entity.DuBaoSX = forecastOrdersInMonth.Where(x => x.ProductId == entity.ProductId).Sum(x => x.Quantity);
                        entity.DonHangSauThangKe = forecastOrdersNextMonth.Where(x => x.ProductId == entity.ProductId).Sum(x => x.Quantity);
                        entity.DonHangConLai = entity.DonHangThangTruoc + entity.DonHangTrongThang;

                        if (chkInventory) {
                            if (entity.TonTong > 0) {
                                entity.HienThi = true;
                            }
                        }
                        if (!entity.HienThi && chkOrder) {
                            if (entity.DonHangConLai + entity.DonHangThangKe + entity.DuBaoSX + entity.DonHangSauThangKe > 0) {
                                entity.HienThi = true;
                            }
                        }
                        if (entity.HienThi)
                            model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("GetProductCurrentReportTotal", ex.Message);
            }
            return model;
        }

