                        shiftCFund.CncMonthly = productionMonthlyByShift.Sum(id => id.Quantity * id.ProductionCNCPrice);

                        // daily calculate
                        if (importSx1Date != null) {
                            var productionCamesDaily = productionCamesMonthly.Where(id => id.MaterialUseDate == importSx1Date).ToList();
                            //A
