                                                  select new {
                                                      td.ReferenceId,
                                                      td.Transaction.WarehouseReceiptId,
                                                      td.Quantity,
                                                      td.Transaction.TransactionCode,
                                                  }).ToList();
                        //var dailyCNC = importCncs.Any(x => x.ImportDate == monthly);
                        foreach (var detail in importCncs) {
                            if (detail.Number1 + detail.Number2 > 0) {
                                var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                    td.ReferenceId == detail.ProductId &&
                                    td.TransactionCode.Equals(detail.TransactionCode) &&
                                    td.Quantity == (detail.Number1 + detail.Number2) &&
                                    td.WarehouseReceiptId != MyUtilities.Warehouse.Processing &&
                                    td.WarehouseReceiptId != MyUtilities.Warehouse.Defect);
                                if (transactionDetailsById != null) {
                                    var numberA = detail.Shift1Name.Contains("A")
                                        ? detail.Number1
                                        : detail.Shift2Name.Contains("A")
                                            ? detail.Number2
                                            : 0;
                                    var numberB = detail.Shift1Name.Contains("B")
                                        ? detail.Number1
                                        : detail.Shift2Name.Contains("B")
                                            ? detail.Number2
                                            : 0;
                                    var numberC = detail.Shift1Name.Contains("C")
                                        ? detail.Number1
                                        : detail.Shift2Name.Contains("C")
                                            ? detail.Number2
                                            : 0;

                                    cncMonthlyA += (numberA * detail.CncPrice);
                                    cncMonthlyB += (numberB * detail.CncPrice);
                                    cncMonthlyC += (numberC * detail.CncPrice);

                                    if (detail.ImportDate.Day == reportDate.Day &&
                                        detail.ImportDate.Month == reportDate.Month &&
                                        detail.ImportDate.Year == reportDate.Year) {
                                        cncDailyA += (numberA * detail.CncPrice);
                                        cncDailyB += (numberB * detail.CncPrice);
                                        cncDailyC += (numberC * detail.CncPrice);
                                    }
                                }
                            }
                        }
                        shiftAFund.CncDaily += cncDailyA;
                        shiftAFund.CncMonthly += cncMonthlyA;
                        shiftBFund.CncDaily += cncDailyB;
                        shiftBFund.CncMonthly += cncMonthlyB;
                        shiftCFund.CncDaily += cncDailyC;
                        shiftCFund.CncMonthly += cncMonthlyC;
                        // waiting approve transations

                        var warehousesCalculate = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                        var warehousesName = (from x in vfi.Transactions
                                              where x.WarehouseReceiptId != null
                                                   && warehousesCalculate.Contains(x.WarehouseReceiptId.Value)
                                                   && x.Status == (byte)MyUtilities.Transaction.Status.Open
                                                   && x.CreatedDate <= reportDate
                                              select x.Warehouse1.WarehouseName).Distinct().ToList();
                        if (warehousesName.Any()) {
                            //var warehouseIds = transactions.Select(x => x.WarehouseReceiptId.Value).Distinct().ToList();
                            //var warehousesName = vfi.Warehouses.Where(x => warehouseIds.Contains(x.WarehouseId))
                            //    .OrderBy(x => x.Idx)
                            //    .Select(x => x.WarehouseName);
                            reportMessage = "Cảnh báo! Còn phiếu luân chuyển kho chưa duyệt";
                            foreach (var warehouseName in warehousesName) {
                                reportMessage += " | " + warehouseName;
                            }
                        }
                    }

                    var smartProductions = vfi.SmartProductions.Where(sm => sm.ProductId != null && productIds.Contains(sm.ProductId.Value)).ToList();
                    //foreach (var customer in customers) {
                    //var getForecast = customer.UseForecast;
                    var deductionCncMachine = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.DeductionCNCMachine);
                    var reProcessWarehouses = MyUtilities.Warehouse.GetWarehouseId_ReProcessingOnly();
                    foreach (var product in products) {
                        //var unitPrice = MyUtilities.Product.ProductVndPrice(product.UnitPrice, productionPriceRate, exchangeRate);
                        var sp = new SoLieuTongHopSanPham {
                            ProductionMonthlyPoint = costInMonth,
                            ProductionWeeklyPoint = costInWeek,
                            CncMonthlyPoint = cncInMonth,
                            CncWeeklyPoint = cncInWeek,
                            Cnc2MonthlyPoint = cnc2InMonth,
                            Cnc2WeeklyPoint = cnc2InWeek,
                            CamesMonthlyPoint = costInMonth - cncInMonth,
                            CamesWeeklyPoint = costInWeek - cncInWeek,
                            ProductionMonthly = productionMonthly,
                            CncMonthly = cncInMonth2,
                            CamesMonthly = productionMonthly - cncInMonth2,

                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            ProcessingType = product.TypeName,
                            CustomerCode = product.CustomerCode,
                            ToDate = reportDate,
                            ReportDate = reportDate,
                            InMonthString = reportDate.ToString("MM/yyyy"),
                            NextMonthString = nextMonth.ToString("MM/yyyy"),
                            DayOfStartSx1 = startDate.ToString("dd/MM"),
                            UseForecast = true,
                            //UnitPrice = product.UnitPrice,
                            UnitPrice = MyUtilities.Product.ProductVndPrice(product.UnitPrice),
                            InventoryPointRate = inventoryPriceRate,
                            Title = "Báo cáo tổng hợp " + reportDate.ToString("dd/MM/yyyy"),
                            ShiftAFunc = shiftAFund,
                            ShiftBFunc = shiftBFund,
                            ShiftCFunc = shiftCFund,
                            DeductionMachine = deductionCncMachine,
                            ReportMessage = reportMessage,
                        };

                        //var traHangById = sendBackInMonth.Where(ep => ep.ProductId == product.ProductId).ToList();
                        sp.DonHangTrongThang =
                            orderDetailInMonth.Where(od => od.ProductId == product.ProductId)
                                              .Sum(od => od.OrderQty ?? 0)
                            //+ traHangById.Sum(ep => (ep.Piece.Value))
                            ;
                        sp.OrderAlert = orderDetailInMonth.Any(od => od.ProductId == product.ProductId && od.RequiedNumber > 0 && od.IsAlert == true);
                        var allExportFinishById = allExportFinish.Where(ep => ep.ProductId == product.ProductId).ToList();
                        //var allSendBackTpById = allSendBack.Where(ep => ep.ProductId == product.ProductId).ToList();
                        sp.DonHangThangTruoc =
                            (orderDetailRemaining.Where(od => od.ProductId == product.ProductId)
                                                 .Sum(od => od.OrderQty ?? 0)) -
                            ((allExportFinishById.Sum(ep => ep.Quantity))
                            //- (allSendBackTpById.Sum(ep => ep.Quantity))
                            );
                        if (sp.DonHangThangTruoc < 0) {
                            sp.DonHangTrongThang += sp.DonHangThangTruoc;
                            sp.DonHangThangTruoc = 0;
                            if (sp.DonHangTrongThang < 0) {
                                sp.DonHangThangTruoc = sp.DonHangTrongThang;
                                sp.DonHangTrongThang = 0;
                            }
                        }
                        sp.DonHangThangKe =
                            orderDetailNextMonth.Where(od => od.ProductId == product.ProductId)
                                                .Sum(od => od.OrderQty ?? 0);

                        var forecastNextMonth = forecastOrdersNextMonth.Where(fo => fo.ProductId == product.ProductId);
                        if (forecastNextMonth.Any()) {
                            sp.DonHangSauThangKe = forecastNextMonth.Sum(fo => fo.Quantity);
                        }
                        else {
                            sp.DonHangSauThangKe = 0;
                        }
                        var forecastInMonth = forecastOrdersInMonth.Where(fo => fo.ProductId == product.ProductId);
                        if (forecastInMonth.Any()) {
                            sp.DuBaoSX = forecastInMonth.Sum(fo => fo.Quantity);
                        }
                        else {
                            sp.DuBaoSX = 0;
                        }

                        sp.LuyKeSX =
                            importSx1Details.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity) -
                            giaodichKho1Huy.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity);
                        sp.LuyKeXuat = giaodichKD.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity);
                        var hangTra =
                            listHangTra.Where(ond => ond.ProductId == product.ProductId).Sum(ond => ond.Quantity);
                        var hangDoi =
                            listHangDoi.Where(ond => ond.ProductId == product.ProductId).Sum(ond => ond.Quantity);
                        sp.LuyKeXuat = sp.LuyKeXuat - hangTra;
                        sp.DonHangConLai = (sp.DonHangThangTruoc) + (sp.DonHangTrongThang) -
                                           (sp.LuyKeXuat);

                        if (importSx1Date != null) {
                            sp.DayOfSX1 = importSx1Date.ToString("dd/MM");
                        }

                        var smartProduction = smartProductions.FirstOrDefault(sm => sm.ProductId == product.ProductId);
                        sp.OnMachine = (smartProduction != null ? 1 : 0);

                        var productPeriodByIds =
                            allProductInventoryPeriodsByDate.Where(pip => pip.ProductId == product.ProductId)
                                                            .ToList();
                        sp.ImportInternal = productPeriodByIds.Where(x => x.PeriodDate.Month == reportDate.Month
                                                                        && x.PeriodDate.Year == reportDate.Year
                                                                        && x.LastPeriodQuantity > x.EarlyPeriodQuantity
                                                                        && x.IsInternal)
                                                            .Sum(x => x.Quantity);
                        sp.ExportInternal = productPeriodByIds.Where(x => x.PeriodDate.Month == reportDate.Month
                                                                        && x.PeriodDate.Year == reportDate.Year
                                                                        && x.LastPeriodQuantity < x.EarlyPeriodQuantity
                                                                        && x.IsInternal)
                                                            .Sum(x => x.Quantity);
                        //ton kho 
                        sp.SanXuat1 = sxKho1.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity);
                        sp.TonKhoSX2CNC =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Cnc)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoSX2SX2 =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Production2)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoSX2SX2B =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Production2B)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoSX2SX2C =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Production2C)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoSX2SX2D =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Production2D)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoNhietLuyen =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.HeatTreatment)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoRungBong =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoGCN =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.WaitingPlating)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoNCU =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Plating)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoNCUKiemTra =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.PlatingTest)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoQCA =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.QcA)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoQCB =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.QcB)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoQCC =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.QcC)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoCXL =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Processing)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoCXL2 =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Processing2)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.ReProcessing =
                            productPeriodByIds.Where(p => reProcessWarehouses.Contains(p.WarehouseId))
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoPP = ppInMonth.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity);
                        sp.DefectPriceInMonth = sp.TonKhoPP * sp.UnitPrice / 1000000;
                        var defectInWeek = ppInWeek.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity);
                        sp.DefectPriceInWeek = defectInWeek * sp.UnitPrice / 1000000;
                        sp.DefectPrice = ppInDay.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity) * sp.UnitPrice / 1000000;
                        sp.TonKhoTPA =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Finish)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.Packing =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Packing)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        sp.TonKhoTPB =
                            productPeriodByIds.Where(p => p.WarehouseId == MyUtilities.Warehouse.Return)
                                              .Sum(p => p.LastPeriodQuantity - p.EarlyPeriodQuantity);
                        // xuat ban
                        sp.XuatThanhPham = xuatTP.Where(p => p.ProductId == product.ProductId).Sum(p => p.Quantity)
                            //-(hangDoi - traHang - daTraHang)
                            + (sp.TonKhoTPB - hangDoi)
                            ;
                        sp.LuyKeXuat = sp.LuyKeXuat + sp.TonKhoTPB - hangDoi;

                        sp.ExportDailyPoint = ((sp.XuatThanhPham) * sp.UnitPrice) / 1000000;
                        sp.ExportWeekly = xuatTPTuan.Where(x => x.ProductId == product.ProductId).Sum(x => x.Quantity);
                        sp.ExportWeeklyPoint = ((sp.ExportWeekly) * sp.UnitPrice) / 1000000;
                        sp.ExportMonthlyPoint = ((sp.LuyKeXuat + hangTra) * sp.UnitPrice) / 1000000;
                        sp.ForecastPoint = ((sp.DuBaoSX) * sp.UnitPrice) / 1000000;
                        sp.OrderPoint = ((sp.DonHangTrongThang) * sp.UnitPrice) / 1000000;
                        var orderRemainingById = orderRemainings.FirstOrDefault(x => x.ProductId == sp.ProductId);
                        if (orderRemainingById != null) {
                            sp.OrderRemainingPoint = orderRemainingById.Quantity * sp.UnitPrice / 1000000;
                        }
                        if (!chkLuyKeSX && !chkLuyKeXuat && !chkDonHangThangKe && !chkDonHangConLai)
                            sp.HienThi = true;
                        else {
                            sp.HienThi = false;
                            if (chkLuyKeSX && (sp.LuyKeSX != 0 || sp.ImportInternal > 0)) {
                                sp.HienThi = true;
                            }
                            else if (chkLuyKeXuat && (sp.LuyKeXuat != 0 || sp.ExportInternal > 0)) {
                                sp.HienThi = true;
                            }
                            else if (chkDonHangThangKe && (sp.DonHangThangKe + sp.DonHangSauThangKe != 0)) {
                                sp.HienThi = true;
                            }
                            else if (chkDonHangConLai && (sp.DonHangConLai + sp.DuBaoSX != 0)) {
                                sp.HienThi = true;
                            }
                        }

                        // cong thuc tinh toan
                        sp.HintProduction = 0;
                        sp.Productivity = product.Productivity;
                        if (sp.HienThi && calculateMode == (int)MyUtilities.Report.Calculate.All) {
                            sp.Index = index++;
                            //if (product.IsUsdOrVnd == 0) {
                            //    sp.UnitPrice = product.UnitPriceVnd;
                            //}
                            //else {
                            //    sp.UnitPrice = product.UnitPriceUsd;
                            //}
                            sp.ProductionDailyPoint =
                                sxKho1.Where(
                                    p => p.ProductId == product.ProductId)
                                      .Sum(
                                          i =>
                                          Math.Round((i.Number1) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint) +
                                          Math.Round((i.Number2) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                            sp.CncDailyPoint =
                                sxKho1.Where(
                                    p => p.ProductId == product.ProductId && p.MachineName.Contains("CNC") && !p.MachineName.Contains("VF2"))
                                      .Sum(
                                          i =>
                                          Math.Round((i.Number1) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint) +
                                          Math.Round((i.Number2) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                            sp.Cnc2DailyPoint =
                                sxKho1.Where(
                                    p => p.ProductId == product.ProductId && p.MachineName.Contains("VF2"))
                                      .Sum(
                                          i =>
                                          Math.Round((i.Number1) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint) +
                                          Math.Round((i.Number2) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                            sp.CamesDailyPoint = sp.ProductionDailyPoint - sp.CncDailyPoint - sp.Cnc2DailyPoint;
                            // cheat point sp.LuyKeXuat - hangTra

                            sp.ProductionDaily = (sp.SanXuat1) * sp.Productivity * 5;
                            sp.CncDaily =
                                sxKho1.Where(
                                    p => p.ProductId == product.ProductId && p.MachineName.Contains("CNC"))
                                      .Sum(i => Math.Round((i.Number1 + i.Number2)) * sp.Productivity) * 5;
                            sp.CamesDaily = sp.ProductionDaily - sp.CncDaily;
                            //sp.ProductionMonthly = (sp.LuyKeSX ?? 0)*sp.Productivity;

                            //var day = 0;

                            var orderRemaining =
                                orderDetails.Where(od => od.ProductId == product.ProductId && od.RequiedNumber > 0
                                && od.Status != (byte)MyUtilities.Sales.Status.Completed
                                && od.Status != (byte)MyUtilities.Sales.Status.Cancel);
                            if (orderRemaining.Any()) {
                                sp.MinOrderDate = orderRemaining.Min(x => x.DueDate.Value);
                                var requireProduction = sp.DonHangConLai - (sp.TonTong - sp.ProcessingInv);
                                if (requireProduction > 0) {
                                    var dayCount = (reportDate - sp.MinOrderDate.Value).TotalDays;
                                    if (dayCount >= 7) {
                                        sp.HintProduction = 1;
                                    }
                                    else if (dayCount > 0) {
                                        sp.HintProduction = 1;
                                    }
                                }
                                var requireProduction2 = sp.DonHangConLai - sp.AfterProduction2Inv;
                                if (product.IsProduction2 && requireProduction2 > 0) {
                                    var dayCount = (reportDate - sp.MinOrderDate.Value).TotalDays;
                                    if (dayCount >= 7) {
                                        sp.HintProduction2 = 1;
                                    }
                                    else if (dayCount > 0) {
                                        sp.HintProduction2 = 1;
                                    }
                                }
                            }

                        }
                        model.Add(sp);
                    }
                }
                //}
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintProductReportTotal", ex.Message);
            }
            return model;
        }

        [GridAction]
        public ActionResult SelectProductCurrentReport(
            bool chkOrder, bool chkInventory,
            int customerId, string productCode, string monthlyDate) {
            if (string.IsNullOrWhiteSpace(monthlyDate))
                return View(new GridModel(new List<SoLieuTongHopSanPham>()));
            var tonkho = new List<SoLieuTongHopSanPham>();
            try {
                tonkho = GetProductCurrentReportTotal(chkOrder, chkInventory,
                                                    customerId, productCode, monthlyDate);

                var jsonResult = Json(tonkho, JsonRequestBehavior.AllowGet);
                jsonResult.MaxJsonLength = Int32.MaxValue;
                return jsonResult;
                //return
                //    View(
                //        new GridModel(tonkho.OrderBy(c => c.CustomerCode).ThenBy(p => p.ProductCode)));

            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductReportByMonthly", ex.Message);
            }
            return View(new GridModel(new List<SoLieuTongHopSanPham>()));
        }

        [GridAction]
        public ActionResult SelectProductReportByMonthly(
            bool chkLuyKeSX,
            bool chkLuyKeXuat,
            bool chkDonHangThangKe,
            bool chkDonHangConLai,
            int customerId
            , string productName
            , string monthlyDate) {
            if (string.IsNullOrWhiteSpace(monthlyDate))
                return View(new GridModel(new List<SoLieuTongHopSanPham>()));
            var model = new List<SoLieuTongHopSanPham>();
            try {
                model = GetProductReportTotal(chkLuyKeSX, chkLuyKeXuat, chkDonHangThangKe, chkDonHangConLai, customerId,
                                               productName, monthlyDate,
                                               (int)MyUtilities.Report.Calculate.InPeriod);

                var jsonResult = Json(model.Where(p => p.HienThi).OrderBy(c => c.CustomerCode).ThenBy(p => p.ProductCode), JsonRequestBehavior.AllowGet);
                jsonResult.MaxJsonLength = Int32.MaxValue;
                return jsonResult;
                // test: with A6 => 3s
                //return
                //    View(
                //        new GridModel(
                //            tonkho.Where(p => p.HienThi).OrderBy(c => c.CustomerCode).ThenBy(p => p.ProductCode)));
                // test: with A6 => 3s
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductReportByMonthly", ex.Message);
            }
            return View(new GridModel(new List<SoLieuTongHopSanPham>()));
        }

        [HttpPost]
        public ActionResult PrintProductCurrentReport(
            int customerId,
            bool chkOrder,
            bool chkInventory,
            string monthlyDate) {
            var model = new List<SoLieuTongHopSanPham>();
            try {
                model = GetProductCurrentReportTotal(chkOrder, chkInventory,
                                                    customerId, "", monthlyDate);
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintProductCurrentReport", ex.Message);
            }
            return PartialView("PageProductReportTotal", model.OrderBy(c => c.CustomerCode).ThenBy(p => p.ProductCode).ToList());
        }

        [HttpPost]
        public ActionResult PrintProductReportTotal(
            int customerId,
            string productName,
            bool chkLuyKeSX,
            bool chkLuyKeXuat,
            bool chkDonHangThangKe,
            bool chkDonHangConLai,
            string monthlyDate) {
            var model = new List<SoLieuTongHopSanPham>();
            try {
                model = GetProductReportTotal(chkLuyKeSX, chkLuyKeXuat, chkDonHangThangKe, chkDonHangConLai, customerId,
                                               productName, monthlyDate,
                                               (int)MyUtilities.Report.Calculate.All);
                //if (model.Any()) {
                //    model = model.Where(x => x.HienThi).ToList();
                //}
                using (var vfi = new tammaContext()) {
                    var workGroup = vfi.WorkGroups.FirstOrDefault(x => x.Active);
                    if (workGroup != null && workGroup.WorkGroupCode.Equals("AVF")) {
                        return PartialView("PageProductReportTotalAVF", model.OrderBy(c => c.CustomerCode).ThenBy(p => p.ProductCode).ToList());
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductReportByMonthly", ex.Message);
            }
            return PartialView("PageProductReportTotal", model.OrderBy(c => c.CustomerCode).ThenBy(p => p.ProductCode).ToList());
        }

