        #endregion

        #region production

        [GridAction]
        public ActionResult SelectProductionPlanReport(string productName, string monthlyDate, bool cames, bool cnc) {
            if (!cames && !cnc)
                return View(new GridModel(new List<ProductionPlanModel>()));
            var model = new List<ProductionPlanModel>();
            try {
                using (var vfi = new tammaContext()) {
                    var ci = new CultureInfo("vi-VN");
                    var reportDate = string.IsNullOrWhiteSpace(monthlyDate)
                                         ? DateTime.Today
                                         : Convert.ToDateTime(monthlyDate, ci);

                    #region part 1: make list machine + product
                    var machines = from m in vfi.Machines
                                   where m.Active && m.MachineName.Contains("C")
                                   orderby m.MachineName
                                   select new {
                                       m.MachineId,
                                       m.MachineName
                                   };
                    if (cames && cnc) {
                    }
                    else if (cames) {
                        machines = machines.Where(m => !m.MachineName.Contains("CNC"));
                    }
                    else if (cnc) {
                        machines = machines.Where(m => m.MachineName.Contains("CNC"));
                    }
                    var machineIds = machines.Select(m => m.MachineId).ToList();

                    var importSx1s = (from i in vfi.ImportFormSX1Detail
                                      where
                                          i.ImportFormSX1.MaterialUseDate == reportDate &&
                                          i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                          i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                          i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                           .Transaction.Status ==
                                          (byte)MyUtilities.Transaction.Status.Approved
                                          && machineIds.Contains(i.MachineId.Value)
                                      select i);
                    var materialUses = from mu in vfi.MaterialUseDetails
                                       where mu.MaterialUseInShift.UsedDate == reportDate &&
                                       mu.MaterialUseInShift.Status != (byte)MyUtilities.Transaction.Status.Cancel &&
                                       machineIds.Contains(mu.MachineId) &&
                                       mu.MaterialUseInShift.Type == 1
                                       select new {
                                           mu.MaterialUseInShift.UsedDate,
                                           mu.MachineId,
                                           Quantity = mu.EditQuantity + mu.EditQuantity2
                                       };
                    var lastMonth = reportDate.AddMonths(-1);

                    var importSx1sOneMonth = (from i in vfi.ImportFormSX1Detail
                                              where
                                                  i.ImportFormSX1.MaterialUseDate < reportDate &&
                                                  i.ImportFormSX1.MaterialUseDate > lastMonth &&
                                                  i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                  i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                  i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                   .Transaction.Status ==
                                                  (byte)MyUtilities.Transaction.Status.Approved
                                                  && machineIds.Contains(i.MachineId.Value)
                                              select i);
                    //if (!importSx1s.Any())
                    //    throw new AggregateException("Không có gì để báo cáo");
                    var productIds = new List<int>();
                    foreach (var machine in machines) {
                        var importSx1sById = importSx1s.Where(i => i.MachineId == machine.MachineId).ToList();
                        if (!importSx1sById.Any()) {
                            var entity = new ProductionPlanModel() {
                                MachineId = machine.MachineId,
                                MachineName = machine.MachineName,
                                //ProductId = importSx1sByIdFirst.ProductId,
                                //ProductCode = importSx1sByIdFirst.Product.ProductCode
                            };
                            model.Add(entity);
                            importSx1sById = importSx1sOneMonth.Where(i => i.MachineId == machine.MachineId).ToList();
                            var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, null, reportDate);
                            if (lastTrack == null && !importSx1sById.Any()) continue;

                            if (importSx1sById.Any()) {
                                var lastImport = importSx1sById.LastOrDefault();
                                entity.ProductId = lastImport.ProductId;
                                entity.ProductCode = lastImport.Product.ProductCode;
                                entity.ProductionRate = lastImport.ProductionRate;
                                if (lastTrack.ProductId != entity.ProductId) {
                                    lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, entity.ProductId, reportDate);
                                }
                                if (lastTrack != null) {
                                    entity.Productivity = lastTrack.RealProductivity;
                                }
                                entity.LastActive = lastImport.ImportFormSX1.MaterialUseDate;
                            }
                            else if (lastTrack != null) {
                                entity.ProductId = lastTrack.ProductId;
                                entity.ProductCode = lastTrack.ProductCode;
                                entity.Productivity = lastTrack.RealProductivity;
                                entity.ProductionRate = lastTrack.RealRate;
                                entity.LastActive = lastTrack.ReportDate;
                            }
                            var materialUse = materialUses.Where(mu => mu.MachineId == machine.MachineId);
                            if (materialUse.Any())
                                entity.MaterialUse = materialUse.Sum(mu => mu.Quantity);
                            continue;
                        }
                        productIds = importSx1sById.Select(i => i.ProductId).Distinct().ToList();
                        foreach (var productId in productIds) {
                            importSx1sById = importSx1s
                                .Where(i => i.MachineId == machine.MachineId && i.ProductId == productId)
                                .ToList();
                            var importSx1sByIdFirst = importSx1sById.FirstOrDefault();

                            var entity = new ProductionPlanModel() {
                                MachineId = machine.MachineId,
                                MachineName = machine.MachineName,
                                ProductId = importSx1sByIdFirst.ProductId,
                                ProductCode = importSx1sByIdFirst.Product.ProductCode,
                                Quantity = importSx1sById.Sum(i => i.Number1 + i.Number2),
                                Processing = importSx1sById.Sum(i => i.Processing1 + i.Processing2),
                                Defect = importSx1sById.Sum(i => i.DefectProduct1 + i.DefectProduct2),
                                MaterialUse = importSx1sById.Sum(i => i.MaterialUse1 + i.MaterialUse2),
                                ProductionRate = importSx1sByIdFirst.ProductionRate,
                            };
                            var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, entity.ProductId, reportDate);
                            if (lastTrack != null) {
                                entity.Productivity = lastTrack.RealProductivity;
                            }
                            model.Add(entity);
                        }
                    }
                    #endregion

                    #region part 2 : calculate order - forecast - require production

                    productIds = model.Select(m => m.ProductId).Distinct().ToList();
                    var forecastInMonths = from f in vfi.ForecastOrders
                                           where productIds.Contains(f.ProductId) &&
                                           f.ForecastDate.Month == reportDate.Month &&
                                           f.ForecastDate.Year == reportDate.Year &&
                                           f.Status == (byte)MyUtilities.Transaction.Status.Approved
                                           select f;
                    var nextMonth = reportDate.AddMonths(1);
                    var forecastNextMonths = from f in vfi.ForecastOrders
                                             where productIds.Contains(f.ProductId) &&
                                             f.ForecastDate.Month == nextMonth.Month &&
                                                f.ForecastDate.Year == nextMonth.Year &&
                                             f.Status == (byte)MyUtilities.Transaction.Status.Approved
                                             select f;
                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvs = from pi in vfi.ProductInventories
                                      where productIds.Contains(pi.ProductId) &&
                                      warehouses.Contains(pi.WarehouseId) &&
                                      pi.TotalQty > 0
                                      select pi;
                    var startMonth = new DateTime(reportDate.Year, reportDate.Month, 1);

                    var orders = from od in vfi.OrderDetails
                                 where productIds.Contains(od.ProductId) &&
                                 od.RequiedNumber > 0 &&
                                 od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                                 od.Order.Status != (byte)MyUtilities.Sales.Status.Completed &&
                                 od.Order.DueDate < startMonth
                                 select od;

                    var exports = from id in vfi.InvoiceDetails
                                  where id.Active &&
                                        id.Invoice.ShipmentDate.Value.Month == reportDate.Month &&
                                        id.Invoice.ShipmentDate.Value.Year == reportDate.Year &&
                                        productIds.Contains(id.ProductId.Value)
                                  //(customerId == 0 || id.Invoice.CustomerId == customerId)
                                  select new {
                                      id.Piece,
                                      id.ProductId
                                  };
                    foreach (var productId in productIds) {

                        var entities = model.Where(m => m.ProductId == productId);
                        //if (!entities.Any())
                        //    continue;
                        var production = new ProductionOrderModel {
                            MachineCount = entities.Count()
                        };

                        production.TotalInv = productInvs.Where(pi => pi.ProductId == productId).ToList()
                            .Sum(pi => pi.TotalQty);
                        production.Order = orders.Where(o => o.ProductId == productId).ToList()
                            .Sum(o => o.RequiedNumber);
                        var forecast = forecastInMonths.FirstOrDefault(f => f.ProductId == productId);
                        if (forecast != null) {
                            production.ForecastInMonth = forecast.Quantity;
                            production.ForecastDate = forecast.ForecastDate;
                            production.ForecastDateStr = forecast.ForecastDate.ToString("dd/MM/yyyy");
                        }
                        forecast = forecastNextMonths.FirstOrDefault(f => f.ProductId == productId);
                        if (forecast != null) {
                            production.ForecastNextMonth = forecast.Quantity;
                            production.ForecastNextDate = forecast.ForecastDate;
                            production.ForecastNextDateStr = forecast.ForecastDate.ToString("dd/MM/yyyy");

                        }
                        var exportsById = exports.Where(e => e.ProductId == productId).ToList();
                        production.ExportSales = exportsById.Sum(e => e.Piece);

                        if (production.TotalInv + production.ExportSales >
                            production.ForecastInMonth + production.Order) {
                            production.TotalRequire =
                                (production.ForecastInMonth - production.ExportSales - production.TotalInv)
                                + production.Order + production.ForecastNextMonth;
                            production.RequireDate = production.ForecastNextDate;
                        }
                        else {
                            production.TotalRequire =
                                (production.ForecastInMonth - production.ExportSales - production.TotalInv)
                                + production.Order;
                            production.RequireDate = production.ForecastDate;
                        }
                        if (production.TotalRequire <= 0) {
                            production.TotalRequire = 0;
                            production.RequireDate = null;
                        }
                        else
                            production.ProductionDay =
                                MyUtilities.Product.GetProductionDay(productId, production.RequirePerMachine) + 6;
                        if (production.ProductionDay > 0 && production.RequireDate != null) {
                            production.RequireDate =
                                MyUtilities.Function.FromDate(production.RequireDate.Value, production.ProductionDay);
                        }
                        foreach (var entity in entities) {
                            var clone = production.Clone();
                            entity.ProductionOrder = clone;
                            if (clone.TotalRequire <= 0) continue;
                            if (clone.RequireDate < DateTime.Now) {
                                if (clone.RequireDate.Value.AddDays(6) < DateTime.Now) {
                                    clone.AlertColor = 1;
                                }
                                else
                                    clone.AlertColor = 2;
                                continue;
                            }
                            if (clone.TotalRequire > 0 && clone.RequireDate != null)
                                clone.ProductionDayLeft = MyUtilities.Function.DaysNoSunDay(DateTime.Now, clone.RequireDate.Value);

                        }
                    }
                    #endregion
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionPlanReport", ex.Message);
            }
            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult SelectProductionDailyReport(string productName, string monthlyDate,
            bool cames, bool cnc, bool phay, bool vf1, bool vf2) {
            var model = new List<ProductionDailyReport>();
            try {
                model = GetProductionDailyReport_2(productName, monthlyDate,
                    cames, cnc, phay,
                    vf1, vf2,
                    (int)MyUtilities.Report.Calculate.InPeriod);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionDailyReport", ex.Message);
            }
            return View(new GridModel(model.OrderBy(m => m.MachineName)));
        }


        private List<ProductionDailyReport> GetProductionDailyReport_2(string productCode, string monthlyDate,
            bool cames, bool cnc, bool phay, bool vf1, bool vf2, int calculateMode) {
            var model = new List<ProductionDailyReport>();
            if (!cames && !cnc && !phay) return model;
            var reportDate = MyUtilities.Function.ParseDate(monthlyDate);
            using (var vfi = new tammaContext()) {
                var shift1Name = "";
                var shift2Name = "";
                var display = (cames || cnc);
                if (!display)
                    goto phayPart;
                var machines = vfi.Machines.Where(m => m.Active
                    //&& ( (cnc && m.MachineName.Contains("CNC")) ||
                    //    (cames && m.MachineName.Contains("C") && !m.MachineName.Contains("CNC")) ||
                    //    (phay && m.MachineName.Contains("P")))
                    && m.MachineName != null
                    //&& !string.IsNullOrWhiteSpace(m.MachineName)
                    ).OrderBy(m => m.MachineName).ToList();
                //
                if (cames && cnc) {
                }
                else if (cames) {
                    machines = machines.Where(i => i.MachineName.Contains("C") && !i.MachineName.Contains("CNC")).ToList();
                }
                else if (cnc) {
                    machines = machines.Where(i => i.MachineName.Contains("CNC")).ToList();
                }
                if (!phay) {
                    machines = machines.Where(i => !i.MachineName.Contains("P")).ToList();
                }
                //
                if (vf1 == vf2) {
                }
                else if (vf1) {
                    machines = machines.Where(i => !i.MachineName.Contains("VF2")).ToList();
                }
                else if (vf2) {
                    machines = machines.Where(i => i.MachineName.Contains("VF2")).ToList();
                }
                var machineIds = machines.Select(m => m.MachineId).ToList();

                #region sx1
                //var toDate = reportDate.AddDays(1).AddSeconds(-1);
                var importSx1InDays = (from i in vfi.ImportFormSX1
                                       where
                                           //i.MaterialUseDate >= reportDate &&
                                           //i.MaterialUseDate <= toDate &&
                                           i.MaterialUseDate.Day == reportDate.Day &&
                                           i.MaterialUseDate.Month == reportDate.Month &&
                                           i.MaterialUseDate.Year == reportDate.Year &&
                                           i.ImportWorkpieceMaterials.Any() &&
                                           i.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                           i.ImportWorkpieceMaterials.FirstOrDefault()
                                            .Transaction.Status ==
                                           (byte)MyUtilities.Transaction.Status.Approved
                                       select i).ToList();
                if (!importSx1InDays.Any())
                    goto phayPart;
                var importSx = importSx1InDays.FirstOrDefault(i => !i.Shift1Name.Trim().Equals(""));
                if (importSx != null) {
                    shift1Name = importSx.Shift1Name;
                    shift1Name = shift1Name.Replace("1", "");
                    shift1Name = shift1Name.Replace("2", "");
                }
                importSx = importSx1InDays.FirstOrDefault(i => !i.Shift2Name.Trim().Equals(""));
                if (importSx != null) {
                    shift2Name = importSx.Shift2Name;
                    shift2Name = shift2Name.Replace("1", "");
                    shift2Name = shift2Name.Replace("2", "");
                }

                //var startDate = new DateTime(reportDate.Year, reportDate.Month, 26);
                //if (reportDate < startDate)
                //    startDate = startDate.AddMonths(-1);
                //var importDate = importSx1InDays.Max(x => x.ImportDate);
                //var materialUseDate = importSx1InDays.FirstOrDefault().MaterialUseDate;
                //var point = MyUtilities.Product.BaseProductionPrice;
                var productionPriceRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseProductionPriceRate);
                var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                //var inventoryRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseInventoryPriceRate);
                var importSx1s = (from i in vfi.ImportFormSX1Detail
                                 where
                                     //i.ImportFormSX1.ImportDate <= importDate &&
                                     //i.ImportFormSX1.MaterialUseDate >= startDate MaterialUseDate
                                     i.ImportFormSX1.MaterialUseDate.Month == reportDate.Month &&
                                     i.ImportFormSX1.MaterialUseDate.Year == reportDate.Year &&
                                     i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                     //i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                     //i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                      // .Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                     //&& i.Product.ProductCode.Contains(productCode) 
                                       machineIds.Contains(i.MachineId.Value) &&
                                      i.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                 select new {
                                     i.ImportFormSX1,
                                     i.ImportFormSX1.MaterialUseDate,
                                     i.ImportFormSX1.ImportDate,
                                     i.MachineId,
                                     i.Machine1.MachineName,
                                     ProcessingFactor = i.Machine1.ProcessingType.ProcessingFactor ?? 0,
                                     i.MaterialInvId,
                                     i.MaterialInventory.MaterialId,
                                     MaterialPrice = i.MaterialInventory.UnitPrice * i.MaterialInventory.UnitWeight,
                                     MaterialWeight = i.MaterialInventory.UnitWeight,
                                     i.ImportFormSX1.Shift1Name,
                                     i.ImportFormSX1.Shift2Name,
                                     i.Number1,
                                     i.Number2,
                                     i.Processing1,
                                     i.Processing2,
                                     i.DefectProduct1,
                                     i.DefectProduct2,
                                     i.MaterialUse1,
                                     i.MaterialUse2,
                                     ProductionRate = i.ProductionRate > 0 ? i.ProductionRate : 0,
                                     i.ProductWeight,
                                     i.MaterialUseDetail,
                                     ProductionMaterial1 = i.ProductionRate > 0 ?
                                     Math.Round((i.Number1 + i.Processing1 + i.DefectProduct1) / i.ProductionRate, 2) : 0,
                                     ProductionMaterial2 = i.ProductionRate > 0 ?
                                     Math.Round((i.Number2 + i.Processing2 + i.DefectProduct2) / i.ProductionRate, 2) : 0,
                                     i.ProductId,
                                     i.Product.Productivity,
                                     i.Product.ProductCode,
                                     //ProductPrice = Math.Round(i.Product.UnitPrice ?? 0, 4) -
                                     //              Math.Round(i.Product.UnitPrice ?? 0, 0) == 0
                                     //                  ? Math.Round((i.Product.UnitPrice ?? 0) * point, 0)
                                     //                  : Math.Round((i.Product.UnitPrice ?? 0) *
                                     //                    MyUtilities.Product.ExchangeRateDesign * point, 0),

                                     ProductPrice = i.Product.UnitPrice <= MyUtilities.Product.MinVndPrice
                                                 ? (i.Product.UnitPrice ?? 0) * exchangeRate * productionPriceRate
                                                 : Math.Round(i.Product.UnitPrice ?? 0, 4) - Math.Round(i.Product.UnitPrice ?? 0, 0) == 0
                                                     ? (i.Product.UnitPrice ?? 0) * productionPriceRate
                                                     : (i.Product.UnitPrice ?? 0) * exchangeRate * productionPriceRate,
                                 }).ToList();

                if (!string.IsNullOrWhiteSpace(productCode)) {
                    importSx1s = importSx1s.Where(x => x.ProductCode.Contains(productCode)).ToList();
                }
                //var display = (cames || cnc);
                // shift A
                var productionByShift = importSx1s.Where(i => i.Shift1Name.Contains("A") || i.Shift2Name.Contains("A")).ToList();
                var totalShiftA = new Shift();
                totalShiftA.Count = productionByShift.Select(i => i.MaterialUseDate).Distinct().ToList().Count;
                productionByShift = importSx1s.Where(i => i.Shift1Name.Contains("A")).ToList();
                if (productionByShift.Any()) {
                    totalShiftA.Quantity = productionByShift.Sum(i => i.Number1); //6
                    totalShiftA.ProductCost = productionByShift
                           .Sum(i => Math.Round((i.Number1) * i.ProductPrice / 1000000,
                               MyUtilities.Product.ProductionDecimalPoint));

                    totalShiftA.ProcessingQuantity = productionByShift.Sum(i => i.Processing1); //9
                    totalShiftA.DefectQuantity = productionByShift.Sum(i => i.DefectProduct1);
                    // luỹ kế NG price
                    totalShiftA.NGCost = productionByShift.Sum(i => (i.Processing1 + i.DefectProduct1) * i.ProductPrice);

                    totalShiftA.MaterialUse = productionByShift.Sum(i => i.MaterialUse1); //3
                    totalShiftA.MaterialDiff = productionByShift.Sum(i => i.MaterialUse1 - i.ProductionMaterial1); //13
                    totalShiftA.MaterialDiffCost =
                        productionByShift.Sum(i => (i.MaterialUse1 - i.ProductionMaterial1) * i.MaterialPrice);
                }

                productionByShift = importSx1s.Where(i => i.Shift2Name.Contains("A")).ToList();
                if (productionByShift.Any()) {
                    totalShiftA.Quantity += productionByShift.Sum(i => i.Number2); //6
                    totalShiftA.ProductCost += productionByShift
                           .Sum(i => Math.Round((i.Number2) * i.ProductPrice / 1000000,
                               MyUtilities.Product.ProductionDecimalPoint));

                    totalShiftA.ProcessingQuantity += productionByShift.Sum(i => i.Processing2); //9
                    totalShiftA.DefectQuantity += productionByShift.Sum(i => i.DefectProduct2);
                    // luỹ kế NG price
                    totalShiftA.NGCost += productionByShift.Sum(i => (i.Processing2 + i.DefectProduct2) * i.ProductPrice);

                    totalShiftA.MaterialUse += productionByShift.Sum(i => i.MaterialUse2); //3
                    totalShiftA.MaterialDiff += productionByShift.Sum(i => i.MaterialUse2 - i.ProductionMaterial2); //13
                    totalShiftA.MaterialDiffCost +=
                        productionByShift.Sum(i => (i.MaterialUse2 - i.ProductionMaterial2) * i.MaterialPrice);
                }
                // shift B
                productionByShift = importSx1s.Where(i => i.Shift1Name.Contains("B") || i.Shift2Name.Contains("B")).ToList();
                var totalShiftB = new Shift();
                totalShiftB.Count = productionByShift.Select(i => i.MaterialUseDate).Distinct().ToList().Count;
                productionByShift = importSx1s.Where(i => i.Shift1Name.Contains("B")).ToList();
                if (productionByShift.Any()) {
                    totalShiftB.Quantity = productionByShift.Sum(i => i.Number1); //6
                    totalShiftB.ProductCost = productionByShift
                           .Sum(i => Math.Round((i.Number1) * i.ProductPrice / 1000000,
                               MyUtilities.Product.ProductionDecimalPoint));

                    totalShiftB.ProcessingQuantity = productionByShift.Sum(i => i.Processing1); //9
                    totalShiftB.DefectQuantity = productionByShift.Sum(i => i.DefectProduct1);
                    // luỹ kế NG price
                    totalShiftB.NGCost = productionByShift.Sum(i => (i.Processing1 + i.DefectProduct1) * i.ProductPrice);

                    totalShiftB.MaterialUse = productionByShift.Sum(i => i.MaterialUse1); //3
                    totalShiftB.MaterialDiff = productionByShift.Sum(i => i.MaterialUse1 - i.ProductionMaterial1); //13
                    totalShiftB.MaterialDiffCost =
                        productionByShift.Sum(i => (i.MaterialUse1 - i.ProductionMaterial1) * i.MaterialPrice);
                }

                productionByShift = importSx1s.Where(i => i.Shift2Name.Contains("B")).ToList();
                if (productionByShift.Any()) {
                    totalShiftB.Quantity += productionByShift.Sum(i => i.Number2); //6
                    totalShiftB.ProductCost += productionByShift
                           .Sum(i => Math.Round((i.Number2) * i.ProductPrice / 1000000,
                               MyUtilities.Product.ProductionDecimalPoint));

                    totalShiftB.ProcessingQuantity += productionByShift.Sum(i => i.Processing2); //9
                    totalShiftB.DefectQuantity += productionByShift.Sum(i => i.DefectProduct2);
                    // luỹ kế NG price
                    totalShiftB.NGCost += productionByShift.Sum(i => (i.Processing2 + i.DefectProduct2) * i.ProductPrice);

                    totalShiftB.MaterialUse += productionByShift.Sum(i => i.MaterialUse2); //3
                    totalShiftB.MaterialDiff += productionByShift.Sum(i => i.MaterialUse2 - i.ProductionMaterial2); //13
                    totalShiftB.MaterialDiffCost +=
                        productionByShift.Sum(i => (i.MaterialUse2 - i.ProductionMaterial2) * i.MaterialPrice);
                }
                // shift C
                productionByShift = importSx1s.Where(i => i.Shift1Name.Contains("C") || i.Shift2Name.Contains("C")).ToList();
                var totalShiftC = new Shift();
                totalShiftC.Count = productionByShift.Select(i => i.MaterialUseDate).Distinct().ToList().Count;
                productionByShift = importSx1s.Where(i => i.Shift1Name.Contains("C")).ToList();
                if (productionByShift.Any()) {
                    totalShiftC.Quantity = productionByShift.Sum(i => i.Number1); //6
                    totalShiftC.ProductCost = productionByShift
                           .Sum(i => Math.Round((i.Number1) * i.ProductPrice / 1000000,
                               MyUtilities.Product.ProductionDecimalPoint));

                    totalShiftC.ProcessingQuantity = productionByShift.Sum(i => i.Processing1); //9
                    totalShiftC.DefectQuantity = productionByShift.Sum(i => i.DefectProduct1);
                    // luỹ kế NG price
                    totalShiftC.NGCost = productionByShift.Sum(i => (i.Processing1 + i.DefectProduct1) * i.ProductPrice);

                    totalShiftC.MaterialUse = productionByShift.Sum(i => i.MaterialUse1); //3
                    totalShiftC.MaterialDiff = productionByShift.Sum(i => i.MaterialUse1 - i.ProductionMaterial1); //13
                    totalShiftC.MaterialDiffCost =
                        productionByShift.Sum(i => (i.MaterialUse1 - i.ProductionMaterial1) * i.MaterialPrice);
                }

                productionByShift = importSx1s.Where(i => i.Shift2Name.Contains("C")).ToList();
                if (productionByShift.Any()) {
                    totalShiftC.Quantity += productionByShift.Sum(i => i.Number2); //6
                    totalShiftC.ProductCost += productionByShift
                           .Sum(i => Math.Round((i.Number2) * i.ProductPrice / 1000000,
                               MyUtilities.Product.ProductionDecimalPoint));

                    totalShiftC.ProcessingQuantity += productionByShift.Sum(i => i.Processing2); //9
                    totalShiftC.DefectQuantity += productionByShift.Sum(i => i.DefectProduct2);
                    // luỹ kế NG price
                    totalShiftC.NGCost += productionByShift.Sum(i => (i.Processing2 + i.DefectProduct2) * i.ProductPrice);

                    totalShiftC.MaterialUse += productionByShift.Sum(i => i.MaterialUse2); //3
                    totalShiftC.MaterialDiff += productionByShift.Sum(i => i.MaterialUse2 - i.ProductionMaterial2); //13
                    totalShiftC.MaterialDiffCost +=
                        productionByShift.Sum(i => (i.MaterialUse2 - i.ProductionMaterial2) * i.MaterialPrice);
                }

                var reports = importSx1s.Where(i => i.MaterialUseDate.Day == reportDate.Day
                    && i.MaterialUseDate.Month == reportDate.Month
                    && i.MaterialUseDate.Year == reportDate.Year).ToList();
                var materialUseDetailIds = reports.Where(i => i.MaterialUseDetail != null)
                    .Select(i => i.MaterialUseDetail.DetailId)
                    .Distinct().ToList();

                var materialUseNotProduction = (from mud in vfi.MaterialUseDetails
                                               where mud.MaterialUseInShift.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                               mud.MaterialUseInShift.Type == 1 &&
                                               mud.MaterialUseInShift.UsedDate == reportDate &&
                                               machineIds.Contains(mud.MachineId) &&
                                              !materialUseDetailIds.Contains(mud.DetailId)
                                               select mud).ToList();
                foreach (var machine in machines) {
                    var text = reportDate.ToString("dd/MM/yyyy");
                    if (machine.MachineName.Contains("CNC"))
                        text += " (CNC)";
                    else if (machine.MachineName.Contains("P"))
                        text += " (Phay)";
                    else
                        text += " (Cames)";
                    if (machine.MachineName.Contains("VF2"))
                        text += " VF2";
                    var reportsById = reports.Where(i => i.MachineId == machine.MachineId);
                    var machineStateName = "";
                    var emptyPlan = false;
                    if (machine.StateId != null) {
                        if (machine.StateId != MyUtilities.Machine.State.Normal
                            && machine.StateId != MyUtilities.Machine.State.EmptyMachine) {
                            machineStateName = machine.MachineState.Description;
                        }
                        if (MyUtilities.Machine.State.GetNoneProductonStateList().Contains(machine.StateId.Value)) {
                            emptyPlan = true;
                        }
                    }

                    if (!reportsById.Any())
                        goto notProductionPart;
                    foreach (var sx1Detail in reportsById) {
                        var entity =
                            model.FirstOrDefault(
                                m =>
                                m.MachineId == machine.MachineId &&
                                m.MaterialInvId == sx1Detail.MaterialInvId &&
                                m.ProductId == sx1Detail.ProductId);
                        if (entity == null) {
                            entity = new ProductionDailyReport {
                                MachineId = machine.MachineId,
                                MachineName = machine.MachineName,
                                MaterialInvId = sx1Detail.MaterialInvId.Value,
                                ProductId = sx1Detail.ProductId,
                                ProductCode = sx1Detail.ProductCode,
                                ProductionRate = sx1Detail.ProductionRate,
                                Productivity = sx1Detail.Productivity ?? 0,
                                UnitWeight = sx1Detail.ProductWeight,
                                ReportDate = reportDate,
                                ReportDateString = text,
                                ProductivityAlarm = 0,
                                ProductivityAlarm2 = 0,
                                Shift1Name = shift1Name,
                                Shift2Name = shift2Name,
                                Shift1Count = 0,
                                Shift2Count = 0,
                                DisplaySum = display,
                                ShiftA = totalShiftA,
                                ShiftB = totalShiftB,
                                ShiftC = totalShiftC,
                                UnitPrice = sx1Detail.ProductPrice,
                                MachineStateName = machineStateName,
                                EmptyPlan = emptyPlan,
                            };
                            if (sx1Detail.MaterialUseDetail != null) {
                                entity.LotNumber = sx1Detail.MaterialUseDetail.Lot;
                            }
                            var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                entity.MachineId,
                                sx1Detail.MaterialId,
                                entity.ProductId,
                                sx1Detail.MaterialUseDate);
                            if (lastTrack != null) {
                                entity.Productivity = lastTrack.RealProductivity;
                            }
                            entity.ProductUnitPrice = entity.Productivity * sx1Detail.ProcessingFactor;

                            var shift1 = new Shift {
                                ShiftName = shift1Name,
                                Quantity = sx1Detail.Number1,
                                ProcessingQuantity = sx1Detail.Processing1,
                                DefectQuantity = sx1Detail.DefectProduct1,
                                MaterialUse = sx1Detail.MaterialUse1,
                                ProductionRate = entity.ProductionRate,
                                ProductionPrice = sx1Detail.Number1 * 5, // ? quên cmnr
                                ProductCost = Math.Round(sx1Detail.Number1 * entity.UnitPrice / 1000000,
                                MyUtilities.Product.ProductionDecimalPoint),
                                ProductivityInShift = entity.ProductivityInShift,
                                MaterialDiff = sx1Detail.MaterialUse1 - sx1Detail.ProductionMaterial1,
                                MaterialDiffCost = (sx1Detail.MaterialUse1 - sx1Detail.ProductionMaterial1)
                                * sx1Detail.MaterialPrice,

                                NGCost = (sx1Detail.Processing1 + sx1Detail.DefectProduct1) * entity.UnitPrice
                            };
                            if (shift1.Quantity + shift1.ProcessingQuantity + shift1.DefectQuantity +
                                shift1.MaterialUse > 0) {
                                entity.Shift1Count = 1;
                                shift1.Count = 1;
                            }
                            //
                            var shift2 = new Shift {
                                ShiftName = shift2Name,
                                Quantity = sx1Detail.Number2,
                                ProcessingQuantity = sx1Detail.Processing2,
                                DefectQuantity = sx1Detail.DefectProduct2,
                                MaterialUse = sx1Detail.MaterialUse2,
                                ProductionRate = entity.ProductionRate,
                                ProductionPrice = sx1Detail.Number2 * 5,
                                ProductCost = Math.Round(sx1Detail.Number2 * entity.UnitPrice / 1000000,
                                MyUtilities.Product.ProductionDecimalPoint),
                                ProductivityInShift = entity.ProductivityInShift,
                                MaterialDiff = sx1Detail.MaterialUse2 - sx1Detail.ProductionMaterial2,
                                MaterialDiffCost = (sx1Detail.MaterialUse2 - sx1Detail.ProductionMaterial2)
                                * sx1Detail.MaterialPrice,
                                NGCost = (sx1Detail.Processing2 + sx1Detail.DefectProduct2) * entity.UnitPrice
                            };
                            if (shift2.Quantity + shift2.ProcessingQuantity + shift2.DefectQuantity +
                                shift2.MaterialUse > 0) {
                                entity.Shift2Count = 1;
                                shift2.Count = 1;
                            }

                            entity.Shifts.Add(shift1);
                            entity.Shifts.Add(shift2);
                            model.Add(entity);
                        }
                        else {// empty value

                            entity.Shifts[0].Quantity += sx1Detail.Number1;
                            entity.Shifts[1].Quantity += sx1Detail.Number2;
                            entity.Shifts[0].ProcessingQuantity += sx1Detail.Processing1;
                            entity.Shifts[1].ProcessingQuantity += sx1Detail.Processing2;
                            entity.Shifts[0].DefectQuantity += sx1Detail.DefectProduct1;
                            entity.Shifts[1].DefectQuantity += sx1Detail.DefectProduct2;

                            entity.Shifts[0].NGCost = (entity.Shifts[0].ProcessingQuantity + entity.Shifts[0].DefectQuantity)
                                * entity.UnitPrice;
                            entity.Shifts[1].NGCost = (entity.Shifts[1].ProcessingQuantity + entity.Shifts[1].DefectQuantity)
                                * entity.UnitPrice;
                            entity.Shifts[0].MaterialUse += sx1Detail.MaterialUse1;
                            entity.Shifts[0].MaterialDiff += sx1Detail.MaterialUse1 - sx1Detail.ProductionMaterial1;
                            entity.Shifts[0].MaterialDiffCost += ((sx1Detail.MaterialUse1 - sx1Detail.ProductionMaterial1)
                               * sx1Detail.MaterialPrice);
                            entity.Shifts[1].MaterialUse += sx1Detail.MaterialUse2;
                            entity.Shifts[1].MaterialDiff += sx1Detail.MaterialUse2 - sx1Detail.ProductionMaterial2;
                            entity.Shifts[1].MaterialDiffCost += ((sx1Detail.MaterialUse2 - sx1Detail.ProductionMaterial2)
                               * sx1Detail.MaterialPrice);

                            entity.Shifts[0].ProductionPrice = entity.Shifts[0].Quantity * 5;
                            entity.Shifts[0].ProductCost = Math.Round(entity.Shifts[0].Quantity * entity.UnitPrice / 1000000,
                                 MyUtilities.Product.ProductionDecimalPoint);

                            entity.Shifts[1].ProductionPrice = entity.Shifts[1].Quantity * 5;
                            entity.Shifts[1].ProductCost = Math.Round(entity.Shifts[1].Quantity * entity.UnitPrice / 1000000,
                                 MyUtilities.Product.ProductionDecimalPoint);

                            if (entity.Shifts[0].Quantity != 0 || entity.Shifts[0].ProcessingQuantity != 0 ||
                                entity.Shifts[0].DefectQuantity != 0 || entity.Shifts[0].MaterialUse != 0) {
                                entity.Shift1Count = 1;
                                entity.Shifts[0].Count = 1;
                            }
                            if (entity.Shifts[1].Quantity != 0 || entity.Shifts[1].ProcessingQuantity != 0 ||
                                entity.Shifts[1].DefectQuantity != 0 || entity.Shifts[1].MaterialUse != 0) {
                                entity.Shift2Count = 1;
                                entity.Shifts[1].Count = 1;
                            }
                        }
                    }

                notProductionPart: {
                        var notProductionsById = materialUseNotProduction.Where(mud => mud.MachineId == machine.MachineId);
                        if (!notProductionsById.Any()) {
                            goto emptyProductionPart;
                        }
                        foreach (var materialUse in notProductionsById) {

                            var entity =
                                model.FirstOrDefault(
                                    m =>
                                    m.MachineId == machine.MachineId && m.MaterialInvId == materialUse.MaterialInvId);
                            if (entity != null) {
                                entity.Shifts[0].MaterialUse += materialUse.EditQuantity;
                                entity.Shifts[1].MaterialUse += materialUse.EditQuantity2;
                                if (entity.Shifts[0].Quantity != 0 || entity.Shifts[0].ProcessingQuantity != 0 ||
                                    entity.Shifts[0].DefectQuantity != 0 || entity.Shifts[0].MaterialUse != 0) {
                                    entity.Shift1Count = 1;
                                    entity.Shifts[0].Count = 1;
                                }
                                if (entity.Shifts[1].Quantity != 0 || entity.Shifts[1].ProcessingQuantity != 0 ||
                                    entity.Shifts[1].DefectQuantity != 0 || entity.Shifts[1].MaterialUse != 0) {
                                    entity.Shift2Count = 1;
                                    entity.Shifts[1].Count = 1;
                                }
                            }
                            else {

                                entity = new ProductionDailyReport {
                                    MachineId = machine.MachineId,
                                    MachineName = machine.MachineName,
                                    MaterialInvId = materialUse.MaterialInvId,
                                    //ProductId = sx1Detail.ProductId,
                                    //ProductCode = sx1Detail.ProductCode,
                                    //ProductionRate = sx1Detail.ProductionRate,
                                    //ProductionRate = 0,
                                    //Productivity = sx1Detail.Productivity ?? 0,
                                    //UnitWeight = sx1Detail.ProductWeight,
                                    ReportDate = reportDate,
                                    ReportDateString = text,
                                    ProductivityAlarm = 0,
                                    ProductivityAlarm2 = 0,
                                    Shift1Name = shift1Name,
                                    Shift2Name = shift2Name,
                                    Shift1Count = 0,
                                    Shift2Count = 0,
                                    DisplaySum = display,
                                    ShiftA = totalShiftA,
                                    ShiftB = totalShiftB,
                                    ShiftC = totalShiftC,
                                    MachineStateName = machineStateName,
                                    EmptyPlan = emptyPlan,
                                };

                                var lastProduction = vfi.ImportFormSX1Detail.Where(id => id.MachineId == machine.MachineId
                                    && id.MaterialInventory.MaterialId == materialUse.MaterialInventory.MaterialId
                                    && id.ImportFormSX1.MaterialUseDate < reportDate)
                                    .OrderByDescending(id => id.ImportFormSX1.MaterialUseDate)
                                    .FirstOrDefault();
                                if (lastProduction != null) {
                                    entity.ProductId = lastProduction.ProductId;
                                    entity.ProductCode = lastProduction.Product.ProductCode;
                                    entity.ProductionRate = lastProduction.ProductionRate;
                                    entity.UnitWeight = lastProduction.ProductWeight;
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                        entity.MachineId,
                                        materialUse.MaterialInventory.MaterialId,
                                        entity.ProductId,
                                        reportDate);
                                    if (lastTrack != null) {
                                        entity.Productivity = lastTrack.RealProductivity;
                                    }
                                }
                                else {
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                        entity.MachineId,
                                        materialUse.MaterialInventory.MaterialId,
                                        null,
                                        reportDate);
                                    if (lastTrack != null) {
                                        entity.ProductId = lastTrack.ProductId;
                                        entity.ProductCode = lastTrack.ProductCode;
                                        entity.Productivity = lastTrack.RealProductivity;
                                        entity.UnitWeight = lastTrack.ProductionWeight;
                                    }
                                }
                                var shift1 = new Shift {
                                    ShiftName = shift1Name,
                                    MaterialUse = materialUse.EditQuantity,
                                    ProductivityInShift = entity.ProductivityInShift,
                                    MaterialDiff = materialUse.EditQuantity,
                                    MaterialDiffCost = materialUse.EditQuantity * materialUse.MaterialInventory.UnitPrice
                                };
                                if (shift1.MaterialUse > 0) {
                                    entity.Shift1Count = 1;
                                    shift1.Count = 1;
                                }
                                var shift2 = new Shift {
                                    ShiftName = shift1Name,
                                    MaterialUse = materialUse.EditQuantity2,
                                    ProductivityInShift = entity.ProductivityInShift,
                                    MaterialDiff = materialUse.EditQuantity2,
                                    MaterialDiffCost = materialUse.EditQuantity2 * materialUse.MaterialInventory.UnitPrice
                                };
                                if (shift2.MaterialUse > 0) {
                                    entity.Shift2Count = 1;
                                    shift2.Count = 1;
                                }
                                entity.Shifts.Add(shift1);
                                entity.Shifts.Add(shift2);
                                model.Add(entity);

                            }
                        }
                    }

                emptyProductionPart: {
                        var entity = model.FirstOrDefault(m => m.MachineId == machine.MachineId);
                        if (entity == null) {
                            entity = new ProductionDailyReport {
                                MachineId = machine.MachineId,
                                MachineName = machine.MachineName,
                                ReportDate = reportDate,
                                ReportDateString = text,
                                ProductivityAlarm = 0,
                                ProductivityAlarm2 = 0,
                                Shift1Name = shift1Name,
                                Shift2Name = shift2Name,
                                Shift1Count = 0,
                                Shift2Count = 0,
                                DisplaySum = display,
                                ShiftA = totalShiftA,
                                ShiftB = totalShiftB,
                                ShiftC = totalShiftC,
                                MachineStateName = machineStateName,
                                EmptyPlan = emptyPlan,
                            };

                            var lastProduction = vfi.ImportFormSX1Detail.Where(id => id.MachineId == machine.MachineId &&
                                    id.ImportFormSX1.MaterialUseDate < reportDate)
                                .OrderByDescending(id => id.ImportFormSX1.MaterialUseDate)
                                .FirstOrDefault();
                            if (lastProduction != null) {
                                entity.ProductId = lastProduction.ProductId;
                                entity.ProductCode = lastProduction.Product.ProductCode;
                                entity.ProductionRate = lastProduction.ProductionRate;
                                entity.UnitWeight = lastProduction.ProductWeight;
                                var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                    entity.MachineId,
                                    lastProduction.MaterialInventory.MaterialId,
                                    entity.ProductId,
                                    reportDate);
                                if (lastTrack != null) {
                                    entity.Productivity = lastTrack.RealProductivity;
                                }
                            }
                            else {
                                var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, null, reportDate);
                                if (lastTrack != null) {
                                    entity.ProductId = lastTrack.ProductId;
                                    entity.ProductCode = lastTrack.ProductCode;
                                    entity.Productivity = lastTrack.RealProductivity;
                                    entity.UnitWeight = lastTrack.ProductionWeight;
                                }
                            }
                            var shift1 = new Shift {
                                ShiftName = shift1Name,
                                ProductivityInShift = 0,
                            };
                            var shift2 = new Shift {
                                ShiftName = shift2Name,
                                ProductivityInShift = 0,
                            };
                            entity.Shifts.Add(shift1);
                            entity.Shifts.Add(shift2);
                            model.Add(entity);
                        }

                    }
                }
                #endregion
            phayPart:
                #region phay
                if (!phay)
                    goto finishPart;
                var importCncs = from i in vfi.ImportFormCncs
                                 where
                                     i.MaterialUseDate == reportDate
                                 select i;
                foreach (var i in importCncs) {
                    var transactionDetails =
                        vfi.TransactionDetails.Where(
                            t =>
                            t.Transaction.TransactionCode.Equals(i.TransactionCode) &&
                            t.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved);
                    if (!transactionDetails.Any())
                        continue;
                    if (string.IsNullOrWhiteSpace(shift1Name))
                        shift1Name = i.Shift1Name;
                    if (string.IsNullOrWhiteSpace(shift2Name))
                        shift2Name = i.Shift2Name;
                    foreach (var detail in i.ImportFormCncDetails) {
                        if (detail.Number1 + detail.Number2 > 0) {
                            var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                td.ReferenceId == detail.ProductId &&
                                td.Quantity == detail.Number1 + detail.Number2 &&
                                td.Transaction.WarehouseReceiptId != MyUtilities.Warehouse.Processing &&
                                td.Transaction.WarehouseReceiptId != MyUtilities.Warehouse.Defect);
                            if (transactionDetailsById != null) {
                                var entity = model.FirstOrDefault(m => m.MachineId == detail.MachineId);
                                if (entity != null &&
                                    entity.ProductId == detail.ProductId) {
                                    entity.UnitWeight = detail.Product.CncWeight ?? 0;
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, entity.ProductId, detail.ImportFormCnc.MaterialUseDate);
                                    if (lastTrack != null) {
                                        if (detail.Productivity == 0)
                                            entity.Productivity = lastTrack.RealProductivity;
                                        if (detail.Rate == 0)
                                            entity.ProductionRate = lastTrack.RealRate;
                                    }
                                    else {
                                        entity.ProductionRate = detail.Rate;
                                        entity.Productivity = detail.Productivity;
                                    }

                                    entity.Shifts[0].ShiftName = shift1Name;
                                    entity.Shifts[0].Quantity += detail.Number1;
                                    entity.Shifts[0].ProductionPrice = entity.Shifts[0].Quantity * 5;
                                    entity.Shifts[0].ProductCost = entity.Shifts[0].Quantity * entity.UnitPrice;

                                    entity.Shift1Count = 1;
                                    entity.Shifts[0].Count = 1;

                                    entity.Shifts[1].ShiftName = shift2Name;
                                    entity.Shifts[1].Quantity += detail.Number2;
                                    entity.Shifts[1].ProductionPrice = entity.Shifts[1].Quantity * 5;
                                    entity.Shifts[1].ProductCost = entity.Shifts[1].Quantity * entity.UnitPrice;
                                    entity.Shift2Count = 1;
                                    entity.Shifts[1].Count = 1;
                                }
                                else {
                                    entity = new ProductionDailyReport {
                                        MachineId = detail.MachineId,
                                        MachineName = detail.Machine.MachineName,
                                        ProductId = detail.ProductId,
                                        ProductCode = detail.Product.ProductCode,
                                        ProductionRate = detail.Rate,
                                        Productivity = detail.Productivity,
                                        UnitWeight = detail.Product.CncWeight ?? 0,
                                        ReportDate = reportDate,
                                        ReportDateString = reportDate.ToString("dd/MM/yyyy") + "(Phay)",
                                        //ProductivityInShift = 0,
                                        //ProductivityInDay = 0,
                                        ProductivityAlarm = 0,
                                        ProductivityAlarm2 = 0,
                                        Shift1Name = shift1Name,
                                        Shift2Name = shift2Name,
                                        Shift1Count = 0,
                                        Shift2Count = 0,
                                        UnitPrice = (detail.Product.UnitPrice ?? 0),
                                        ShiftAProductionCostInMonth = 0,
                                        ShiftBProductionCostInMonth = 0,
                                        ShiftCProductionCostInMonth = 0,
                                        DisplaySum = display,
                                    };
                                    //entity.UnitPrice = MyUtilities.Product.StockPrice(detail.Product.UnitPrice ?? 0);
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                        entity.MachineId,
                                        null,
                                        entity.ProductId,
                                        detail.ImportFormCnc.MaterialUseDate);
                                    if (lastTrack != null) {
                                        if (detail.Productivity == 0)
                                            entity.Productivity = lastTrack.RealProductivity;
                                        if (detail.Rate == 0)
                                            entity.ProductionRate = lastTrack.RealRate;
                                    }
                                    entity.ProductUnitPrice = entity.Productivity *
                                                              detail.Machine.ProcessingType.ProcessingFactor.Value;
                                    var shift1 = new Shift {
                                        ShiftName = shift1Name,
                                        Quantity = detail.Number1,
                                    };
                                    if (shift1.TotalQuantity != 0) {
                                        entity.Shift1Count = 1;
                                        shift1.Count = 1;
                                    }
                                    var shift2 = new Shift {
                                        ShiftName = shift2Name,
                                        Quantity = detail.Number2,
                                    };
                                    if (shift2.TotalQuantity != 0) {
                                        entity.Shift2Count = 1;
                                        shift2.Count = 1;
                                    }
                                    entity.Shifts.Add(shift1);
                                    entity.Shifts.Add(shift2);
                                    model.Add(entity);
                                }
                            }
                        }

                        if (detail.Processing1 + detail.Processing2 > 0) {
                            var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                td.ReferenceId == detail.ProductId &&
                                td.Quantity == detail.Processing1 + detail.Processing2 &&
                                td.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Processing);
                            if (transactionDetailsById != null) {
                                var entity = model.FirstOrDefault(m => m.MachineId == detail.MachineId);
                                if (entity != null &&
                                    entity.ProductId == detail.ProductId) {
                                    entity.UnitWeight = detail.Product.CncWeight ?? 0;
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, entity.ProductId, detail.ImportFormCnc.MaterialUseDate);

                                    if (lastTrack != null) {
                                        if (detail.Productivity == 0)
                                            entity.Productivity = lastTrack.RealProductivity;
                                        if (detail.Rate == 0)
                                            entity.ProductionRate = lastTrack.RealRate;
                                    }
                                    else {
                                        entity.ProductionRate = detail.Rate;
                                        entity.Productivity = detail.Productivity;
                                    }

                                    entity.Shifts[0].ShiftName = shift1Name;
                                    entity.Shifts[0].ProcessingQuantity += detail.Processing1;
                                    entity.Shift1Count = 1;
                                    entity.Shifts[0].Count = 1;

                                    entity.Shifts[1].ShiftName = shift2Name;
                                    entity.Shifts[1].ProcessingQuantity += detail.Processing2;
                                    entity.Shift2Count = 1;
                                    entity.Shifts[1].Count = 1;
                                }
                                else {
                                    entity = new ProductionDailyReport {
                                        MachineId = detail.MachineId,
                                        MachineName = detail.Machine.MachineName,
                                        ProductId = detail.ProductId,
                                        ProductCode = detail.Product.ProductCode,
                                        ProductionRate = detail.Rate,
                                        Productivity = detail.Productivity,
                                        UnitWeight = detail.Product.CncWeight ?? 0,
                                        ReportDate = reportDate,
                                        ReportDateString = reportDate.ToString("dd/MM/yyyy") + "(Phay)",
                                        ProductivityAlarm = 0,
                                        ProductivityAlarm2 = 0,
                                        Shift1Name = shift1Name,
                                        Shift2Name = shift2Name,
                                        Shift1Count = 0,
                                        Shift2Count = 0,
                                        UnitPrice = (detail.Product.UnitPrice ?? 0),
                                        ShiftAProductionCostInMonth = 0,
                                        ShiftBProductionCostInMonth = 0,
                                        ShiftCProductionCostInMonth = 0,
                                        DisplaySum = display,
                                    };
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                        entity.MachineId,
                                        null,
                                        entity.ProductId,
                                        detail.ImportFormCnc.MaterialUseDate);
                                    if (lastTrack != null) {
                                        if (detail.Productivity == 0)
                                            entity.Productivity = lastTrack.RealProductivity;
                                        if (detail.Rate == 0)
                                            entity.ProductionRate = lastTrack.RealRate;
                                    }
                                    entity.ProductUnitPrice = entity.Productivity *
                                                              detail.Machine.ProcessingType.ProcessingFactor
                                                                    .Value;
                                    var shift1 = new Shift {
                                        ShiftName = shift1Name,
                                        ProcessingQuantity = detail.Processing1,
                                    };
                                    if (shift1.TotalQuantity != 0) {
                                        entity.Shift1Count = 1;
                                        shift1.Count = 1;
                                    }
                                    var shift2 = new Shift {
                                        ShiftName = shift2Name,
                                        ProcessingQuantity = detail.Processing2,
                                    };
                                    if (shift2.TotalQuantity != 0) {
                                        entity.Shift2Count = 1;
                                        shift2.Count = 1;
                                    }
                                    entity.Shifts.Add(shift1);
                                    entity.Shifts.Add(shift2);
                                    model.Add(entity);
                                }
                            }

                        }
                        if (detail.DefectProduct1 + detail.DefectProduct2 > 0) {
                            var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                td.ReferenceId == detail.ProductId &&
                                td.Quantity == detail.DefectProduct1 + detail.DefectProduct2 &&
                                td.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Defect);
                            if (transactionDetailsById != null) {
                                var entity = model.FirstOrDefault(m => m.MachineId == detail.MachineId);
                                if (entity != null &&
                                    entity.ProductId == detail.ProductId) {
                                    entity.UnitWeight = detail.Product.CncWeight ?? 0;
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                        entity.MachineId,
                                        null,
                                        entity.ProductId,
                                        detail.ImportFormCnc.MaterialUseDate);
                                    if (lastTrack != null) {
                                        if (detail.Productivity == 0)
                                            entity.Productivity = lastTrack.RealProductivity;
                                        if (detail.Rate == 0)
                                            entity.ProductionRate = lastTrack.RealRate;
                                    }
                                    else {
                                        entity.ProductionRate = detail.Rate;
                                        entity.Productivity = detail.Productivity;
                                    }

                                    entity.Shifts[0].ShiftName = shift1Name;
                                    entity.Shifts[0].DefectQuantity += detail.DefectProduct1;
                                    entity.Shift1Count = 1;
                                    entity.Shifts[0].Count = 1;


                                    entity.Shifts[1].ShiftName = shift2Name;
                                    entity.Shifts[1].DefectQuantity += detail.DefectProduct2;
                                    entity.Shift2Count = 1;
                                    entity.Shifts[1].Count = 1;

                                }
                                else {
                                    entity = new ProductionDailyReport {
                                        MachineId = detail.MachineId,
                                        MachineName = detail.Machine.MachineName,
                                        ProductId = detail.ProductId,
                                        ProductCode = detail.Product.ProductCode,
                                        ProductionRate = detail.Rate,
                                        Productivity = detail.Productivity,
                                        UnitWeight = detail.Product.CncWeight ?? 0,
                                        ReportDate = reportDate,
                                        ReportDateString = reportDate.ToString("dd/MM/yyyy") + "(Phay)",
                                        ProductivityAlarm = 0,
                                        ProductivityAlarm2 = 0,
                                        Shift1Name = shift1Name,
                                        Shift2Name = shift2Name,
                                        Shift1Count = 0,
                                        Shift2Count = 0,
                                        UnitPrice = (detail.Product.UnitPrice ?? 0),
                                        ShiftAProductionCostInMonth = 0,
                                        ShiftBProductionCostInMonth = 0,
                                        ShiftCProductionCostInMonth = 0,
                                        DisplaySum = display,
                                    };
                                    var lastTrack = MyUtilities.Machine.LastTrackUpMachine(
                                        entity.MachineId,
                                        null,
                                        entity.ProductId,
                                        detail.ImportFormCnc.MaterialUseDate);

                                    if (lastTrack != null) {
                                        if (detail.Productivity == 0)
                                            entity.Productivity = lastTrack.RealProductivity;
                                        if (detail.Rate == 0)
                                            entity.ProductionRate = lastTrack.RealRate;
                                    }
                                    entity.ProductUnitPrice = entity.Productivity *
                                                              detail.Machine.ProcessingType.ProcessingFactor
                                                                    .Value;
                                    var shift1 = new Shift {
                                        ShiftName = shift1Name,
                                        DefectQuantity = detail.DefectProduct1,
                                    };
                                    if (shift1.TotalQuantity != 0) {
                                        entity.Shift1Count = 1;
                                        shift1.Count = 1;
                                    }
                                    var shift2 = new Shift {
                                        ShiftName = shift2Name,
                                        DefectQuantity = detail.DefectProduct2,
                                    };
                                    if (shift2.TotalQuantity != 0) {
                                        entity.Shift2Count = 1;
                                        shift2.Count = 1;
                                    }
                                    entity.Shifts.Add(shift1);
                                    entity.Shifts.Add(shift2);
                                    model.Add(entity);
                                }
                            }
                        }
                    }
                }
                #endregion

            finishPart:
                var productIds = model.Select(m => m.ProductId).Distinct().ToList();
                var productionPricings = vfi.ProductionPricings.Where(pp => productIds.Contains(pp.ProductId));
                foreach (var productionPricing in productionPricings) {
                    var entities = model.Where(m => m.ProductId == productionPricing.ProductId);
                    foreach (var entity in entities) {
                        if (entity.MachineName.Contains("CNC")) {
                            entity.ProductionPrice = productionPricing.ProductionCncPricing;
                        }
                        else if (entity.MachineName.Contains("P")) {
                            entity.ProductionPrice = productionPricing.CncPricing;
                        }
                        else if (entity.MachineName.Contains("C")) {
                            entity.ProductionPrice = productionPricing.ProductionCamesPricing;
                        }
                    }
                }
                if (!string.IsNullOrWhiteSpace(productCode)) {
                    model = model.Where(x => x.ProductCode.Contains(productCode)).ToList();
                }
                return model;
            }
        }


        private List<ProductionDailyReport> GetProductionDailyReport(string productCode, string monthlyDate, bool cames,
                                                                     bool cnc, bool phay) {
            var model = new List<ProductionDailyReport>();
            try {
                using (var vfi = new tammaContext()) {
                    var user = vfi.Users.FirstOrDefault(u => u.Username.Equals(HttpContext.User.Identity.Name));
                    if (user == null)
                        return model;
                    var productionPriceRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseProductionPriceRate);
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    var ci = new CultureInfo("vi-VN");
                    var reportDate = string.IsNullOrWhiteSpace(monthlyDate)
                                         ? DateTime.Today
                                         : Convert.ToDateTime(monthlyDate, ci);
                    var importSx1InDays = (from i in vfi.ImportFormSX1Detail
                                           where
                                               i.ImportFormSX1.MaterialUseDate == reportDate &&
                                               i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                               i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                               i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                .Transaction.Status ==
                                               (byte)MyUtilities.Transaction.Status.Approved
                                               && i.Product.ProductCode.Contains(productCode)
                                           //&& i.MachineId == 68
                                           select i).ToList();
                    var shift1Name = "";
                    var shift2Name = "";
                    var display = (cames || cnc);
                    if (!importSx1InDays.Any())
                        goto part2;
                    try {
                        shift1Name = importSx1InDays.FirstOrDefault(id => id.Shift1.Trim().Length > 0).Shift1;
                    }
                    catch {

                    }
                    try {
                        shift2Name = importSx1InDays.FirstOrDefault(id => id.Shift2.Trim().Length > 0).Shift2;
                    }
                    catch {

                    }
                    if (string.IsNullOrWhiteSpace(shift1Name)) {
                        try {
                            shift1Name = importSx1InDays.FirstOrDefault().ImportFormSX1.Shift1Name.Trim()[1].ToString();
                        }
                        catch { }
                    }
                    if (string.IsNullOrWhiteSpace(shift2Name)) {
                        try {
                            shift2Name = importSx1InDays.FirstOrDefault().ImportFormSX1.Shift2Name.Trim()[1].ToString();
                        }
                        catch { }
                    }
                    //if (cames || cnc)
                    //{
                    #region sx1
                    var startDate = new DateTime(reportDate.Year, reportDate.Month, 26);
                    if (reportDate < startDate)
                        startDate = new DateTime(reportDate.AddMonths(-1).Year, reportDate.AddMonths(-1).Month, 26);
                    var importDate = importSx1InDays.FirstOrDefault().ImportFormSX1.ImportDate;
                    var importSx1s = (from i in vfi.ImportFormSX1Detail
                                      where
                                          i.ImportFormSX1.ImportDate <= importDate &&
                                          i.ImportFormSX1.MaterialUseDate >= startDate &&
                                          //i.ImportFormSX1.ImportDate.Month ==
                                          //importSx1InDay.ImportFormSX1.ImportDate.Month &&
                                          //i.ImportFormSX1.ImportDate.Year ==
                                          //importSx1InDay.ImportFormSX1.ImportDate.Year &&
                                          i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                          i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                          i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                           .Transaction.Status ==
                                          (byte)MyUtilities.Transaction.Status.Approved
                                          && i.Product.ProductCode.Contains(productCode)
                                      //&& i.MachineId == 68
                                      select new {
                                          i.ImportFormSX1,
                                          i.ImportFormSX1.MaterialUseDate,
                                          i.ImportFormSX1.ImportDate,
                                          i.MachineId,
                                          i.Machine1,
                                          i.MaterialInvId,
                                          i.ProductId,
                                          i.ImportFormSX1.Shift1Name,
                                          i.ImportFormSX1.Shift2Name,
                                          i.Number1,
                                          i.Number2,
                                          i.Processing1,
                                          i.Processing2,
                                          i.DefectProduct1,
                                          i.DefectProduct2,
                                          i.MaterialUse1,
                                          i.MaterialUse2,
                                          i.ProductionRate,
                                          i.ProductWeight,
                                          i.MaterialUseDetail,

                                          UnitPrice = i.Product.UnitPrice <= MyUtilities.Product.MinVndPrice
                                                      ? (i.Product.UnitPrice ?? 0) * exchangeRate * productionPriceRate
                                                      : Math.Round(i.Product.UnitPrice ?? 0, 4) - Math.Round(i.Product.UnitPrice ?? 0, 0) == 0
                                                          ? (i.Product.UnitPrice ?? 0) * productionPriceRate
                                                          : (i.Product.UnitPrice ?? 0) * exchangeRate * productionPriceRate,
                                      }).ToList();
                    if (cames && cnc == false) {
                        importSx1s = importSx1s.Where(i => !i.Machine1.MachineName.Contains("CNC")).ToList();
                    }
                    else if (cames == false && cnc) {
                        importSx1s = importSx1s.Where(i => i.Machine1.MachineName.Contains("CNC")).ToList();
                    }
                    var shiftACostInMonth = 0.0;
                    var shiftAMaterialUse = 0.0;
                    var shift1ProductionInMonths = importSx1s.Where(i => i.Shift1Name.Contains("A")).ToList();
                    if (shift1ProductionInMonths.Any()) {
                        shiftACostInMonth += shift1ProductionInMonths
                               .Sum(i => Math.Round((i.Number1) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                        shiftAMaterialUse += shift1ProductionInMonths.Sum(i => i.MaterialUse1);
                    }
                    shift1ProductionInMonths = importSx1s.Where(i => i.Shift2Name.Contains("A")).ToList();
                    if (shift1ProductionInMonths.Any()) {
                        shiftACostInMonth += shift1ProductionInMonths.Sum(i => Math.Round((i.Number2) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                        shiftAMaterialUse += shift1ProductionInMonths.Sum(i => i.MaterialUse2);
                    }
                    //
                    var shiftBCostInMonth = 0.0;
                    var shiftBMaterialUse = 0.0;
                    shift1ProductionInMonths = importSx1s.Where(i => i.Shift1Name.Contains("B")).ToList();
                    if (shift1ProductionInMonths.Any()) {
                        shiftBCostInMonth += shift1ProductionInMonths
                            .Sum(i => Math.Round((i.Number1) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                        shiftBMaterialUse += shift1ProductionInMonths.Sum(i => i.MaterialUse1);
                    }
                    shift1ProductionInMonths = importSx1s.Where(i => i.Shift2Name.Contains("B")).ToList();
                    if (shift1ProductionInMonths.Any()) {
                        shiftBCostInMonth += shift1ProductionInMonths
                            .Sum(i => Math.Round((i.Number2) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                        shiftBMaterialUse += shift1ProductionInMonths.Sum(i => i.MaterialUse2);
                    }
                    //
                    var shiftCCostInMonth = 0.0;
                    var shiftCMaterialUse = 0.0;
                    shift1ProductionInMonths = importSx1s.Where(i => i.Shift1Name.Contains("C")).ToList();
                    if (shift1ProductionInMonths.Any()) {
                        shiftCCostInMonth += shift1ProductionInMonths
                               .Sum(i => Math.Round((i.Number1) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                        shiftCMaterialUse += shift1ProductionInMonths.Sum(i => i.MaterialUse1);
                    }
                    shift1ProductionInMonths = importSx1s.Where(i => i.Shift2Name.Contains("C")).ToList();
                    if (shift1ProductionInMonths.Any()) {
                        shiftCCostInMonth += shift1ProductionInMonths
                               .Sum(i => Math.Round((i.Number2) * i.UnitPrice / 1000000, MyUtilities.Product.ProductionDecimalPoint));
                        shiftCMaterialUse += shift1ProductionInMonths.Sum(i => i.MaterialUse2);
                    }
                    var machines = vfi.Machines.Where(m => m.Active
                        //&& ( (cnc && m.MachineName.Contains("CNC")) ||
                        //    (cames && m.MachineName.Contains("C") && !m.MachineName.Contains("CNC")) ||
                        //    (phay && m.MachineName.Contains("P")))
                        ).OrderBy(m => m.MachineName);

                    var materialUseDetails = (from mud in vfi.MaterialUseDetails
                                              where mud.MaterialUseInShift.Status == (byte)MyUtilities.Transaction.Status.Approved
                                                    && mud.MaterialUseInShift.UsedDate == reportDate
                                              select mud).ToList();
                    foreach (var machine in machines) {
                        var text = reportDate.ToString("dd/MM/yyyy");
                        if (machine.MachineName.Contains("CNC"))
                            text += " (CNC)";
                        else if (machine.MachineName.Contains("P"))
                            text += " (Phay)";
                        else
                            text += " (Cames)";
                        var materialUseDetailsById =
                            importSx1s.Where(
                                id =>
                                id.MachineId == machine.MachineId && id.MaterialUseDate == reportDate);
                        foreach (var sx1Detail in materialUseDetailsById) {
                            var entity =
