                                    entity.Shifts[0].ProductCost = entity.Shifts[0].Quantity * entity.UnitPrice;
                                    entity.Shifts[1].ProductionPrice = entity.Shifts[1].Quantity *
                                                                       5;
                                    entity.Shifts[1].ProductCost = entity.Shifts[1].Quantity * entity.UnitPrice;

                                    if (entity.Shifts[0].Quantity != 0 || entity.Shifts[0].ProcessingQuantity != 0 ||
                                        entity.Shifts[0].DefectQuantity != 0 || entity.Shifts[0].MaterialUse != 0)
                                        entity.Shift1Count = 1;
                                    if (entity.Shifts[1].Quantity != 0 || entity.Shifts[1].ProcessingQuantity != 0 ||
                                        entity.Shifts[1].DefectQuantity != 0 || entity.Shifts[1].MaterialUse != 0)
                                        entity.Shift2Count = 1;
                                }
                            }
                        }
                        if (!materialUseDetailsById.Any()) {
                            var smartProduction =
                                vfi.SmartProductions.FirstOrDefault(
                                    sp =>
                                    sp.MachineId == machine.MachineId &&
                                    sp.Product.ProductCode.Contains(productCode));
                            if (smartProduction != null) {
                                var product =
                                    vfi.Products.FirstOrDefault(p => p.ProductId == smartProduction.ProductId);
                                var entity = new ProductionDailyReport {
                                    MachineId = machine.MachineId,
                                    MachineName = machine.MachineName,
                                    ProductId = product.ProductId,
                                    ProductCode = product.ProductCode,
                                    ProductionRate = product.ProductionRate ?? 0,
                                    Productivity = product.Productivity ?? 0,
                                    UnitWeight = product.ProductionWeight ?? 0,
                                    ReportDate = reportDate,
                                    ReportDateString = text,
                                    //ProductivityInShift = 0,
                                    //ProductivityInDay = 0,
                                    ProductivityAlarm = 0,
                                    ProductivityAlarm2 = 0,
                                    //CountMachineRun = 0,
                                    Shift1Name = shift1Name,
                                    Shift2Name = shift2Name,
                                    ProductUnitPrice = product.UnitPrice ?? 0,
                                    Shift1Count = 0,
                                    Shift2Count = 0,
                                    ShiftAProductionCostInMonth = shiftACostInMonth,
                                    ShiftBProductionCostInMonth = shiftBCostInMonth,
                                    ShiftCProductionCostInMonth = shiftCCostInMonth,
                                    DisplaySum = display,
                                    ShiftAMateialUse = shiftAMaterialUse,
                                    ShiftBMateialUse = shiftBMaterialUse,
                                    ShiftCMateialUse = shiftCMaterialUse,
                                };
                                var productionPrice =
                                    vfi.RealProductions.FirstOrDefault(
                                        rp => rp.ProductId == entity.ProductId && rp.MachineId == entity.MachineId);
                                if (productionPrice != null) {
                                    entity.Productivity = productionPrice.TrackUpMachine.RealProductivity;
                                    entity.ProductionRate = productionPrice.TrackUpMachine.RealRate;
                                }
                                var realProduction =
                                    vfi.RealProductions.FirstOrDefault(
                                        rp => rp.ProductId == entity.ProductId && rp.MachineId == entity.MachineId);
                                if (realProduction != null) {
                                    entity.Productivity = realProduction.TrackUpMachine.RealProductivity;
                                    entity.ProductionRate = realProduction.TrackUpMachine.RealRate;
                                }
