                                //    //20h
                                //    entity.ProductivityInDay = MyUtilities.Product.Second/20h / entity.Productivity;
                                //}
                                var shift1 = new Shift {
                                    ShiftName = "",
                                };
                                entity.Shifts.Add(shift1);
                                entity.Shifts.Add(shift1);
                                //if (permisstion == null || permisstion.Execution == false)
                                //    entity.PrintCost = 0;
                                //else entity.PrintCost = 1;
                                model.Add(entity);
                            }
                            else if (string.IsNullOrWhiteSpace(productCode)) {
                                var entity = new ProductionDailyReport {
                                    MachineId = machine.MachineId,
                                    MachineName = machine.MachineName,
                                    ProductCode = "",
                                    ProductionRate = 0,
                                    UnitWeight = 0,
                                    ReportDate = reportDate,
                                    ReportDateString = text,
                                    Productivity = 0,
                                    //ProductivityInShift = 0,
                                    //ProductivityInDay = 0,
                                    Shift1Name = shift1Name,
                                    Shift2Name = shift2Name,
                                    Shift1Count = 0,
                                    Shift2Count = 0,
                                    DisplaySum = display,
                                    ShiftAMateialUse = shiftAMaterialUse,
                                    ShiftBMateialUse = shiftBMaterialUse,
                                    ShiftCMateialUse = shiftCMaterialUse,
                                };
                                var shift1 = new Shift {
                                    ShiftName = "",
                                };
                                entity.Shifts.Add(shift1);
                                entity.Shifts.Add(shift1);
                                //if (permisstion == null || permisstion.Execution == false)
                                //    entity.PrintCost = 0;
                                //else entity.PrintCost = 1;
                                model.Add(entity);
                            }
                        }
                    }
                    #endregion

                    #region phay
                //}
                //if (phay)
                //{
                part2:
                    var importCncs = from i in vfi.ImportFormCncs
                                     where
                                         i.MaterialUseDate == reportDate
                                     select i;
                    //var transactionCodes = importCncs.Select(i => i.TransactionCode);
                    //var transactions =
                    //    vfi.Transactions.Where(
                    //        t => transactionCodes.Contains(t.TransactionCode) &&
                    //        t.Status == (byte)MyUtilities.Transaction.Status.Approved);
                    foreach (var i in importCncs) {
                        var transactionDetails =
                            vfi.TransactionDetails.Where(
