        [HttpPost]
        public ActionResult PrintProductionDailyReport(string monthlyDate,
            bool cames, bool cnc, bool phay, bool vf1, bool vf2) {
            var model = new List<ProductionDailyReport>();
            try {
                model = GetProductionDailyReport_2("", monthlyDate,
                    cames, cnc, phay,
                    vf1, vf2,
                   (int)MyUtilities.Report.Calculate.InPeriod);
                var groups = model.GroupBy(x => new { x.ProductId, x.MachineId })
                    //.Where(x => x.Count() > 1)
                    .Select(x => new { x.Key.ProductId, x.Key.MachineId })
                    .Distinct()
                    .ToList();
                var importDate = MyUtilities.Function.ParseDate(monthlyDate);
                var startWeekDate = MyUtilities.Function.StartOfWeekDate(importDate);
                using (var vfi = new tammaContext()) {
                    var importSx1s = (from i in vfi.ImportFormSX1Detail
                                      where
                                          i.ImportFormSX1.MaterialUseDate >= startWeekDate &&
                                          i.ImportFormSX1.MaterialUseDate <= importDate &&
                                          i.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                      select new {
                                          i.MachineId,
                                          i.ProductId,
                                          Quantity = i.Number1 + i.Number2
                                      })
                                      .GroupBy(x => new { x.MachineId, x.ProductId })
                                      .Select(x => new {
                                          x.Key.MachineId,
                                          x.Key.ProductId,
                                          Quantity = x.Sum(y => y.Quantity)
                                      })
                                      .ToList();

                    foreach (var group in groups) {
                        var details = model.Where(x => x.ProductId == group.ProductId && x.MachineId == group.MachineId).ToList();
                        var import = importSx1s.FirstOrDefault(x => x.MachineId == group.MachineId && x.ProductId == group.ProductId);
                        foreach (var detail in details) {
                            if (!detail.EmptyPlan) {
                                detail.ProductivityInDayPlan = 
                                    MyUtilities.Function.RoundUp(details.Sum(x => x.ProductivityInDay) * 0.9, -2);
                            }

                            

                            detail.ProductivityInDayReal = details.Sum(x => x.TotalShift.Quantity);
                            if (import != null) {
                                detail.ProductivityInWeekReal = import.Quantity;
                            }
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintProductionDailyReport", ex.Message);
            }

            return PartialView("PageProductionDailySX1", model.OrderBy(p => p.MachineName).ToList());
        }
        [GridAction]
        public ActionResult SelectProductionTotalReport(string fromDate, string toDate,
            string productCode, string materialCode, string machineName, string shiftName) {
            var model = new List<ProductionDailyReport>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                var ci = new CultureInfo("vi-VN");
                var fDate = string.IsNullOrWhiteSpace(fromDate)
                    ? DateTime.Today
                    : Convert.ToDateTime(fromDate, ci);
                var tDate = string.IsNullOrWhiteSpace(toDate)
                    ? DateTime.Today
                    : Convert.ToDateTime(toDate, ci);
                var soNgay = (tDate - fDate).TotalDays;
                using (var vfi = new tammaContext()) {
                    //vfi.Configuration.LazyLoadingEnabled = false;

                    #region sx1

                    var importSx1Details = (from sx in vfi.ImportFormSX1Detail
                                            where sx.ImportFormSX1.MaterialUseDate >= fDate &&
                                                  sx.ImportFormSX1.MaterialUseDate <= tDate &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                      .Transaction.Status ==
                                                  (byte)MyUtilities.Transaction.Status.Approved
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                            orderby sx.ImportFormSX1.MaterialUseDate
                                            select new {
                                                sx.DetailId,
                                                sx.MachineId,
                                                sx.Machine,
                                                sx.Machine1.ProcessingType,
                                                sx.ProductId,
                                                sx.Product.ProductCode,
                                                ProductPrice = sx.Product.UnitPrice ?? 0,
                                                ProductionRate = sx.ProductionRate > 0 ? sx.ProductionRate : 0,
                                                sx.ImportFormSX1.MaterialUseDate,
                                                sx.Product.Productivity,
                                                sx.Product.CncProductivity,
                                                sx.MaterialInvId,
                                                sx.MaterialInventory.Material.MaterialId,
                                                sx.MaterialInventory.Material.MaterialCode,
                                                sx.MaterialInventory.Material.MaterialName,
                                                sx.MaterialInventory.Material.OutDiameter,
                                                sx.MaterialInventory.Material.InDiameter,
                                                sx.MaterialInventory.Material.Shape,
                                                sx.MaterialInventory.Material.DiameterType,
                                                sx.MaterialInventory.LotNumber,
                                                sx.MaterialInventory.Vendor.VendorCode,
                                                sx.MaterialInventory.Length,
                                                sx.MaterialInventory.Material.MaterialType.MaterialTypeName,
                                                MaterialWeight = sx.MaterialInventory.UnitWeight,
                                                MaterialPrice = sx.MaterialInventory.UnitPrice,
                                                sx.Number1,
                                                sx.Number2,
                                                sx.Processing1,
                                                sx.Processing2,
                                                sx.DefectProduct1,
                                                sx.DefectProduct2,
                                                sx.MaterialUse1,
                                                sx.MaterialUse2,
                                                //sx.ImportFormSX1.Shift1Name,
                                                ShiftName = (sx.ImportFormSX1.Shift1Name + "") + (sx.ImportFormSX1.Shift2Name + ""),
                                                sx.ImportFormSX1.Shift1Name,
                                                sx.ImportFormSX1.Shift2Name
                                            }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode)) {
                        importSx1Details = importSx1Details.Where(sx => sx.ProductCode.Contains(productCode))
                            .ToList();
                    }
                    if (!string.IsNullOrWhiteSpace(materialCode)) {
                        importSx1Details = importSx1Details.Where(sx => sx.MaterialCode.Contains(materialCode))
                            .ToList();
                    }
                    if (!string.IsNullOrWhiteSpace(shiftName))
                        importSx1Details = importSx1Details.Where(sx => sx.ShiftName.Contains(shiftName))
                            .ToList();
                    if (!string.IsNullOrWhiteSpace(machineName))
                        importSx1Details = importSx1Details.Where(sx => sx.Machine.Contains(machineName))
                            .ToList();

                    var repairForms = (from ms in vfi.MachineRepairForms
                                       where ms.Status != (byte)MyUtilities.Machine.State.RepairStatus.Delete &&
                                         (
                                          (ms.CauseDate >= fDate && ms.CauseDate <= tDate) ||
                                           (ms.CauseDate <= tDate && ms.FinishDate == null) ||
                                           (ms.FinishDate >= fDate && ms.FinishDate <= tDate) ||
                                           (ms.CauseDate < fDate && ms.FinishDate > tDate)
                                          )
                                       select new {
                                           ms.MachineId,
                                           ms.StateId,
                                           StartDate = (ms.CauseDate < fDate ? fDate : ms.CauseDate),
                                           FinishDate = (ms.FinishDate == null || ms.FinishDate > tDate)
                                           ? tDate
                                           : ms.FinishDate.Value,
                                           StartState = ms.CauseDate,
                                           FinishState = ms.FinishDate,
                                           ms.FormId
                                       }).ToList();
                    var productIds = importSx1Details.Select(id => id.ProductId).Distinct().ToList();
                    var productionPricings = vfi.ProductionPricings.Where(pp => productIds.Contains(pp.ProductId));
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    var productionPriceRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseProductionPriceRate);
                    foreach (var detail in importSx1Details) {
                        var shiftN = "";
                        for (var str = 'A'; str <= 'D'; str++) {
                            if (detail.Shift1Name.Contains(str) || detail.Shift2Name.Contains(str)) {
                                shiftN = str + "";
                                break;
                            }
                        }
                        var entity = model.FirstOrDefault(m => m.ProductId == detail.ProductId &&
                            m.MachineId == detail.MachineId &&
                            m.MaterialInvId == m.MaterialInvId &&
                            m.ProductionRate == m.ProductionRate &&
                             m.Shift1Name.Contains(shiftN));
                        if (entity == null) {
                            entity = new ProductionDailyReport {
                                MachineId = detail.MachineId.Value,
                                MachineName = detail.Machine,
                                ProductId = detail.ProductId,
                                ProductCode = detail.ProductCode,
                                ProductionRate = detail.ProductionRate,
                                Shifts = new List<Shift>(),
                                Shift1Name = shiftN,
                                FromDate = fromDate,
                                ToDate = toDate,
                                Productivity = detail.Productivity ?? 0,
                                MaterialCode =
                                    detail.MaterialName + MyUtilities.Material.GetMaterialDesignNo(
                                        detail.OutDiameter, detail.InDiameter,
                                        detail.DiameterType, detail.Shape),
                                ProductUnitPrice = MyUtilities.Product.ProductVndPrice(detail.ProductPrice, productionPriceRate, exchangeRate),
                                DesignProductivity = detail.Productivity ?? 0,
                                MachineTypeCost = 0,
                                MaterialLength = detail.Length,
                                MaterialWeight = detail.MaterialWeight,
                                MaterialTypeName = detail.MaterialTypeName
                            };
                            if (detail.Machine.Contains("CNC")) {
                                entity.DesignProductivity = detail.CncProductivity ?? 0;
                            }
                            if (detail.ProcessingType != null) {
                                entity.MachineTypeCost = detail.ProcessingType.ProcessingFactor ?? 1;
                            }
                            //if (entity.ProductUnitPrice > 0) {
                            //    var productPrice = Math.Round(entity.ProductUnitPrice, 4);
                            //    var temp = Convert.ToInt32(productPrice);
                            //    if (productPrice - temp != 0)
                            //        productPrice = productPrice * MyUtilities.Product.ExchangeRateDesign;
                            //    entity.ProductUnitPrice = productPrice;
                            //}
                            var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, detail.MaterialId, entity.ProductId, detail.MaterialUseDate);
                            //var realProduction =
                            //    vfi.RealProductions.FirstOrDefault(
                            //        rp => rp.ProductId == entity.ProductId && rp.MachineId == entity.MachineId);
                            if (lastTrack != null) {
                                entity.Productivity = lastTrack.RealProductivity;
                                entity.WorkpieceLength = lastTrack.WorkPiece;
                                //entity.ProductionRate = realProduction.TrackUpMachine.RealRate;
                            }
                            if (detail.Shift1Name.Contains(shiftN)) {
                                var shift = new Shift() {
                                    UseDate = detail.MaterialUseDate,

                                    Quantity = detail.Number1,
                                    ProcessingQuantity = detail.Processing1,
                                    DefectQuantity = detail.DefectProduct1,
                                    MaterialUse = detail.MaterialUse1,
                                    MaterialPrice = detail.MaterialPrice,
                                    ProductionRate = entity.ProductionRate,
                                    DesignProductivity = entity.DesignProductivity,
                                };
                                entity.Shifts.Add(shift);
                            }
                            else if (detail.Shift2Name.Contains(shiftN)) {
                                var shift = new Shift() {
                                    UseDate = detail.MaterialUseDate,

                                    Quantity = detail.Number2,
                                    ProcessingQuantity = detail.Processing2,
                                    DefectQuantity = detail.DefectProduct2,
                                    MaterialUse = detail.MaterialUse2,
                                    MaterialPrice = detail.MaterialPrice,
                                    ProductionRate = entity.ProductionRate,
                                    DesignProductivity = entity.DesignProductivity,
                                };
                                entity.Shifts.Add(shift);
                            }
                            entity.Shift1Count = entity.Shifts.Count;
                            entity.UnitPrice = entity.Shifts.Average(s => s.MaterialPrice);

                            var repairFormsById = repairForms.Where(rm => rm.MachineId == entity.MachineId);
                            if (repairFormsById.Any()) {
                                entity.ErrorTimeByRepairForm = repairFormsById.Sum(rm => (rm.FinishDate - rm.StartDate).TotalHours);
                                entity.ErrorCountByRepairForm = repairFormsById.Count(rm => rm.StateId != MyUtilities.Machine.State.Setup);
                            }
                            entity.TimeByMachineRunning = soNgay * 24 - entity.ErrorTimeByRepairForm;
                            //var details = new List<MachineRepairFormModel>();
                            //foreach (var repair in repairMachinesById) {
                            //    var detail = new MachineRepairFormModel() {
                            //        MachineName = repair.MachineRepairForm.Machine.MachineName,
                            //        EstimateTime = repair.MachineRepairForm.MachineState.EstimateTime,
                            //        StateCode = repair.MachineRepairForm.MachineState.StateCode,
                            //        StartDate = repair.StartRepair,
                            //        FinishDate = repair.FinishRepair,
                            //        StatusName = MyUtilities.Machine.State.GetRepairStatusText(repair.Status)
                            //    };
                            //    details.Add(detail);
                            //}
                            var productionPricing = productionPricings.FirstOrDefault(pp => pp.ProductId == entity.ProductId);
                            if (productionPricing != null) {
                                if (entity.MachineName.Contains("CNC")) {
                                    entity.ProductionPrice = productionPricing.ProductionCncPricing;
                                }
                                else {
                                    entity.ProductionPrice = productionPricing.ProductionCamesPricing;
                                    entity.TeamDPrice = productionPricing.ProductionTeamDPricing;
                                    entity.TechnicalPrice = productionPricing.ProductionTechnicalPricing;
                                }
                            }
                            model.Add(entity);
                        }
                        else {
                            var shift = entity.Shifts.FirstOrDefault(s => s.UseDate == detail.MaterialUseDate);
                            if (shift == null) {
                                if (detail.Shift1Name.Contains(shiftN)) {
                                    shift = new Shift() {
                                        UseDate = detail.MaterialUseDate,

                                        Quantity = detail.Number1,
                                        ProcessingQuantity = detail.Processing1,
                                        DefectQuantity = detail.DefectProduct1,
                                        MaterialUse = detail.MaterialUse1,
                                        MaterialPrice = detail.MaterialPrice,
                                        ProductionRate = entity.ProductionRate,
                                        DesignProductivity = entity.DesignProductivity,
                                    };
                                    entity.Shifts.Add(shift);
                                }
                                else if (detail.Shift2Name.Contains(shiftN)) {
                                    shift = new Shift() {
                                        UseDate = detail.MaterialUseDate,

                                        Quantity = detail.Number2,
                                        ProcessingQuantity = detail.Processing2,
                                        DefectQuantity = detail.DefectProduct2,
                                        MaterialUse = detail.MaterialUse2,
                                        MaterialPrice = detail.MaterialPrice,
                                        ProductionRate = entity.ProductionRate,
                                        DesignProductivity = entity.DesignProductivity,
                                    };
                                    entity.Shifts.Add(shift);
                                }
                                entity.Shift1Count = entity.Shifts.Count;
                                entity.UnitPrice = entity.Shifts.Average(s => s.MaterialPrice);
                            }
                            else {
                                if (detail.Shift1Name.Contains(shiftN)) {
                                    shift.Quantity += detail.Number1;
                                    shift.ProcessingQuantity += detail.Processing1;
                                    shift.DefectQuantity += detail.DefectProduct1;
                                    shift.MaterialUse += detail.MaterialUse1;
                                }
                                else if (detail.Shift2Name.Contains(shiftN)) {
                                    shift.Quantity += detail.Number2;
                                    shift.ProcessingQuantity += detail.Processing2;
                                    shift.DefectQuantity += detail.DefectProduct2;
                                    shift.MaterialUse += detail.MaterialUse2;
                                }
                            }
                        }
                    }
                    #endregion

                    #region phay

                    var importCncs = (from sxd in vfi.ImportFormCncDetails
                                      where sxd.ImportFormCnc.MaterialUseDate >= fDate &&
                                            sxd.ImportFormCnc.MaterialUseDate <= tDate
                                      orderby sxd.ImportFormCnc.MaterialUseDate
                                      select new {
                                          sxd.MachineId,
                                          sxd.ImportFormCnc.MaterialUseDate,
                                          sxd.Machine.MachineName,
                                          sxd.Machine.ProcessingType,
                                          sxd.ProductId,
                                          sxd.Product.ProductCode,
                                          sxd.Product.CncProductivity,
                                          sxd.Product.MillProductivity,
                                          ProductPrice = sxd.Product.UnitPrice ?? 0,
                                          sxd.ImportFormCnc.Shift1Name,
                                          sxd.ImportFormCnc.Shift2Name,
                                          ShiftName = sxd.ImportFormCnc.Shift1Name + sxd.ImportFormCnc.Shift2Name,
                                          sxd.ImportFormCnc.TransactionCode,
                                          sxd.Number1,
                                          sxd.Number2,
                                          sxd.Processing1,
                                          sxd.Processing2,
                                          sxd.DefectProduct1,
                                          sxd.DefectProduct2,
                                          MaterialPrice = sxd.Product.MaterialId != null ? sxd.Product.Material.UnitPrice : 0,
                                          MaterialInvId = sxd.ProductInvId != null ? sxd.ProductInventory.MaterialInvId : 0,
                                      }).ToList();

                    if (!string.IsNullOrWhiteSpace(productCode))
                        importCncs =
                            importCncs.Where(sx => sx.ProductCode.Contains(productCode))
                                .ToList();
                    if (!string.IsNullOrWhiteSpace(shiftName))
                        importCncs =
                            importCncs.Where(sx => sx.ShiftName.Contains(shiftName))
                                .ToList();
                    if (!string.IsNullOrWhiteSpace(machineName))
                        importCncs =
                            importCncs.Where(sx => sx.MachineName.Contains(machineName))
                                .ToList();

                    var transactionCodes = importCncs.Select(id => id.TransactionCode).Distinct().ToList();
                    var transactionDetails = from td in vfi.TransactionDetails
                                             where transactionCodes.Contains(td.Transaction.TransactionCode) &&
                                             td.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                             select td;
                    var materialInvIds = importCncs.Where(id => id.MaterialInvId > 0).Select(id => id.MaterialInvId.Value);
                    var materialInvs = from mi in vfi.MaterialInventories
                                       where materialInvIds.Contains(mi.MaterialInventoryId)
                                       select new {
                                           mi.MaterialInventoryId,
                                           mi.Material.MaterialId,
                                           mi.Material.MaterialName,
                                           mi.Material.OutDiameter,
                                           mi.Material.InDiameter,
                                           mi.Material.Shape,
                                           mi.Material.DiameterType,
                                           mi.LotNumber,
                                           mi.Vendor.VendorCode,
                                           mi.Length,
                                           mi.UnitPrice,
                                       };

                    productIds = importCncs.Select(id => id.ProductId).Distinct().ToList();
                    productionPricings = vfi.ProductionPricings.Where(pp => productIds.Contains(pp.ProductId));
                    for (var str = 'A'; str <= 'D'; str++) {
                        if (!string.IsNullOrWhiteSpace(shiftName) && !shiftName.Contains(str)) continue;

                        var detailByShift = importCncs.Where(id => id.ShiftName.Contains(str));
                        foreach (var detail in detailByShift) {
                            bool isTransaction = false, isProcessing = false, isDefect = false;
                            if (detail.Number1 + detail.Number2 > 0) {
                                var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                    td.ReferenceId == detail.ProductId &&
                                    td.Transaction.TransactionCode.Equals(detail.TransactionCode) &&
                                    td.Quantity == detail.Number1 + detail.Number2 &&
                                    td.Transaction.WarehouseReceiptId != MyUtilities.Warehouse.Processing &&
                                    td.Transaction.WarehouseReceiptId != MyUtilities.Warehouse.Defect);
                                if (transactionDetailsById != null)
                                    isTransaction = true;
                            }
                            if (detail.Processing1 + detail.Processing2 > 0) {
                                var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                    td.ReferenceId == detail.ProductId &&
                                    td.Transaction.TransactionCode.Equals(detail.TransactionCode) &&
                                    td.Quantity == detail.Processing1 + detail.Processing2 &&
                                    td.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Processing);
                                if (transactionDetailsById != null)
                                    isProcessing = true;
                            }
                            if (detail.DefectProduct1 + detail.DefectProduct2 > 0) {
                                var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                    td.ReferenceId == detail.ProductId &&
                                    td.Transaction.TransactionCode.Equals(detail.TransactionCode) &&
                                    td.Quantity == detail.DefectProduct1 + detail.DefectProduct2 &&
                                    td.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Defect);
                                if (transactionDetailsById != null)
                                    isDefect = true;
                            }
                            if (!isTransaction && !isProcessing && !isDefect)
                                continue;
                            if (detail.Shift1Name.Contains(str) && detail.Number1 + detail.Processing1 + detail.DefectProduct1 <= 0)
                                continue;
                            if (detail.Shift2Name.Contains(str) && detail.Number2 + detail.Processing2 + detail.DefectProduct2 <= 0)
                                continue;
                            //if (!string.IsNullOrWhiteSpace(shift) && shiftName.Equals(shift))

                            var materialPrice = detail.MaterialPrice;
                            var materialInv = materialInvs.FirstOrDefault(mi => mi.MaterialInventoryId == detail.MaterialInvId);
                            if (materialInv != null)
                                materialPrice = materialInv.UnitPrice;
                            var entity = model.FirstOrDefault(m => m.ProductId == detail.ProductId &&
                                m.MachineId == detail.MachineId &&
                                 m.Shift1Name.Contains(str));
                            if (entity == null) {
                                entity = new ProductionDailyReport {
                                    MachineId = detail.MachineId,
                                    MachineName = detail.MachineName,
                                    ProductId = detail.ProductId,
                                    ProductCode = detail.ProductCode,
                                    ProductionRate = 0,
                                    Shifts = new List<Shift>(),
                                    Shift1Name = str + "",
                                    FromDate = fromDate,
                                    ToDate = toDate,
                                    //Productivity = detail.Productivity ?? 0,
                                    //MaterialCode =
                                    //    detail.MaterialName + MyUtilities.Material.GetMaterialDesignNo(
                                    //        detail.OutDiameter, detail.InDiameter,
                                    //        detail.DiameterType, detail.Shape),
                                    ProductUnitPrice = MyUtilities.Product.ProductVndPrice(detail.ProductPrice, productionPriceRate, exchangeRate),
                                    DesignProductivity = detail.MillProductivity ?? 0,
                                };
                                if (detail.ProcessingType != null) {
                                    entity.MachineTypeCost = detail.ProcessingType.ProcessingFactor ?? 1;
                                }
                                if (materialInv != null) {
                                    entity.MaterialCode =
                                        materialInv.MaterialName + MyUtilities.Material.GetMaterialDesignNo(
                                            materialInv.OutDiameter, materialInv.InDiameter,
                                            materialInv.DiameterType, materialInv.Shape);
                                }
                                //if (entity.ProductUnitPrice > 0) {
                                //    var productPrice = Math.Round(entity.ProductUnitPrice, 4);
                                //    var temp = Convert.ToInt32(productPrice);
                                //    if (productPrice - temp != 0)
                                //        productPrice = productPrice * MyUtilities.Product.ExchangeRateDesign;
                                //    entity.ProductUnitPrice = productPrice;
                                //}
                                var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, entity.ProductId, detail.MaterialUseDate);
                                if (lastTrack != null) {
                                    //if (detail.Productivity == 0)
                                    entity.Productivity = lastTrack.RealProductivity;
                                    entity.ProductionRate = lastTrack.RealRate;
                                }
                                if (detail.Shift1Name.Contains(str)) {
                                    var shift = new Shift() {
                                        UseDate = detail.MaterialUseDate,

                                        Quantity = isTransaction ? detail.Number1 : 0,
                                        ProcessingQuantity = isProcessing ? detail.Processing1 : 0,
                                        DefectQuantity = isDefect ? detail.DefectProduct1 : 0,
                                        MaterialUse = 0,
                                        MaterialPrice = materialPrice,
                                        ProductionRate = entity.ProductionRate,
                                        DesignProductivity = entity.DesignProductivity,
                                    };
                                    if (shift.Quantity + shift.ProcessingQuantity + shift.DefectQuantity > 0)
                                        entity.Shifts.Add(shift);
                                }
                                else if (detail.Shift2Name.Contains(str)) {
                                    var shift = new Shift() {
                                        UseDate = detail.MaterialUseDate,

                                        Quantity = isTransaction ? detail.Number2 : 0,
                                        ProcessingQuantity = isProcessing ? detail.Processing2 : 0,
                                        DefectQuantity = isDefect ? detail.DefectProduct2 : 0,
                                        MaterialUse = 0,
                                        MaterialPrice = materialPrice,
                                        ProductionRate = entity.ProductionRate,
                                        DesignProductivity = entity.DesignProductivity,
                                    };
                                    if (shift.Quantity + shift.ProcessingQuantity + shift.DefectQuantity > 0)
                                        entity.Shifts.Add(shift);
                                }
                                entity.Shift1Count = entity.Shifts.Count;
                                if (entity.Shift1Count > 0) {
                                    var repairFormsById = repairForms.Where(rm => rm.MachineId == entity.MachineId);
                                    if (repairFormsById.Any()) {
                                        entity.ErrorTimeByRepairForm = repairFormsById.Sum(rm => (rm.FinishDate - rm.StartDate).TotalHours);
                                        entity.ErrorCountByRepairForm = repairFormsById.Count(rm => rm.StateId != MyUtilities.Machine.State.Setup);
                                    }
                                    entity.UnitPrice = entity.Shifts.Average(s => s.MaterialPrice);
                                    var productionPricing = productionPricings.FirstOrDefault(pp => pp.ProductId == entity.ProductId);
                                    if (productionPricing != null) {
                                        entity.ProductionPrice = productionPricing.CncPricing;
                                    }
                                    model.Add(entity);
                                }
                            }
                            else {
                                var shift = entity.Shifts.FirstOrDefault(s => s.UseDate == detail.MaterialUseDate);
                                if (shift == null) {
                                    if (detail.Shift1Name.Contains(str)) {
                                        shift = new Shift() {
                                            UseDate = detail.MaterialUseDate,

                                            Quantity = isTransaction ? detail.Number1 : 0,
                                            ProcessingQuantity = isProcessing ? detail.Processing1 : 0,
                                            DefectQuantity = isDefect ? detail.DefectProduct1 : 0,
                                            MaterialUse = 0,
                                            MaterialPrice = materialPrice,
                                            ProductionRate = entity.ProductionRate,
                                            DesignProductivity = entity.DesignProductivity,
                                        };
                                        if (shift.Quantity + shift.ProcessingQuantity + shift.DefectQuantity > 0)
                                            entity.Shifts.Add(shift);
                                    }
                                    else if (detail.Shift2Name.Contains(str)) {
                                        shift = new Shift() {
                                            UseDate = detail.MaterialUseDate,

                                            Quantity = isTransaction ? detail.Number2 : 0,
                                            ProcessingQuantity = isProcessing ? detail.Processing2 : 0,
                                            DefectQuantity = isDefect ? detail.DefectProduct2 : 0,
                                            MaterialUse = 0,
                                            MaterialPrice = materialPrice,
                                            ProductionRate = entity.ProductionRate,
                                            DesignProductivity = entity.DesignProductivity,
                                        };
                                        if (shift.Quantity + shift.ProcessingQuantity + shift.DefectQuantity > 0)
                                            entity.Shifts.Add(shift);
                                    }
                                    entity.Shift1Count = entity.Shifts.Count;
                                    entity.UnitPrice = entity.Shifts.Average(s => s.MaterialPrice);
                                }
                                else {
                                    if (detail.Shift1Name.Contains(str)) {
                                        shift.Quantity += (isTransaction ? detail.Number1 : 0);
                                        shift.ProcessingQuantity += (isProcessing ? detail.Processing1 : 0);
                                        shift.DefectQuantity += (isDefect ? detail.DefectProduct1 : 0);
                                        //shiftProduction.MaterialUse += detail.MaterialUse1;
                                    }
                                    else if (detail.Shift2Name.Contains(str)) {
                                        shift.Quantity += (isTransaction ? detail.Number2 : 0);
                                        shift.ProcessingQuantity += (isProcessing ? detail.Processing2 : 0);
                                        shift.DefectQuantity += (isDefect ? detail.DefectProduct2 : 0);
                                        //shiftProduction.MaterialUse += detail.MaterialUse2;
                                    }
                                }
                            }
                        }
                    }
                    #endregion
                }

                if (!string.IsNullOrWhiteSpace(productCode))
                    model = model.Where(sx => sx.ProductCode.Contains(productCode))
                        .ToList();
                if (!string.IsNullOrWhiteSpace(machineName))
                    model = model.Where(sx => sx.MachineName.Contains(machineName))
                        .ToList();
                model = model.OrderBy(m => m.Shift1Name).ThenBy(m => m.MachineName).ToList();
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionTotalReport", ex.Message);
            }
            //return View(new GridModel(model.OrderBy(m => m.ReportDate)
            //    .ThenBy(m => m.Shifts)
            //    .ThenBy(m => m.MachineName)
            //    .ToList()));
            return View(new GridModel(model));
        }


        [GridAction]
        public ActionResult SelectProductionTotalDetailReport(string fromDate, string toDate,
           int productId, int machineId, string shift) {
            var model = new List<ProductionDailyReport>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                var ci = new CultureInfo("vi-VN");
                var fDate = string.IsNullOrWhiteSpace(fromDate)
                    ? DateTime.Today
                    : Convert.ToDateTime(fromDate, ci);
                var tDate = string.IsNullOrWhiteSpace(toDate)
                    ? DateTime.Today
                    : Convert.ToDateTime(toDate, ci);
                using (var vfi = new tammaContext()) {
                    //vfi.Configuration.LazyLoadingEnabled = false;

                    #region sx1

                    var importSx1Details = (from sx in vfi.ImportFormSX1Detail
                                            where sx.ImportFormSX1.MaterialUseDate >= fDate &&
                                                  sx.ImportFormSX1.MaterialUseDate <= tDate &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                  sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                      .Transaction.Status ==
                                                  (byte)MyUtilities.Transaction.Status.Approved &&
                                                  sx.MachineId == machineId &&
                                                  sx.ProductId == productId
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                            orderby sx.ImportFormSX1.MaterialUseDate
                                            select new {
                                                sx.DetailId,
                                                sx.MachineId,
                                                sx.Machine,
                                                sx.ProductId,
                                                sx.Product.ProductCode,
                                                ProductPrice = sx.Product.UnitPrice ?? 0,
                                                sx.ProductionRate,
                                                sx.ImportFormSX1.MaterialUseDate,
                                                sx.Product.Productivity,
                                                sx.MaterialInvId,
                                                sx.MaterialInventory.Material.MaterialId,
                                                sx.MaterialInventory.Material.MaterialName,
                                                sx.MaterialInventory.Material.OutDiameter,
                                                sx.MaterialInventory.Material.InDiameter,
                                                sx.MaterialInventory.Material.Shape,
                                                sx.MaterialInventory.Material.DiameterType,
                                                sx.MaterialInventory.LotNumber,
                                                sx.MaterialInventory.Vendor.VendorCode,
                                                sx.MaterialInventory.Length,
                                                MaterialPrice = sx.MaterialInventory.UnitPrice,
                                                Number = sx.Number1 + sx.Number2,
                                                Processing = sx.Processing1 + sx.Processing2,
                                                Defect = sx.DefectProduct1 + sx.DefectProduct2,
                                                MaterialUse = sx.MaterialUse1 + sx.MaterialUse2,
                                                //sx.ImportFormSX1.Shift1Name,
                                                ShiftName = (sx.ImportFormSX1.Shift1Name + "") + (sx.ImportFormSX1.Shift2Name + ""),
                                                ProductionLot = sx.LotNumber
                                            }).ToList();
                    if (!string.IsNullOrWhiteSpace(shift))
                        importSx1Details = importSx1Details.Where(sx => sx.ShiftName.Contains(shift))
                            .ToList();
                    foreach (var firstDetail in importSx1Details) {
                        if (!firstDetail.ShiftName.Contains(shift)) continue;
                        var entity = new ProductionDailyReport {
                            MachineId = firstDetail.MachineId.Value,
                            MachineName = firstDetail.Machine,
                            ProductId = firstDetail.ProductId,
                            ProductCode = firstDetail.ProductCode,
                            ProductionRate = firstDetail.ProductionRate,
                            ReportDate = firstDetail.MaterialUseDate,
                            Shifts = new List<Shift>(),
                            Shift1Name = firstDetail.ShiftName,
                            Productivity = firstDetail.Productivity ?? 0,
                            MaterialCode =
                                firstDetail.MaterialName + MyUtilities.Material.GetMaterialDesignNo(
                                    firstDetail.OutDiameter, firstDetail.InDiameter,
                                    firstDetail.DiameterType, firstDetail.Shape),
                            //Shift1Count = importSx1DetailsById.Count(),
                            ProductUnitPrice = firstDetail.ProductPrice,
                            LotNumber = firstDetail.ProductionLot
                        };
                        //entity.UnitPrice =
                        //    importSx1DetailsById.Select(id => id.MaterialPrice).Distinct().Average();

                        var shift1 = new Shift() {
                            Quantity = firstDetail.Number,
                            ProcessingQuantity = firstDetail.Processing,
                            DefectQuantity = firstDetail.Defect,
                            MaterialUse = firstDetail.MaterialUse,
                            //ProductionRate = detail.ProductionRate,
                            ProductionRate = firstDetail.ProductionRate,
                        };
                        entity.Shifts.Add(shift1);
                        model.Add(entity);
                    }

                    #endregion

                    #region phay

                    var importCncs = (from sxd in vfi.ImportFormCncDetails
                                      where sxd.ImportFormCnc.MaterialUseDate >= fDate &&
                                            sxd.ImportFormCnc.MaterialUseDate <= tDate &&
                                            sxd.ProductId == productId &&
                                            sxd.MachineId == machineId &&
                                            (sxd.ImportFormCnc.Shift1Name.Contains(shift) ||
                                            sxd.ImportFormCnc.Shift2Name.Contains(shift))
                                      orderby sxd.ImportFormCnc.MaterialUseDate
                                      select new {
                                          sxd.MachineId,
                                          sxd.ImportFormCnc.MaterialUseDate,
                                          sxd.Machine.MachineName,
                                          sxd.ProductId,
                                          sxd.Product.ProductCode,
                                          ProductPrice = sxd.Product.UnitPrice ?? 0,
                                          sxd.ImportFormCnc.Shift1Name,
                                          sxd.ImportFormCnc.Shift2Name,
                                          ShiftName = sxd.ImportFormCnc.Shift1Name + sxd.ImportFormCnc.Shift2Name,
                                          sxd.ImportFormCnc.TransactionCode,
                                          sxd.Number1,
                                          sxd.Number2,
                                          sxd.Processing1,
                                          sxd.Processing2,
                                          sxd.DefectProduct1,
                                          sxd.DefectProduct2,
                                          MaterialPrice = sxd.Product.Material.UnitPrice,
                                      }).ToList();

                    if (!string.IsNullOrWhiteSpace(shift))
                        importCncs =
                            importCncs.Where(sx => sx.ShiftName.Contains(shift))
                                .ToList();
                    var transactionCodes = importCncs.Select(id => id.TransactionCode).Distinct().ToList();
                    var transactionDetails = from td in vfi.TransactionDetails
                                             where transactionCodes.Contains(td.Transaction.TransactionCode) &&
                                             td.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                             select td;

                    var productionPriceRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseProductionPriceRate);
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    foreach (var detail in importCncs) {
                        if (!detail.ShiftName.Contains(shift)) continue;
                        bool isTransaction = false, isProcessing = false, isDefect = false;
                        if (detail.Number1 + detail.Number2 > 0) {
                            var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                td.ReferenceId == detail.ProductId &&
                                td.Transaction.TransactionCode.Equals(detail.TransactionCode) &&
                                td.Quantity == detail.Number1 + detail.Number2 &&
                                td.Transaction.WarehouseReceiptId != MyUtilities.Warehouse.Processing &&
                                td.Transaction.WarehouseReceiptId != MyUtilities.Warehouse.Defect);
                            if (transactionDetailsById != null)
                                isTransaction = true;
                        }
                        if (detail.Processing1 + detail.Processing2 > 0) {
                            var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                td.ReferenceId == detail.ProductId &&
                                td.Transaction.TransactionCode.Equals(detail.TransactionCode) &&
                                td.Quantity == detail.Processing1 + detail.Processing2 &&
                                td.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Processing);
                            if (transactionDetailsById != null)
                                isProcessing = true;
                        }
                        if (detail.DefectProduct1 + detail.DefectProduct2 > 0) {
                            var transactionDetailsById = transactionDetails.FirstOrDefault(td =>
                                td.ReferenceId == detail.ProductId &&
                                td.Transaction.TransactionCode.Equals(detail.TransactionCode) &&
                                td.Quantity == detail.DefectProduct1 + detail.DefectProduct2 &&
                                td.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Defect);
                            if (transactionDetailsById != null)
                                isDefect = true;
                        }
                        if (!isTransaction && !isProcessing && !isDefect)
                            continue;
                        var shiftName = "0";
                        for (var str = 'A'; str <= 'C'; str++) {
                            if (detail.Shift1Name.Contains(str) || detail.Shift2Name.Contains(str)) {
                                shiftName = str + "";
                                break;
                            }
                        }
                        //var entity = model.FirstOrDefault(m => m.ProductId == detail.ProductId &&
                        //    m.MachineId == detail.MachineId &&
                        //    m.MaterialInvId == m.MaterialInvId &&
                        //     m.Shift1Name.Contains(shiftName));
                        //if (entity == null)
                        //{
                        var entity = new ProductionDailyReport {
                            MachineId = detail.MachineId,
                            MachineName = detail.MachineName,
                            ProductId = detail.ProductId,
                            ProductCode = detail.ProductCode,
                            ProductionRate = 0,
                            Shifts = new List<Shift>(),
                            Shift1Name = shiftName,
                            FromDate = fromDate,
                            ToDate = toDate,
                            ReportDate = detail.MaterialUseDate,
                            //Productivity = detail.Productivity ?? 0,
                            //MaterialCode =
                            //    detail.MaterialName + MyUtilities.Material.GetMaterialDesignNo(
                            //        detail.OutDiameter, detail.InDiameter,
                            //        detail.DiameterType, detail.Shape),
                            ProductUnitPrice = MyUtilities.Product.ProductVndPrice(detail.ProductPrice, productionPriceRate, exchangeRate),
                        };
                        //if (entity.ProductUnitPrice > 0) {
                        //    var productPrice = Math.Round(entity.ProductUnitPrice, 4);
                        //    var temp = Convert.ToInt32(productPrice);
                        //    if (productPrice - temp != 0)
                        //        productPrice = productPrice * MyUtilities.Product.ExchangeRateDesign;
                        //    entity.ProductUnitPrice = productPrice;
                        //}
                        var lastTrack = MyUtilities.Machine.LastTrackUpMachine(entity.MachineId, null, entity.ProductId, detail.MaterialUseDate);
                        if (lastTrack != null) {
                            //if (detail.Productivity == 0)
                            entity.Productivity = lastTrack.RealProductivity;
                            entity.ProductionRate = lastTrack.RealRate;
                        }
                        if (detail.Shift1Name.Contains(shiftName)) {
                            var shift1 = new Shift() {
                                UseDate = detail.MaterialUseDate,

                                Quantity = isTransaction ? detail.Number1 : 0,
                                ProcessingQuantity = isProcessing ? detail.Processing1 : 0,
                                DefectQuantity = isDefect ? detail.DefectProduct1 : 0,
                                MaterialUse = 0,
                                ProductionRate = entity.ProductionRate,
                                MaterialPrice = detail.MaterialPrice
                            };
                            entity.Shifts.Add(shift1);
                        }
                        else if (detail.Shift2Name.Contains(shiftName)) {
                            var shift2 = new Shift() {
                                UseDate = detail.MaterialUseDate,

                                Quantity = isTransaction ? detail.Number2 : 0,
                                ProcessingQuantity = isProcessing ? detail.Processing2 : 0,
                                DefectQuantity = isDefect ? detail.DefectProduct2 : 0,
                                MaterialUse = 0,
                                ProductionRate = entity.ProductionRate,
                                MaterialPrice = detail.MaterialPrice
                            };
                            entity.Shifts.Add(shift2);
                        }
                        model.Add(entity);
                    }

                    #endregion
                }

                //if (!string.IsNullOrWhiteSpace(productCode))
                //    model = model.Where(sx => sx.ProductCode.Contains(productCode))
                //        .ToList();
                //if (!string.IsNullOrWhiteSpace(machineName))
                //    model = model.Where(sx => sx.MachineName.Contains(machineName))
                //        .ToList();
                model = model.OrderBy(m => m.ReportDate).ToList();
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionTotalDetailReport", ex.Message);
            }
            //return View(new GridModel(model.OrderBy(m => m.ReportDate)
            //    .ThenBy(m => m.Shifts)
            //    .ThenBy(m => m.MachineName)
            //    .ToList()));
            return View(new GridModel(model));
        }

        [HttpPost]
        public ActionResult PrintProductionMonthlyDateReport(string fromDate, string toDate) {
            var model = new List<ProductionMonthlyReport>();
            try {
                var ci = new CultureInfo("vi-VN");
                var fromD = string.IsNullOrWhiteSpace(fromDate)
                                  ? DateTime.Today
                                  : Convert.ToDateTime(fromDate, ci);
                var toD = string.IsNullOrWhiteSpace(toDate)
                                  ? DateTime.Today
                                  : Convert.ToDateTime(toDate, ci);
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var importSx1Details = from sxd in vfi.ImportFormSX1Detail
                                           where
                                           sxd.ImportFormSX1.MaterialUseDate >= fromD &&
                                           sxd.ImportFormSX1.MaterialUseDate <= toD &&
                                           sxd.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                           sxd.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                           sxd.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                               .Transaction.Status ==
                                           (byte)MyUtilities.Transaction.Status.Approved
                                           orderby sxd.ImportFormSX1.MaterialUseDate
                                           select new {
                                               sxd.ProductId,
                                               sxd.Product.ProductCode,
                                               sxd.Product.UnitPrice,
                                               Number = sxd.Number1 + sxd.Number2,
                                               Processing = sxd.Processing1 + sxd.Processing2,
                                               DefectProduct = sxd.DefectProduct1 + sxd.DefectProduct2,
                                               MaterialUse = sxd.MaterialUse1 + sxd.MaterialUse2,
                                               sxd.ImportFormSX1.MaterialUseDate,
                                               sxd.Machine,
                                               sxd.MachineId,
                                               MaterialInvId = sxd.MaterialInvId ?? 0,
                                               MaterialCode = sxd.MaterialInventory.Material.MaterialCode,
                                               MaterialLot = sxd.MaterialInventory.LotNumber,
                                               MaterialWeight = sxd.MaterialInventory.UnitWeight,
                                               sxd.LotNumber,
                                               sxd.ProductionRate,
                                               sxd.ProductWeight,
                                           };
                    var importSx1DetailsById = (from id in importSx1Details
                                                select new {
                                                    id.MachineId,
                                                    id.Machine,
                                                    id.ProductId,
                                                    id.ProductCode,
                                                    id.ProductWeight,
                                                    id.MaterialInvId,
                                                    MaterialCode = id.MaterialCode,
                                                    MaterialLot = id.MaterialLot,
                                                    id.LotNumber,
                                                }).Distinct().ToList();
                    var materialDates = importSx1Details.Select(id => id.MaterialUseDate).Distinct().ToList();
                    foreach (var sx1Detail in importSx1DetailsById) {
                        var entity = new ProductionMonthlyReport() {
                            MachineId = sx1Detail.MachineId.Value,
                            MachineName = sx1Detail.Machine,
                            ProductionLot = sx1Detail.LotNumber,
                            ProductId = sx1Detail.ProductId,
                            ProductCode = sx1Detail.ProductCode,
                            MaterialInvId = sx1Detail.MaterialInvId,
                            ProductWeight = sx1Detail.ProductWeight,
                            MaterialInvCode = sx1Detail.MaterialCode + "-" + sx1Detail.MaterialLot,
                            ReportDate = toD,
                        };
                        foreach (var materialDate in materialDates) {
                            var importSx1DetailsByDate = importSx1Details
                                .Where(id => id.MaterialUseDate == materialDate &&
                                             id.ProductId == entity.ProductId &&
                                             id.MachineId == entity.MachineId &&
                                             id.MaterialInvId == entity.MaterialInvId &&
                                             id.ProductWeight == entity.ProductWeight);
                            var shift = new Shift();
                            if (importSx1DetailsByDate.Any()) {
                                shift = new Shift() {
                                    UseDate = materialDate,
                                    MaterialUse = importSx1DetailsByDate.Sum(id => id.MaterialUse),
                                    Quantity = importSx1DetailsByDate.Sum(id => id.Number),
                                    ProcessingQuantity = importSx1DetailsByDate.Sum(id => id.Processing),
                                    DefectQuantity = importSx1DetailsByDate.Sum(id => id.DefectProduct),
                                    ProductionRate = importSx1DetailsByDate.FirstOrDefault().ProductionRate,
                                    MaterialWeight = importSx1DetailsByDate.FirstOrDefault().MaterialWeight,
                                };
                            }
                            else {
                                shift = new Shift() {
                                    UseDate = materialDate,
                                };
                            }
                            entity.Shifts.Add(shift);
                        }
                        model.Add(entity);

                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("ProductionMonthlyDate", ex.Message);
            }
            model = model.OrderBy(m => m.MachineName).ThenBy(m => m.ProductionLot).ToList();
            return PartialView("PageProductionMonthlyDate", model);
        }

        [HttpPost]
        public ActionResult PrintProductionMonthlyReport(int month, int year, string shift) {
            var model = new List<ProductionMonthlyReport>();
            try {
                using (var vfi = new tammaContext()) {
                    var toDate = new DateTime(year, month, 26);
                    var fromDate = toDate.AddMonths(-1);
                    var importSx1Details = (from sxd in vfi.ImportFormSX1Detail
                                            where
                                                (sxd.ImportFormSX1.Shift1Name.Contains(shift) ||
                                                 sxd.ImportFormSX1.Shift2Name.Contains(shift)) &&
                                                sxd.ImportFormSX1.MaterialUseDate >= fromDate &&
                                                sxd.ImportFormSX1.MaterialUseDate < toDate &&
                                                sxd.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                sxd.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                sxd.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                   .Transaction.Status ==
                                                (byte)MyUtilities.Transaction.Status.Approved
                                            //&& sxd.Product.ProductCode.Equals("F3 105A")
                                            //&& sxd.ImportFormSX1.MaterialUseDate.Day == 5
                                            //&& sxd.ProductId == 411
                                            orderby sxd.ImportFormSX1.MaterialUseDate
                                            select new {
                                                sxd.ProductId,
                                                sxd.Product.ProductCode,
                                                sxd.Product.Productivity,
                                                sxd.Product.UnitPrice,
                                                Shift1Name = sxd.ImportFormSX1.Shift1Name.Trim(),
                                                Shift2Name = sxd.ImportFormSX1.Shift2Name.Trim(),
                                                Production1 = (sxd.Number1 + sxd.Processing1),
                                                Production2 = (sxd.Number2 + sxd.Processing2),
                                                DefectProduct1 = sxd.DefectProduct1,
                                                DefectProduct2 = sxd.DefectProduct2,
                                                sxd.ImportFormSX1.MaterialUseDate,
                                                sxd.Machine1,
                                                sxd.MachineId,
                                            }).ToList();
                    var productionPriceRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.BaseProductionPriceRate);
                    var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
                    foreach (var sx1Detail in importSx1Details) {
                        var entity = model.FirstOrDefault(m => m.ProductId == sx1Detail.ProductId);
                        var trackUps =
                                vfi.RealProductions.Where(
                                    rp => rp.ProductId == sx1Detail.ProductId && rp.MachineId == sx1Detail.MachineId).ToList();
                        var productivity = 0.0;
                        if (trackUps.Any()) {
                            productivity = trackUps.LastOrDefault().TrackUpMachine.RealProductivity;
                        }
                        else {
                            productivity = sx1Detail.Productivity ?? 0;
                        }
                        //var processing =
                        //    processingType.FirstOrDefault(pt => pt.TypeId == sx1Detail.Product.ProcessingDesign);
                        if (entity == null) {
                            entity = new ProductionMonthlyReport {
                                ProductId = sx1Detail.ProductId,
                                ProductCode = sx1Detail.ProductCode,
                                ReportDate = new DateTime(year, month, 1),
                                Shift = shift,
                                SalePrice = MyUtilities.Product.ProductVndPrice(sx1Detail.UnitPrice, productionPriceRate, exchangeRate)
                            };
                            //entity.SalePrice = sx1Detail.UnitPrice ?? 0*MyUtilities.Product.DesignPrice;
                            //if (sx1Detail.UnitPrice != null || sx1Detail.UnitPrice != 0) {
                            //    var productPrice = Math.Round(sx1Detail.UnitPrice.Value, 4);
                            //    var temp = Convert.ToInt32(productPrice);
                            //    if (productPrice - temp != 0)
                            //        productPrice = Math.Round(productPrice * MyUtilities.Product.ExchangeRateDesign, 0);
                            //    entity.SalePrice = productPrice * MyUtilities.Product.BaseProductionPrice;
                            //}
                            if (sx1Detail.Shift1Name.Contains(shift)) {
                                entity.Production[sx1Detail.MaterialUseDate.Day - 1] =
                                    sx1Detail.Production1;
                                entity.Defect[sx1Detail.MaterialUseDate.Day - 1] =
                                    sx1Detail.DefectProduct1;
                                entity.ProductionCost[sx1Detail.MaterialUseDate.Day - 1] =
                                    sx1Detail.Production1 * productivity *
                                    (sx1Detail.Machine1.ProcessingType.ProcessingFactor ?? 0);
                            }
                            else {
                                entity.Production[sx1Detail.MaterialUseDate.Day - 1] =
                                    sx1Detail.Production2;
                                entity.Defect[sx1Detail.MaterialUseDate.Day - 1] =
                                    sx1Detail.DefectProduct2;
                                entity.ProductionCost[sx1Detail.MaterialUseDate.Day - 1] =
                                    sx1Detail.Production2 * productivity *
                                    (sx1Detail.Machine1.ProcessingType.ProcessingFactor ?? 0);
                            }
                            entity.TotalProduction = entity.Production.Sum();
                            entity.TotalDefect = entity.Defect.Sum();
                            entity.TotalProductionCost = entity.ProductionCost.Sum();
                            entity.TotalDefectCost = entity.TotalDefect * entity.SalePrice;
                            model.Add(entity);
                        }
                        else {
                            if (sx1Detail.Shift1Name.Contains(shift)) {
                                entity.Production[sx1Detail.MaterialUseDate.Day - 1] +=
                                    sx1Detail.Production1;
                                entity.Defect[sx1Detail.MaterialUseDate.Day - 1] +=
                                    sx1Detail.DefectProduct1;
                                entity.ProductionCost[sx1Detail.MaterialUseDate.Day - 1] +=
                                    sx1Detail.Production1 * productivity *
                                    (sx1Detail.Machine1.ProcessingType.ProcessingFactor ?? 0);
                            }
                            else {
                                entity.Production[sx1Detail.MaterialUseDate.Day - 1] +=
                                    sx1Detail.Production2;
                                entity.Defect[sx1Detail.MaterialUseDate.Day - 1] +=
                                    sx1Detail.DefectProduct2;
                                entity.ProductionCost[sx1Detail.MaterialUseDate.Day - 1] +=
                                    sx1Detail.Production2 * productivity *
                                    (sx1Detail.Machine1.ProcessingType.ProcessingFactor ?? 0);
                            }
                            entity.TotalProduction = entity.Production.Sum();
                            entity.TotalDefect = entity.Defect.Sum();
                            entity.TotalProductionCost = entity.ProductionCost.Sum();
                            entity.TotalDefectCost = entity.TotalDefect * entity.SalePrice;
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("ProductionMonthlyInShift", ex.Message);
            }
            return PartialView("PageProductionMonthlyInShift", model.OrderBy(p => p.ProductCode).ToList());
        }

        [HttpPost]
        public ActionResult PrintProductionDefectDailyReport(string monthlyDate) {
            var model = new List<ProductionDefectDailyModel>();
            try {
                using (var vfi = new tammaContext()) {
                    var ci = new CultureInfo("vi-VN");

                    var reportDate = string.IsNullOrWhiteSpace(monthlyDate)
                                         ? DateTime.Today
                                         : Convert.ToDateTime(monthlyDate, ci);
                    var startDate = new DateTime(reportDate.Year, reportDate.Month, 1);
                    var transactionDetails = from t in vfi.TransactionDetails
                                             where t.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                                   &&
                                                   t.Transaction.WarehouseReceiptId ==
                                                   MyUtilities.Warehouse.Defect
                                                   && t.Transaction.CreatedDate >= startDate
                                                   && t.Transaction.CreatedDate <= reportDate
                                             select new {
                                                 t.ReferenceId,
                                                 t.Quantity,
                                                 t.Note,
                                                 t.Transaction.WarehouseIssueId,
                                                 t.Transaction.CreatedDate,
                                             };
                    var productIds = transactionDetails.Select(td => td.ReferenceId).Distinct();
                    var i = 1;
                    var production2Ids = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    foreach (var productId in productIds) {
                        var product = vfi.Products.FirstOrDefault(p => p.ProductId == productId);
                        if (productId == null)
                            throw new AggregateException("Lỗi sản phẩm không tìm thấy");
                        var entity = new ProductionDefectDailyModel {
                            ProductCode = product.ProductCode,
                            FromCncQuantityInMonth = 0,
                            FromCncQuantity = 0,
                            FromProcessingQuantity = 0,
                            FromProcessingQuantityInMonth = 0,
                            FromQcQuantity = 0,
                            FromQcQuantityInMonth = 0,
                            FromSx1Quantity = 0,
                            FromSx1QuantityInMonth = 0,
                            FromSx2Quantity = 0,
                            FromSx2QuantityInMonth = 0,
                            Index = i,
                            ReportDate = reportDate
                        };
                        var transactionSx1 =
                            transactionDetails.Where(
                                td =>
                                td.WarehouseIssueId == null &&
                                td.ReferenceId == productId);
                        if (transactionSx1.Any()) {
                            entity.FromSx1QuantityInMonth = transactionSx1.Sum(t => t.Quantity);
                            var transactionSx1InDay = transactionSx1.Where(t => t.CreatedDate == reportDate);
                            if (transactionSx1InDay.Any()) {
                                entity.FromSx1Quantity = transactionSx1InDay.Sum(t => t.Quantity);
                            }
                        }
                        var transactionCnc =
                            transactionDetails.Where(td => td.WarehouseIssueId == MyUtilities.Warehouse.Cnc &&
                                td.ReferenceId == productId);
                        if (transactionCnc.Any()) {
                            entity.FromCncQuantityInMonth = transactionCnc.Sum(t => t.Quantity);
                            var transactionCncInDay = transactionSx1.Where(t => t.CreatedDate == reportDate);
                            if (transactionCncInDay.Any()) {
                                entity.FromCncQuantity = transactionCncInDay.Sum(t => t.Quantity);
                            }
                        }
                        var transactionSx2 =
                            transactionDetails.Where(td => production2Ids.Contains(td.WarehouseIssueId.Value) &&
                                                           td.ReferenceId == productId);
                        if (transactionSx2.Any()) {
                            entity.FromSx2QuantityInMonth = transactionSx2.Sum(t => t.Quantity);
                            var transactionSx2InDay = transactionSx2.Where(t => t.CreatedDate == reportDate);
                            if (transactionSx2InDay.Any()) {
                                entity.FromSx2Quantity = transactionSx2InDay.Sum(t => t.Quantity);
                            }
                        }
                        var transactionQc =
                            transactionDetails.Where(
                                td =>
                                (td.WarehouseIssueId == MyUtilities.Warehouse.QcA ||
                                td.WarehouseIssueId == MyUtilities.Warehouse.QcB) &&
                                td.ReferenceId == productId);
                        if (transactionQc.Any()) {
                            entity.FromQcQuantityInMonth = transactionQc.Sum(t => t.Quantity);
                            var transactionQcInDay = transactionQc.Where(t => t.CreatedDate == reportDate);
                            if (transactionQcInDay.Any()) {
                                entity.FromQcQuantity = transactionQcInDay.Sum(t => t.Quantity);
                            }
                        }
                        var transactionProcessing =
                            transactionDetails.Where(td => td.WarehouseIssueId == MyUtilities.Warehouse.Processing &&
                                td.ReferenceId == productId);
                        if (transactionProcessing.Any()) {
                            entity.FromProcessingQuantityInMonth = transactionProcessing.Sum(t => t.Quantity);
                            var transactionProcessingInDay =
                                transactionProcessing.Where(t => t.CreatedDate == reportDate);
                            if (transactionProcessingInDay.Any()) {
                                entity.FromProcessingQuantity = transactionProcessingInDay.Sum(t => t.Quantity);
                            }
                        }
                        entity.FromTotal = entity.FromSx1Quantity + entity.FromSx2Quantity + entity.FromCncQuantity +
                                           entity.FromQcQuantity + entity.FromProcessingQuantity;
                        entity.FromTotalInMonth = entity.FromSx1QuantityInMonth + entity.FromSx2QuantityInMonth +
                                                  entity.FromCncQuantityInMonth +
                                                  entity.FromQcQuantityInMonth + entity.FromProcessingQuantityInMonth;
                        i++;
                        model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintProductionDefectDailyReport", ex.Message);
            }
            return PartialView("PageProductionDefectDaily", model.OrderBy(p => p.ProductCode).ToList());
        }

        [GridAction]
        public ActionResult SelectProductionMaterialManagement(string materialcode, string fromDate, string toDate) {
            var model = new List<MaterialInventoryModel>();
            if (string.IsNullOrWhiteSpace(fromDate))
                return View(new GridModel(model));
            try {
                var ci = new CultureInfo("vi-VN");
                var fdate = string.IsNullOrWhiteSpace(fromDate)
                                ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                                : Convert.ToDateTime(fromDate, ci);
                var tdate = string.IsNullOrWhiteSpace(toDate)
                                ? DateTime.Now
                                : Convert.ToDateTime(toDate, ci);
                using (var vfi = new tammaContext()) {
                    //var materiaInvs = materialInvs.Select(mi => mi.MaterialInventoryId).ToList();
                    var productions = (from i in vfi.ImportFormSX1Detail
                                       where
                                           i.ImportFormSX1.MaterialUseDate >= fdate &&
                                           i.ImportFormSX1.MaterialUseDate <= tdate &&
                                           i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                           i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                           i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                            .Transaction.Status ==
                                           (byte)MyUtilities.Transaction.Status.Approved
                                       //&& i.Product.ProductCode.Contains(productCode)
                                       //&& i.MachineId == 68
                                       select i.MaterialInvId);
                    var materialInvIds = productions.Select(mi => mi).ToList();
                    var materialInvs = from mi in vfi.MaterialInventories
                                       where mi.Material.MaterialCode.Contains(materialcode) &&
                                             mi.Material.Active &&
                                             materialInvIds.Contains(mi.MaterialInventoryId)
                                       select mi;
                    var materialIds = materialInvs.Select(mi => mi.MaterialId).Distinct().ToList();
                    var imports = from id in vfi.ImportPurchaseOrderDetails
                                  where
                                      id.ImportPurchaseOrder.Transaction.Status ==
                                      (byte)MyUtilities.Transaction.Status.Approved
                                      && materialIds.Contains(id.MaterialId.Value)
                                  //&& id.ImportPurchaseOrder.PurchaseOrderId == null
                                  select new {
                                      id.MaterialId,
                                      id.LotNumber,
                                      id.VendorId,
                                      id.ImportPurchaseOrder.PurchaseOrderId,
                                      id.Length,
                                      id.Quantity
                                  };
                    var destroys = (from em in vfi.ExportMaterialDetails
                                    where
                                        em.ExportMaterial.Transaction.Status ==
                                        (byte)MyUtilities.Transaction.Status.Approved &&
                                        em.MachineId == null
                                        && materialInvIds.Contains(em.MaterialInvId)
                                    select new {
                                        em.MaterialInvId,
                                        em.Quantity,
                                    }).ToList();
                    var destroysOnMachine = from dom in vfi.MaterialUseDetails
                                            where
                                                dom.MaterialUseInShift.Status ==
                                                (byte)MyUtilities.Transaction.Status.Approved
                                                && dom.IsDetroy
                                                && materialInvIds.Contains(dom.MaterialInvId)
                                            select new {
                                                dom.MaterialInvId,
                                                Quantity = dom.EditQuantity + dom.EditQuantity2
                                            };
                    foreach (var materialInventory in materialInvs) {
                        var entity = new MaterialInventoryModel {
                            MaterialId = materialInventory.MaterialId,
                            MaterialInventoryId = materialInventory.MaterialInventoryId,
                            Length = materialInventory.Length,
                            MaterialTypeCode = materialInventory.Material.MaterialType.IdentityCode,
                            MaterialCode = materialInventory.Material.MaterialCode,
                            MaterialName = materialInventory.Material.MaterialName,
                            OutDiameter = materialInventory.Material.OutDiameter,
                            InDiameter = materialInventory.Material.InDiameter,
                            Shape = materialInventory.Material.Shape,
                            DiameterType = materialInventory.Material.DiameterType,
                            LotNumber = materialInventory.LotNumber,
                            TotalQty = materialInventory.TotalQty,
                            UnitWeight = materialInventory.UnitWeight,
                            UnitPrice = materialInventory.UnitPrice,
                            EarlyQuantity = materialInventory.ImportQuantity,
                            EarlyQuantityKg = materialInventory.ImportQuantityKg,
                            ImportDate = materialInventory.ImportDate,
                            //EarlyQuantity = 
                            EndDate = materialInventory.EndDate ?? DateTime.Now,
                            VendorCode = materialInventory.Vendor.VendorCode,
                            VendorName = materialInventory.Vendor.VendorName,
                            VendorId = materialInventory.VendorId ?? 0,
                            Code = MyUtilities.Material.GetMaterialInvDesignNo(materialInventory),
                        };
                        var productionsById = (from i in vfi.ImportFormSX1Detail
                                               where
                                                   i.MaterialInvId == entity.MaterialInventoryId &&
                                                   i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                   i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                   i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                    .Transaction.Status ==
                                                   (byte)MyUtilities.Transaction.Status.Approved
                                               //&& i.Product.ProductCode.Contains(productCode)
                                               //&& i.MachineId == 68
                                               select new {
                                                   i.MachineId,
                                                   i.ProductId,
                                                   i.Product.ProductCode,
                                                   MaterialUse = i.MaterialUse1 + i.MaterialUse2,
                                                   Quantity = i.Number1 + i.Number2 +
                                                              i.Processing1 + i.Processing2 +
                                                              i.DefectProduct1 + i.DefectProduct2,
                                                   i.ImportFormSX1.MaterialUseDate,
                                                   i.ProductionRate,
                                                   i.ProductWeight,
                                                   ProductLength = i.Product.Length ?? 0,
                                                   MaterialLength = i.MaterialInventory.Length,
                                               });
                        //var machineIds = productionsById.Select(id => id.MachineId).Distinct().ToList();
                        //foreach (var machineId in machineIds)
                        //{
                        //    var details = GetProductionMaterialManagementMachineDetail(entity.MaterialInventoryId,
                        //                                                               machineId.Value);
                        //    entity.ProductionDiff += details.Sum(d => d.MaterialDiff);
                        //    entity.ExportUse += details.Sum(d => d.TotalUse);
                        //}
                        var productionList = (from id in productionsById
                                              select new {
                                                  id.ProductId,
                                                  id.MachineId
                                              }).Distinct().ToList();
                        foreach (var production in productionList) {
                            var realProduction =
                                vfi.RealProductions.FirstOrDefault(
                                    rp => rp.ProductId == production.ProductId && rp.MachineId == production.MachineId);
                            var rate = 1.0;
                            if (realProduction != null) {
                                rate = MyUtilities.Product.GetProductRate(entity.Length,
                                                                          realProduction.TrackUpMachine.WorkPiece,
                                                                          realProduction.TrackUpMachine.KnifeCut,
                                                                          realProduction.Product.Length ?? 0);
                                entity.Require += Math.Round(realProduction.TrackUpMachine.Quantity / rate, 2);
                            }
                            var productionDetails =
                                productionsById.Where(
                                    id => id.MachineId == production.MachineId && id.ProductId == production.ProductId);
                            var quantity = 0.0;
                            var use = 0.0;
                            if (productionDetails.Any()) {
                                quantity = productionDetails.Sum(id => id.Quantity);
                                use = productionDetails.Sum(id => id.MaterialUse);
                            }
                            entity.ProductionDiff += quantity / rate - use;
                            entity.ExportUse += use;
                        }
                        if (productionsById.Any()) {
                            entity.Day =
                                productionsById.Select(id => id.MaterialUseDate).Distinct().Count();
                        }


                        var materialOnMachines =
                            vfi.MaterialInvOnMachines.Where(mim => mim.MaterialInvId == entity.MaterialInventoryId);
                        if (materialOnMachines.Any()) {
                            entity.MaterialInvOnMachine = materialOnMachines.Sum(mim => mim.TotalQuantity);
                        }
                        entity.TotalQtyKg = materialInventory.TotalQty * entity.UnitWeight;

                        var importDetails =
                            imports.Where(
                                id =>
                                id.LotNumber.Equals(entity.LotNumber) &&
                                id.Length == entity.Length &&
                                id.VendorId == entity.VendorId &&
                                id.MaterialId == entity.MaterialId &&
                                id.PurchaseOrderId != null);
                        if (importDetails.Any())
                            entity.ImportPurchase = importDetails.Sum(id => id.Quantity);
                        importDetails =
                            imports.Where(
                                id =>
                                id.LotNumber.Equals(entity.LotNumber) &&
                                id.Length == entity.Length &&
                                id.VendorId == entity.VendorId &&
                                id.MaterialId == entity.MaterialId &&
                                id.PurchaseOrderId == null);
                        if (importDetails.Any())
                            entity.ImportMore = importDetails.Sum(id => id.Quantity);
                        var destroy = destroys.Where(ed => ed.MaterialInvId == entity.MaterialInventoryId);
                        if (destroy.Any())
                            entity.ExportDestroy = destroy.Sum(ed => ed.Quantity);
                        var destroyById = destroysOnMachine.Where(dom => dom.MaterialInvId == entity.MaterialInventoryId);
                        if (destroyById.Any())
                            entity.DestroyOnMachine = destroyById.Sum(dom => dom.Quantity);
                        model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionMaterialManagement", ex.Message);
            }
            return View(new GridModel(model.OrderBy(m => m.MaterialTypeCode)
                                           .ThenBy(m => m.MaterialName)
                                           .ThenBy(m => m.OutDiameter)
                                           .ThenBy(m => m.InDiameter)
                                           .ThenBy(m => m.Shape)
                                           .ThenBy(m => m.DiameterType)
                                           .ThenBy(m => m.VendorCode)
                                           .ThenBy(m => m.LotNumber)
                                           .ThenBy(m => m.Length)
                            ));
        }

