        private List<ProductionMaterialMachine> GetSelectProductionMaterialManagementDetail(int materialInvId) {
            var model = new List<ProductionMaterialMachine>();
            var machineIds = new List<int>();
            var machineInvs = new List<double>();
            using (var vfi = new tammaContext()) {
                var productions = (from i in vfi.ImportFormSX1Detail
                                   where
                                       i.MaterialInvId == materialInvId &&
                                       i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                       i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                       i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                        .Transaction.Status ==
                                       (byte)MyUtilities.Transaction.Status.Approved
                                   //&& i.Product.ProductCode.Contains(productCode)
                                   //&& i.MachineId == 68
                                   select i.MachineId.Value
                                  ).ToList();

                var exports = (from ed in vfi.ExportMaterialDetails
                               where
                                   ed.ExportMaterial.Transaction.Status ==
                                   (byte)MyUtilities.Transaction.Status.Approved &&
                                   ed.MaterialInvId == materialInvId &&
                                   ed.MachineId != null
                               select ed.MachineId.Value).ToList();
                productions.AddRange(exports);
                machineIds = productions.Distinct().ToList();
                foreach (var machineId in machineIds) {
                    var materialInvMachine =
                        vfi.MaterialInvOnMachines.FirstOrDefault(
                            mimp => mimp.MaterialInvId == materialInvId && mimp.MachineId == machineId);
                    if (materialInvMachine == null)
                        machineInvs.Add(0);
                    else
                        machineInvs.Add(materialInvMachine.TotalQuantity);
                }
            }
            for (int i = 0; i < machineIds.Count; i++) {
                var machineId = machineIds[i];
                var entity = new ProductionMaterialMachine {
                    MachineId = machineId,
                    MaterialInvId = materialInvId,
                    MaterialInvOnMachine = machineInvs[i]
                };
                var details = GetProductionMaterialManagementMachineDetail(entity.MaterialInvId, entity.MachineId);
                var lastProduction = details.LastOrDefault(d => d.ProductId != 0);
                if (lastProduction != null) {
                    entity.ProductCode = lastProduction.ProductCode;
                    entity.Require = lastProduction.Require;
                }
                entity.MachineName = details.FirstOrDefault().MachineName;
                entity.Day = details.Count(d => d.ProductRate > 1);
                entity.TotalAssign = details.Sum(d => d.TotalAssign);
                entity.SendBack = details.Sum(d => d.SendBack);
                entity.TotalUse = details.Sum(d => d.TotalUse);
                entity.TotalDestroy = details.Sum(d => d.TotalDestroy);
                entity.ProductionDiff = details.Sum(d => d.ProductionDiff);
                entity.MaterialDiff = details.Sum(d => d.MaterialDiff);
                model.Add(entity);
            }
            return model;
        }

