        List<ProductionMaterialMachineDetail> GetProductionMaterialManagementMachineDetail(int materialInvId,
                                                                                           int machineId) {
            var model = new List<ProductionMaterialMachineDetail>();
            try {
                using (var vfi = new tammaContext()) {
                    var materialInv =
                        vfi.MaterialInventories.FirstOrDefault(mi => mi.MaterialInventoryId == materialInvId);
                    var machine = vfi.Machines.FirstOrDefault(m => m.MachineId == machineId);
                    var productions = (from i in vfi.ImportFormSX1Detail
                                       where
                                           i.MaterialInvId == materialInvId &&
                                           i.MachineId == machineId &&
                                           i.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                           i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                           i.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                            .Transaction.Status ==
                                           (byte)MyUtilities.Transaction.Status.Approved
                                       //&& i.Product.ProductCode.Contains(productCode)
                                       //&& i.MachineId == 68
                                       select new {
                                           i.MachineId,
                                           ProductId = i.ProductId,
                                           i.Product.ProductCode,
                                           MaterialUse = i.MaterialUse1 + i.MaterialUse2,
                                           Production = i.Number1 + i.Number2,
                                           Process = i.Processing1 + i.Processing2,
                                           Defect = i.DefectProduct1 + i.DefectProduct2,
                                           i.ImportFormSX1.MaterialUseDate,
                                           i.ProductionRate,
                                           i.ProductWeight,
                                           ProductLength = i.Product.Length ?? 0,
                                           MaterialLength = i.MaterialInventory.Length,
                                       });
                    var exports = from ed in vfi.ExportMaterialDetails
                                  where
                                      ed.ExportMaterial.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                      ed.MaterialInvId == materialInvId &&
                                      ed.MachineId == machineId
                                  select new {
                                      Quantity = ed.Quantity,
                                      ed.ExportMaterial.ExportDate,
                                  };
                    var uses = from md in vfi.MaterialUseDetails
                               where
                                   md.MaterialUseInShift.Status ==
                                   (byte)MyUtilities.Transaction.Status.Approved
                                   //&& dom.IsDetroy
                                   && materialInvId == md.MaterialInvId
                                   && md.MachineId == machineId
                               select new {
                                   md.MaterialUseInShift.UsedDate,
                                   md.IsDetroy,
                                   md.MaterialUseInShift.Type,
                                   Quantity = md.EditQuantity + md.EditQuantity2
                               };
                    var date = productions.Select(id => id.MaterialUseDate).ToList();
                    var date2 = exports.Select(ed => ed.ExportDate);
                    date.AddRange(date2);
                    date2 = uses.Select(md => md.UsedDate);
                    date.AddRange(date2);
                    date = date.Distinct().OrderBy(d => d).ToList();
                    var productIds = productions.Select(id => id.ProductId).Distinct().ToList();
                    var tracks = (from t in vfi.TrackUpMachines
                                  where t.MachineId == machineId &&
                                        t.MaterialId == materialInv.MaterialId &&
                                        productIds.Contains(t.ProductId) &&
                                        t.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                        t.DeliveryDate != null
                                  orderby t.DeliveryDate
                                  select new {
                                      t.ProductId,
                                      t.KnifeCut,
                                      t.WorkPiece,
                                      t.Quantity,
                                      Date = t.DeliveryDate.Value,
                                      t.RealProductivity,
                                  }).ToList();
                    foreach (var d in date) {
                        var productionsByDate = productions.Where(id => id.MaterialUseDate == d);
                        productIds = productionsByDate.Select(id => id.ProductId).Distinct().ToList();
                        var alreadyAssign = false;
                        foreach (var productId in productIds) {
                            var entity = new ProductionMaterialMachineDetail {
                                MachineId = machineId,
                                MachineName = machine.MachineName,
                                OutDiamter = materialInv.Material.OutDiameter,
                                Date = d,
                                Month = d.Month,
                                Day = d.Day,
                                Year = d.Year,
                            };
                            var productionsById = productionsByDate.Where(id => id.ProductId == productId);
                            entity.ProductCode = productionsById.FirstOrDefault().ProductCode;
                            entity.ProductId = productId;
                            entity.ProductLength = productionsById.FirstOrDefault().ProductLength;
                            entity.MaterialLength = productionsById.FirstOrDefault().MaterialLength;
                            entity.Quantity = productionsById.Sum(id => id.Production);
                            entity.Process = productionsById.Sum(id => id.Process);
                            entity.Defect = productionsById.Sum(id => id.Defect);
                            entity.TotalUse = productionsById.Sum(id => id.MaterialUse);

                            var track = tracks.LastOrDefault(t => t.ProductId == entity.ProductId && t.Date <= entity.Date);
                            if (track != null) {
                                entity.Productivity = track.RealProductivity;
                                entity.KnifeCut = track.KnifeCut;
                                entity.MaterialWorkpiece = track.WorkPiece;
                                entity.Require = track.Quantity / entity.ProductRate;
                            }
                            if (!alreadyAssign) {
                                var exportsById = exports.Where(e => e.ExportDate == entity.Date);
                                if (exportsById.Any()) {
                                    entity.TotalAssign = exportsById.Sum(ed => ed.Quantity);
                                }
                                var usesByDate = uses.Where(md => md.UsedDate == d && md.Type == (int)MyUtilities.Material.UseType.SendBack && !md.IsDetroy).ToList();
                                entity.SendBack = usesByDate.Sum(mu => mu.Quantity); // trả NL
                                usesByDate = uses.Where(md => md.UsedDate == d && md.Type == (int)MyUtilities.Material.UseType.SendBack && md.IsDetroy).ToList();
                                entity.TotalDestroy = usesByDate.Sum(mu => mu.Quantity); // huy NL tren may
                                alreadyAssign = true;
                            }
                            model.Add(entity);
                        }
                        if (productIds.Count == 0) {
                            var entity = new ProductionMaterialMachineDetail {
                                MachineId = machineId,
                                MachineName = machine.MachineName,
                                OutDiamter = materialInv.Material.OutDiameter,
                                Date = d,
                                Month = d.Month,
                                Day = d.Day,
                                Year = d.Year,
                                ProductId = 0
                            };
                            var exportsById = exports.Where(e => e.ExportDate == entity.Date);
                            if (exportsById.Any()) {
                                entity.TotalAssign = exportsById.Sum(ed => ed.Quantity);
                            }
                            var usesByDate = uses.Where(md => md.UsedDate == d && md.Type == (int)MyUtilities.Material.UseType.SendBack && !md.IsDetroy).ToList();
                            entity.SendBack = usesByDate.Sum(mu => mu.Quantity); // trả NL
                            usesByDate = uses.Where(md => md.UsedDate == d && md.Type == (int)MyUtilities.Material.UseType.SendBack && md.IsDetroy).ToList();
                            entity.TotalDestroy = usesByDate.Sum(mu => mu.Quantity); // huy NL tren may
                            model.Add(entity);
                        }
                        //if (productIds.Count > 1)
                        //{
                        //    var exportsById = exports.Where(e => e.ExportDate == entity.Date);
                        //    if (exportsById.Any())
                        //    {
                        //        entity.TotalAssign = exportsById.Sum(ed => ed.Quantity);
                        //    }
                        //    var usesByDate = uses.Where(md => md.UsedDate == d && md.Type == 2).ToList();
                        //    entity.SendBack = usesByDate.Sum(mu => mu.Quantity); // trả NL
                        //    usesByDate = uses.Where(md => md.UsedDate == d && md.Type == 1 && md.IsDetroy).ToList();
                        //    entity.TotalDestroy = usesByDate.Sum(mu => mu.Quantity); // huy NL tren may
                        //    model.Add(entity);
                        //}
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionMaterialManagementDetail", ex.Message);
            }
            return model;
        }

        [GridAction]
        public ActionResult SelectExpectedMaterialPlan(string materialcode, int month, int year, int monthCount, bool isAll) {
            var model = new List<ExpectedMaterialPlanModel>();
            //var nextMonth = new DateTime(year, month, 1).AddMonths(2).AddSeconds(-1);
            //var reportDate = new DateTime(year, month, 1).AddMonths(1).AddSeconds(-1);
            //var lastDate = new DateTime(year, month, 1).AddSeconds(-1);

            var toDate = new DateTime(year, month, 1).AddMonths(monthCount + 1).AddSeconds(-1);
            var fromDate = new DateTime(year, month, 1);
            var nextMonthDate = fromDate.AddMonths(1);
            var startYearDate = new DateTime(year, 1, 1);
            var startLastYearDate = startYearDate.AddYears(-1);

            try {
                using (var vfi = new tammaContext()) {

                    var materials = (from m in vfi.Materials
                                     where m.Active && m.MaterialCode.Contains(materialcode)
                                     orderby m.MaterialType.IdentityCode, m.MaterialName,
                                         m.Shape, m.OutDiameter, m.InDiameter
                                     select new {
                                         m.MaterialId,
                                         m.MaterialCode,
                                         m.MaterialName,
                                         m.MaterialType.MaterialTypeName,
                                         Shape = (m.Shape + "").Trim(),
                                         m.OutDiameter,
                                         m.InDiameter,
                                         DiameterType = m.DiameterType + ""
                                     }).ToList();
                    if (!string.IsNullOrWhiteSpace(materialcode)) {
                        materials = materials.Where(x => x.MaterialCode.Contains(materialcode)).ToList();
                    }
                    var materialIds = materials.Select(m => m.MaterialId).ToList();
                    var pos = (from x in vfi.PurchaseOrderDetails
                               where x.MaterialClassifiedId == 1
                               && materialIds.Contains(x.ReferenceId)
                               && x.OrderQty > x.ReceivedQty
                               && x.PurchaseOrder.Status != (byte)MyUtilities.Sales.Status.Cancel
                               && x.PurchaseOrder.Status != (byte)MyUtilities.Sales.Status.Completed
                               select new {
                                   x.ReferenceId,
                                   Quantity = x.OrderQty - x.ReceivedQty
                               })
                               .GroupBy(x => x.ReferenceId)
                               .Select(x => new {
                                   MaterialId = x.Key,
                                   Quantity = x.Sum(y => y.Quantity)
                               })
                               .ToList();
                    var materialInvs = (from mi in vfi.MaterialInventories
                                        where mi.TotalQty != null && mi.TotalQty > 0 &&
                                        materialIds.Contains(mi.MaterialId)
                                        select new {
                                            mi.MaterialId,
                                            //mi.MaterialInventoryId,
                                            TotalQtyKg = mi.TotalQty * mi.UnitWeight,
                                            OnMachineKg = mi.MaterialInvOnMachines.Any()
                                                        ? mi.MaterialInvOnMachines.Sum(y => y.TotalQuantity) * mi.UnitWeight
                                                        : 0
                                        })
                                       .GroupBy(x => x.MaterialId)
                                       .Select(x => new {
                                           MaterialId = x.Key,
                                           Quantity = x.Sum(y => y.TotalQtyKg + y.OnMachineKg)
                                       })
                                       .ToList();
                    var details = GetExpectedProductionMaterialPlanModel(materialIds, month, year, monthCount);
                    var duplicateProducts = details
                        .GroupBy(x => x.ProductId)
                        .Select(x => new {
                            x.Key,
                            MaterialIds = x.Select(y => y.MaterialId).ToList(),
                            MaterialCount = x.Count()
                        })
                        .Where(x => x.MaterialCount > 1)
                        .ToList();
                    foreach (var material in materials) {
                        //var productsById = productionMaterials.Where(p => p.MaterialId == material.MaterialId);
                        //var productionsById = productions.Where(p => p.MaterialId == material.MaterialId);
                        //if (!productsById.Any() && !productionsById.Any()) continue;
                        var detailsById = details.Where(x => x.MaterialId == material.MaterialId).ToList();
                        if (detailsById.Any()) {
                            var entity = new ExpectedMaterialPlanModel {
                                MaterialTypeName = material.MaterialTypeName,
                                MaterialId = material.MaterialId,
                                MaterialCode = material.MaterialCode,
                                Details = detailsById,
                                TotalInv = 0,
                                TotalInvKg = 0,
                                MonthCount = monthCount,
                                HasProductDuplicate = false,
                            };
                            var po = pos.FirstOrDefault(x => x.MaterialId == material.MaterialId);
                            if (po != null) {
                                entity.OnPurchaseQuantity = po.Quantity;
                            }
                            var materialInv = materialInvs.FirstOrDefault(mi => mi.MaterialId == material.MaterialId);
                            if (materialInv != null) {
                                entity.TotalInvKg = materialInv.Quantity;
                            }
                            var duplicateProduct = duplicateProducts.FirstOrDefault(x => x.MaterialIds.Contains(entity.MaterialId));
                            if (duplicateProduct != null) {
                                entity.HasProductDuplicate = true;
                            }
                            model.Add(entity);
                        }
                        else if(isAll) {
                            var entity = new ExpectedMaterialPlanModel {
                                MaterialTypeName = material.MaterialTypeName,
                                MaterialId = material.MaterialId,
                                MaterialCode = material.MaterialCode,
                                TotalInv = 0,
                                TotalInvKg = 0,
                                MonthCount = monthCount,
                                HasProductDuplicate = false,
                            };
                            var po = pos.FirstOrDefault(x => x.MaterialId == material.MaterialId);
                            if (po != null) {
                                entity.OnPurchaseQuantity = po.Quantity;
                            }
                            var materialInv = materialInvs.FirstOrDefault(mi => mi.MaterialId == material.MaterialId);
                            if (materialInv != null) {
                                entity.TotalInvKg = materialInv.Quantity;
                            }
                            model.Add(entity);
                        }

                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectExpectedMaterialPlan", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<ExpectedProductionMaterialPlanModel> GetExpectedProductionMaterialPlanModel(
            List<int> materialIds, 
            int month, int year, int monthCount) {
            var model = new List<ExpectedProductionMaterialPlanModel>();

            var toDate = new DateTime(year, month, 1).AddMonths(monthCount).AddSeconds(-1);
            var fromDate = new DateTime(year, month, 1);
            var nextMonthDate = fromDate.AddMonths(1);
            var startYearDate = new DateTime(year, 1, 1);
            var startLastYearDate = startYearDate.AddYears(-1);

            using (var vfi = new tammaContext()) {

                var productions = (from x in vfi.ImportFormSX1Detail
                                   where x.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                         materialIds.Contains(x.MaterialInventory.MaterialId) &&
                                        x.ImportFormSX1.MaterialUseDate >= startYearDate &&
                                        x.ImportFormSX1.MaterialUseDate < toDate
                                   select new {
                                       x.ProductId,
                                       x.MaterialInventory.MaterialId,
                                       //MonthDate = x.ImportFormSX1.MaterialUseDate.ToString("MM-yyyy"),
                                       Month = x.ImportFormSX1.MaterialUseDate.Month,
                                       Year = x.ImportFormSX1.MaterialUseDate.Year,
                                       //MonthDate = new DateTime(x.ImportFormSX1.MaterialUseDate.Year, x.ImportFormSX1.MaterialUseDate.Month, 1),
                                       Quantity = (x.MaterialUse1 + x.MaterialUse2) * x.MaterialInventory.UnitWeight,
                                   })
                                   .GroupBy(x => new { x.MaterialId, x.ProductId, x.Month, x.Year })
                                   .Select(x => new {
                                       x.Key.MaterialId,
                                       x.Key.ProductId,
                                       x.Key.Month,
                                       x.Key.Year,
                                       //MonthDate = new DateTime(x.Key.Year, x.Key.Month, 1),
                                       Quantity = x.Sum(y => y.Quantity),
                                       MaxQuantity = x.Max(y => y.Quantity)
                                   })
                                   .ToList();
                //var productionMaterials = (from pm in vfi.ProductionMaterials
                //                           orderby pm.Priority
                //                           where pm.Active && pm.Product.Active &&
                //                                 materialIds.Contains(pm.MaterialId)
                //                           select new {
                //                               pm.ProductId,
                //                               pm.Product.ProductCode,
                //                               pm.MaterialId,
                //                               DesignMaterialId = pm.Product.MaterialId ?? 0,
                //                               pm.UnitWeightByMaterial
                //                           }).ToList();
                //var productIds = productions.Select(x => x.ProductId).Union(productionMaterials.Select(y => y.ProductId))
                //                          .Distinct().ToList();

                var productIds = vfi.Products
                                    .Where(x=> x.MaterialId !=null && materialIds.Contains(x.MaterialId.Value) && x.Active)
                                    .Select(x => x.ProductId)
                                    .Union(productions.Select(x => x.ProductId))
                                    .Distinct()
                                    .ToList();
                var forecasts = (from f in vfi.ForecastOrders
                                 where f.ForecastDate <= toDate &&
                                       f.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                       productIds.Contains(f.ProductId)
                                 select new {
                                     f.ProductId,
                                     Date = f.ForecastDate,
                                     f.Quantity
                                 }).ToList();
                var ordersByMonth = (from od in vfi.OrderDetails
                                     where (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                            od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                            productIds.Contains(od.ProductId) &&
                                           od.OrderQty > 0 &&
                                           od.Order.DueDate != null &&
                                           od.Order.DueDate.Value >= fromDate &&
                                           od.Order.DueDate.Value <= toDate
                                     select new {
                                         od.ProductId,
                                         od.Order.DueDate.Value.Month,
                                         od.Order.DueDate.Value.Year,
                                         od.OrderQty,
                                     })
                                     .GroupBy(x => new { x.ProductId, x.Month, x.Year })
                                     .Select(x => new {
                                         ProductId = x.Key.ProductId,
                                         Month = x.Key.Month,
                                         Year = x.Key.Year,
                                         Quantity = x.Sum(y => y.OrderQty ?? 0)
                                     })
                                     .ToList();

                var productionMaterials = (from pm in vfi.ProductionMaterials
                                           orderby pm.Priority
                                           where pm.Active && pm.Product.Active &&
                                                 //materialIds.Contains(pm.MaterialId) &&
                                                 productIds.Contains(pm.ProductId)
                                           select new {
                                               pm.ProductId,
                                               pm.Product.ProductCode,
                                               pm.MaterialId,
                                               DesignMaterialId = pm.Product.MaterialId ?? 0,
                                               pm.UnitWeightByMaterial
                                           }).ToList();

                //var productIds = forecasts.Where(x => x.Date >= fromDate).Select(x => x.ProductId).Union(productions.Select(x => x.ProductId)).ToList();
                var orders = (from od in vfi.OrderDetails
                              where (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                     od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                     productIds.Contains(od.ProductId) &&
                                    od.RequiedNumber > 0 &&
                                    od.Order.DueDate != null &&
                                    od.Order.DueDate.Value < fromDate
                              select new {
                                  od.ProductId,
                                  od.RequiedNumber,
                              })
                            .GroupBy(x => x.ProductId)
                            .Select(x => new {
                                ProductId = x.Key,
                                Quantity = x.Sum(y => y.RequiedNumber)
                            })
                            .ToList();

                var orderLastYears = (from od in vfi.OrderDetails
                                      where od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                                            productIds.Contains(od.ProductId) &&
                                            od.OrderQty > 0 &&
                                            od.Order.DueDate != null &&
                                            od.Order.DueDate.Value < startYearDate &&
                                            od.Order.DueDate.Value >= startLastYearDate
                                      select new {
                                          od.ProductId,
                                          od.OrderQty,
                                      })
                                    .GroupBy(x => x.ProductId)
                                    .Select(x => new {
                                        ProductId = x.Key,
                                        Quantity = x.Sum(y => y.OrderQty ?? 0)
                                    })
                                    .ToList();
                //var products = vfi.Products.Where(x => productIds.Contains(x.ProductId))
                //            .Select(x => new {
                //                x.ProductId,
                //                x.ProductCode,
                //            }).ToList();
                var productInvs = vfi.ProductInventories
                                    .Where(x => productIds.Contains(x.ProductId)
                                            && x.TotalQty > 0
                                            && x.Warehouse.CanStock
                                            && !x.Warehouse.IsReprocessing)
                                     .GroupBy(x => x.ProductId)
                                     .Select(x => new {
                                         ProductId = x.Key,
                                         TotalQuantity = x.Sum(y => y.TotalQty)
                                     })
                                    .ToList();
                var groups = productions.Select(x => new { x.ProductId, x.MaterialId })
                    .Union(productionMaterials.Select(x => new { x.ProductId, x.MaterialId }))
                    .Distinct().ToList();
                var products = vfi.Products.Where(x => productIds.Contains(x.ProductId))
                    .Select(x => new {
                        x.ProductId,
                        x.ProductCode,
                        MaterialId = x.MaterialId ?? 0,
                        //TotalQuantity = x.ProductInventories.Where(y => y.TotalQty > 0 && y.Warehouse.CanStock).Sum(y => y.TotalQty)
                    }).ToList();
                foreach (var group in groups) {
                    var product = products.FirstOrDefault(x => x.ProductId == group.ProductId);
                    var detail = new ExpectedProductionMaterialPlanModel {
                        ProductId = group.ProductId,
                        ProductCode = product.ProductCode,
                        MaterialId = group.MaterialId,
                        //ForecastInYear = product.ForecastsQuality,
                        //ForecastByMonth = product.ForecastsQuality * monthCount / 12,
                        //UnitWeightByMaterial = product.UnitWeightByMaterial,
                        //TotalInv = product.TotalQuantity
                    };
                    //var productionMaterialsById = productionMaterials.Where(p => p.ProductId == detail.ProductId).ToList();
                    if (product.MaterialId == group.MaterialId) {
                        var productionMaterialsById = productionMaterials.FirstOrDefault(p => p.MaterialId == detail.MaterialId
                                                                                            && p.ProductId == detail.ProductId);
                        if (productionMaterialsById != null) {
                            detail.UnitWeightByMaterial = productionMaterialsById.UnitWeightByMaterial;
                            var forecastsById = forecasts.Where(f => f.ProductId == detail.ProductId).ToList();
                            detail.ForecastByMonth = forecastsById.Where(x => x.Date >= fromDate)
                                                                  .ToList().Sum(x => x.Quantity);
                            detail.ForecastInYear = forecastsById.Where(x => x.Date >= startYearDate)
                                                                 .ToList().Sum(x => x.Quantity);
                            detail.ForecastInMonth = forecastsById.Where(x => x.Date.Month == month && x.Date.Year == year)
                                                                  .ToList().Sum(x => x.Quantity);
                            detail.ForecastNextMonth = forecastsById.Where(x => x.Date.Month == nextMonthDate.Month
                                                                             && x.Date.Year == nextMonthDate.Year)
                                                                  .ToList().Sum(x => x.Quantity);
                            detail.OrderLastYear = orderLastYears.Where(x => x.ProductId == detail.ProductId)
                                                                 .ToList().Sum(x => x.Quantity);
                            detail.OrderRemaining = orders.Where(x => x.ProductId == detail.ProductId)
                                                          .ToList().Sum(y => y.Quantity);
                            var ordersByMonthById = ordersByMonth.Where(x => x.ProductId == detail.ProductId).ToList();
                            if (ordersByMonthById.Any()) {
                                detail.ForecastByMonth = Math.Max(detail.ForecastByMonth, ordersByMonthById.Sum(x => x.Quantity));
                                var ordersNextMonthById = ordersByMonthById.FirstOrDefault(x => x.Month == nextMonthDate.Month
                                                                                             && x.Year == nextMonthDate.Year);;
                                if (ordersNextMonthById != null) {
                                    detail.ForecastNextMonth = Math.Max(detail.ForecastNextMonth, ordersNextMonthById.Quantity);
                                }
                            }
                        }
                    }

                    var productionsById = productions.Where(p => p.MaterialId == detail.MaterialId && p.ProductId == detail.ProductId);
                    var productionInMonth = productionsById.FirstOrDefault(x => x.Month == month && x.Year == year);
                    if (productionInMonth != null) {
                        detail.UseInMonthKg = productionInMonth.Quantity;
                        detail.MaxUseInMonthKg = productionInMonth.MaxQuantity;
                    }

                    var productionsByIdById = productionsById.Where(x => x.Year == year && x.Month < month)
                                                             .ToList();
                    if (productionsByIdById.Any()) {
                        detail.UseAvgInYearKg = productionsByIdById.Sum(x => x.Quantity) / productionsByIdById.Count;
                    }
                    var productInvsById = productInvs.FirstOrDefault(x => x.ProductId == detail.ProductId);
                    if (productInvsById != null) {
                        detail.TotalInv = productInvsById.TotalQuantity;
                    }
                    detail.RequireByMonth = detail.OrderRemaining + detail.ForecastByMonth - detail.TotalInv;
                    if (detail.RequireByMonth < 0) {
                        detail.RequireByMonth = 0;
                    }
                    if (detail.Show) {
                        model.Add(detail);
                    }
                }
            }

            return model;
        }

        [GridAction]
        public ActionResult SelectExpectedProductionMaterialPlan(int materialId, int month, int year, int monthCount) {
            var model = new List<ExpectedProductionMaterialPlanModel>();
            try {
                model = GetExpectedProductionMaterialPlanModel(new List<int> { materialId }, month, year, monthCount);
                model = model.Where(x => x.MaterialId == materialId).ToList();
            }
