        [GridAction]
        public ActionResult SelectOrderTrackingManagement(int customerId, string productCode,
            int poStatus, int productInvStatus, int deliveryStatus,
            string fromDate, string toDate) {
            var model = new List<OrderTrackingModel>();
            if (customerId == 0)
                return View(new GridModel(model));
            try {
                model = GetOrderTrackingManagement(customerId, productCode,
                    poStatus, productInvStatus, deliveryStatus,
                    fromDate, toDate);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectOrderTrackingManagement", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<OrderTrackingModel> GetOrderTrackingManagement(int customerId, string productCode,
            int poStatus, int productInvStatus, int deliveryStatus,
            string fromDate, string toDate) {
            var model = new List<OrderTrackingModel>();
            var ci = new CultureInfo("vi-VN");
            var tDate = Convert.ToDateTime(toDate, ci);
            var fDate = Convert.ToDateTime(fromDate, ci);
            using (var vfi = new tammaContext()) {

                var salesManager = MyUtilities.UserRole.CheckRole(HttpContext.User.Identity.Name,
                    MyUtilities.UserRole.SaleManagement);
                var customerIds = MyUtilities.Sales.GetCustomerAccessList(HttpContext.User.Identity.Name);

                var orderDetails = (from od in vfi.OrderDetails
                                    where od.Order.CustomerId == customerId &&
                                          (salesManager || customerIds.Contains(od.Order.CustomerId)) &&
                                          od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                                          od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                          od.Order.DueDate != null &&
                                          od.Order.DueDate <= tDate
                                    orderby od.Product.ProductCode, od.Order.DueDate, od.CustomerDueDate
                                    select new {
                                        od.OrderDetailId,
                                        od.Order.OrderId,
                                        od.Order.OrderNumber,
                                        od.Order.CurrencyCode,
                                        od.Order.CustomerId,
                                        od.Order.Customer.CustomerCode,
                                        DueDate = od.Order.DueDate.Value,

                                        CustomerDueDate = od.CustomerDueDate != null ? od.CustomerDueDate.Value : od.Order.DueDate.Value,
                                        od.VFIDueDate,
                                        OrderQty = od.OrderQty.Value,
                                        od.RequiedNumber,
                                        od.UnitPrice,
                                        od.PONumber,
                                        od.Note,

                                        od.ProductId,
                                        od.Product.ProductCode,
                                        //od.Product.DesignNo,
                                    }).ToList();

                if (!string.IsNullOrWhiteSpace(productCode)) {
                    orderDetails = orderDetails.Where(od => od.ProductCode.Equals(productCode)).ToList();
                }
                if (poStatus == 1) {
                    orderDetails = orderDetails.Where(od => od.RequiedNumber > 0).ToList();
                }
                else {
                    orderDetails = orderDetails.Where(od => od.DueDate >= fDate || od.RequiedNumber > 0).ToList();
                    if (poStatus == 2) {
                        orderDetails = orderDetails.Where(od => od.RequiedNumber == 0).ToList();
                    }
                }

                var orderDetailIds = orderDetails.Select(od => od.OrderDetailId).ToList();
                var exportDetails = from ed in vfi.InvoiceDetails
                                    where orderDetailIds.Contains(ed.OrderDetailId.Value) &&
                                          ed.Piece > 0
                                    select new {
                                        ed.OrderDetailId,
                                        Date = ed.Invoice.ShipmentDate.Value,
                                        ed.Piece
                                    };
                var productIds = orderDetails.Select(od => od.ProductId).Distinct().ToList();
                var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                var productInvs = from pi in vfi.ProductInventories
                                  where warehouses.Contains(pi.WarehouseId) &&
                                        productIds.Contains(pi.ProductId) &&
                                        pi.TotalQty > 0
                                  select pi;
                var products = (from p in vfi.Products
                                where productIds.Contains(p.ProductId) &&
                                      p.Active
                                select new {
                                    p.ProductId,
                                    p.ProductCode,
                                    p.DesignNo,
                                }).ToList();
                foreach (var product in products) {
                    var orderDetailsById = orderDetails.Where(od => od.ProductId == product.ProductId);

                    var productInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId).ToList();
                    var totalInvQuantity = productInvsById.Sum(pi => pi.TotalQty);
                    productInvsById =
                        productInvsById.Where(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish).ToList();
                    var finishInvQuantity = productInvsById.Sum(pi => pi.TotalQty);
                    var totalRequire = 0.0;
                    var finishRequire = 0.0;
                    foreach (var orderDetail in orderDetailsById) {
                        var entity = new OrderTrackingModel {
                            OrderId = orderDetail.OrderId,
                            OrderNumber = orderDetail.OrderNumber,
                            Currency = orderDetail.CurrencyCode,
                            CustomerId = orderDetail.CustomerId,
                            CustomerCode = orderDetail.CustomerCode,

                            ProductId = orderDetail.ProductId,
                            ProductVfCode = product.ProductCode,
                            ProductCustomerCode = product.DesignNo,

                            VfDeliveryDate = orderDetail.DueDate,
                            CustomerDeliveryDate = orderDetail.CustomerDueDate,
                            OrderQuantity = orderDetail.OrderQty,
                            RequireQuantity = orderDetail.RequiedNumber,
                            UnitPrice = orderDetail.UnitPrice,
                            ProductPoNo = orderDetail.PONumber,
                            Note = orderDetail.Note,
                            DeliveryStatus = 0,
                            AvailableStatus = 0,
                            //DeliveryStatusName = "",
                            AvailableStatusName = "",
                            OrderDetailId = orderDetail.OrderDetailId,
                            SalesManager = salesManager,
                            ExpectDate = orderDetail.VFIDueDate
                        };
                        var exportDetailsById = exportDetails.Where(ed => ed.OrderDetailId == orderDetail.OrderDetailId).ToList();
                        foreach (var exportDetail in exportDetailsById) {
                            entity.Note += " Delivered: " + exportDetail.Piece + " - " +
                                           exportDetail.Date.ToString("dd/MM/yy");
                        }
                        entity.ExportQuantity = exportDetailsById.Sum(ed => ed.Piece);
                        if (entity.VfDeliveryDate < DateTime.Now) {
                            entity.DeliveryStatus = (byte)MyUtilities.Sales.DeliveryStatus.Late;
                        }
                        if (entity.RequireQuantity > 0) {
                            entity.StatusName = "On Process";
                            entity.AvailableStatus = (byte)MyUtilities.Sales.ProductInvStatus.Enough;

                            entity.AvailableTotalInv = totalInvQuantity;
                            totalInvQuantity -= entity.RequireQuantity;
                            if (totalInvQuantity < 0) {
                                totalRequire += (totalInvQuantity * -1);
                                totalInvQuantity = 0;
                                entity.AvailableStatus = (byte)MyUtilities.Sales.ProductInvStatus.NotProduction;
                                entity.PlanDay = MyUtilities.Product.GetProductionDay(entity.ProductId, totalRequire);
                                if (entity.DeliveryStatus == (byte)MyUtilities.Sales.DeliveryStatus.Late) {
                                    entity.PlanDeliveryDate = MyUtilities.Function.ToDate(DateTime.Now, entity.PlanDay);
                                    entity.PlanDeliveryDateStr = entity.PlanDeliveryDate.ToString("dd/MM/yyyy");
                                }
                                else {
                                    entity.PlanDeliveryDate = MyUtilities.Function.FromDate(entity.VfDeliveryDate, entity.PlanDay);
                                    if (entity.PlanDeliveryDate <= DateTime.Now) {
                                        entity.PlanDeliveryDate = MyUtilities.Function.ToDate(DateTime.Now, entity.PlanDay);
                                        entity.DeliveryStatus = (byte)MyUtilities.Sales.DeliveryStatus.WillLate;
                                    }
                                    else {
                                        entity.PlanDeliveryDate = MyUtilities.Function.ToDate(DateTime.Now, 3);
                                    }
                                    entity.PlanDeliveryDateStr = entity.PlanDeliveryDate.ToString("dd/MM/yyyy");
                                }
                            }
                            entity.AvailableFinishInv = finishInvQuantity;
                            finishInvQuantity -= entity.RequireQuantity;
                            if (finishInvQuantity < 0) {
                                finishRequire += (finishInvQuantity * -1);
                                finishInvQuantity = 0;
                                if (entity.AvailableStatus != (byte)MyUtilities.Sales.ProductInvStatus.NotProduction) {
                                    entity.AvailableStatus = (byte)MyUtilities.Sales.ProductInvStatus.NotFinish;
                                    //entity.PlanDay = 3;
                                    entity.PlanDay = MyUtilities.Product.GetPlanDay(entity.ProductId, finishRequire, 0);
                                    if (entity.DeliveryStatus == (byte)MyUtilities.Sales.DeliveryStatus.Late) {
                                        entity.PlanDeliveryDate = MyUtilities.Function.ToDate(DateTime.Now, entity.PlanDay);
                                        entity.PlanDeliveryDateStr = entity.PlanDeliveryDate.ToString("dd/MM/yyyy");
                                    }
                                    else {
                                        entity.PlanDeliveryDate = MyUtilities.Function.FromDate(entity.VfDeliveryDate, entity.PlanDay);
                                        if (entity.PlanDeliveryDate <= DateTime.Now) {
                                            entity.PlanDeliveryDate = MyUtilities.Function.ToDate(DateTime.Now, entity.PlanDay);
                                            entity.DeliveryStatus = (byte)MyUtilities.Sales.DeliveryStatus.WillLate;
                                        }
                                        else {
                                            entity.PlanDeliveryDate = MyUtilities.Function.ToDate(DateTime.Now, 3);
                                        }
                                        entity.PlanDeliveryDateStr = entity.PlanDeliveryDate.ToString("dd/MM/yyyy");
                                    }
                                }
                            }
                        }
                        else
                            entity.StatusName = "Finish";
                        if (string.IsNullOrWhiteSpace(entity.PlanDeliveryDateStr))
                            entity.ExpectDate = null;
                        else if (entity.ExpectDate == null)
                            entity.ExpectDate = entity.PlanDeliveryDate;
                        model.Add(entity);
                    }

                }
            }
            if (productInvStatus != 0)
                model = model.Where(m => m.AvailableStatus == productInvStatus).ToList();
            if (deliveryStatus != 0)
                model = model.Where(m => m.DeliveryStatus == deliveryStatus).ToList();

            return model;
        }

        public ActionResult PrintForecastOrder(string monthly) {
            var model = new List<ForecastOrderModel>();
            try {
                var listDetail = (List<ForecastOrderDetailModel>)Session["SessionForecastOrder"];
                if (listDetail == null || !listDetail.Any()) {
                    throw new AggregateException("");
                }
                var customerIds = listDetail.Select(m => m.CustomerId).Distinct().ToList();
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var ci = new CultureInfo("vi-VN");
                    var reportDate = string.IsNullOrWhiteSpace(monthly)
                                      ? DateTime.Today
                                      : Convert.ToDateTime(monthly, ci);
                    foreach (var customerId in customerIds) {
                        var customer = vfi.Customers.FirstOrDefault(c => c.CustomerId == customerId);
                        var entity = new ForecastOrderModel {
                            CustomerCode = customer.CustomerCode,
                            CustomerName = customer.CompanyName,
                            Details = new List<ForecastOrderDetailModel>(),
                            ReportDate = reportDate,
                        };
                        var productById =
                            listDetail.Where(m => m.CustomerId == customerId && m.PlanQuantity != 0).ToList();
                        if (productById.Any()) {
                            entity.Details.AddRange(productById);
                            entity.TotalPlanQuantity = productById.Sum(p => p.PlanQuantity);
                            entity.TotalFinishInventory = productById.Sum(p => p.FinishInventory);
                            entity.TotalTotalInventory = productById.Sum(p => p.TotalInventory);
                            model.Add(entity);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintForecastOrder", ex.Message);
            }
            return PartialView("PageForecastOrderReport", model);
        }

        [HttpPost]
        public ActionResult Save(IEnumerable<HttpPostedFileBase> attachments) {
            // The Name of the Upload component is "attachments"       
            try {
                if (attachments.Any()) {
                    foreach (var file in attachments) {
                        // Some browsers send file names with full path. We only care about the file name.
                        var fileName = Path.GetFileName(file.FileName);
                        if (fileName == null) continue;
                        var destinationPath = Path.Combine(Server.MapPath("~/Content/FileUpload"), fileName);

                        byte[] fileBytes = new byte[file.ContentLength];
                        file.InputStream.Read(fileBytes, 0, Convert.ToInt32(file.ContentLength));
                        System.IO.File.WriteAllBytes(destinationPath, fileBytes);
                    }
                    return Json("Oke");
                }
                else {
                    throw new AggregateException("attachments null");
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("UploadSave", ex.Message);
                return Json(ex.Message);
            }
            // Redirect to a view showing the result of the form submission.    
            //return Json("False");

        }

        private static int oke;
        private static int error;
        private static int duplicate;
        private static string errorIndex;
        [GridAction]
        public ActionResult SelectForecastOrder(string fileName, int productIndex, int columnIndex, string sheetName) {

            var model = new List<ForecastOrderDetailModel>();
            if (string.IsNullOrWhiteSpace(fileName))
                return View(new GridModel(model));
            var dt = new DataTable();
            try {
                using (var conn = new OleDbConnection()) {
                    var destinationPath = Path.Combine(Server.MapPath("~/Content/FileUpload"), fileName);
                    string fileExtension = Path.GetExtension(destinationPath);
                    if (fileExtension == ".xls")
                        conn.ConnectionString = "Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + destinationPath + ";" +
                                                "Extended Properties='Excel 8.0;HDR=YES;'";
                    if (fileExtension == ".xlsx")
                        conn.ConnectionString = "Provider=Microsoft.ACE.OLEDB.12.0;Data Source=" + destinationPath + ";" +
                                                "Extended Properties='Excel 12.0 Xml;HDR=YES;'";
                    using (var comm = new OleDbCommand()) {
                        //var sheetName = "Sheet1";
                        comm.CommandText = "Select * from [" + sheetName + "$]";
                        comm.Connection = conn;
                        using (var da = new OleDbDataAdapter()) {
                            da.SelectCommand = comm;
                            da.Fill(dt);
                        }
                    }
                }
                using (var vfi = new tammaContext()) {
                    errorIndex = "";
                    oke = error = duplicate = 0;
                    dt.Rows.RemoveAt(0);
                    dt.Rows.RemoveAt(1);

                    Session["SessionForecastOrder"] = new List<ForecastOrderDetailModel>();
                    foreach (DataRow row in dt.Rows) {
                        var productCode = "";
                        if (productIndex == 0)
                            productCode = row[5].ToString().Trim();
                        else
                            productCode = row[productIndex - 1].ToString().Trim();
                        if (string.IsNullOrWhiteSpace(productCode)) continue;
                        var product = vfi.Products.FirstOrDefault(p => p.ProductCode.Equals(productCode));
                        if (product == null) {
                            error++;
                            errorIndex += "Error: Không tìm thấy: " + productCode + "\n";
                            continue;
                        }
                        var entity = model.FirstOrDefault(m => m.ProductId == product.ProductId);
                        if (entity != null) {
                            duplicate++;
                            errorIndex += "Error: Bị trùng mã: " + product.ProductCode + "\n";
                            continue;
                        }
                        var productInventorys =
                          vfi.ProductInventories.Where(
                              pi =>
                              pi.WarehouseId != 1 &&
                              pi.WarehouseId != 9 &&
                              pi.WarehouseId != 11 &&
                              pi.WarehouseId != 15 &&
                              pi.ProductId == product.ProductId);
                        entity = new ForecastOrderDetailModel {
                            CustomerId = product.CustomerId,
                            Index = oke + error + 1,
                            ProductCode = product.ProductCode,
                            ProductName = product.ProductName,
                            ProductId = product.ProductId,
                            CustomerCode = product.Customer.CustomerCode,
                            CustomerProductCode = product.DesignNo,
                            UploadDate = DateTime.Now,
                            PlanQuantity = 0,
                            RealQuantity = 0,
                            TotalInventory = 0,
                        };
                        if (productInventorys.Any())
                            entity.TotalInventory = productInventorys.Sum(pi => pi.TotalQty);
                        var finishInventory = productInventorys.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInventory != null)
                            entity.FinishInventory = finishInventory.TotalQty;
                        if (columnIndex == 0) {
                            if (!string.IsNullOrWhiteSpace(row[9].ToString()))
                                try {
                                    entity.PlanQuantity = Convert.ToDouble(row[9]);
                                }
                                catch (FormatException) {
                                }
                            if (!string.IsNullOrWhiteSpace(row[10].ToString()))
                                try {
                                    entity.RealQuantity = Convert.ToDouble(row[10]);
                                }
                                catch (FormatException) {
                                }
                        }
                        else {
                            if (!string.IsNullOrWhiteSpace(row[columnIndex - 1].ToString()))
                                try {
                                    entity.PlanQuantity = Convert.ToDouble(row[columnIndex - 1]);
                                }
                                catch (FormatException) {
                                }
                            if (!string.IsNullOrWhiteSpace(row[columnIndex].ToString()))
                                try {
                                    entity.RealQuantity = Convert.ToDouble(row[columnIndex]);
                                }
                                catch (FormatException) {
                                }

                        }
                        oke++;
                        model.Add(entity);
                    }
                }
            }
            catch (OleDbException oledbEx) {
                ModelState.AddModelError("OleDbException", oledbEx.Message);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectForecastOrder", ex.Message);
            }
            Session["SessionForecastOrder"] = model;
            return View(new GridModel(model));
        }
