        [HttpPost]
        public ActionResult SelectProductMasterPlanReport(
            int month, int year,
            int customerId, string productCode) {
            var model = new ProductMasterPlanReportModel();
            try {
                using (var vfi = new tammaContext()) {
                    model = GetProductMasterPlanReportModel(month, year, customerId, productCode);
                }
            }
            catch (FormatException ex) {
                return Json(ex.Message);
            }
            Session["SessionProductMasterPlanReport"] = model;
            return Json("OKIE");
        }

        ProductMasterPlanReportModel GetProductMasterPlanReportModel(
            int month, int year,
            int customerId, string productCode) {
            var model = new ProductMasterPlanReportModel();
            try {
                var reportDate = new DateTime(year, month, 1);
                model.ReportDate = reportDate;
                model.Section = DateTime.Now.ToFileTime();
                using (var vfi = new tammaContext()) {
                    var products = (from p in vfi.Products
                                    where p.Active &&
                                    (customerId == 0 || p.CustomerId == customerId)
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        p.ProductId,
                                        p.ProductCode,
                                        p.Productivity,
                                        p.MillProductivity,
                                        p.ProcessingType.TypeName
                                    }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode))
                        products = products.Where(p => p.ProductCode.Contains(productCode)).ToList();
                    var productIds = products.Select(p => p.ProductId).ToList();

                    var orderDetails = (from od in vfi.OrderDetails
                                        where (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                               od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess ||
                                               od.Order.Status == (byte)MyUtilities.Sales.Status.Completed) &&
                                              od.Order.DueDate > MyUtilities.Sales.StartOrderReportDate &&
                                              od.Order.DueDate != null &&
                                             productIds.Contains(od.ProductId)
                                        select new {
                                            od.ProductId,
                                            od.Order.DueDate,
                                            OrderQty = od.OrderQty ?? 0,
                                            od.RequiedNumber,
                                            od.IsAlert
                                        }).ToList();
                    var orderDetailsInMonth = (from od in orderDetails
                                               where od.DueDate.Value.Month == reportDate.Month &&
                                                     od.DueDate.Value.Year == reportDate.Year
                                               select od).ToList();
                    var orderDetailsLate = (from od in orderDetails
                                            where od.DueDate < DateTime.Now &&
                                            od.RequiedNumber > 0
                                            select od).ToList();
                    var nextMonth = reportDate.AddMonths(1);
                    var orderDetailsNextMonth = (from od in orderDetails
                                                 where
                                                     od.DueDate.Value.Month == nextMonth.Month &&
                                                     od.DueDate.Value.Year == nextMonth.Year
                                                 select od).ToList();
                    var orderDetailsRemaining = (from od in orderDetails
                                                 where od.DueDate < reportDate
                                                 select od).ToList();
                    var exportsInMonth = (from pip in vfi.ProductInventoryPeriods
                                          where
                                              pip.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                              pip.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Business &&
                                              pip.WarehouseId == MyUtilities.Warehouse.Business &&
                                             pip.PeriodDate.Month == reportDate.Month &&
                                             pip.PeriodDate.Year == reportDate.Year &&
                                                 productIds.Contains(pip.ProductId)
                                          select new {
                                              pip.ProductId,
                                              pip.Quantity
                                          }).ToList();
                    var exportsLastMonth = (from pip in vfi.ProductInventoryPeriods
                                            where pip.PeriodDate > MyUtilities.Sales.StartOrderReportDate &&
                                            pip.PeriodDate < reportDate &&
                                            pip.WarehouseId == MyUtilities.Warehouse.Finish &&
                                            ((pip.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                            pip.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Business) ||
                                            (pip.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Business &&
                                            pip.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Finish)) &&
                                              productIds.Contains(pip.ProductId)
                                            select new {
                                                pip.ProductId,
                                                Quantity = pip.EarlyPeriodQuantity - pip.LastPeriodQuantity
                                            }).ToList();
                    var forecastOrdersNextMonth = (from fo in vfi.ForecastOrders
                                                   where fo.ForecastDate.Month == nextMonth.Month &&
                                                         fo.ForecastDate.Year == nextMonth.Year &&
                                                         fo.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                        productIds.Contains(fo.ProductId)
                                                   select new {
                                                       fo.ProductId,
                                                       fo.Quantity
                                                   }).ToList();
                    var forecastOrdersInMonth = (from fo in vfi.ForecastOrders
                                                 where fo.ForecastDate.Month == reportDate.Month &&
                                                       fo.ForecastDate.Year == reportDate.Year &&
                                                        fo.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                        productIds.Contains(fo.ProductId)
                                                 select new {
                                                     fo.ProductId,
                                                     fo.Quantity
                                                 }).ToList();
                    var productionProcesses = (from pp in vfi.ProductionProcesses
                                               where productIds.Contains(pp.ProductId) &&
                                                    pp.IsNecessary
                                               orderby pp.ProcessIndex descending
                                               select pp).ToList();
                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity2();
                    var production2Warehouses = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    var qcWarehouses = MyUtilities.Warehouse.GetWarehouseIdQc();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where productIds.Contains(pi.ProductId)
                                             && pi.TotalQty > 0
                                             && warehouses.Contains(pi.WarehouseId)
                                       select pi).ToList();
                    var smartProductions = vfi.SmartProductions.Where(sm => sm.ProductId != null
                                                                        && sm.MachineId != null
                                                                        && productIds.Contains(sm.ProductId.Value));
                    foreach (var product in products) {
                        var baseInfo = new BaseInfoPlanReportModel() {
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            CustomerId = product.CustomerId,
                            CustomerCode = product.CustomerCode
                        };
                        var isProduction = smartProductions.Any(sp => sp.ProductId == product.ProductId
                                                                    && sp.Machine.MachineName.Contains("C"));
                        var totalInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId);
                        var totalInvQuantity = totalInvsById.Sum(pi => pi.TotalQty);
                        var qcForecastState = "";
                        var qcOrderState = "";
                        var latedState = "";
                        // order
                        var orderPlan = new OrderPlanReportModel() {
                            Info = baseInfo,
                            InMonth = orderDetailsInMonth.Where(od => od.ProductId == baseInfo.ProductId).Sum(od => od.OrderQty),
                            NextMonth = orderDetailsNextMonth.Where(od => od.ProductId == baseInfo.ProductId).Sum(od => od.OrderQty),
                            LastMonth = orderDetailsRemaining.Where(od => od.ProductId == product.ProductId).Sum(od => od.OrderQty)
                                        - exportsLastMonth.Where(ep => ep.ProductId == product.ProductId).Sum(ep => ep.Quantity),
                            AccumulatedExport = exportsInMonth.Where(ep => ep.ProductId == product.ProductId).Sum(ep => ep.Quantity)
                        };
                        if (orderPlan.LastMonth < 0) {
                            orderPlan.InMonth += orderPlan.LastMonth;
                            orderPlan.LastMonth = 0;
                            if (orderPlan.InMonth < 0) {
                                orderPlan.LastMonth = orderPlan.InMonth;
                                orderPlan.InMonth = 0;
                            }
                        }
                        model.OrderPlans.Add(orderPlan);
                        if (orderPlan.PlanRequired > totalInvQuantity) {
                            var productionPlan = new ProductionOrderPlanReportModel {
                                Info = baseInfo,
                                TotalOrder = orderPlan.Total,
                                AccumulatedExport = orderPlan.AccumulatedExport,
                                AfterInvQuantity = totalInvQuantity,
                                IsProduction = isProduction,
                                Productivity = product.Productivity ?? 0,
                                MachineType = product.TypeName
                            };
                            model.ProductionOrderPlans.Add(productionPlan);
                            latedState += "SX1; ";
                            qcOrderState += "SX1; ";
                        }
                        // forecast
                        var forecastPlan = new ForecastPlanReportModel() {
                            Info = baseInfo,
                            InMonth = forecastOrdersInMonth.Where(od => od.ProductId == baseInfo.ProductId).Sum(od => od.Quantity),
                            NextMonth = forecastOrdersNextMonth.Where(od => od.ProductId == baseInfo.ProductId).Sum(od => od.Quantity),
                            AccumulatedExport = orderPlan.AccumulatedExport
                        };
                        model.ForecastPlans.Add(forecastPlan);
                        if (forecastPlan.PlanRequired > totalInvQuantity) {
                            var productionPlan = new ProductionForecastPlanReportModel {
                                Info = baseInfo,
                                TotalOrder = forecastPlan.Total,
                                AccumulatedExport = forecastPlan.AccumulatedExport,
                                AfterInvQuantity = totalInvQuantity,
                                IsProduction = isProduction,
                                Productivity = product.Productivity ?? 0,
                                MachineType = product.TypeName
                            };
                            model.ProductionForecastPlans.Add(productionPlan);
                            qcForecastState += "SX1; ";
                        }
                        var productionProcessesById = productionProcesses.Where(pp => pp.ProductId == product.ProductId).ToList();
                        var cncProcess = productionProcessesById.FirstOrDefault(pp => pp.WarehouseId == MyUtilities.Warehouse.Cnc);
                        if (cncProcess != null) {
                            var cncInv = totalInvsById.Where(pi => pi.WarehouseId == MyUtilities.Warehouse.Cnc).ToList().Sum(pi => pi.TotalQty);
                            var afterProcess = productionProcessesById.Where(pp => pp.ProcessIndex > cncProcess.ProcessIndex);
                            var afterWarehouses = afterProcess.Select(pp => pp.WarehouseId).ToList();
                            if (afterWarehouses.Contains(MyUtilities.Warehouse.Production2))
                                afterWarehouses.AddRange(production2Warehouses);
                            if (afterWarehouses.Contains(MyUtilities.Warehouse.QcA)
                                || afterWarehouses.Contains(MyUtilities.Warehouse.QcB))
                                afterWarehouses.AddRange(qcWarehouses);
                            afterWarehouses = afterWarehouses.Distinct().ToList();
                            var afterInv = totalInvsById.Where(pi => afterWarehouses.Contains(pi.WarehouseId)).ToList().Sum(pi => pi.TotalQty);
                            var isCNC = smartProductions.Any(sp => sp.ProductId == product.ProductId
                                                                        && sp.Machine.MachineName.Contains("P"));
                            if (orderPlan.PlanRequired > afterInv) {
                                var productionPlan = new CncOrderPlanReportModel {
                                    Info = baseInfo,
                                    TotalOrder = orderPlan.Total,
                                    AccumulatedExport = orderPlan.AccumulatedExport,
                                    InvQuantity = cncInv,
                                    IsProduction = isCNC,
                                    Productivity = product.MillProductivity ?? 0,
                                    AfterInvQuantity = afterInv,
                                };
                                model.CncOrderPlans.Add(productionPlan);
                                latedState += "CNC; ";
                                qcOrderState += "CNC; ";
                            }
                            if (forecastPlan.PlanRequired > afterInv) {
                                var productionPlan = new CncForecastPlanReportModel {
                                    Info = baseInfo,
                                    TotalOrder = forecastPlan.Total,
                                    AccumulatedExport = forecastPlan.AccumulatedExport,
                                    InvQuantity = cncInv,
                                    IsProduction = isCNC,
                                    Productivity = product.MillProductivity ?? 0,
                                    AfterInvQuantity = afterInv,
                                };
                                model.CncForecastPlans.Add(productionPlan);
                                qcForecastState += "CNC; ";
                            }
                        }
                        var production2Process = productionProcessesById
                            .FirstOrDefault(pp => pp.WarehouseId == MyUtilities.Warehouse.Production2);
                        if (production2Process != null) {
                            var production2Inv = totalInvsById.Where(pi => production2Warehouses.Contains(pi.WarehouseId)).ToList().Sum(pi => pi.TotalQty);
                            var afterProcess = productionProcessesById.Where(pp => pp.ProcessIndex > production2Process.ProcessIndex);
                            var afterWarehouses = afterProcess.Select(pp => pp.WarehouseId).ToList();
                            if (afterWarehouses.Contains(MyUtilities.Warehouse.QcA)
                                || afterWarehouses.Contains(MyUtilities.Warehouse.QcB))
                                afterWarehouses.AddRange(qcWarehouses);
                            afterWarehouses = afterWarehouses.Distinct().ToList();
                            var afterInv = totalInvsById.Where(pi => afterWarehouses.Contains(pi.WarehouseId)).ToList().Sum(pi => pi.TotalQty);
                            if (orderPlan.PlanRequired > afterInv) {
                                var productionPlan = new Production2OrderPlanReportModel {
                                    Info = baseInfo,
                                    TotalOrder = orderPlan.Total,
                                    AccumulatedExport = orderPlan.AccumulatedExport,
                                    InvQuantity = production2Inv,
                                    AfterInvQuantity = afterInv,
                                };
                                model.Production2OrderPlans.Add(productionPlan);
                                latedState += "SX2; ";
                                qcOrderState += "SX2; ";
                            }
                            if (forecastPlan.PlanRequired > afterInv) {
                                var productionPlan = new Production2ForecastPlanReportModel {
                                    Info = baseInfo,
                                    TotalOrder = forecastPlan.Total,
                                    AccumulatedExport = forecastPlan.AccumulatedExport,
                                    InvQuantity = production2Inv,
                                    AfterInvQuantity = afterInv,
                                };
                                model.Production2ForecastPlans.Add(productionPlan);
                                qcForecastState += "SX2; ";
                            }
                        }


                        var elseProcess = productionProcessesById
                            .Where(pp => pp.WarehouseId != MyUtilities.Warehouse.Production1
                                && pp.WarehouseId == MyUtilities.Warehouse.Cnc
                                && pp.WarehouseId == MyUtilities.Warehouse.Production2);
                        foreach (var process in elseProcess) {
                            var afterWarehouses = new List<int> { process.WarehouseId };
                            if (process.WarehouseId == MyUtilities.Warehouse.Plating) {
                                afterWarehouses = MyUtilities.Warehouse.GetWarehouseIds_Plating();
                            }
                            var afterInv = totalInvsById.Where(pi => afterWarehouses.Contains(pi.WarehouseId)).ToList().Sum(pi => pi.TotalQty);

                            latedState += (process.Warehouse.ShortName + "; ");
                            qcOrderState += (process.Warehouse.ShortName + "; ");
                        }


                        var qcOrder = 0.0;
                        var qcForecast = 0.0;
                        var qcProcess = productionProcessesById
                            .FirstOrDefault(pp => pp.WarehouseId == MyUtilities.Warehouse.QcA || pp.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcProcess != null) {
                            var qcInv = totalInvsById.Where(pi => qcWarehouses.Contains(pi.WarehouseId)).ToList().Sum(pi => pi.TotalQty);
                            var afterProcess = productionProcessesById.Where(pp => pp.ProcessIndex > qcProcess.ProcessIndex);
                            var afterWarehouses = afterProcess.Select(pp => pp.WarehouseId).ToList();
                            if (afterWarehouses.Contains(MyUtilities.Warehouse.Production2))
                                afterWarehouses.AddRange(production2Warehouses);
                            afterWarehouses = afterWarehouses.Distinct().ToList();
                            var afterInv = totalInvsById.Where(pi => afterWarehouses.Contains(pi.WarehouseId)).ToList().Sum(pi => pi.TotalQty);
                            if (orderPlan.PlanRequired > afterInv) {
                                var productionPlan = new QcOrderPlanReportModel {
                                    Info = baseInfo,
                                    TotalOrder = orderPlan.Total,
                                    AccumulatedExport = orderPlan.AccumulatedExport,
                                    InvQuantity = qcInv,
                                    AfterInvQuantity = afterInv,
                                };
                                qcOrder = productionPlan.TotalOrder;
                                latedState += "QC; ";
                                qcOrderState += "QC; ";
                                productionPlan.State = qcOrderState;
                                model.QcOrderPlans.Add(productionPlan);
                            }
                            if (forecastPlan.PlanRequired > afterInv) {
                                var productionPlan = new QcForecastPlanReportModel {
                                    Info = baseInfo,
                                    TotalOrder = forecastPlan.Total,
                                    AccumulatedExport = forecastPlan.AccumulatedExport,
                                    InvQuantity = qcInv,
                                    AfterInvQuantity = afterInv,
                                };
                                qcForecastState += "QC; ";
                                productionPlan.State = qcForecastState;
                                qcForecast = productionPlan.TotalOrder;
                                model.QcForecastPlans.Add(productionPlan);
                            }
                        }
                        var latedOrder = 0.0;
                        var lateOrdersById = orderDetailsLate.Where(od => od.ProductId == product.ProductId);
                        if (lateOrdersById.Any()) {
                            var latedProduct = new OrderLatePlanReportModel {
                                Info = baseInfo,
                                OrderQuatity = lateOrdersById.Sum(od => od.OrderQty),
                                ExportQuantity = lateOrdersById.Sum(od => od.OrderQty - od.RequiedNumber),
                                State = latedState
                            };
                            latedOrder = latedProduct.PlanRequired;
                            model.OrderLatedPlans.Add(latedProduct);
                        }

                        //foreach (var process in productionProcessesById) {
                        //    var str = process.Warehouse.ShortName + ";";
                        //    if (latedOrder > 0) {
                        //        latedState += str;
                        //    }
                        //    if (qcOrder > 0) {
                        //        qcOrderState += str;
                        //    }
                        //    if (qcForecast > 0) {
                        //        qcForecastState += str;
                        //    }
                        //}
                        // end
                    }
                }
            }
            catch (Exception ex) {
                throw ex;
            }
            return model;
        }

        [GridAction]
        public ActionResult SelectExpectedProduction2Plan(string fromDate, string toDate, string productCode, int customerId) {
            if (string.IsNullOrWhiteSpace(fromDate)) {
                return View(new GridModel(new List<ExpectedProduction2PlanModel>()));
            }
            var model = new List<ExpectedProduction2PlanModel>();
            try {
                model = GetExpectedProduction2Plan(fromDate, toDate, productCode, customerId);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectExpectedProduction2Plan", ex.Message);
            }
            return View(new GridModel(model));
        }

        public ActionResult PrintExpectedProduction2Plan(string fromDate, string toDate, string productCode, int customerId) {
            var model = new List<ExpectedProduction2PlanModel>();
            try {
                model = GetExpectedProduction2Plan(fromDate, toDate, productCode, customerId);
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintExpectedProduction2Plan", ex.Message);
            }
            return PartialView("PageExpectedProduction2Plan", model);
        }

        private List<ExpectedProduction2PlanModel> GetExpectedProduction2Plan(string fromDate, string toDate, string productCode, int customerId) {
            var model = new List<ExpectedProduction2PlanModel>();
            try {
                //var fromD = new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1);
                var ci = new CultureInfo("vi-VN");
                var fromD = string.IsNullOrWhiteSpace(fromDate)
                                  ? DateTime.Today
                                  : Convert.ToDateTime(fromDate, ci);
                var toD = string.IsNullOrWhiteSpace(toDate)
                                  ? DateTime.Today
                                  : Convert.ToDateTime(toDate, ci);
                //var toD = fromD.AddMonths(1).AddSeconds(-1);
                using (var vfi = new tammaContext()) {
                    var process2s = (from x in vfi.ProductionProcesses
                                     where x.Warehouse.IsProduction2 == true
                                         && x.IsNecessary && x.IsAlert
                                         && x.Product.Active
                                         && (customerId == 0 || x.Product.CustomerId == customerId)
                                     select new {
                                         x.ProductId,
                                         x.Product.ProductCode,
                                         x.Product.Customer.CustomerCode,
                                         x.ProcessIndex
                                     }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode)) { process2s = process2s.Where(x => x.ProductCode.Contains(productCode)).ToList(); }
                    var productIds = process2s.Select(pp => pp.ProductId).Distinct().ToList();
                    var allProcesses = (from x in vfi.ProductionProcesses
                                        where productIds.Contains(x.ProductId) && x.IsNecessary && x.IsAlert
                                        select new {
                                            x.ProductId,
                                            x.ProcessIndex,
                                            x.WarehouseId,
                                        }).ToList();
                    var orders = (from od in vfi.OrderDetails
                                  where od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                                        od.Order.Status != (byte)MyUtilities.Sales.Status.Completed &&
                                        od.Order.DueDate <= toD &&
                                        od.RequiedNumber > 0 &&
                                        productIds.Contains(od.ProductId)
                                  orderby od.Order.DueDate.Value
                                  select new {
                                      od.ProductId,
                                      OrderQty = od.OrderQty.Value,
                                      od.RequiedNumber,
                                      DueDate = od.Order.DueDate.Value
                                  }).ToList();
                    var forecasts = (from fd in vfi.ForecastOrders
                                     where fd.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                           fd.ForecastDate >= fromD &&
                                           fd.ForecastDate <= toD &&
                                           productIds.Contains(fd.ProductId)
                                     orderby fd.ForecastDate
                                     select new {
                                         fd.ProductId,
                                         fd.ForecastDate,
                                         fd.Quantity
                                     }).ToList();

                    //var allInvIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var allInvIds = _warehouseController.GetActiveWarehouseIds(new WarehouseConfiguration { CanStock = true });
                    var totalInvs = (from x in vfi.ProductInventories
                                     where productIds.Contains(x.ProductId) &&
                                         allInvIds.Contains(x.WarehouseId) &&
                                         x.TotalQty > 0
                                     select new {
                                         x.ProductId,
                                         x.WarehouseId,
                                         x.TotalQty,
                                     }).ToList();
                    var productionSections = (from x in vfi.ProductionSections
                                              where productIds.Contains(x.ProductId) && x.Active && x.IsMainProcess
                                              select new {
                                                  x.ProductId,
                                                  x.ProductionSectionId,
                                                  x.SectionId,
                                                  x.Section.SectionName,
                                                  x.Productivity,
                                              }).ToList();


                    var exportsFinish = (from p in vfi.ProductInventoryPeriods
                                         where
                                             p.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Finish &&
                                             p.Transaction.WarehouseReceiptId == MyUtilities.Warehouse.Business &&
                                             p.WarehouseId == MyUtilities.Warehouse.Business &&
                                             p.PeriodDate >= fromD &&
                                             p.PeriodDate <= toD &&
                                             productIds.Contains(p.ProductId)
                                         select new {
                                             p.ProductId,
                                             p.Quantity,
                                         }).ToList();

                    //var warehouse2Ids = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    var warehouse2Ids = _warehouseController.GetActiveWarehouseIds(new WarehouseConfiguration { IsProduction2 = true });
                    var qcIds = _warehouseController.GetActiveWarehouseIds(new WarehouseConfiguration { IsQC = true });
                    //var reprocessIds = _warehouseController.GetActiveWarehouseIds(new WarehouseConfiguration { IsReprocessing = true });
                    foreach (var process2 in process2s) {
                        var entity = new ExpectedProduction2PlanModel {
                            CustomerCode = process2.CustomerCode,
                            ProductId = process2.ProductId,
                            ProductCode = process2.ProductCode,
                            BeforeProduction2Day = 5,
                        };
                        var productionSectionsById = productionSections.Where(ps => ps.ProductId == entity.ProductId);
                        foreach (var productionSection in productionSectionsById) {
                            var section = new ExpectedProduction2PlanSection {
                                SectionId = productionSection.SectionId,
                                SectionName = productionSection.SectionName,
                                Productivity = productionSection.Productivity
                            };
                            entity.Sections.Add(section);
                        }
                        if (!entity.Sections.Any()) {
                            entity.Sections.Add(new ExpectedProduction2PlanSection {
                                SectionId = 0,
                                SectionName = "Chưa thiết lập",
                                Productivity = 0
                            });
                        }
                        entity.ExportFinish = exportsFinish.Where(x => x.ProductId == entity.ProductId).Sum(x => x.Quantity);

                        var nextProcesses = allProcesses.Where(pp => pp.ProductId == entity.ProductId && pp.ProcessIndex > process2.ProcessIndex);
                        if (!nextProcesses.Any()) continue;

                        var nextWarehouseIds = nextProcesses.Select(x => x.WarehouseId).Distinct().ToList();
                        if (nextWarehouseIds.Any(x => qcIds.Contains(x))) { nextWarehouseIds.AddRange(qcIds); }
                        nextWarehouseIds = nextWarehouseIds.Distinct().ToList();

                        var totalInvsById = totalInvs.Where(pi => pi.ProductId == entity.ProductId).ToList();
                        if (totalInvsById.Any()) {
                            entity.TotalInv = totalInvsById.Sum(pi => pi.TotalQty);
                            var invs = totalInvsById.Where(pi => warehouse2Ids.Contains(pi.WarehouseId));
                            entity.Production2Inv = invs.Sum(x => x.TotalQty);
                            invs = totalInvsById.Where(pi => nextWarehouseIds.Contains(pi.WarehouseId)).ToList();
                            entity.BeforeProduction2Inv = invs.Sum(pi => pi.TotalQty);
                        }
                        var beforeProduction2Inv = entity.BeforeProduction2Inv;
                        var ordersById = orders.Where(od => od.ProductId == entity.ProductId);
                        foreach (var orderDetail in ordersById) {
                            if (beforeProduction2Inv > orderDetail.RequiedNumber) {
                                beforeProduction2Inv -= orderDetail.RequiedNumber;
                                if (beforeProduction2Inv < 0) beforeProduction2Inv = 0;
                                continue;
                            }
                            var orderInfo = new ExpectedProduction2PlanInfo {
                                Quantity = orderDetail.RequiedNumber,
                                RequireQuantity = orderDetail.RequiedNumber - beforeProduction2Inv,
                                Second = entity.SmallestProductivity * (orderDetail.RequiedNumber - beforeProduction2Inv),
                                Date = orderDetail.DueDate,
                                EndDate = orderDetail.DueDate.AddDays(entity.BeforeProduction2Day * -1)
                            };
                            var requireDay = 0;
                            if (entity.ProductivityInDay > 0) {
                                requireDay = MyUtilities.Function.RoundUp(orderInfo.RequireQuantity / entity.ProductivityInDay);
                            }
                            orderInfo.StartDate = orderInfo.EndDate.Value.AddDays(requireDay * -1);
                            if (orderInfo.StartDate < DateTime.Now) {
                                orderInfo.StartDate = DateTime.Now;
                                orderInfo.EndDate = orderInfo.StartDate.Value.AddDays(requireDay);
                            }
                            entity.Orders.Add(orderInfo);
                        }
                        var forecastsById = forecasts.Where(fd => fd.ProductId == entity.ProductId).ToList();
                        var totalForecaseQuantity = forecastsById.Sum(x => x.Quantity);
                        var orderQuantity = ordersById.Where(x => x.DueDate >= fromD).Sum(x => x.OrderQty);
                        if (totalForecaseQuantity - entity.ExportFinish > orderQuantity) {
                            beforeProduction2Inv = entity.BeforeProduction2Inv + entity.ExportFinish;
                            foreach (var forecast in forecastsById) {
                                if (beforeProduction2Inv > forecast.Quantity) {
                                    beforeProduction2Inv -= forecast.Quantity;
                                    if (beforeProduction2Inv < 0) beforeProduction2Inv = 0;
                                    continue;
                                }
                                var forecastInfo = new ExpectedProduction2PlanInfo {
                                    Quantity = forecast.Quantity,
                                    EndDate = forecast.ForecastDate.AddDays(entity.BeforeProduction2Day * -1),
                                    Date = forecast.ForecastDate,
                                    RequireQuantity = forecast.Quantity - beforeProduction2Inv,
                                    Second = (forecast.Quantity - beforeProduction2Inv) * entity.SmallestProductivity
                                };
                                var requireDay = 0;
                                if (entity.ProductivityInDay > 0) {
                                    requireDay = MyUtilities.Function.RoundUp(forecastInfo.RequireQuantity / entity.ProductivityInDay);
                                }
                                forecastInfo.StartDate = forecastInfo.EndDate.Value.AddDays(requireDay * -1);
                                if (forecastInfo.StartDate < DateTime.Now) {
                                    forecastInfo.StartDate = DateTime.Now;
                                    forecastInfo.EndDate = forecastInfo.StartDate.Value.AddDays(requireDay);
                                }
                                entity.Forecasts.Add(forecastInfo);
                            }
                        }
                        if (entity.Orders.Any() || entity.Forecasts.Any()) {
                            if (!entity.Orders.Any()) {
                                entity.Orders.Add(new ExpectedProduction2PlanInfo {
                                    Quantity = 0,
                                    Second = 0,
                                    RequireQuantity = 0,
                                });
                            }
                            else if (!entity.Forecasts.Any()) {
                                entity.Forecasts.Add(new ExpectedProduction2PlanInfo {
                                    Quantity = 0,
                                    Second = 0,
                                    RequireQuantity = 0,
                                });
                            }
                            model.Add(entity);
                        }
                    }
                }
                var statistics = new List<SectionStatistic>();
                foreach (var entity in model) {
                    foreach (var section in entity.Sections) {
                        var statistic = statistics.FirstOrDefault(x => x.SectionId == section.SectionId);
                        if (statistic == null) {
                            statistic = new SectionStatistic {
                                SectionId = section.SectionId,
                                SectionName = section.SectionName
                            };
                            statistics.Add(statistic);
                        }
                        foreach (var detail in entity.Orders) {
                            statistic.OrderRequire += detail.RequireQuantity;
                            statistic.OrderSecond += (detail.RequireQuantity * section.Productivity);
                        }
                        foreach (var detail in entity.Forecasts) {
                            statistic.ForecastRequire += detail.RequireQuantity;
                            statistic.ForecastSecond += (detail.RequireQuantity * section.Productivity);
                        }
                    }
                }
                model = model.OrderBy(x => x.Date).ToList();
                var firstModel = model.FirstOrDefault();
                firstModel.Statistics = statistics.OrderBy(x => x.SectionName).ToList();
            }
            catch (Exception ex) {
                ModelState.AddModelError("GetExpectedProduction2Plan", ex.Message);
            }
            //return model.OrderBy(m => m.CustomerCode).ThenBy(m => m.ProductCode).ToList();
            return model;
        }

