        [GridAction]
        public ActionResult SelectOrderProgress(int customerId, string productCode, int month, int year) {
            var model = new List<ProductState>();
            try {
                model = GetOrderProgress(customerId, productCode, month, year);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectExpectedPlan", ex.Message);
            }
            return View(new GridModel(model));
        }
        [GridAction]
        public ActionResult UpdateOrderProgress(
            [Bind(Prefix = "inserted")] IEnumerable<ProductState> inserteds,
            [Bind(Prefix = "updated")] IEnumerable<ProductState> updateds,
            [Bind(Prefix = "deleted")] IEnumerable<ProductState> deleteds,
            int customerId, string productCode, int month, int year) {
            if (updateds != null) {
                try {
                    if (!Request.IsAuthenticated)
                        ModelState.AddModelError("UpdateOrderProgress",
                                                 @"Vui lòng đang nhập lại hệ thống. (IsAuthenticated) ");

                    ModelState.Clear();
                    using (var vfi = new tammaContext()) {
                        //var lastDate = new DateTime(year, month, 1).AddMonths(-1);
                        //var next2Month = new DateTime(year, month, 1).AddMonths(1);
                        //var next3Month = new DateTime(year, month, 1).AddMonths(2);
                        foreach (var update in updateds) {
                            var product = vfi.Products.FirstOrDefault(p => p.ProductId == update.ProductId);
                            if (product == null)
                                throw new AggregateException("Không tìm thấy sản phẩm ! Liên hệ admin " +
                                                             update.ProductCode);
                            var forecastOrder =
                                vfi.ForecastOrders.FirstOrDefault(
                                    fo =>
                                    fo.ProductId == product.ProductId &&
                                    fo.ForecastDate.Month == month &&
                                    fo.ForecastDate.Year == year);
                            if (forecastOrder == null) {
                                forecastOrder = new ForecastOrder {
                                    ProductId = update.ProductId,
                                    ForecastDate = new DateTime(year, month, 1),
                                    Quantity = 0,
                                    ModifiedDate = DateTime.Now,
                                    ModifiedUser = HttpContext.User.Identity.Name,
                                    MaterialEnoughDate = update.EnoughMaterialDate,
                                    IsSelling = true,
                                };
                                vfi.ForecastOrders.Add(forecastOrder);
                            }
                            else {
                                forecastOrder.MaterialEnoughDate = update.EnoughMaterialDate;
                            }
                        }
                        vfi.SaveChanges();
                    }
                }
                catch (Exception ex) {
                    ModelState.AddModelError("UpdateOrderProgress", ex.Message);
                }

            }

            //Session["SessionRotateTransactionProduct"] = new List<ProductInventoryRotateModel>();
            return View(new GridModel(GetOrderProgress(customerId, productCode, month, year)));
        }

        [GridAction]
        public ActionResult SelectExpectedSales(int type, int customerId, int employeeId, string productCode,
            int month, int year) {
            var model = new List<ExpectedSalesModel>();
            //var reportDate = new DateTime(year, month, 1).AddSeconds(-1);
            //if (month < 3)
            //{
            //    year--;
            //}
            var endDate = new DateTime(year, month, 1).AddMonths(-1).AddSeconds(-1);
            var startDate = new DateTime(year, month, 1).AddYears(-1).AddSeconds(-1);
            //var forecastDate = endDate.AddMonths(5); // tang forecast len 3 thang
            if (customerId != 0)
                employeeId = 0;
            try {
                using (var vfi = new tammaContext()) {
                    var flag = string.IsNullOrWhiteSpace(productCode);
                    var customerIds = (from c in vfi.Customers
                                       where
                                           (customerId == 0 || c.CustomerId == customerId) &&
                                           (employeeId == 0 || c.EmployeeId == employeeId)
                                           && c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                       select c.CustomerId).ToList();
                    var products = (from p in vfi.Products
                                    where p.Active &&
                                          customerIds.Contains(p.CustomerId) &&
                                          (flag || p.ProductCode.Contains(productCode))
                                    //&& (type == 2 || p.IsSelling == (type == 1))
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        ProductionFactor = p.ProductionFactor ?? 1,
                                        IsSelling = p.IsSelling ?? false,
                                        SaleFactor = p.SaleFactor ?? 1,
                                        NewUpdateDate = p.NewUpdateDate ?? DateTime.Now,
                                        LastSaleFactor = p.LastSaleFactor ?? (p.SaleFactor ?? 1),
                                        LastUpdateDate = p.LastUpdateDate ?? (p.NewUpdateDate ?? DateTime.Now),
                                        LastMonthSaleFactor = p.LastMonthSaleFactor ?? (p.SaleFactor ?? 1),
                                        LastMonthUpdateDate =
                                    p.LastMonthUpdateDate ?? (p.NewUpdateDate ?? DateTime.Now),
                                        Productivity = p.Productivity ?? 0,
                                        p.FinishProcessingDate,
                                        p.DiffRequestInv
                                    }).ToList();
                    if (!products.Any())
                        return View(model);
                    var productIds = products.Select(p => p.ProductId).ToList();
                    //var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    //var productInvs = (from pi in vfi.ProductInventories
                    //                   where warehouseIds.Contains(pi.WarehouseId) &&
                    //                   productIds.Contains(pi.ProductId)
                    //                   select new
                    //                       {
                    //                           pi.ProductId,
                    //                           pi.Product.CustomerId,
                    //                           TotalQty = pi.TotalQty.Value,
                    //                           pi.WarehouseId,
                    //                       }).ToList();
                    var orderDetails = (from od in vfi.OrderDetails
                                        where
                                            od.Order.DueDate != null &&
                                            od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                            od.Order.DueDate > startDate &&
                                            od.Order.DueDate < endDate &&
                                            (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.Completed) &&
                                            //od.Order.Status != (byte)MyUtilities.Sales.Status.Waiting &&
                                            productIds.Contains(od.ProductId)
                                        select new {
                                            od.ProductId,
                                            od.Order.CustomerId,
                                            OrderQty = od.OrderQty.Value,
                                            DueDate = od.Order.DueDate.Value,
                                        }).ToList();
                    var i = 1;
                    var foreacastOrders = from fo in vfi.ForecastOrders
                                          where
                                              productIds.Contains(fo.ProductId) &&
                                              fo.ForecastDate.Month == month &&
                                              fo.ForecastDate.Year == year
                                          select new {
                                              fo.ProductId,
                                              fo.Quantity,
                                              fo.IsSelling,
                                              fo.ForecastDate
                                          };

                    Session["SessionExpectedSales"] = new List<ExpectedSalesModel>();
                    foreach (var product in products) {
                        var entity = new ExpectedSalesModel {
                            Index = i,
                            ProductId = product.ProductId,
                            ProductCustomerCode = product.DesignNo,
                            ProductName = product.ProductName,
                            ProductCode = product.ProductCode,
                            AvgOrderQuantity = 0,
                            SaleFactor = product.SaleFactor,
                            ProductionFactor = product.ProductionFactor,
                            ProductTotalInventory = 0,
                            FinishInventory = 0,
                            MonthOrder = "",
                            ExpectedSalesQuantity = 0,
                            ForecastProduction = 0,
                            MonthCount = 0,
                            ForeCastNext2Month = 0,
                            ForeCastNext3Month = 0,
                            MaxOrderQuantityInMonth = 0,
                            InventoryAlarmColor = 0,
                            InvQuantityNeed = 0,
                            InvQuantityNeedProcessing = 0,
                            InvQuantityNeedProduction = 0,
                            DateNeedProcessing = null,
                            DateNeedProduction = null,
                            CustomerCode = product.CustomerCode,
                            DayNeedProcessing = 0,
                            DiffRequestInv = 0
                        };
                        var diffRequest = foreacastOrders.FirstOrDefault(fo => fo.ProductId == product.ProductId);
                        if (diffRequest != null) {
                            if ((type != 2 && !diffRequest.IsSelling == (type == 1)))
                                continue;
                            entity.ExpectedSalesQuantity = diffRequest.Quantity;
                            entity.IsSelling = diffRequest.IsSelling;
                            entity.ForeCastDate = diffRequest.ForecastDate;
                        }
                        else {
                            //continue;
                            if (type != 2)
                                continue;
                            //entity.IsSelling = product.IsSelling;
                        }
                        var orderDetailsById = orderDetails.Where(od => od.ProductId == product.ProductId);
                        if (orderDetailsById.Any()) {
                            entity.MonthCount = orderDetailsById.Select(od => od.DueDate.Month).Distinct().Count();
                            entity.AvgOrderQuantity = Convert.ToDouble(orderDetailsById.Sum(od => od.OrderQty)) /
                                                      entity.MonthCount;
                            var orderMonth = orderDetailsById.Select(od => od.DueDate.Month).Distinct();
                            foreach (var i1 in orderMonth) {
                                var orderInMonth = orderDetailsById.Where(od => od.DueDate.Month == i1);
                                if (entity.MaxOrderQuantityInMonth < orderInMonth.Sum(od => od.OrderQty))
                                    entity.MaxOrderQuantityInMonth = orderInMonth.Sum(od => od.OrderQty);
                                entity.MonthOrder += (i1 + ",");
                            }
                            entity.MonthOrder = entity.MonthOrder.Remove(entity.MonthOrder.Length - 1);
                            var temp = entity.AvgOrderQuantity % 100;
                            if (temp != 0)
                                entity.AvgOrderQuantity = entity.AvgOrderQuantity - temp + 100;
                        }
                        //var productInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId);
                        //if (productInvsById.Any())
                        //{
                        //    entity.ProductTotalInventory = productInvsById.Sum(od => od.TotalQty);
                        //    var finishProduct =
                        //        productInvsById.FirstOrDefault(
                        //            p => p.WarehouseId == MyUtilities.Warehouse.Finish);
                        //    if (finishProduct != null)
                        //        entity.FinishInventory = finishProduct.TotalQty;
                        //}
                        if (entity.ExpectedSalesQuantity == 0)
                            entity.ExpectedSalesQuantity = entity.AvgOrderQuantity;
                        else entity.DiffRequestInv = entity.ExpectedSalesQuantity - entity.AvgOrderQuantity;
                        if (entity.AvgOrderQuantity != 0)
                            entity.SaleFactor = entity.ExpectedSalesQuantity / entity.AvgOrderQuantity;
                        else entity.SaleFactor = 1;
                        i++;
                        model.Add(entity);
                    }
                }
                //}
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectExpectedSales", ex.Message);
            }
            Session["SessionExpectedSales"] = model;
            return View(new GridModel(model));
        }

        [GridAction]
        public ActionResult UpdateExpectedSales(
            [Bind(Prefix = "inserted")] IEnumerable<ExpectedSalesModel> inserteds,
            [Bind(Prefix = "updated")] IEnumerable<ExpectedSalesModel> updateds,
            [Bind(Prefix = "deleted")] IEnumerable<ExpectedSalesModel> deleteds,
            int month, int year) {
            if (updateds != null) {
                try {
                    if (!Request.IsAuthenticated)
                        ModelState.AddModelError("UpdateExpectedSales",
                                                 @"Vui lòng đang nhập lại hệ thống. (IsAuthenticated) ");
                    ModelState.Clear();
                    using (var vfi = new tammaContext()) {
                        var listExpectedSales = (List<ExpectedSalesModel>)Session["SessionExpectedSales"];
                        foreach (var expectedSalesModel in listExpectedSales) {
                            var expectedNew = updateds.FirstOrDefault(es => es.ProductId == expectedSalesModel.ProductId) ??
                                              expectedSalesModel;
                            var product = vfi.Products.FirstOrDefault(p => p.ProductId == expectedNew.ProductId);
                            if (product == null)
                                throw new AggregateException("Không tìm thấy sản phẩm ! Liên hệ admin " +
                                                             expectedNew.ProductCode);
                            var forecastOrder =
                                vfi.ForecastOrders.FirstOrDefault(
                                    fo =>
                                    fo.ProductId == product.ProductId &&
                                    fo.ForecastDate == expectedNew.ForeCastDate.Value);
                            if (forecastOrder == null) {
                                if (!expectedNew.IsSelling) continue;
                                forecastOrder = new ForecastOrder {
                                    ProductId = expectedNew.ProductId,
                                    ForecastDate = expectedNew.ForeCastDate.Value,
                                    Quantity = expectedNew.ExpectedSalesQuantity,
                                    ModifiedDate = DateTime.Now,
                                    ModifiedUser = HttpContext.User.Identity.Name,
                                    IsSelling = expectedNew.IsSelling
                                };
                                vfi.ForecastOrders.Add(forecastOrder);
                            }
                            else {
                                forecastOrder.Quantity = expectedNew.ExpectedSalesQuantity;
                                forecastOrder.IsSelling = expectedNew.IsSelling;
                                //product.IsSelling = expectedNew.IsSelling;
                            }
                        }
                        vfi.SaveChanges();
                    }
                }
                catch (Exception ex) {
                    ModelState.AddModelError("UpdateExpectedSales", ex.Message);
                }

            }

            //Session["SessionRotateTransactionProduct"] = new List<ProductInventoryRotateModel>();
            return View(new GridModel(new List<ExpectedSalesModel>()));
        }


        public ActionResult PrintExpectedSalesReport(
           int type, int month, int year) {
            var model = new List<ExpectedSalesGroupModel>();
            var reportDate = new DateTime(year, month, 1).AddSeconds(-1);
            var endDate = new DateTime(year, month, 1).AddMonths(-1);
            var startDate = new DateTime(year, month, 1).AddYears(-1).AddSeconds(-1);
            var forecastDate = reportDate.AddMonths(3); // tang forecast len 3 thang
            try {
                using (var vfi = new tammaContext()) {
                    var products = (from p in vfi.Products
                                    where p.Active
                                    orderby p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        ProductionFactor = p.ProductionFactor ?? 1,
                                        IsSelling = p.IsSelling ?? false,
                                        SaleFactor = p.SaleFactor ?? 1,
                                        NewUpdateDate = p.NewUpdateDate ?? DateTime.Now,
                                        LastSaleFactor = p.LastSaleFactor ?? (p.SaleFactor ?? 1),
                                        LastUpdateDate = p.LastUpdateDate ?? (p.NewUpdateDate ?? DateTime.Now),
                                        LastMonthSaleFactor = p.LastMonthSaleFactor ?? (p.SaleFactor ?? 1),
                                        LastMonthUpdateDate =
                                    p.LastMonthUpdateDate ?? (p.NewUpdateDate ?? DateTime.Now),
                                        Productivity = p.Productivity ?? 0,
                                        p.FinishProcessingDate,
                                        p.DiffRequestInv,
                                        ForecastsQuality = p.ForecastsQuality ?? 0,
                                    }).ToList();
                    if (type == 1)
                        products = products.Where(p => p.IsSelling).ToList();
                    else if (type == 0)
                        products = products.Where(p => !p.IsSelling).ToList();
                    if (!products.Any())
                        return PartialView("PageExpectedSalesReport", null);
                    var customerIds = products.Select(p => p.CustomerId).Distinct();
                    var customers = (from c in vfi.Customers
                                     where customerIds.Contains(c.CustomerId) &&
                                     c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                     orderby c.CustomerCode
                                     select new {
                                         c.CustomerId,
                                         c.CustomerCode,
                                         c.ShortName
                                     }).ToList();
                    if (!customers.Any())
                        return PartialView("PageExpectedSalesReport", null);
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where warehouseIds.Contains(pi.WarehouseId) &&
                                       productIds.Contains(pi.ProductId)
                                       select new {
                                           pi.ProductId,
                                           pi.Product.CustomerId,
                                           TotalQty = pi.TotalQty,
                                           pi.WarehouseId,
                                       }).ToList();
                    var orderDetails = (from od in vfi.OrderDetails
                                        where
                                            od.Order.DueDate != null &&
                                            od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                            od.Order.DueDate > startDate &&
                                            od.Order.DueDate < endDate &&
                                            (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.Completed) &&
                                            //od.Order.Status != (byte)MyUtilities.Sales.Status.Waiting &&
                                            productIds.Contains(od.ProductId)
                                        select new {
                                            od.ProductId,
                                            od.Order.CustomerId,
                                            OrderQty = od.OrderQty.Value,
                                            DueDate = od.Order.DueDate.Value,
                                        }).ToList();
                    //var forecastOrder = (from fo in vfi.ForecastOrders
                    //                     where productIds.Contains(fo.ProductId) &&
                    //                           fo.ForecastDate < forecastDate
                    //                     orderby fo.ForecastDate
                    //                     select new
                    //                     {
                    //                         fo.ProductId,
                    //                         fo.ForecastDate,
                    //                         fo.Quantity,
                    //                     }).ToList();
                    var next2Month = forecastDate.AddMonths(-1);
                    var i = 1;
                    foreach (var customer in customers) {
                        var productsByCustomer = products.Where(p => p.CustomerId == customer.CustomerId);
                        var list = new List<ExpectedSalesModel>();
                        foreach (var product in productsByCustomer) {
                            var entity = new ExpectedSalesModel {
                                Index = i,
                                ProductId = product.ProductId,
                                ProductCustomerCode = product.DesignNo,
                                ProductName = product.ProductName,
                                ProductCode = product.ProductCode,
                                AvgOrderQuantity = 0,
                                SaleFactor = product.SaleFactor,
                                ProductionFactor = product.ProductionFactor,
                                ProductTotalInventory = 0,
                                FinishInventory = 0,
                                MonthOrder = "",
                                ExpectedSalesQuantity = 0,
                                ForecastProduction = product.ForecastsQuality,
                                MonthCount = 0,
                                IsSelling = product.IsSelling,
                                ForeCastNext2Month = 0,
                                ForeCastNext3Month = 0,
                                MaxOrderQuantityInMonth = 0,
                                InventoryAlarmColor = 0,
                                InvQuantityNeed = 0,
                                InvQuantityNeedProcessing = 0,
                                InvQuantityNeedProduction = 0,
                                DateNeedProcessing = null,
                                DateNeedProduction = null,
                                OrderQuantityInYear = 0,
                            };
                            var orderDetailsById = orderDetails.Where(od => od.ProductId == product.ProductId);
                            if (orderDetailsById.Any()) {
                                entity.MonthCount = orderDetailsById.Select(od => od.DueDate.Month).Distinct().Count();
                                entity.OrderQuantityInYear = orderDetailsById.Sum(od => od.OrderQty);
                                entity.AvgOrderQuantity = Convert.ToDouble(entity.OrderQuantityInYear) / entity.MonthCount;
                                var orderMonth = orderDetailsById.Select(od => od.DueDate.Month).Distinct();
                                foreach (var i1 in orderMonth) {
                                    var orderInMonth = orderDetailsById.Where(od => od.DueDate.Month == i1);
                                    if (entity.MaxOrderQuantityInMonth < orderInMonth.Sum(od => od.OrderQty))
                                        entity.MaxOrderQuantityInMonth = orderInMonth.Sum(od => od.OrderQty);
                                    entity.MonthOrder += (i1 + ",");
                                }
                                entity.MonthOrder = entity.MonthOrder.Remove(entity.MonthOrder.Length - 1);
                                var temp = entity.AvgOrderQuantity % 100;
                                if (temp != 0)
                                    entity.AvgOrderQuantity = entity.AvgOrderQuantity - temp + 100;
                            }
                            var productInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId);
                            if (productInvsById.Any()) {
                                entity.ProductTotalInventory = productInvsById.Sum(od => od.TotalQty);
                                var finishProduct =
                                    productInvsById.FirstOrDefault(
                                        p => p.WarehouseId == MyUtilities.Warehouse.Finish);
                                if (finishProduct != null)
                                    entity.FinishInventory = finishProduct.TotalQty;
                            }
                            entity.ExpectedSalesQuantity = entity.AvgOrderQuantity + product.DiffRequestInv;
                            if (entity.AvgOrderQuantity != 0)
                                entity.SaleFactor = (entity.AvgOrderQuantity + product.DiffRequestInv) /
                                                    entity.AvgOrderQuantity;
                            if (entity.ExpectedSalesQuantity != 0)
                                entity.ProductionFactor = entity.ForecastProduction / entity.ExpectedSalesQuantity;
                            i++;
                            list.Add(entity);
                        }
                        if (list.Any()) {
                            var group = new ExpectedSalesGroupModel {
                                CustomerId = customer.CustomerId,
                                CustomerCode = customer.CustomerCode,
                                CustomerName = customer.ShortName,
                                //List = new List<ExpectedSalesModel>(),
                                ReportDate = reportDate.AddMonths(1),
                                Next2Month = next2Month.ToString("MM/yyyy"),
                                Next3Month = forecastDate.ToString("MM/yyyy"),
                                PrintDate = DateTime.Now,
                                PrintDateString = DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss"),
                                AvgOrderQuantity = list.Sum(l => l.AvgOrderQuantity),
                                ExpectedSalesQuantity = list.Sum(l => l.ExpectedSalesQuantity),
                                ForecastProduction = list.Sum(l => l.ForecastProduction),
                                InvQuantityNeed = list.Sum(l => l.InvQuantityNeed),
                                ProductCount = list.Count,
                                InvQuantityNeedProduction = list.Sum(l => l.InvQuantityNeedProduction),
                                ForeCastNext2Month = list.Sum(l => l.ForeCastNext2Month),
                                ForeCastNext3Month = list.Sum(l => l.ForeCastNext3Month),
                                MaxOrderQuantityInMonth = list.Sum(l => l.MaxOrderQuantityInMonth),
                                OrderQuantityInYear = list.Sum(l => l.OrderQuantityInYear),
                                List = list.OrderBy(l => l.ProductCode).ToList(),
                            };
                            //group.AvgOrderQuantity = list.Sum(l => l.AvgOrderQuantity);
                            //group.ExpectedSalesQuantity = list.Sum(l => l.ExpectedSalesQuantity);
                            //group.ForecastProduction = list.Sum(l => l.ForecastProduction);
                            //group.InvQuantityNeed = list.Sum(l => l.InvQuantityNeed);
                            //group.ProductCount = list.Count;
                            //group.List.AddRange(list.OrderBy(l => l.ProductCode));
                            model.Add(group);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintExpecedSalesReport", ex.Message);
            }
            return PartialView("PageExpectedSalesReport", model);
        }

        public ActionResult PrintOrderProgress(int month, int year) {
            var model = new List<ProductState>();
            var reportDate = new DateTime(year, month, 1);
            var endDate = reportDate.AddMonths(1).AddSeconds(-1);
            var nextMonth = reportDate.AddMonths(1);
            //var forecastDate = reportDate.AddMonths(3); // tang forecast len 3 thang
            try {
                using (var vfi = new tammaContext()) {
                    var products = (from p in vfi.Products
                                    where p.Active
                                    //&& p.ProductCode.Equals("A2 0204")
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        p.Customer.CustomerCode,
                                        ProductionFactor = p.ProductionFactor ?? 1,
                                        IsSelling = p.IsSelling ?? false,
                                        SaleFactor = p.SaleFactor ?? 1,
                                        NewUpdateDate = p.NewUpdateDate ?? DateTime.Now,
                                        Productivity = p.Productivity ?? 0,
                                        CncProductivity = p.CncProductivity ?? 0,
                                        //p.FinishProcessingDate,
                                        ForecastsQuality = p.ForecastsQuality ?? 0,
                                        p.MaterialNameDesign,
                                        p.DiffRequestInv,
                                        p.ProductionMaterials,
                                        ProductionProcesses =
                                    p.ProductionProcesses.OrderByDescending(pp => pp.ProcessIndex)
                                    }).ToList();
                    //if (type == 2)
                    //    products = products.Where(p => p.IsSelling).ToList();
                    //else if (type == 3)
                    //    products = products.Where(p => !p.IsSelling).ToList();
                    if (!products.Any())
                        return PartialView("PageOrderProgress", null);
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where warehouseIds.Contains(pi.WarehouseId) &&
                                             productIds.Contains(pi.ProductId)
                                       select new {
                                           pi.ProductId,
                                           pi.Product.CustomerId,
                                           TotalQty = pi.TotalQty,
                                           pi.WarehouseId,
                                       }).ToList();
                    //var orderDetails = (from od in vfi.OrderDetails
                    //                    where
                    //                        od.Order.DueDate != null &&
                    //                        od.Order.DueDate > vfStartDate &&
                    //                        od.Order.DueDate < nextMonth &&
                    //                        od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                    //                        //od.Order.Status != (byte)MyUtilities.Sales.Status.Waiting &&
                    //                        productIds.Contains(od.ProductId)
                    //                    select new
                    //                        {
                    //                            od.ProductId,
                    //                            //od.Order.CustomerId,
                    //                            OrderQty = od.OrderQty.Value,
                    //                            RequiedNumber = od.RequiedNumber.Value,
                    //                            DueDate = od.Order.DueDate.Value,
                    //                            //od.Order.Status 
                    //                        }).ToList();
                    var requirementOrderDetails = (from od in vfi.OrderDetails
                                                   where
                                                       od.Order.DueDate != null &&
                                                       od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                                       (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                        od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                       productIds.Contains(od.ProductId) &&
                                                       od.RequiedNumber != 0
                                                   select new {
                                                       od.ProductId,
                                                       //od.Order.CustomerId,
                                                       //OrderQty = od.OrderQty.Value,
                                                       RequiedNumber = od.RequiedNumber,
                                                       DueDate = od.Order.DueDate.Value,
                                                       //od.Order.Status
                                                   }).ToList();
                    var productionMaterials = from pm in vfi.ProductionMaterials
                                              where productIds.Contains(pm.ProductId)
                                              select pm;
                    var materialIds = productionMaterials.Select(pm => pm.MaterialId);
                    var materialInvs = from mi in vfi.MaterialInventories
                                       where materialIds.Contains(mi.MaterialId) && mi.TotalQty != 0
                                       select new {
                                           TotalQty = mi.TotalQty,
                                           mi.MaterialId,
                                           mi.Material.MaterialCode,
                                           mi.Material.MaterialName,
                                           mi.Material.OutDiameter,
                                           mi.Material.InDiameter,
                                           mi.Material.DiameterType,
                                           mi.Material.Shape,
                                           mi.UnitWeight
                                       };
                    var forecastOrders = from fo in vfi.ForecastOrders
                                         where productIds.Contains(fo.ProductId) &&
                                               fo.ForecastDate.Month == nextMonth.Month &&
                                               fo.ForecastDate.Year == nextMonth.Year
                                         select new {
                                             fo.ProductId,
                                             fo.Quantity,
                                             fo.IsSelling,
                                         };
                    //var orderProgresses = from op in vfi.OrderProgresses
                    //                      where productIds.Contains(op.ProductId) &&
                    //                            op.Month == month &&
                    //                            op.Year == year &&
                    //                            op.WarehouseId != MyUtilities.Warehouse.Finish
                    //                      select new
                    //                      {
                    //                          op.ProductId,
                    //                          op.WarehouseId,
                    //                          op.StartDate,
                    //                          op.ExpectedDay,
                    //                          op.ExpectedFactor,
                    //                      };
                    var smartProductions = from sp in vfi.SmartProductions
                                           where productIds.Contains(sp.ProductId.Value)
                                           select new {
                                               sp.ProductId,
                                           };
                    var lastProductions = (from sx in vfi.ImportFormSX1Detail
                                           where productIds.Contains(sx.ProductId) &&
                                               sx.ImportFormSX1.ImportDate <= endDate &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                 .Transaction.Status ==
                                               (byte)MyUtilities.Transaction.Status.Approved
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                           orderby sx.ImportFormSX1.MaterialUseDate
                                           select new {
                                               sx.ProductId,
                                               sx.ImportFormSX1.MaterialUseDate,
                                               Quantity = (sx.Number1 + sx.Number2),
                                               sx.MachineId,
                                           }).ToList();
                    var customersUseForecast = (from c in vfi.Customers
                                                where c.UseForecast && c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                                select new {
                                                    c.CustomerId,
                                                }).Select(c => c.CustomerId).ToList();
                    //var list = new List<ProductState>();
                    var customers = from c in vfi.Customers
                                    where c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                    orderby c.Area.AreaName, c.CustomerCode
                                    select new {
                                        c.CustomerId
                                    };
                    var i = 1; var production2Ids = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    foreach (var customer in customers) {
                        var productsByCustomer =
                            products.Where(p => p.CustomerId == customer.CustomerId).OrderBy(p => p.ProductCode);
                        foreach (var product in productsByCustomer) {
                            //if (!product.ProductCode.Equals("0604")) continue;
                            var entity = new ProductState {
                                Index = i,
                                ProductId = product.ProductId,
                                ProductCode = product.ProductCode,
                                CustomerCode = product.CustomerCode,
                                MaterialCode = product.MaterialNameDesign,
                                MaterialName = product.MaterialNameDesign,
                                Productivity = product.Productivity,
                                CncProductivity = product.CncProductivity,
                                //PlatingInv = 0,
                                //CncInv = 0,
                                FinishInv = 0,
                                //HeatTreatmentInv = 0,
                                //QcInv = 0,
                                //SurfaceTreatmentInv = 0,
                                TotalInv = 0,
                                //WaitingPlatingInv = 0,
                                MaterialInv = 0,
                                //Production2Inv = 0,
                                ProcessingInv = 0,
                                ProductionForecasts = product.ForecastsQuality,
                                RequirementInventory = 0,
                                RequirementOrder = 0,
                                ReportDate = reportDate,
                                InMonthDateString = reportDate.ToString("MM/yyyy"),
                                NextMonthDateString = nextMonth.ToString("MM/yyyy"),
                                ProductionStatus = 0,
                                //CncStatus = 0,
                                //HeatTreatmentStatus = 0,
                                //PlatingStatus = 0,
                                //Production2Status = 0,
                                ProductionForecastsStatus = 0,
                                //QcStatus = 0,
                                RequirementInvStatus = 0,
                                RequirementOrderStatus = 0,
                                //WaitingPlatingStatus = 0,
                                //SurfaceTreatmentStatus = 0,
                                MaterialStatus = 0,
                                RequirementOrderInMonth = 0,
                                RequirementOrderNextMonth = 0,
                                Details = new List<OrderProgressDetailModel>(),
                                Productions = new List<OrderProgressProduction>(),
                                CncProgress = new OrderProgressInventory(),
                                Production2Progress = new OrderProgressInventory(),
                                HeatProgress = new OrderProgressInventory(),
                                SurfaceProgress = new OrderProgressInventory(),
                                QcProgress = new OrderProgressInventory(),
                                PlatingProgress = new OrderProgressInventory(),
                            };
                            var requirementOrderInMonth =
                                requirementOrderDetails.Where(
                                    od => od.ProductId == product.ProductId && od.DueDate < endDate)
                                                       .OrderBy(od => od.DueDate)
                                                       .ToList();
                            if (requirementOrderInMonth.Any()) {
                                foreach (var orderDetail in requirementOrderInMonth) {
                                    var detail =
                                        entity.Details.FirstOrDefault(od => od.OrderDueDate == orderDetail.DueDate);
                                    if (detail == null) {

                                        detail = new OrderProgressDetailModel {
                                            OrderDueDate = orderDetail.DueDate,
                                            OrderQuantity = orderDetail.RequiedNumber,
                                            OrderDueDateString = orderDetail.DueDate.ToString("dd/MM")
                                        };
                                        entity.Details.Add(detail);
                                    }
                                    else {
                                        detail.OrderQuantity += orderDetail.RequiedNumber;
                                    }
                                }
                                entity.RequirementOrderInMonth = requirementOrderInMonth.Sum(od => od.RequiedNumber);
                            }
                            else {
                                var detail = new OrderProgressDetailModel {
                                    OrderQuantity = 0,
                                    OrderDueDateString = ""
                                };
                                entity.Details.Add(detail);
                            }
                            var requirementOrderNextMonth =
                                requirementOrderDetails.Where(
                                    od =>
                                    od.ProductId == product.ProductId &&
                                    od.DueDate.Month == nextMonth.Month &&
                                    od.DueDate.Year == nextMonth.Year).ToList();
                            if (requirementOrderNextMonth.Any()) {
                                entity.RequirementOrderNextMonth = requirementOrderNextMonth.Sum(od => od.RequiedNumber);
                            }
                            var diffRequest = forecastOrders.FirstOrDefault(fo => fo.ProductId == product.ProductId);
                            if (entity.RequirementOrderInMonth == 0 &&
                                (diffRequest == null || !diffRequest.IsSelling) &&
                                entity.RequirementOrderNextMonth == 0)
                                continue;
                            var useForecast = customersUseForecast.Contains(product.CustomerId);
                            if (useForecast && diffRequest != null) {
                                entity.RequirementOrderNextMonth = diffRequest.Quantity;
                            }
                            else if (entity.RequirementOrderNextMonth == 0 && diffRequest != null) {
                                entity.RequirementOrderNextMonth = diffRequest.Quantity;
                            }
                            else {
                                if (diffRequest != null)
                                    entity.RequirementInvStatus = 1;
                            }
                            entity.RequirementInventory = entity.RequirementOrderInMonth +
                                                          entity.RequirementOrderNextMonth;
                            //if (diffRequest != null) entity.RequirementInventory = diffRequest.Quantity;
                            //if (entity.RequirementOrder > entity.RequirementInventory)
                            //{
                            //    //entity.RequirementInvStatus = 1;
                            //    entity.RequirementInventory = entity.RequirementOrder;
                            //}
                            //else if (entity.RequirementOrder == 0 && entity.RequirementInventory != 0)
                            //    entity.RequirementInvStatus = 2;

                            var productInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId).ToList();
                            if (productInvsById.Any()) {
                                entity.TotalInv = productInvsById.Sum(od => od.TotalQty);
                                entity.ProductionRequirement = entity.RequirementInventory - entity.TotalInv;
                                if (entity.ProductionRequirement < 0) entity.ProductionRequirement = 0;
                                var inv = productInvsById.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                                if (inv != null)
                                    entity.FinishInv = inv.TotalQty;
                                //inv = productInvsById.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                                //if (inv != null)
                                //    entity.WaitingPlatingInv = inv.TotalQty;
                                //inv = productInvsById.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                                //if (inv != null)
                                //    entity.PlatingInv = inv.TotalQty;
                                inv =
                                    productInvsById.FirstOrDefault(
                                        pi => pi.WarehouseId == MyUtilities.Warehouse.HeatTreatment);
                                if (inv != null)
                                    entity.HeatProgress.Inv = inv.TotalQty;
                                inv =
                                    productInvsById.FirstOrDefault(
                                        pi => pi.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment);
                                if (inv != null)
                                    entity.SurfaceProgress.Inv = inv.TotalQty;
                                inv = productInvsById.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Cnc);
                                if (inv != null)
                                    entity.CncProgress.Inv = inv.TotalQty;
                                var invs =
                                    productInvsById.Where(
                                        pi =>
                                        pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB)
                                                   .ToList();
                                if (invs.Any()) {
                                    entity.QcProgress.Inv = invs.Sum(pi => pi.TotalQty);
                                }
                                invs =
                                    productInvsById.Where(
                                        pi =>
                                        pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating ||
                                        pi.WarehouseId == MyUtilities.Warehouse.Plating).ToList();
                                if (invs.Any())
                                    entity.PlatingProgress.Inv = invs.Sum(pi => pi.TotalQty);
                                invs =
                                    productInvsById.Where(
                                        pi =>
                                        pi.WarehouseId == MyUtilities.Warehouse.Processing ||
                                        pi.WarehouseId == MyUtilities.Warehouse.Processing2).ToList();
                                if (invs.Any())
                                    entity.ProcessingInv = invs.Sum(pi => pi.TotalQty);
                                invs =
                                    productInvsById.Where(
                                        pi => production2Ids.Contains(pi.WarehouseId)).ToList();
                                if (invs.Any())
                                    entity.Production2Progress.Inv = invs.Sum(pi => pi.TotalQty);
                            }
                            if (entity.ProductionRequirement > 0) {
                                var startProduct =
                                    lastProductions.Where(id => id.ProductId == entity.ProductId).ToList();
                                //if (product.Productivity > 0)
                                //    entity.ProductivityInDay = (72000 / product.Productivity);
                                entity.Average = 0;
                                if (startProduct.Any()) {
                                    entity.ProductionLast =
                                        startProduct.LastOrDefault().MaterialUseDate;
                                    entity.MachineRun =
                                        Math.Round((entity.ProductionRequirement / entity.ProductivityInDay) / 25, 1);
                                    if (entity.MachineRun == 0.0)
                                        entity.MachineRun = 0.1;
                                    if (product.Productivity == 0)
                                        entity.ProductionLastDate = "E";
                                    else
                                        entity.ProductionLastDate = string.Format("{0:N1}", entity.MachineRun);
                                    if (entity.ProductionLast < new DateTime(year, month, 5).AddDays(-7)) {
                                        entity.ProductionStatus = 1;
                                    }

                                    var groupSx = (from sx in startProduct
                                                   //where sx.MachineId == 55
                                                   group sx by new { sx.MachineId, sx.MaterialUseDate }
                                                       into sxsx1
                                                       select new {
                                                           sxsx1.Key.MachineId,
                                                           sxsx1.Key.MaterialUseDate,
                                                           Quantity = sxsx1.Sum(sx => sx.Quantity),
                                                       }).ToList();
                                    var machines = groupSx.Select(sx => sx.MachineId).Distinct();
                                    var lastProduct =
                                        lastProductions.LastOrDefault(id => id.ProductId == entity.ProductId);
                                    var count = 0;
                                    foreach (var machine in machines) {
                                        var startDiffProduct =
                                            lastProductions.LastOrDefault(
                                                id =>
                                                id.ProductId != entity.ProductId &&
                                                id.MaterialUseDate < lastProduct.MaterialUseDate &&
                                                id.MachineId == machine);
                                        var groupDetail = groupSx.Where(sx => sx.MachineId == machine);
                                        if (startDiffProduct != null)
                                            groupDetail =
                                                groupDetail.Where(
                                                    sx => sx.MaterialUseDate >= startDiffProduct.MaterialUseDate);
                                        if (groupDetail.Any()) {
                                            entity.Average += (groupDetail.Sum(sx => sx.Quantity) / groupDetail.Count());
                                            count++;
                                        }
                                    }
                                    entity.Average = entity.Average / count;
                                }
                            }
                            var smartProduction = smartProductions.FirstOrDefault(sp => sp.ProductId == entity.ProductId);
                            if (smartProduction != null) {
                                entity.ProductionDateStatus = 1;
                            }
                            if (entity.QcProgress.Inv != 0) {
                                entity.QcProgress.Requirement = entity.RequirementInventory - entity.FinishInv;
                            }
                            var productionProcesses = product.ProductionProcesses.FirstOrDefault(
                                pp =>
                                pp.WarehouseId == MyUtilities.Warehouse.QcA || pp.WarehouseId == MyUtilities.Warehouse.QcB);
