        public List<ProductState> GetOrderProgressInMonth(
            int customerId, string productCode, 
            string toDate, string invDate, 
            int month, int year,
            bool isAllOrder) {
            var model = new List<ProductState>();
            if (month == 0) return model;

            var toDatetime = MyUtilities.Function.ParseLastDateTime(toDate);
            var invDatetime = MyUtilities.Function.ParseLastDateTime(invDate);
            var reportDate = new DateTime(year, month, 1);
            var endDate = reportDate.AddMonths(1).AddDays(-1);
            var nextMonth = reportDate.AddMonths(1);
            //var forecastDate = reportDate.AddMonths(3); // tang forecast len 3 thang
            try {
                using (var vfi = new tammaContext()) {
                    var checkProduct = string.IsNullOrWhiteSpace(productCode);
                    var products = (from p in vfi.Products
                                    where p.Active &&
                                          (checkProduct || p.ProductCode.Contains(productCode))
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        p.Customer.CustomerCode,
                                        ProductionFactor = p.ProductionFactor ?? 1,
                                        IsSelling = p.IsSelling ?? false,
                                        SaleFactor = p.SaleFactor ?? 1,
                                        NewUpdateDate = p.NewUpdateDate ?? DateTime.Now,
                                        Productivity = p.Productivity ?? 0,
                                        CncProductivity = p.CncProductivity ?? 0,
                                        ForecastsQuality = p.ForecastsQuality ?? 0,
                                        p.MaterialNameDesign,
                                        p.DiffRequestInv,
                                        p.ProductionMaterials,
                                        ProductionProcesses =
                                    p.ProductionProcesses.OrderByDescending(pp => pp.ProcessIndex)
                                    }).ToList();
                    if (!products.Any()) return model;
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where warehouseIds.Contains(pi.WarehouseId) &&
                                             productIds.Contains(pi.ProductId) &&
                                             pi.TotalQty > 0
                                       select new {
                                           pi.ProductId,
                                           pi.Product.CustomerId,
                                           TotalQty = pi.TotalQty,
                                           pi.WarehouseId,
                                           pi.Warehouse,
                                       }).ToList();
                    var production1 = (from sx1 in vfi.ImportFormSX1
                                       where sx1.ImportDate.Day == invDatetime.Day
                                             && sx1.ImportDate.Month == invDatetime.Month
                                             && sx1.ImportDate.Year == invDatetime.Year
                                             && sx1.ImportWorkpieceMaterials.Any()
                                             &&
                                             sx1.ImportWorkpieceMaterials.FirstOrDefault().Transaction.Status ==
                                             (byte)MyUtilities.Transaction.Status.Approved
                                       select sx1);
                    var production1Date = invDatetime;
                    if (production1.Any())
                        production1Date = production1.FirstOrDefault().MaterialUseDate;
                    var cncExports = (from pip in vfi.ProductInventoryPeriods
                                      where
                                            pip.Warehouse.IsCncMilling == true &&
                                            pip.LastPeriodQuantity < pip.EarlyPeriodQuantity &&
                                            pip.Transaction.WarehouseReceiptId != null &&
                                            pip.Transaction.Warehouse1.IsDefect == false &&
                                            pip.Transaction.Warehouse1.IsReprocessing == false &&
                                            pip.Transaction.Warehouse1.IsDestroy == false &&
                                            pip.PeriodDate == production1Date
                                      select new {
                                          pip.ProductId,
                                          pip.EarlyPeriodQuantity,
                                          pip.LastPeriodQuantity
                                      }).ToList();
                    var production2Exports = (from pip in vfi.ProductInventoryPeriods
                                              where
                                                  pip.Warehouse.IsProduction2 == true &&
                                                  pip.LastPeriodQuantity < pip.EarlyPeriodQuantity &&
                                                  pip.Transaction.WarehouseReceiptId != null &&
                                                  pip.Transaction.Warehouse1.IsDefect == false &&
                                                  pip.Transaction.Warehouse1.IsReprocessing == false &&
                                                  pip.Transaction.Warehouse1.IsDestroy == false &&
                                                  pip.PeriodDate == invDatetime
                                              select new {
                                                  pip.ProductId,
                                                  pip.EarlyPeriodQuantity,
                                                  pip.LastPeriodQuantity
                                              }).ToList();
                    var requirementOrderDetails = (from od in vfi.OrderDetails
                                                   where
                                                       od.Order.DueDate != null &&
                                                       od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                                       od.Order.DueDate < toDatetime &&
                                                       (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                        od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                       productIds.Contains(od.ProductId) &&
                                                       od.RequiedNumber != 0
                                                   select new {
                                                       od.OrderDetailId,
                                                       od.ProductId,
                                                       od.RequiedNumber,
                                                       DueDate = od.Order.DueDate.Value,
                                                   }).ToList();
                    var orderDetailsInMonth = (from od in vfi.OrderDetails
                                               where
                                                   od.Order.DueDate != null &&
                                                   od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                                   od.Order.DueDate.Value.Month == month &&
                                                   od.Order.DueDate.Value.Year == year &&
                                                   (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                    od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                   productIds.Contains(od.ProductId) &&
                                                   od.RequiedNumber != 0
                                               select new {
                                                   od.OrderDetailId,
                                                   od.ProductId,
                                                   od.RequiedNumber,
                                                   DueDate = od.Order.DueDate.Value,
                                               }).ToList();
                    //var productionMaterials = from pm in vfi.ProductionMaterials
                    //                          where productIds.Contains(pm.ProductId)
                    //                          select pm;
                    //var materialIds = productionMaterials.Select(pm => pm.MaterialId);
                    //var forecastOrders = (from fo in vfi.ForecastOrders
                    //                      orderby fo.ForecastDate
                    //                      where productIds.Contains(fo.ProductId) &&
                    //                            fo.ForecastDate.Month == month &&
                    //                            fo.ForecastDate.Year == year &&
                    //                            fo.Status == (byte)MyUtilities.Transaction.Status.Approved
                    //                      select new {
                    //                          fo.ForecastOrderId,
                    //                          fo.ProductId,
                    //                          fo.ForecastDate,
                    //                          fo.Quantity,
                    //                      }).ToList();
                    //var forecastOrderNextMonths = (from fo in vfi.ForecastOrders
                    //                               where productIds.Contains(fo.ProductId) &&
                    //                                     fo.ForecastDate.Month == nextMonth.Month &&
                    //                                     fo.ForecastDate.Year == nextMonth.Year &&
                    //                                     fo.Status == (byte)MyUtilities.Transaction.Status.Approved
                    //                               select new {
                    //                                   fo.ForecastOrderId,
                    //                                   fo.ProductId,
                    //                                   fo.ForecastDate,
                    //                                   fo.Quantity,
                    //                               }).ToList();
                    var smartProductions = from sp in vfi.SmartProductions
                                           where productIds.Contains(sp.ProductId.Value)
                                           select new { sp.ProductId };
                    var lastProductions = (from sx in vfi.ImportFormSX1Detail
                                           where productIds.Contains(sx.ProductId) &&
                                               sx.ImportFormSX1.ImportDate <= endDate &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                 .Transaction.Status ==
                                               (byte)MyUtilities.Transaction.Status.Approved
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                           orderby sx.ImportFormSX1.MaterialUseDate
                                           select new {
                                               sx.ProductId,
                                               sx.ImportFormSX1.MaterialUseDate,
                                               Quantity = (sx.Number1 + sx.Number2),
                                               sx.MachineId,
                                               sx.Machine1.MachineName
                                           }).ToList();
                    var productSections = (from ps in vfi.ProductionSections
                                           where productIds.Contains(ps.ProductId)
                                                 && ps.Active &&
                                                 ps.Productivity > 0
                                           select new {
                                               ps.ProductId,
                                               ps.Productivity,
                                           }).ToList();
                    var productPlatings = (from pp in vfi.ProductionPlatings
                                           where productIds.Contains(pp.ProductId) && pp.Active
                                           select new {
                                               pp.ProductId,
                                               pp.PlatingDay,
                                           }).ToList();
                    // xuat kho trong thang duoc giao boi don hang trong thang
                    var invoiceDetails = (from id in vfi.InvoiceDetails
                                          where id.Active &&
                                                id.Invoice.ShipmentDate > reportDate &&
                                                id.Invoice.ShipmentDate < endDate &&
                                                id.OrderDetail.Order.DueDate > reportDate &&
                                                id.OrderDetail.Order.DueDate < endDate &&
                                              productIds.Contains(id.ProductId.Value)
                                          select new {
                                              id.ProductId,
                                              id.Piece,
                                          }).ToList();
                    var i = 1;
                    var customerIds = products.Select(p => p.CustomerId).Distinct().ToList();
                    var customers = (from c in vfi.Customers
                                     where c.State == (byte)MyUtilities.Sales.CustomerState.Active &&
                                           (customerId == 0 || c.CustomerId == customerId) &&
                                           customerIds.Contains(c.CustomerId)
                                     orderby c.Area.AreaName, c.CustomerCode
                                     select new {
                                         c.CustomerId
                                     }).ToList();
                    foreach (var customer in customers) {
                        var productsByCustomer =
                            products.Where(p => p.CustomerId == customer.CustomerId).OrderBy(p => p.ProductCode);
                        foreach (var product in productsByCustomer) {
                            //if (!product.ProductCode.Equals("H2739"))
                            //    continue;
                            var entity = new ProductState {
                                Index = i,
                                ProductId = product.ProductId,
                                ProductCode = product.ProductCode,
                                CustomerCode = product.CustomerCode,
                                MaterialCode = product.MaterialNameDesign,
                                MaterialName = product.MaterialNameDesign,
                                Productivity = product.Productivity,
                                CncProductivity = product.CncProductivity,
                                FinishInv = 0,
                                TotalInv = 0,
                                MaterialInv = 0,
                                ProcessingInv = 0,
                                ProductionForecasts = product.ForecastsQuality,
                                RequirementInventory = 0,
                                RequirementOrder = 0,
                                ReportDate = reportDate,
                                InMonthDateString = reportDate.ToString("MM/yyyy"),
                                NextMonthDateString = nextMonth.ToString("MM/yyyy"),
                                ProductionStatus = 0,
                                ProductionForecastsStatus = 0,
                                RequirementInvStatus = 0,
                                RequirementOrderStatus = 0,
                                MaterialStatus = 0,
                                RequirementOrderInMonth = 0,
                                RequirementOrderNextMonth = 0,
                                OrderStatus = 3,
                                Details = new List<OrderProgressDetailModel>(),
                                Productions = new List<OrderProgressProduction>(),
                            };
                            // xuat kho trong thang bang don dat hang trong thang
                            var exportById = invoiceDetails.Where(id => id.ProductId == product.ProductId);
                            if (exportById.Any())
                                entity.ExportInMonth = exportById.Sum(id => id.Piece);
                            var exportInMonth = entity.ExportInMonth;
                            // don hang con no
                            var requirementOrderInMonth =
                                requirementOrderDetails.Where(
                                    od => od.ProductId == product.ProductId)
                                                       .OrderBy(od => od.DueDate)
                                                       .ToList();
                            if (requirementOrderInMonth.Any()) {
                                var detail = new OrderProgressDetailModel {
                                    ModifiedUser = "ĐH"
                                };
                                entity.Details.Add(detail);
                                foreach (var orderDetail in requirementOrderInMonth) {
                                    var late = new LateOrder() {
                                        OrderDueDate = orderDetail.DueDate,
                                        OrderQuantity = orderDetail.RequiedNumber,
                                        OrderDueDateString = orderDetail.DueDate.ToString("dd/MM"),
                                        OrderDetailId = orderDetail.OrderDetailId,
                                    };
                                    detail.LateOrders.Add(late);
                                }
                                detail.OrderQuantity = detail.LateOrders.Sum(lo => lo.OrderQuantity);
                                detail.OrderDueDate = detail.LateOrders.FirstOrDefault().OrderDueDate;
                                detail.OrderDueDateString = detail.OrderDueDate.ToString("dd/MM");
                                if (detail.OrderDueDate < DateTime.Now)
                                    entity.OrderStatus = 1;
                            }
                            // du bao trong thang
                            //var forecastsById = forecastOrders.Where(f => f.ProductId == product.ProductId);
                            //var totalForecast = 0.0;
                            //if (forecastsById.Any()) {
                            //    totalForecast = forecastsById.Sum(od => od.Quantity);
                            //    foreach (var forecast in forecastsById) {
                            //        if (exportInMonth > forecast.Quantity) {
                            //            exportInMonth -= forecast.Quantity;
                            //            if (exportInMonth < 0)
                            //                exportInMonth = 0;
                            //            continue;
                            //        }
                            //        var detail = new OrderProgressDetailModel {
                            //            OrderDueDate = forecast.ForecastDate,
                            //            OrderQuantity = forecast.Quantity - exportInMonth,
                            //            OrderDueDateString = forecast.ForecastDate.ToString("dd/MM"),
                            //            OrderDetailId = forecast.ForecastOrderId,
                            //            ModifiedUser = "DB"
                            //        };
                            //        entity.Details.Add(detail);
                            //        var late = new LateOrder() {
                            //            OrderDueDate = forecast.ForecastDate,
                            //            OrderQuantity = forecast.Quantity - exportInMonth,
                            //            OrderDueDateString = forecast.ForecastDate.ToString("dd/MM"),
                            //            OrderDetailId = forecast.ForecastOrderId,
                            //        };
                            //        exportInMonth = 0;
                            //        detail.LateOrders.Add(late);
                            //        if (detail.OrderDueDate < DateTime.Now)
                            //            entity.OrderStatus = 1;
                            //    }
                            //}
                            //else {
                            //    // k co du bao trong thang se lay don hang
                            //    //entity.Details.AddRange();
                            //}
                            //forecastsById = forecastOrderNextMonths.Where(f => f.ProductId == product.ProductId);
                            //if (forecastsById.Any()) {
                            //    entity.RequirementOrderNextMonth = forecastsById.Sum(f => f.Quantity);
                            //}

                            requirementOrderInMonth =
                                    orderDetailsInMonth.Where(
                                        od => od.ProductId == product.ProductId)
                                                       .OrderBy(od => od.DueDate)
                                                       .ToList();
                            if (requirementOrderInMonth.Any()) {
                                var detail = new OrderProgressDetailModel {
                                    ModifiedUser = "ĐH"
                                };
                                entity.DetailInMonths.Add(detail);
                                //var status = requirementOrderInMonth.Sum(od => od.RequiedNumber) > totalForecast ? 1 : 0;

                                foreach (var orderDetail in requirementOrderInMonth) {
                                    var late = new LateOrder() {
                                        OrderDueDate = orderDetail.DueDate,
                                        OrderQuantity = orderDetail.RequiedNumber,
                                        OrderDueDateString = orderDetail.DueDate.ToString("dd/MM"),
                                        OrderDetailId = orderDetail.OrderDetailId,
                                        Status = 0
                                    };
                                    detail.LateOrders.Add(late);
                                }
                                detail.OrderQuantity = detail.LateOrders.Sum(lo => lo.OrderQuantity);
                                detail.OrderDueDate = detail.LateOrders.FirstOrDefault().OrderDueDate;
                                detail.OrderDueDateString = detail.OrderDueDate.ToString("dd/MM");
                                if (detail.OrderDueDate < DateTime.Now)
                                    entity.OrderStatus = 1;
                            }
                            // neu ko co chi tiet
                            //if (!entity.Details.Any() && !entity.DetailInMonths.Any())
                            //{
                            //    //if (entity.RequirementOrderNextMonth > 0)
                            //    //{
                            //    //    var detail = new OrderProgressDetailModel
                            //    //    {
                            //    //        OrderQuantity = 0,
                            //    //        OrderDueDateString = ""
                            //    //    };
                            //    //    entity.Details.Add(detail);
                            //    //}
                            //    //else
                            //    continue;
                            //}
                            if (entity.Details.Any())
                                entity.FirstOrderDate = entity.Details.FirstOrDefault().OrderDueDate;
                            else if (entity.DetailInMonths.Any())
                                entity.FirstOrderDate = entity.DetailInMonths.FirstOrDefault().OrderDueDate;
                            else continue;
                            entity.RequirementOrderInMonth = entity.Details.Sum(d => d.OrderQuantity);
                            // don hang thang sau
                            //var requirementOrderNextMonth =
                            //    requirementOrderDetails.Where(
                            //        od =>
                            //        od.ProductId == product.ProductId &&
                            //        od.DueDate.Month == nextMonth.Month &&
                            //        od.DueDate.Year == nextMonth.Year).ToList();
                            //if (requirementOrderNextMonth.Any())
                            //{
                            //    entity.RequirementOrderNextMonth = requirementOrderNextMonth.Sum(od => od.RequiedNumber);
                            //}
                            entity.RequirementInventory = entity.RequirementOrderInMonth;
                            // lay du lieu ton kho
                            var productInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId).ToList();
                            if (productInvsById.Any()) {
                                entity.TotalInv = productInvsById.Sum(od => od.TotalQty);
                                var invs = productInvsById.Where(pi => pi.Warehouse.IsFinish).ToList();
                                if (invs != null) {
                                    entity.FinishInv = invs.Sum(pi => pi.TotalQty);
                                    entity.FinishProgress.Inv = entity.FinishInv;
                                }
                                //
                                invs = productInvsById.Where(pi => pi.Warehouse.IsQC).ToList();
                                if (invs.Any()) {
                                    entity.QcInv = invs.Sum(pi => pi.TotalQty);
                                    entity.QcProgress.Inv = entity.QcInv;
                                }
                                //
                                invs =
                                   productInvsById.Where(
                                       pi =>
                                       pi.WarehouseId == MyUtilities.Warehouse.Plating ||
                                       pi.WarehouseId == MyUtilities.Warehouse.PlatingTest).ToList();
                                if (invs.Any()) {
                                    entity.PlatingInv = invs.Sum(pi => pi.TotalQty);
                                    entity.PlatingProgress.Inv = entity.PlatingInv;
                                }
                                //
                                invs =
                                   productInvsById.Where(
                                       pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating).ToList();
                                if (invs != null) {
                                    entity.WaitingPlatingInv = invs.Sum(pi => pi.TotalQty);
                                    entity.WaitingPlatingProgress.Inv = entity.WaitingPlatingInv;
                                }
                                //
                                invs =  productInvsById.Where(  pi => pi.Warehouse.IsPolish).ToList();
                                if (invs != null) {
                                    entity.SurfaceInv = invs.Sum(pi => pi.TotalQty);
                                    entity.SurfaceProgress.Inv = entity.SurfaceInv;
                                }
                                //
                                invs =
                                    productInvsById.Where(
                                        pi => pi.Warehouse.IsHeatTreatment).ToList();
                                if (invs != null) {
                                    entity.HeatInv = invs.Sum(pi => pi.TotalQty);
                                    entity.HeatProgress.Inv = entity.HeatInv;
                                }
                                //
                                invs = productInvsById.Where(pi => pi.Warehouse.IsProduction2).ToList();
                                if (invs.Any()) {
                                    entity.Production2Inv = invs.Sum(pi => pi.TotalQty);
                                    entity.Production2Progress.Inv = entity.Production2Inv;
                                    var exportInDay = production2Exports.Where(pip => pip.ProductId == entity.ProductId);
                                    if (exportInDay.Any())
                                        entity.Production2Progress.Export =
                                            exportInDay.Sum(pip => pip.EarlyPeriodQuantity - pip.LastPeriodQuantity);
                                }
                                //
                                invs = productInvsById.Where(pi => pi.WarehouseId == MyUtilities.Warehouse.Cnc).ToList();
                                if (invs != null) {
                                    entity.CncInv = invs.Sum(pi => pi.TotalQty);
                                    entity.CncProgress.Inv = entity.CncInv;
                                    var exportInDay = cncExports.Where(pip => pip.ProductId == entity.ProductId);
                                    if (exportInDay.Any())
                                        entity.CncProgress.Export =
                                            exportInDay.Sum(pip => pip.EarlyPeriodQuantity - pip.LastPeriodQuantity);
                                }
                                invs = productInvsById.Where(pi => pi.Warehouse.IsReprocessing).ToList();
                                if (invs.Any()) {
                                    entity.ProcessingInv = invs.Sum(pi => pi.TotalQty);
                                }
                                // yeu cau san xuat - ko tinh hang cxl
                                entity.ProductionRequirement = entity.RequirementInventory - entity.AfterProductionInv;
                                if (entity.ProductionRequirement < 0) entity.ProductionRequirement = 0;
                            }
                            // neu co yeu cau san xuat se lay du lieu san xuat
                            if (entity.ProductionRequirement > 0) {
                                var startProduct =
                                    lastProductions.Where(id => id.ProductId == entity.ProductId).ToList();
                                if (startProduct.Any()) {
                                    entity.ProductionLast =
                                        startProduct.LastOrDefault().MaterialUseDate;
                                    //entity.MachineRun =
                                    //    Math.Round((entity.ProductionRequirement / entity.ProductivityInDay) / 25, 1);
                                    //if (entity.MachineRun == 0.0)
                                    //    entity.MachineRun = 0.1;
                                    //if (product.Productivity == 0)
                                    //    entity.ProductionLastDate = "E";
                                    //else
                                    //    entity.ProductionLastDate = string.Format("{0:N1}", entity.MachineRun);
                                    if (entity.ProductionLast < new DateTime(year, month, 5).AddDays(-7)) {
                                        entity.ProductionStatus = 1;
                                    }
                                    var groupSx = (from sx in startProduct
                                                   //where sx.MachineId == 55
                                                   group sx by new { sx.MachineId, sx.MaterialUseDate, sx.MachineName }
                                                       into sxsx1
                                                       select new {
                                                           sxsx1.Key.MachineId,
                                                           sxsx1.Key.MachineName,
                                                           sxsx1.Key.MaterialUseDate,
                                                           Quantity = sxsx1.Sum(sx => sx.Quantity),
                                                       }).ToList();
                                    var machines = groupSx.Select(sx => sx.MachineId).Distinct();
                                    var lastProductById =
                                        lastProductions.LastOrDefault(id => id.ProductId == entity.ProductId);
                                    var count = 0;
                                    foreach (var machine in machines) {
                                        var startDiffProduct =
                                            lastProductions.LastOrDefault(
                                                id =>
                                                id.ProductId != entity.ProductId &&
                                                id.MaterialUseDate < lastProductById.MaterialUseDate &&
                                                id.MachineId == machine);
                                        var groupDetail = groupSx.Where(sx => sx.MachineId == machine).ToList();
                                        if (startDiffProduct != null)
                                            groupDetail =
                                                groupDetail.Where(
                                                    sx => sx.MaterialUseDate >= startDiffProduct.MaterialUseDate).ToList();
                                        var newestDetail =
                                            groupDetail.LastOrDefault(
                                                id => id.MaterialUseDate == lastProductById.MaterialUseDate);
                                        if (groupDetail.Any()) {
                                            entity.Average += (groupDetail.Sum(sx => sx.Quantity) / groupDetail.Count());
                                            count++;
                                            var production = new OrderProgressProduction {
                                                MachineName = groupDetail.FirstOrDefault().MachineName,
                                                AverageByMachine =
                                                    (groupDetail.Sum(sx => sx.Quantity) / groupDetail.Count()),
                                                StartDateString =
                                                    groupDetail.FirstOrDefault()
                                                               .MaterialUseDate.ToString("dd/MM"),
                                                LastDateString =
                                                    groupDetail.LastOrDefault()
                                                               .MaterialUseDate.ToString("dd/MM"),
                                                LastQuantity = 0
                                            };
                                            if (newestDetail != null) {
                                                production.LastQuantity = newestDetail.Quantity;
                                            }
                                            var realProduction =
                                 vfi.RealProductions.FirstOrDefault(
                                     rp => rp.ProductId == entity.ProductId && rp.MachineId == machine);
                                            if (realProduction != null) {
                                                production.ProductivityInDay = 72000 /
                                                                               (realProduction.TrackUpMachine
                                                                                              .RealProductivity);
                                            }
                                            entity.Productions.Add(production);
                                        }
                                    }
                                    entity.Average = entity.Average / count;
                                }
                            }
                            if (!entity.Productions.Any()) {
                                var production = new OrderProgressProduction {
                                    MachineName = "",
                                    AverageByMachine = 0,
                                    StartDateString = "",
                                    LastDateString = "",
                                    LastQuantity = 0,
                                    ProductivityInDay = 0,
                                };
                                entity.Productions.Add(production);
                            }
                            // kiem tra xem co dang tren may hay k
                            var smartProduction = smartProductions.FirstOrDefault(sp => sp.ProductId == entity.ProductId);
                            if (smartProduction != null) {
                                entity.ProductionDateStatus = 1;
                            }
                            // lay du lieu
                            var productionProcesses = product.ProductionProcesses.FirstOrDefault(
                                pp =>
                                (pp.WarehouseId == MyUtilities.Warehouse.WaitingPlating ||
                                pp.WarehouseId == MyUtilities.Warehouse.Plating) && pp.IsNecessary);
                            if (productionProcesses == null) {
                                if (entity.PlatingInv > 0) {
                                    entity.PlatingPendingDay = 7;
                                    entity.WaitingPlatingPendingDay = 1;
                                }
                            }
                            else {
                                var productPlatingById =
                                    productPlatings.Where(pp => pp.ProductId == entity.ProductId).ToList();
                                if (productPlatingById.Any()) {
                                    entity.PlatingPendingDay = productPlatingById.Sum(pp => pp.PlatingDay);
                                }
                                else {
                                    entity.PlatingPendingDay = 7;
                                }
                                entity.WaitingPlatingPendingDay = 1;
                            }
                            productionProcesses = product.ProductionProcesses.FirstOrDefault(
                                pp =>
                                pp.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment && pp.IsNecessary);
                            if (productionProcesses != null || entity.SurfaceInv > 0) {
                                entity.SurfacePendingDay = 1;
                            }
                            productionProcesses = product.ProductionProcesses.FirstOrDefault(
                                pp =>
                                pp.WarehouseId == MyUtilities.Warehouse.HeatTreatment && pp.IsNecessary);
                            if (productionProcesses != null || entity.HeatInv > 0) {
                                entity.HeatPendingDay = 1;
                            }
                            productionProcesses = product.ProductionProcesses.FirstOrDefault(
                                pp =>
                                pp.WarehouseId == MyUtilities.Warehouse.Production2 && pp.IsNecessary);
                            if (productionProcesses == null) {
                                if (entity.Production2Inv > 0) {
                                    entity.Production2PendingDay = 1;
                                }
                            }
                            else {
                                var productSecionById =
                                    productSections.Where(ps => ps.ProductId == entity.ProductId).ToList();
                                if (productSecionById.Any()) {
                                    entity.Production2PendingDay = productSecionById.Count();
                                    entity.SmallestProduction2Productivity =
                                        productSecionById.OrderByDescending(ps => ps.Productivity)
                                                         .FirstOrDefault().Productivity;
                                }
                                else {
                                    entity.Production2PendingDay = 1;
                                }
                            }

                            productionProcesses = product.ProductionProcesses.FirstOrDefault(
                                pp =>
                                pp.WarehouseId == MyUtilities.Warehouse.Cnc && pp.IsNecessary);
                            if (productionProcesses == null) {
                                if (entity.CncInv > 0) {
                                    entity.CncPendingDay = 1;
                                }
                            }
                            else entity.CncPendingDay = 1;

                            if (entity.FinishProgress.Requirement < 0) goto part2;
                            //qc
                            entity.QcProgress.Requirement = entity.RequirementInventory - entity.AfterQcInv;
                            if (entity.QcProgress.Requirement < 0) {
                                entity.QcProgress.Requirement = 0;
                                goto part2;
                            }
                            // nha cung ung
                            else if (entity.PlatingPendingDay > 0)
                                entity.PlatingProgress.Requirement = entity.RequirementInventory - entity.AfterPlatingInv;
                            if (entity.PlatingProgress.Requirement < 0) {
                                entity.PlatingProgress.Requirement = 0;
                                goto part2;
                            }
                            // cho gia cong ngoai
                            else if (entity.WaitingPlatingPendingDay > 0)
                                entity.WaitingPlatingProgress.Requirement = entity.RequirementInventory -
                                                                            entity.AfterWaitingPlatingInv;
                            if (entity.WaitingPlatingProgress.Requirement < 0) {
                                entity.WaitingPlatingProgress.Requirement = 0;
                                goto part2;
                            }
                            // rung bong
                            else if (entity.SurfacePendingDay > 0)
                                entity.SurfaceProgress.Requirement = entity.RequirementInventory - entity.AfterSurfaceInv;
                            if (entity.SurfaceProgress.Requirement < 0) {
                                entity.SurfaceProgress.Requirement = 0;
                                goto part2;
                            }
                            // nhiet luyen
                            else if (entity.HeatPendingDay > 0)
                                entity.HeatProgress.Requirement = entity.RequirementInventory - entity.AfterHeatInv;
                            if (entity.HeatProgress.Requirement < 0) {
                                entity.HeatProgress.Requirement = 0;
                                goto part2;
                            }
                            // sx2
                            if (entity.Production2PendingDay > 0)
                                entity.Production2Progress.Requirement = entity.RequirementInventory - entity.AfterProduction2Inv;
                            if (entity.Production2Progress.Requirement < 0) {
                                entity.Production2Progress.Requirement = 0;
                                goto part2;
                            }
                            //cnc
                            if (entity.CncPendingDay > 0)
                                entity.CncProgress.Requirement = entity.RequirementInventory - entity.AfterCncInv;
                            if (entity.CncProgress.Requirement < 0) entity.CncProgress.Requirement = 0;

                        part2:
                            if (!isAllOrder && entity.QcProgress.Requirement == 0)
                                continue;
                            var orderQuantity = 0.0;
                            if (entity.OrderStatus == 3) {
                                if (entity.Details.Sum(od => od.OrderQuantity) > entity.FinishInv)
                                    entity.OrderStatus = 2;
                            }
                            var startProductionDate = DateTime.Now;
                            foreach (var detail in entity.Details) {
                                orderQuantity = detail.OrderQuantity;
                                detail.WaitingPlatingPendingDay = entity.WaitingPlatingPendingDay;
                                detail.SurfacePendingDay = entity.SurfacePendingDay;
                                detail.HeatPendingDay = entity.HeatPendingDay;
                                //qc
                                if (orderQuantity > entity.FinishProgress.Inv) {
                                    detail.QcProgress.Requirement = orderQuantity - entity.FinishProgress.Inv;
                                    entity.FinishProgress.Inv = 0;
                                    orderQuantity = detail.QcProgress.Requirement;
                                }
                                else {
                                    entity.FinishProgress.Inv -= orderQuantity;
                                    goto date;
                                }

                                //plating - waitingplating
                                detail.PlatingPendingDay = entity.PlatingPendingDay;
                                detail.WaitingPlatingPendingDay = entity.WaitingPlatingPendingDay;
                                if (orderQuantity > entity.QcProgress.Inv) {
                                    detail.PlatingProgress.Requirement = orderQuantity -
                                                                         entity.QcProgress.Inv;
                                    entity.QcProgress.Inv = 0;
                                    orderQuantity = detail.PlatingProgress.Requirement;
                                }
                                else {
                                    entity.QcProgress.Inv -= orderQuantity;
                                    goto date;
                                }
                                if (orderQuantity > entity.PlatingProgress.Inv) {
                                    detail.WaitingPlatingProgress.Requirement = orderQuantity -
                                                                                entity.PlatingProgress.Inv;
                                    entity.PlatingProgress.Inv = 0;
                                    orderQuantity = detail.WaitingPlatingProgress.Requirement;
                                }
                                else {
                                    entity.PlatingProgress.Inv -= orderQuantity;
                                    goto date;
                                }
                                if (entity.PlatingPendingDay == 0) {
                                    detail.PlatingProgress.Requirement = 0;
                                    detail.WaitingPlatingProgress.Requirement = 0;
                                }
                                //surface
                                if (orderQuantity > entity.WaitingPlatingProgress.Inv) {
                                    detail.SurfaceProgress.Requirement = orderQuantity -
                                                                         entity.WaitingPlatingProgress.Inv;
                                    entity.WaitingPlatingProgress.Inv = 0;
                                    orderQuantity = detail.SurfaceProgress.Requirement;
                                }
                                else {
                                    entity.WaitingPlatingProgress.Inv -= orderQuantity;
                                    goto date;
                                }
                                if (entity.SurfacePendingDay == 0) {
                                    detail.SurfaceProgress.Requirement = 0;
                                }
                                //heat
                                if (orderQuantity > entity.SurfaceProgress.Inv) {
                                    detail.HeatProgress.Requirement = orderQuantity - entity.SurfaceProgress.Inv;
                                    entity.SurfaceProgress.Inv = 0;
                                    orderQuantity = detail.HeatProgress.Requirement;
                                }
                                else {
                                    entity.SurfaceProgress.Inv -= orderQuantity;
                                    goto date;
                                }
                                if (entity.HeatPendingDay == 0) {
                                    detail.HeatProgress.Requirement = 0;
                                }
                                //production2
                                detail.SmallestProduction2Productivity = entity.SmallestProduction2Productivity;
                                if (orderQuantity > entity.HeatProgress.Inv) {
                                    detail.Production2Progress.Requirement = orderQuantity -
                                                                             entity.HeatProgress.Inv;
                                    entity.HeatProgress.Inv = 0;
                                    orderQuantity = detail.Production2Progress.Requirement;
                                }
                                else {
                                    entity.HeatProgress.Inv -= orderQuantity;
                                    goto date;
                                }
                                if (entity.Production2PendingDay == 0) {
                                    detail.Production2Progress.Requirement = 0;
                                }
                                //cnc
                                detail.CncProductivity = entity.CncProductivity;
                                if (orderQuantity > entity.Production2Progress.Inv) {
                                    detail.CncProgress.Requirement = orderQuantity - entity.Production2Progress.Inv;
                                    entity.Production2Progress.Inv = 0;
                                    orderQuantity = detail.CncProgress.Requirement;
                                }
                                else {
                                    entity.Production2Progress.Inv -= orderQuantity;
                                    goto date;
                                }
                                if (entity.CncPendingDay == 0) {
                                    detail.CncProgress.Requirement = 0;
                                }
                                //production
                                if (orderQuantity > entity.CncProgress.Inv) {
                                    detail.Productivity = entity.Productivity;
                                    detail.ProductionProgress.Requirement = orderQuantity - entity.CncProgress.Inv;
                                    entity.CncProgress.Inv = 0;
                                }
                                else {
                                    entity.CncProgress.Inv -= orderQuantity;
                                    goto date;
                                }
                            date:
                                var orderProgress =
                                    vfi.OrderProgresses.FirstOrDefault(op => op.OrderDetailId == detail.OrderDetailId);
                                if (orderProgress != null) {
                                    detail.StartDateString = orderProgress.StartDate.ToString("dd/MM");
                                    detail.MachineRun = orderProgress.ExpectedFactor;
                                }
                                detail.Production2PendingDay2 = detail.Production2PendingDay;
                                if (detail.ProductionPendingDay / 2 > detail.Production2PendingDay2) {
                                    detail.Production2PendingDay2 = 1;
                                }
                                var date =
                                    detail.OrderDueDate.AddDays((detail.AfterProductionPendingDay +
                                                                 detail.ProductionPendingDay) * -1);
                                if (date > DateTime.Now) {
                                    if (detail.ProductionProgress.Requirement > 0)
                                        detail.ProductionProgress.AddDate(detail.AfterProductionPendingDay * -1,
                                                                          detail.OrderDueDate);
                                    if (detail.CncProgress.Requirement > 0)
                                        detail.CncProgress.AddDate(detail.AfterCncPendingDay * -1, detail.OrderDueDate);
                                    if (detail.Production2Progress.Requirement > 0)
                                        detail.Production2Progress.AddDate(detail.AfterProduction2PendingDay * -1,
                                                                           detail.OrderDueDate);
                                    if (detail.HeatProgress.Requirement > 0)
                                        detail.HeatProgress.AddDate(detail.AfterHeatPendingDay * -1, detail.OrderDueDate);
                                    if (detail.SurfaceProgress.Requirement > 0)
                                        detail.SurfaceProgress.AddDate(detail.AfterSurfacePendingDay * -1,
                                                                       detail.OrderDueDate);
                                    if (detail.WaitingPlatingProgress.Requirement > 0)
                                        detail.WaitingPlatingProgress.AddDate(detail.AfterWaitingPlatingPendingDay * -1,
                                                                              detail.OrderDueDate);
                                    if (detail.PlatingProgress.Requirement > 0)
                                        detail.PlatingProgress.AddDate(detail.AfterPlatingPendingDay * -1,
                                                                       detail.OrderDueDate);
                                    if (detail.QcProgress.Requirement > 0)
                                        detail.QcProgress.AddDate(detail.AfterQcPendingDay * -1, detail.OrderDueDate);
                                    detail.CompleteDate = detail.OrderDueDate;
                                }
                                else {
                                    if (detail.ProductionProgress.Requirement > 0)
                                        detail.ProductionProgress.AddDate(detail.ProductionPendingDay, startProductionDate);
                                    if (detail.CncProgress.Requirement > 0)
                                        detail.CncProgress.AddDate(detail.BeforeCncPendingDay, startProductionDate);
                                    if (detail.Production2Progress.Requirement > 0)
                                        detail.Production2Progress.AddDate(detail.BeforeProduction2PendingDay,
                                                                           startProductionDate);
                                    if (detail.HeatProgress.Requirement > 0)
                                        detail.HeatProgress.AddDate(detail.BeforeHeatPendingDay, startProductionDate);
                                    if (detail.SurfaceProgress.Requirement > 0)
                                        detail.SurfaceProgress.AddDate(detail.BeforeSurfacePendingDay, startProductionDate);
                                    if (detail.WaitingPlatingProgress.Requirement > 0)
                                        detail.WaitingPlatingProgress.AddDate(detail.BeforeWaitingPlatingPendingDay,
                                                                            startProductionDate);
                                    if (detail.PlatingProgress.Requirement > 0)
                                        detail.PlatingProgress.AddDate(detail.BeforePlatingPendingDay, startProductionDate);
                                    if (detail.QcProgress.Requirement > 0)
                                        detail.QcProgress.AddDate(detail.BeforeQcPendingDay, startProductionDate);
                                    detail.CompleteDate = detail.QcProgress.Date == null
                                                              ? DateTime.Now
                                                              : detail.QcProgress.Date.Value.AddDays(
                                                                  detail.FinishPendingDay);
                                    if (detail.ProductionProgress.Requirement > 0)
                                        startProductionDate = detail.ProductionProgress.Date.Value;
                                }
                            }
                            i++;
                            if (entity.QcProgress.Requirement <= 0)
                                entity.OrderStatus = 3;
                            model.Add(entity);
                            if (model.Count == 26)
                                entity.OrderStatus = entity.OrderStatus;
                        }
                    }
                }
            }
            catch (Exception ex) {
                throw ex;
            }
            return model;
        }
