        public ActionResult PrintOrderProgressProduction(int month, int year) {
            var model = new List<ProductState>();
            var reportDate = new DateTime(year, month, 1);
            var endDate = reportDate.AddMonths(1).AddSeconds(-1);
            var nextMonth = reportDate.AddMonths(1);
            //var forecastDate = reportDate.AddMonths(3); // tang forecast len 3 thang
            try {
                using (var vfi = new tammaContext()) {
                    var products = (from p in vfi.Products
                                    where p.Active
                                    //&& p.ProductCode.Equals("S1")
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        p.Customer.CustomerCode,
                                        ProductionFactor = p.ProductionFactor ?? 1,
                                        IsSelling = p.IsSelling ?? false,
                                        SaleFactor = p.SaleFactor ?? 1,
                                        NewUpdateDate = p.NewUpdateDate ?? DateTime.Now,
                                        Productivity = p.Productivity ?? 0,
                                        //p.FinishProcessingDate,
                                        ForecastsQuality = p.ForecastsQuality ?? 0,
                                        p.MaterialNameDesign,
                                        p.DiffRequestInv,
                                        p.ProductionMaterials,
                                        ProductionProcesses = p.ProductionProcesses.OrderByDescending(pp => pp.ProcessIndex)
                                    }).ToList();
                    if (!products.Any())
                        return PartialView("PageOrderProgressInMonth", null);
                    var productIds = products.Select(p => p.ProductId).ToList();
                    var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvs = (from pi in vfi.ProductInventories
                                       where warehouseIds.Contains(pi.WarehouseId) &&
                                             productIds.Contains(pi.ProductId)
                                       select new {
                                           pi.ProductId,
                                           pi.Product.CustomerId,
                                           TotalQty = pi.TotalQty,
                                           pi.WarehouseId,
                                       }).ToList();
                    var requirementOrderDetails = (from od in vfi.OrderDetails
                                                   where
                                                       od.Order.DueDate != null &&
                                                       od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                                       (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                        od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                       productIds.Contains(od.ProductId) &&
                                                       od.RequiedNumber != 0
                                                   orderby od.Order.DueDate
                                                   select new {
                                                       od.ProductId,
                                                       //od.Order.CustomerId,
                                                       //OrderQty = od.OrderQty.Value,
                                                       RequiedNumber = od.RequiedNumber,
                                                       DueDate = od.Order.DueDate.Value,
                                                       //od.Order.Status
                                                   }).ToList();
                    var smartProductions = from sp in vfi.SmartProductions
                                           where productIds.Contains(sp.ProductId.Value)
                                           select new { sp.ProductId };
                    var lastProductions = (from sx in vfi.ImportFormSX1Detail
                                           where productIds.Contains(sx.ProductId) &&
                                               sx.ImportFormSX1.ImportDate <= endDate &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                               sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                 .Transaction.Status ==
                                               (byte)MyUtilities.Transaction.Status.Approved
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                           orderby sx.ImportFormSX1.MaterialUseDate
                                           select new {
                                               sx.ProductId,
                                               sx.ImportFormSX1.MaterialUseDate,
                                               Quantity = (sx.Number1 + sx.Number2),
                                               sx.MachineId,
                                               sx.Machine1.MachineName
                                           }).ToList();
                    var lastProduction = lastProductions.LastOrDefault();
                    var i = 1;
                    var customers = from c in vfi.Customers
                                    where c.State == (byte)MyUtilities.Sales.CustomerState.Active
                                    orderby c.Area.AreaName, c.CustomerCode
                                    select new {
                                        c.CustomerId
                                    };
                    foreach (var customer in customers) {
                        var productsByCustomer =
                            products.Where(p => p.CustomerId == customer.CustomerId).OrderBy(p => p.ProductCode);
                        foreach (var product in productsByCustomer) {
                            var entity = new ProductState {
                                Index = i,
                                ProductId = product.ProductId,
                                ProductCode = product.ProductCode,
                                CustomerCode = product.CustomerCode,
                                MaterialCode = product.MaterialNameDesign,
                                MaterialName = product.MaterialNameDesign,
                                //PlatingInv = 0,
                                //CncInv = 0,
                                FinishInv = 0,
                                //HeatTreatmentInv = 0,
                                //QcInv = 0,
                                //SurfaceTreatmentInv = 0,
                                TotalInv = 0,
                                //WaitingPlatingInv = 0,
                                MaterialInv = 0,
                                //Production2Inv = 0,
                                ProcessingInv = 0,
                                ProductionForecasts = product.ForecastsQuality,
                                RequirementInventory = 0,
                                RequirementOrder = 0,
                                ReportDate = reportDate,
                                InMonthDateString = reportDate.ToString("MM/yyyy"),
                                NextMonthDateString = nextMonth.ToString("MM/yyyy"),
                                ProductionStatus = 0,
                                //CncStatus = 0,
                                //HeatTreatmentStatus = 0,
                                //PlatingStatus = 0,
                                //Production2Status = 0,
                                ProductionForecastsStatus = 0,
                                //QcStatus = 0,
                                RequirementInvStatus = 0,
                                RequirementOrderStatus = 0,
                                //WaitingPlatingStatus = 0,
                                //SurfaceTreatmentStatus = 0,
                                MaterialStatus = 0,
                                RequirementOrderInMonth = 0,
                                RequirementOrderNextMonth = 0,
                                Details = new List<OrderProgressDetailModel>(),
                                //PendingDay = 5,
                                Productions = new List<OrderProgressProduction>(),
                                RealPerformance = 0,
                                AveragePerformance = 0
                            };
                            var requirementOrderInMonth =
                                requirementOrderDetails.Where(
                                    od => od.ProductId == product.ProductId && od.DueDate < endDate)
                                                       .OrderBy(od => od.DueDate)
                                                       .ToList();
                            if (!requirementOrderInMonth.Any()) continue; // khong co don hang
                            entity.RequirementOrderInMonth = requirementOrderInMonth.Sum(od => od.RequiedNumber);
                            var productInvsById = productInvs.Where(pi => pi.ProductId == product.ProductId).ToList();
                            if (productInvsById.Any()) {
                                entity.TotalInv = productInvsById.Sum(od => od.TotalQty);
                                if (entity.TotalInv > entity.RequirementOrderInMonth) continue; // tong ton du so luong
                                entity.ProductionRequirement = entity.RequirementOrderInMonth - entity.TotalInv;
                                if (entity.ProductionRequirement < 0) entity.ProductionRequirement = 0;
                                var inv = productInvsById.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                                if (inv != null)
                                    entity.FinishInv = inv.TotalQty;
                                var invs =
                                     productInvsById.Where(
                                         pi =>
                                         pi.WarehouseId == MyUtilities.Warehouse.Processing ||
                                         pi.WarehouseId == MyUtilities.Warehouse.Processing2).ToList();
                                if (invs.Any())
                                    entity.ProcessingInv = invs.Sum(pi => pi.TotalQty);
                            }
                            if (entity.ProductionRequirement > 0) {
                                var startProduct =
                                    lastProductions.Where(id => id.ProductId == entity.ProductId).ToList();
                                //if (product.Productivity > 0)
                                //    entity.ProductivityInDay = 72000 / product.Productivity;
                                if (startProduct.Any()) {
                                    entity.ProductionLast = startProduct.LastOrDefault().MaterialUseDate;
                                    //if (entity.MachineRun == 0.0)
                                    //    entity.MachineRun = 0.1;
                                    var groupSx = (from sx in startProduct
                                                   //where sx.MachineId == 55
                                                   group sx by new { sx.MachineId, sx.MaterialUseDate, sx.MachineName }
                                                       into sxsx1
                                                       select new {
                                                           sxsx1.Key.MachineId,
                                                           sxsx1.Key.MachineName,
                                                           sxsx1.Key.MaterialUseDate,
                                                           Quantity = sxsx1.Sum(sx => sx.Quantity),
                                                       }).ToList();
                                    var machines = groupSx.Select(sx => sx.MachineId).Distinct();
                                    var lastProduct =
                                        lastProductions.LastOrDefault(id => id.ProductId == entity.ProductId);
                                    entity.ProductionDate = lastProduction.MaterialUseDate.ToString("dd/MM/yyyy");
                                    var count = 0;
                                    foreach (var machine in machines) {
                                        var startDiffProduct =
                                            lastProductions.LastOrDefault(
                                                id =>
                                                id.ProductId != entity.ProductId &&
                                                id.MaterialUseDate < lastProduct.MaterialUseDate &&
                                                id.MachineId == machine);
                                        var groupDetail = groupSx.Where(sx => sx.MachineId == machine).ToList();
                                        if (startDiffProduct != null)
                                            groupDetail =
                                                groupDetail.Where(
                                                    sx => sx.MaterialUseDate >= startDiffProduct.MaterialUseDate).ToList();
                                        if (groupDetail.Any()) {
                                            entity.Average += (groupDetail.Sum(sx => sx.Quantity) / groupDetail.Count());
                                            count++;
                                            var production = new OrderProgressProduction {
                                                MachineName = groupDetail.FirstOrDefault().MachineName,
                                                AverageByMachine =
                                                    (groupDetail.Sum(sx => sx.Quantity) / groupDetail.Count()),
                                                StartDateString =
                                                    groupDetail.FirstOrDefault()
                                                               .MaterialUseDate.ToString("dd/MM/yy"),
                                                LastDateString =
                                                    groupDetail.LastOrDefault()
                                                               .MaterialUseDate.ToString("dd/MM/yy"),
                                                LastQuantity = 0,
                                                RealPerformance = 0,
                                            };
                                            production.AveragePerformance =
                                                Math.Round(100 * production.AverageByMachine /
                                                           entity.ProductivityInDay, 0);
                                            if (groupDetail.LastOrDefault().MaterialUseDate ==
                                                lastProduction.MaterialUseDate) {
                                                production.LastQuantity = groupDetail.LastOrDefault().Quantity;
                                                production.RealPerformance =
                                                    Math.Round(100 * production.LastQuantity / entity.ProductivityInDay, 0);
                                            }
                                            entity.Productions.Add(production);
                                        }
                                    }
                                    entity.Average = entity.Average / count;
                                }
                            }
                            if (!entity.Productions.Any()) {
                                var production = new OrderProgressProduction {
                                    MachineName = "",
                                    AverageByMachine = 0,
                                    StartDateString = "",
                                    LastQuantity = 0,
                                    AveragePerformance = 0,
                                    RealPerformance = 0,
                                };
                                entity.Productions.Add(production);
                            }
                            //entity.ProductionQuantity = entity.Productions.Sum(p => p.LastQuantity);
                            var smartProduction = smartProductions.FirstOrDefault(sp => sp.ProductId == entity.ProductId);
                            if (smartProduction != null) {
                                entity.ProductionDateStatus = 1;
                            }
                            var totalInv = entity.TotalInv - entity.ProcessingInv;
                            var needProductionDay = 0;
                            foreach (var orderDetail in requirementOrderInMonth) {
                                var detail =
                                    entity.Details.FirstOrDefault(od => od.OrderDueDate == orderDetail.DueDate);
                                if (detail == null) {
                                    detail = new OrderProgressDetailModel {
                                        OrderDueDate = orderDetail.DueDate,
                                        OrderQuantity = orderDetail.RequiedNumber,
                                        OrderDueDateString = orderDetail.DueDate.ToString("dd/MM/yy"),
                                        OrderRequired = 0,
                                        DiffDay = 0,
                                        ProductionDay = 0,
                                    };
                                    entity.Details.Add(detail);
                                }
                                else {
                                    detail.OrderQuantity += orderDetail.RequiedNumber;
                                }
                                if (totalInv == 0) {
                                    detail.OrderRequired = detail.OrderQuantity;
                                }
                                else if (totalInv > orderDetail.RequiedNumber) {
                                    detail.OrderRequired = 0;
                                    totalInv -= orderDetail.RequiedNumber;
                                    if (totalInv < 0)
                                        totalInv = 0;
                                }
                                else if (totalInv < orderDetail.RequiedNumber) {
                                    detail.OrderRequired = orderDetail.RequiedNumber - totalInv;
                                    totalInv = 0;
                                }
                                if (detail.OrderRequired > 0) {
                                    if (entity.ProductivityInDay == 0)
                                        detail.ProductionDay = -1;
                                    else {
                                        var productionDay = detail.OrderRequired / entity.ProductionQuantity;
                                        if (entity.ProductionQuantity == 0)
                                            productionDay = detail.OrderRequired / entity.ProductivityInDay;
                                        if (productionDay % 1 > 0) {
                                            detail.ProductionDay = Convert.ToInt32(productionDay - (productionDay % 1) + 1);
                                        }
                                    }
                                }
                                //if (detail.ProductionDay > 0)
                                //{
                                //detail.CompleteDate = DateTime.Now.AddDays(detail.ProductionDay + entity.PendingDay + needProductionDay);
                                //detail.CompleteDateString = detail.CompleteDate.Value.ToString("dd/MM/yy");
                                //}
                                detail.DiffDay = Convert.ToInt32((detail.OrderDueDate - detail.CompleteDate).Value.TotalDays) + 1;
                                needProductionDay += detail.ProductionDay;
                            }
                            entity.OrderInMonth = entity.Details.Sum(od => od.OrderQuantity);
                            entity.RequirementOrder = entity.Details.Sum(od => od.OrderRequired);
                            if (entity.Productions.Any(p => p.AveragePerformance != 0))
                                entity.AveragePerformance =
                                    entity.Productions.Where(p => p.AveragePerformance != 0)
                                          .Sum(p => p.AveragePerformance) /
                                    entity.Productions.Count(p => p.AveragePerformance != 0);
                            if (entity.Productions.Any(p => p.RealPerformance != 0))
                                entity.RealPerformance =
                                    entity.Productions.Where(p => p.RealPerformance != 0).Sum(p => p.RealPerformance) /
                                    entity.Productions.Count(p => p.RealPerformance != 0);
                        part5:
                            i++;
                            if (entity.Details.FirstOrDefault(d => d.DiffDay < 0) != null) {
                                if (entity.ProductionDateStatus == 1)
                                    entity.ProductionStatus = 2; // orange
                                else
                                    entity.ProductionStatus = 1; // red
                            }
                            else {
                                if (entity.Details.FirstOrDefault(d => d.DiffDay < 5) != null)
                                    if (entity.ProductionDateStatus != 1)
                                        entity.ProductionStatus = 3; // yellow
                            }
                            model.Add(entity);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("OrderProgressProduction", ex.Message);
            }
            return PartialView("PageOrderProgressProduction", model);
        }
        [GridAction]
        public ActionResult SelectExpectedPlating(int customerId, string productCode, string toDate) {
            var model = new List<ExpectPlatingModel>();
            try {
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var ci = new CultureInfo("vi-VN");

                    var reportDate = string.IsNullOrWhiteSpace(toDate)
                                         ? DateTime.Today
                                         : Convert.ToDateTime(toDate, ci);
                    reportDate =
                        new DateTime(reportDate.Year, reportDate.Month, reportDate.Day).AddDays(1).AddSeconds(-1);
                    var productIds = (from pi in vfi.ProductInventories
                                      where
                                          (pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating ||
                                           pi.WarehouseId == MyUtilities.Warehouse.Plating ||
                                           pi.WarehouseId == MyUtilities.Warehouse.PlatingTest)
                                      select pi.ProductId).Distinct().ToList();
                    var products = (from p in vfi.Products
                                    where p.Active && productIds.Contains(p.ProductId)
                                    orderby p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                    }).ToList();
                    if (customerId != 0 && !string.IsNullOrWhiteSpace(productCode)) {
                        products =
                            products.Where(
                                p => p.CustomerId == customerId && p.ProductCode.Contains(productCode))
                               .ToList();
                        if (!products.Any())
                            return View(new GridModel(new List<SoLieuTongHopSanPham>()));
                    }
                    else if (customerId != 0) {
                        products.Where(p => p.CustomerId == customerId).ToList();
                        if (!products.Any())
                            return View(new GridModel(new List<SoLieuTongHopSanPham>()));
                    }
                    else if (!string.IsNullOrWhiteSpace(productCode)) {
                        products = products.Where(p => p.ProductCode.Contains(productCode)).ToList();
                        if (!products.Any())
                            return View(new GridModel(new List<SoLieuTongHopSanPham>()));
                    }
                    productIds = products.Select(p => p.ProductId).ToList();
                    var warehouseList = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvPeriods = (from pip in vfi.ProductInventoryPeriods
                                             where
                                                 pip.PeriodDate < reportDate &&
                                                 productIds.Contains(pip.ProductId) &&
                                                 warehouseList.Contains(pip.WarehouseId)
                                             select new {
                                                 pip.ProductId,
                                                 LastPeriodQuantity = pip.LastPeriodQuantity,
                                                 EarlyPeriodQuantity = pip.EarlyPeriodQuantity,
                                                 pip.WarehouseId,
                                             }).ToList();
                    var orderDetails = from od in vfi.OrderDetails
                                       where od.Order.DueDate != null &&
                                             od.RequiedNumber != 0 &&
                                             productIds.Contains(od.ProductId) &&
                                             (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess)
                                       select new {
                                           od.ProductId,
                                           OrderQty = od.OrderQty.Value,
                                           DueDate = od.Order.DueDate.Value,
                                       };
                    var customerIds = products.Select(p => p.CustomerId).Distinct().ToList();
                    var customers = from c in vfi.Customers
                                    where customerIds.Contains(c.CustomerId)
                                    orderby c.CustomerCode
                                    select new {
                                        c.CustomerId,
                                        c.CustomerCode
                                    };
                    int i = 1;
                    foreach (var customer in customers) {
                        var productsByCustomer = from p in products
                                                 where p.CustomerId == customer.CustomerId
                                                 orderby p.ProductCode
                                                 select new {
                                                     p.ProductId,
                                                     p.ProductCode,
                                                     p.ProductName,
                                                     p.DesignNo,
                                                 };
                        foreach (var product in productsByCustomer) {

                            if (product == null)
                                throw new AggregateException("Lỗi sản phẩm ! Liên hệ Admin");
                            var entity = new ExpectPlatingModel {
                                ProductCode = product.ProductCode,
                                ProductCustomerCode = product.DesignNo,
                                ProductName = product.ProductName,
                                CustomerCode = customer.CustomerCode,
                                FinishInv = 0,
                                OrderQuantity = 0,
                                PlatingInv = 0,
                                PlatingTestInv = 0,
                                TotalInv = 0,
                                WaitingPlatingInv = 0,
                                Index = i,
                                OrderDate = null
                            };
                            var productPeriodsById = productInvPeriods.Where(pip => pip.ProductId == product.ProductId);
                            entity.WaitingPlatingInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.WaitingPlating)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.PlatingInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.Plating)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.PlatingTestInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.PlatingTest)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.FinishInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.Finish)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.TotalInv =
                                productPeriodsById.Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            var order =
                                orderDetails.Where(od => od.ProductId == product.ProductId).OrderBy(od => od.DueDate);
                            if (order.Any()) {
                                entity.OrderQuantity = order.Sum(od => od.OrderQty);
                                entity.OrderDate = order.FirstOrDefault().DueDate;
                            }
                            model.Add(entity);
                            i++;
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectExpecedPlatingReport", ex.Message);
            }
            return View(new GridModel(model.OrderBy(m => m.CustomerCode).ThenBy(m => m.ProductCode)));
        }

        public ActionResult PrintExpecedPlatingReport(string toDate) {
            var model = new List<ExpectPlatingGroupModel>();
            try {
                using (var vfi = new tammaContext()) {
                    vfi.Configuration.LazyLoadingEnabled = false;
                    var ci = new CultureInfo("vi-VN");
                    var reportDate = MyUtilities.Function.ParseLastDateTime(toDate);
                    //var reportDate = string.IsNullOrWhiteSpace(toDate)
                    //                     ? DateTime.Today
                    //                     : Convert.ToDateTime(toDate, ci);
                    //reportDate =
                    //    new DateTime(reportDate.Year, reportDate.Month, reportDate.Day).AddDays(1).AddSeconds(-1);
                    var productIds = (from pi in vfi.ProductInventories
                                      where
                                          (pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating ||
                                           pi.WarehouseId == MyUtilities.Warehouse.Plating ||
                                           pi.WarehouseId == MyUtilities.Warehouse.PlatingTest)
                                      select pi.ProductId).Distinct().ToList();
                    var productPlatings = (from pp in vfi.ProductionPlatings
                                           where pp.Active
                                           select pp.ProductId).Distinct().ToList();
                    productIds = productIds.Union(productPlatings).Distinct().ToList();
                    var products = (from p in vfi.Products
                                    where p.Active && productIds.Contains(p.ProductId)
                                    orderby p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.CustomerId,
                                        p.ProductCode,
                                        p.ProductName,
                                        p.DesignNo,
                                        WaitingPlatingWeight = p.WaitingPlatingWeight ?? 1,
                                    }).ToList();
                    var warehouseList = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var productInvPeriods = (from pip in vfi.ProductInventoryPeriods
                                             where
                                                 pip.PeriodDate < reportDate &&
                                                 productIds.Contains(pip.ProductId) &&
                                                 warehouseList.Contains(pip.WarehouseId)
                                             select new {
                                                 pip.ProductId,
                                                 LastPeriodQuantity = pip.LastPeriodQuantity,
                                                 EarlyPeriodQuantity = pip.EarlyPeriodQuantity,
                                                 pip.WarehouseId,
                                             }).ToList();
                    var orderDetails = from od in vfi.OrderDetails
                                       where od.Order.DueDate != null &&
                                             od.RequiedNumber != 0 &&
                                             productIds.Contains(od.ProductId) &&
                                             (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess)
                                       select new {
                                           od.ProductId,
                                           OrderQty = od.OrderQty.Value,
                                           RequiedNumber = od.RequiedNumber,
                                           DueDate = od.Order.DueDate.Value,
                                       };
                    var customerIds = products.Select(p => p.CustomerId).Distinct().ToList();
                    var customers = from c in vfi.Customers
                                    where customerIds.Contains(c.CustomerId)
                                    orderby c.CustomerCode
                                    select new {
                                        c.CustomerId,
                                        c.CustomerCode
                                    };
                    int i = 1;
                    var production2Ids = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    foreach (var customer in customers) {
                        var group = new ExpectPlatingGroupModel {
                            CustomerId = customer.CustomerId,
                            CustomerCode = customer.CustomerCode,
                            List = new List<ExpectPlatingModel>(),
                            ReportDate = reportDate
                        };
                        var productsByCustomer = from p in products
                                                 where p.CustomerId == customer.CustomerId
                                                 orderby p.ProductCode
                                                 select p;
                        var _list = new List<ExpectPlatingModel>();
                        foreach (var product in productsByCustomer) {
                            if (product == null)
                                throw new AggregateException("Lỗi sản phẩm ! Liên hệ Admin");
                            var entity = new ExpectPlatingModel {
                                ProductCode = product.ProductCode,
                                ProductCustomerCode = product.DesignNo,
                                ProductName = product.ProductName,
                                CustomerCode = customer.CustomerCode,
                                FinishInv = 0,
                                OrderQuantity = 0,
                                PlatingInv = 0,
                                PlatingTestInv = 0,
                                TotalInv = 0,
                                WaitingPlatingInv = 0,
                                WaitingPlatingWeight = product.WaitingPlatingWeight,
                                Details = new List<ExpectPlatingDetailModel>()
                            };
                            var productPeriodsById = productInvPeriods.Where(pip => pip.ProductId == product.ProductId).ToList();
                            entity.WaitingPlatingInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.WaitingPlating)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.WaitingPlatingInvWeight = entity.WaitingPlatingInv * entity.WaitingPlatingWeight / 1000;
                            entity.PlatingInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.Plating)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.PlatingTestInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.PlatingTest)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.Production2Inv =
                                productPeriodsById.Where(pip => production2Ids.Contains(pip.WarehouseId))
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.QcBInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.QcB)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.FinishInv =
                                productPeriodsById.Where(pip => pip.WarehouseId == MyUtilities.Warehouse.Finish)
                                                  .Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            entity.TotalInv =
                                productPeriodsById.Sum(pip => pip.LastPeriodQuantity - pip.EarlyPeriodQuantity);
                            var order =
                                orderDetails.Where(od => od.ProductId == product.ProductId).OrderBy(od => od.DueDate);
                            var _details = new List<ExpectPlatingDetailModel>();
                            foreach (var od in order) {
                                var detail = _details.FirstOrDefault(d => d.OrderDate == od.DueDate);
                                if (detail == null) {
                                    detail = new ExpectPlatingDetailModel {
                                        OrderDate = od.DueDate,
                                        OrderQuantity = od.RequiedNumber,
                                        OrderDateString = od.DueDate.ToString("dd/MM/yy")
                                    };
                                    _details.Add(detail);
                                }
                                else {
                                    if (od.DueDate == detail.OrderDate) {
                                        detail.OrderQuantity += od.RequiedNumber;
                                    }
                                }
                            }
                            if (_details.Any()) {
                                entity.OrderQuantity = _details.Sum(od => od.OrderQuantity);
                                entity.OrderDate = _details.OrderByDescending(d => d.OrderDate).FirstOrDefault().OrderDate;
                                if (entity.OrderQuantity > entity.TotalInv)
                                    entity.PlanDate = entity.OrderDate.Value.AddDays(10);
                                else entity.PlanDate = entity.OrderDate.Value;
                                entity.PlanDateString = entity.PlanDate.ToString("dd/MM/yy");
                                entity.Details.AddRange(_details);
                            }
                            if (entity.WaitingPlatingInv != 0 || entity.PlatingInv != 0
                                || entity.PlatingTestInv != 0 || entity.OrderQuantity != 0) {
                                entity.Show = true;
                                entity.Index = i;
                                i++;
                            }
                            _list.Add(entity);
                        }
                        if (_list.Any()) {
                            group.WaitingPlatingInv = _list.Sum(l => l.WaitingPlatingInv);
                            group.WaitingPlatingInvWeight = _list.Sum(l => l.WaitingPlatingInvWeight);
                            group.PlatingInv = _list.Sum(l => l.PlatingInv);
                            group.PlatingTestInv = _list.Sum(l => l.PlatingTestInv);
                            group.Production2Inv = _list.Sum(l => l.Production2Inv);
                            group.QcBInv = _list.Sum(l => l.QcBInv);
                            group.FinishInv = _list.Sum(l => l.FinishInv);
                            group.TotalInv = _list.Sum(l => l.TotalInv);
                            group.OrderQuantity = _list.Sum(l => l.OrderQuantity);
                            group.List.AddRange(_list.Where(l => l.Show));
                            group.ProductCount = group.List.Count;
                            model.Add(group);
                        }
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("RptExpectedPlating", ex.Message);
            }
            return PartialView("PageExpectedPlating", model);
        }

        [GridAction]
        public ActionResult SelectProductionExpectedProcessById(int productId, int month, int year,
            double requirementInventory, double requirementOrder) {
            var model = new List<OrderProgressModel>();
            try {
                model = GetExpectedProcessesByProductId(productId, month, year, requirementInventory, requirementOrder);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionSectionById", ex.Message);
            }
            return View(new GridModel(model));
        }

        private List<OrderProgressModel> GetExpectedProcessesByProductId(int productId, int month, int year,
            double requirementInventory, double requirementOrder) {
            var reportDate = new DateTime(year, month, 1);
            var endDate = reportDate.AddMonths(1).AddSeconds(-1);
            var nextMonth = reportDate.AddMonths(1);
            var model = new List<OrderProgressModel>();
            using (var vfi = new tammaContext()) {
                var process =
                    vfi.ProductionProcesses
                       .Where(pp => pp.ProductId == productId && pp.IsNecessary)
                       .OrderBy(pp => pp.ProcessIndex);
                DateTime? lastDate = null;
                var production2Ids = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                var requirementOrderDetails = (from od in vfi.OrderDetails
                                               where
                                                   od.Order.DueDate != null &&
                                                   od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                                   (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                   od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                   productId == od.ProductId
                                               select new {
                                                   RequiedNumber = od.RequiedNumber,
                                                   DueDate = od.Order.DueDate.Value,
                                                   //od.Order.Status
                                               }).ToList();
                var diffRequest = (from fo in vfi.ForecastOrders
                                   where productId == fo.ProductId &&
                                         fo.ForecastDate.Month == nextMonth.Month &&
                                         fo.ForecastDate.Year == nextMonth.Year
                                   select new {
                                       fo.ProductId,
                                       fo.Quantity,
                                       fo.IsSelling,
                                   }).FirstOrDefault();
                foreach (var productionProcess in process) {
                    var entity = new OrderProgressModel {
                        ProductId = productId,
                        WarehouseName = productionProcess.Warehouse.WarehouseName,
                        WarehouseId = productionProcess.WarehouseId,
                        ExpectedDay = 0,
                        ExpectedFactor = 1,
                        Month = month,
                        Year = year,
                        NumberProcess = 0
                        //requirementInventory > requirementOrder
                        //                   ? requirementInventory
                        //                   : requirementOrder
                    };
                    var warehouseIds = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity();
                    var invs =
                        vfi.ProductInventories.Where(
                            pi => warehouseIds.Contains(pi.WarehouseId) && pi.ProductId == productId);
                    if (!invs.Any()) goto continue2;
                    var requirementOrderInMonth =
                          requirementOrderDetails.Where(od => od.DueDate < endDate).ToList();
                    if (requirementOrderInMonth.Any()) {
                        entity.NumberProcess += requirementOrderInMonth.Sum(od => od.RequiedNumber);
                    }
                    var requirementOrderNextMonth =
                            requirementOrderDetails.Where(
                                od => od.DueDate >= nextMonth).ToList();
                    if (requirementOrderNextMonth.Any()) {
                        entity.NumberProcess += requirementOrderNextMonth.Sum(od => od.RequiedNumber);
                    }
                    else {

                        if (diffRequest != null) {
                            entity.NumberProcess += diffRequest.Quantity;
                        }
                    }
                    if (entity.WarehouseId == MyUtilities.Warehouse.Production1) {
                        entity.NumberProcess = (productionProcess.Product.ForecastsQuality ?? 0) -
                                               invs.Sum(pi => pi.TotalQty);
                        if (entity.NumberProcess <= 0)
                            entity.NumberProcess = 0;
                        else {
                            entity.ExpectedDay = Convert.ToInt32(Math.Round(entity.NumberProcess /
                                                (72000 / productionProcess.Product.Productivity.Value), 0));
                            entity.WarehouseName += " (NS: " +
                                                    string.Format("{0:n0}",
                                                                  Math.Round(
                                                                      (72000 /
                                                                       productionProcess.Product.Productivity.Value), 0)) +
                                                    " (pcs/máy))";
                            if (entity.ExpectedDay * (72000 / productionProcess.Product.Productivity.Value) <
                                entity.NumberProcess)
                                entity.ExpectedDay++;
                        }
                    }
                    else if (entity.NumberProcess <= 0)
                        entity.NumberProcess = 0;
                    else if (entity.WarehouseId == MyUtilities.Warehouse.Finish) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.InvQuantity = (finishInv.TotalQty);
                        if (entity.InvQuantity > entity.NumberProcess) entity.NumberProcess = 0;
                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.QcA || entity.WarehouseId == MyUtilities.Warehouse.QcB) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        if (productionProcess.Product.QcProductivity != 0) {
                            entity.ExpectedDay =
                                Convert.ToInt32(
                                    Math.Round(entity.NumberProcess / (productionProcess.Product.QcProductivity * 8), 0));
                            entity.WarehouseName += " (NS: " +
                                                    string.Format("{0:n0}",
                                                                  Math.Round(
                                                                      (productionProcess.Product.QcProductivity * 8), 0)) +
                                                    " (pcs/người))";
                        }
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.InvQuantity = (qcInv.Sum(pi => pi.TotalQty));
                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.Plating) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.NumberProcess -= (qcInv.Sum(pi => pi.TotalQty));
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        var platingInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                        if (platingInv != null)
                            entity.InvQuantity = (platingInv.TotalQty);

                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.WaitingPlating) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.NumberProcess -= (qcInv.Sum(pi => pi.TotalQty));
                        var platingInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                        if (platingInv != null)
                            entity.NumberProcess -= (platingInv.TotalQty);
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        var waitingPlatingInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                        if (waitingPlatingInv != null)
                            entity.InvQuantity = (waitingPlatingInv.TotalQty);

                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.NumberProcess -= (qcInv.Sum(pi => pi.TotalQty));
                        var platingInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                        if (platingInv != null)
                            entity.NumberProcess -= (platingInv.TotalQty);
                        var waitingPlatingInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                        if (waitingPlatingInv != null)
                            entity.NumberProcess -= (waitingPlatingInv.TotalQty);
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        var surfaceTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment);
                        if (surfaceTreatmentInv != null)
                            entity.InvQuantity = (surfaceTreatmentInv.TotalQty);
                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.HeatTreatment) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.NumberProcess -= (qcInv.Sum(pi => pi.TotalQty));
                        var platingInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                        if (platingInv != null)
                            entity.NumberProcess -= (platingInv.TotalQty);
                        var waitingPlatingInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                        if (waitingPlatingInv != null)
                            entity.NumberProcess -= (waitingPlatingInv.TotalQty);
                        var surfaceTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment);
                        if (surfaceTreatmentInv != null)
                            entity.NumberProcess -= (surfaceTreatmentInv.TotalQty);
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        var heatTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.HeatTreatment);
                        if (heatTreatmentInv != null)
                            entity.InvQuantity = (heatTreatmentInv.TotalQty);

                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.Production2) {
                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.NumberProcess -= (qcInv.Sum(pi => pi.TotalQty));
                        var platingInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                        if (platingInv != null)
                            entity.NumberProcess -= (platingInv.TotalQty);
                        var waitingPlatingInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                        if (waitingPlatingInv != null)
                            entity.NumberProcess -= (waitingPlatingInv.TotalQty);
                        var surfaceTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment);
                        if (surfaceTreatmentInv != null)
                            entity.NumberProcess -= (surfaceTreatmentInv.TotalQty);
                        var heatTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.HeatTreatment);
                        if (heatTreatmentInv != null)
                            entity.NumberProcess -= (heatTreatmentInv.TotalQty);
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        var production2Invs = invs.Where(pi => production2Ids.Contains(pi.WarehouseId));
                        if (production2Invs.Any())
                            entity.InvQuantity = (production2Invs.Sum(pi => pi.TotalQty));

                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.Cnc) {

                        var finishInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Finish);
                        if (finishInv != null)
                            entity.NumberProcess -= (finishInv.TotalQty);
                        var qcInv =
                            invs.Where(
                                pi =>
                                pi.WarehouseId == MyUtilities.Warehouse.QcA || pi.WarehouseId == MyUtilities.Warehouse.QcB);
                        if (qcInv.Any())
                            entity.NumberProcess -= (qcInv.Sum(pi => pi.TotalQty));
                        var platingInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Plating);
                        if (platingInv != null)
                            entity.NumberProcess -= (platingInv.TotalQty);
                        var waitingPlatingInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                        if (waitingPlatingInv != null)
                            entity.NumberProcess -= (waitingPlatingInv.TotalQty);
                        var surfaceTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment);
                        if (surfaceTreatmentInv != null)
                            entity.NumberProcess -= (surfaceTreatmentInv.TotalQty);
                        var heatTreatmentInv =
                            invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.HeatTreatment);
                        if (heatTreatmentInv != null)
                            entity.NumberProcess -= (heatTreatmentInv.TotalQty);
                        var production2Invs = invs.Where(pi => production2Ids.Contains(pi.WarehouseId));
                        if (production2Invs.Any())
                            entity.NumberProcess -= (production2Invs.Sum(pi => pi.TotalQty));
                        if (entity.NumberProcess <= 0) {
                            entity.NumberProcess = 0;
                        }
                        var cncInv = invs.FirstOrDefault(pi => pi.WarehouseId == MyUtilities.Warehouse.Cnc);
                        if (cncInv != null)
                            entity.InvQuantity = (cncInv.TotalQty);
                    }
                    var progress =
                        vfi.OrderProgresses.FirstOrDefault(
                            op =>
                            op.ProductId == productId &&
                            op.Month == month && op.Year == year &&
                            op.WarehouseId == productionProcess.WarehouseId);
                    if (progress != null) {
                        entity.ProgressId = progress.ProgressId;
                        entity.ExpectedDay = progress.ExpectedDay;
                        entity.ExpectedFactor = progress.ExpectedFactor;
                        entity.StartDate = progress.StartDate;
                        entity.ModifiedDate = progress.ModifiedDate;
                        entity.ModifiedUser = progress.ModifiedUser;
                    }
                    else {
                        entity.StartDate = lastDate;
                        if (entity.WarehouseId != MyUtilities.Warehouse.Production1 ||
                            productionProcess.Product.Productivity == 0 ||
                            productionProcess.Product.Productivity == null ||
                            entity.NumberProcess == 0)
                            goto continue2;
                        var productivityInDay = 72000 / productionProcess.Product.Productivity.Value;
                        //if (entity.WarehouseId != MyUtilities.Warehouse.QcA ||
                        //    entity.WarehouseId != MyUtilities.Warehouse.QcB)
                        //{
                        //    productivityInDay = productionProcess.Product.QcProductivity * 8;
                        //}
                        entity.ExpectedDay = Convert.ToInt32(Math.Round(entity.NumberProcess / productivityInDay));
                        //if (entity.ExpectedDay != 0)
                    }
                continue2:
                    if (entity.WarehouseId == MyUtilities.Warehouse.Production2) {
                        var sections = vfi.ProductionSections.Where(ps => ps.ProductId == productId);
                        foreach (var productionSection in sections) {
                            entity.WarehouseName += ("-" + productionSection.Section.SectionName);
                        }
                    }
                    else if (entity.WarehouseId == MyUtilities.Warehouse.WaitingPlating) {
                        var platings = vfi.ProductionPlatings.Where(pp => pp.ProductId == productId);
                        foreach (var plating in platings) {
                            entity.WarehouseName += ("-" + plating.PlatingName);
                        }
                    }
                    if (entity.StartDate != null) {
                        entity.FinishDate =
                            entity.StartDate.Value.AddDays(Convert.ToInt32(entity.ExpectedDay / entity.ExpectedFactor));
                        lastDate = entity.FinishDate;
                    }
                    model.Add(entity);
                }
            }
            return model;
        }

        [GridAction]
        public ActionResult UpdateProductionExpectedProcessById(OrderProgressModel update, int productId, int month, int year,
            double requirementInventory, double requirementOrder) {
            var model = new List<OrderProgressModel>();
            try {
                if (update.ExpectedFactor == 0) throw new AggregateException("Lỗi! Hệ số không được là 0!");
                using (var vfi = new tammaContext()) {
                    OrderProgress progress;
                    if (update.ProgressId > 0) {
                        progress = vfi.OrderProgresses.FirstOrDefault(op => op.ProgressId == update.ProgressId);
                        if (progress == null)
                            throw new AggregateException("Lỗi! Không tìm thấy quy trình " + update.WarehouseName);
                        progress.ExpectedDay = update.ExpectedDay;
                        progress.ExpectedFactor = update.ExpectedFactor;
                        progress.ModifiedDate = DateTime.Now;
                        progress.ModifiedUser = HttpContext.User.Identity.Name;
                        progress.StartDate = update.StartDate.Value;
                    }
                    else {
                        if (update.ExpectedDay != 0 && update.StartDate == null)
                            throw new AggregateException("Lỗi! Phải cập nhật đầy đủ mới được lưu!");
                        progress = new OrderProgress {
                            ProductId = productId,
                            ExpectedDay = update.ExpectedDay,
                            ExpectedFactor = update.ExpectedFactor,
                            ModifiedDate = DateTime.Now,
                            ModifiedUser = HttpContext.User.Identity.Name,
                            Month = month,
                            Year = year,
                            WarehouseId = update.WarehouseId,
                            StartDate = update.StartDate.Value,
                        };
                        vfi.OrderProgresses.Add(progress);
                    }
                    vfi.SaveChanges();
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionSectionById", ex.Message);
            }
            return View(new GridModel(GetExpectedProcessesByProductId(productId, month, year, requirementInventory, requirementOrder)));
        }


        [GridAction]
        public ActionResult SelectTrackUpProduct(int customerId, string productCode) {
            var model = new List<ForecastOrderDetailModel>();
            try {
                using (var vfi = new tammaContext()) {
                    var orderProgresses = from op in vfi.OrderProgresses
                                          where op.OrderDetailId != null
                                          //&& op.ProductId == 148
                                          orderby op.StartDate descending
                                          select op;
                    //var orderDetailId = orderProgresses.Select(op => op.OrderDetailId).Distinct().ToList();
                    var orderDetails = from od in vfi.OrderDetails
                                       where
                                           od.Order.DueDate != null &&
                                           (od.Order.Status == 0 ||
                                            od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                            od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                           od.RequiedNumber != 0
                                       select new {
                                           od.OrderDetailId,
                                           od.ProductId,
                                           od.Product,
                                           od.Order,
                                           od.OrderQty,
                                           od.RequiedNumber,
                                       };
                    //if (!string.IsNullOrWhiteSpace(productCode))
                    //    orderDetails = orderDetails.Where(od => od.Product.ProductCode.Contains(productCode));
                    var productIds = orderDetails.Select(od => od.ProductId).Distinct();
                    var lastProductions = vfi.ImportFormSX1Detail.Where(id => productIds.Contains(id.ProductId)).ToList();
                    foreach (var productId in productIds) {
                        var orderDetailsById = orderDetails.Where(od => od.ProductId == productId);
                        if (!orderDetailsById.Any()) continue;
                        var orderDetailIds = orderDetailsById.Select(op => op.OrderDetailId).Distinct().ToList();
                        var orderProgressesById = orderProgresses.Where(op => orderDetailIds.Contains(op.OrderDetailId));
                        if (!orderProgressesById.Any()) continue;

                        var entity = new ForecastOrderDetailModel {
                            CustomerCode = orderDetailsById.FirstOrDefault().Order.Customer.CustomerCode,
                            ProductCode = orderDetailsById.FirstOrDefault().Product.ProductCode,
                            ProductId = productId,
                            PlanQuantity = orderDetailsById.Sum(od => od.RequiedNumber),
                            UploadDate = orderProgressesById.FirstOrDefault().StartDate
                        };
                        var lastProduction = lastProductions.LastOrDefault(id => id.ProductId == productId);
                        if (lastProduction != null) {
                            entity.MaterialCode = lastProduction.MaterialInventory.Material.MaterialCode;
                        }
                        var production =
                            vfi.ImportFormSX1Detail.FirstOrDefault(
                                id => id.ProductId == productId && id.ImportFormSX1.MaterialUseDate >= entity.UploadDate);
                        if (production == null)
                            model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionSectionById", ex.Message);
            } return View(new GridModel(model.OrderBy(m => m.CustomerCode).ThenBy(m => m.ProductCode)));

        }

        [GridAction]
        public ActionResult SelectTrackUpProductDetail(int productId) {
            var model = new List<OrderDetailModel>();
            try {
                using (var vfi = new tammaContext()) {
                    var orderDetails = (from od in vfi.OrderDetails
                                        where od.Order.Status != (byte)MyUtilities.Sales.Status.Cancel &&
                                              od.Order.Status != (byte)MyUtilities.Sales.Status.Completed &&
                                              od.RequiedNumber != 0 &&
                                              od.Order.DueDate != null &&
                                              od.ProductId == productId
                                        select od);
                    var orderDetailIds = orderDetails.Select(od => od.OrderDetailId);
                    var orderProgresses = from op in vfi.OrderProgresses
                                          where orderDetailIds.Contains(op.OrderDetailId)
                                          select op;
                    var forecast = from f in vfi.ForecastOrders
                                   where productId == f.ProductId
                                   select f;
                    //if (!string.IsNullOrWhiteSpace(productCode))
                    //    orderDetails = orderDetails.Where(od => od.Product.ProductCode.Contains(productCode));
                    foreach (var orderDetail in orderDetails) {
                        var entity = new OrderDetailModel {
                            OrderNumber = orderDetail.Order.OrderNumber,
                            ProductId = orderDetail.ProductId,
                            ProductCode = orderDetail.Product.ProductCode,
                            OrderDetailId = orderDetail.OrderDetailId,
                            OrderId = orderDetail.OrderId,
                            VFIDueDate = orderDetail.VFIDueDate,
                            CustomerDueDate = orderDetail.Order.DueDate,
                            OrderQty = orderDetail.OrderQty ?? 0,
                            UnitPrice = 0.0,
                            PONumber = orderDetail.PONumber,
                            AvailableQty = 0,
                            TotalInventory = 0,
                            Note = orderDetail.Note,
                            ApproveType = false,
                            IsApprove = orderDetail.VFIDueDate != null,
                            DetailApproved = (orderDetail.Status == (int)MyUtilities.Sales.Status.Completed),
                            RequiredNumber = orderDetail.RequiedNumber,
                        };

                        var forecastById =
                            forecast.FirstOrDefault(
                                f =>
                                f.ProductId == entity.ProductId &&
                                (orderDetail.VFIDueDate == null
                                     ? (f.ForecastDate.Month == entity.CustomerDueDate.Value.Month &&
                                        f.ForecastDate.Year == entity.CustomerDueDate.Value.Year)
                                     : (f.ForecastDate.Month == entity.VFIDueDate.Value.Month &&
                                        f.ForecastDate.Year == entity.VFIDueDate.Value.Year)));
                        if (forecastById != null) {
                            entity.ForecastInMonth = forecastById.Quantity;
                        }
                        // so sanh du bao - doi voi don hang chua duyet
                        var orderProgress =
                            orderProgresses.FirstOrDefault(op => op.OrderDetailId == orderDetail.OrderDetailId);
                        if (orderProgress != null) {
                            entity.ProductionDate = orderProgress.StartDate;
                            entity.MachineRun = orderProgress.ExpectedFactor;
                            entity.ProductionApprove = true;
                        }
                        model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionSectionById", ex.Message);
            }
            return View(new GridModel(model.OrderBy(m => m.CustomerDueDate)
                                           .ThenBy(m => m.VFIDueDate)
                                           .ThenBy(m => m.ProductionDate)));

        }

