        [GridAction]
        public ActionResult PrintDeliverySalesReport(int customerId) {
            var model = new List<ProductDeliverySalesReportModel>();
            try {
                var list = GetDeliverySalesReport(customerId, "");
                var productIds = list.Select(x => x.ProductId).Distinct().ToList();
                //var products = list.Select(x => new { x.ProductCode, x.ProductNumber, x.FinishInv, x.TotalInv });
                foreach (var productId in productIds) {
                    var entity = new ProductDeliverySalesReportModel { 
                        ReportDate = DateTime.Today
                    };
                    entity.List = list.Where(x => x.ProductId == productId).ToList();
                    var detail = entity.List.FirstOrDefault();
                    entity.ProductCode = detail.ProductCode;
                    entity.ProductNumber = detail.ProductNumber;
                    entity.FinishInv = detail.FinishInv;
                    entity.TotalInv = detail.TotalInv;
                    detail = list.FirstOrDefault(x => x.ProductId == productId && x.Productions.Any());
                    if (detail != null) {
                        entity.Productions = detail.Productions;
                        entity.ProductionStatus = detail.Status;
                    }
                    model.Add(entity);
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("PrintDeliverySalesReport", ex.Message);
            }

            return PartialView("PageDeliverySalesReport", model);
        }

        List<DeliverySalesReportModel> GetDeliverySalesReport(int customerId, string productCode) {
            var model = new List<DeliverySalesReportModel>();
            using (var vfi = new tammaContext()) {

                var invoiceDetails = vfi.InvoiceDetails
                        .Where(x => x.Invoice.ShipmentDate >= MyUtilities.Sales.StartTaxInvoiceDate
                            && x.Invoice.Active && x.Active
                            && (customerId == 0 || x.Invoice.CustomerId == customerId)
                            && (x.ExportFormTP_KDDetail.IsInvoiced == false 
                                || x.OrderDetail.RequiedNumber > 0)
                            && (x.Invoice.Status == (byte)(byte)MyUtilities.Sales.Status.Waiting
                                || x.Invoice.Status == (byte)MyUtilities.Sales.Status.InProcess))
                        .Select(x => new {
                            x.OrderDetailId,
                            IsInvoiced = x.ExportFormTP_KDDetail.IsInvoiced ?? false,
                            ShipmentDate = x.Invoice.ShipmentDate.Value,
                            Quantity = x.Piece
                        })
                        .GroupBy(x => new { x.OrderDetailId, x.IsInvoiced, x.ShipmentDate })
                        .Select(x => new {
                            x.Key.OrderDetailId,
                            x.Key.IsInvoiced,
                            x.Key.ShipmentDate,
                            Quantity = x.Sum(y => y.Quantity)
                        })
                        .Where(x => x.Quantity > 0)
                        .OrderBy(x => x.ShipmentDate)
                        .ToList();

                var orderDetailsOnDelivery = invoiceDetails.Select(x => x.OrderDetailId).Distinct().ToList();
                var orderDetails = vfi.OrderDetails
                        .Where(x => 
                            (x.Order.Status != (byte)MyUtilities.Sales.Status.Cancel
                                && x.Order.Status != (byte)MyUtilities.Sales.Status.Completed
                                && x.Order.DueDate != null
                                && (customerId == 0 || x.Order.CustomerId == customerId)
                                && x.RequiedNumber > 0)
                            || orderDetailsOnDelivery.Contains(x.OrderDetailId))
                        .OrderBy(x => new { x.Order.Customer.CustomerCode, x.Product.ProductCode, x.Order.DueDate.Value })
                        .Select(x => new {
                            x.OrderDetailId,
                            OrderQty = x.OrderQty ?? 0,
                            x.UnitPrice,
                            x.RequiedNumber,
                            x.PONumber,

                            x.ProductId,
                            x.Product.ProductCode,
                            x.Product.DesignNo,

                            x.Order.OrderDate,
                            DueDate = x.Order.DueDate.Value,
                            x.Order.OrderNumber,

                            x.Order.Customer.CustomerCode,
                            ShipMethod = x.Order.Customer.ShippingMethodId != null
                                        ? x.Order.Customer.ShipMethod.Name
                                        : "No Method Config",
                        }).ToList();
                if (!string.IsNullOrWhiteSpace(productCode)) {
                    orderDetails = orderDetails.Where(x => x.ProductCode.Contains(productCode)).ToList();
                }
                var products = orderDetails.Select(x => new { x.ProductId, x.ProductCode }).Distinct().ToList();
                var productIds = orderDetails.Select(x => x.ProductId).ToList();
                //var filterProduction = vfi.ImportFormSX1Detail
                //    .Where(x => x.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                //        && productIds.Contains(x.ProductId))
                //        .Select(x => new { x.ProductId, x.ImportFormSX1.MaterialUseDate })
                //        .GroupBy(x => x.ProductId)
                //        .Select(x => new ProductionNoteModel { ProductId = x.Key, ProductionDate = x.Max(y => y.MaterialUseDate) })
                //        .ToList();
                var productionDate = vfi.ImportFormSX1.Where(x => x.Status == (byte)MyUtilities.Transaction.Status.Approved)
                    .Select(x => x.MaterialUseDate).OrderByDescending(x => x).First();
                var filterDate = new DateTime(productionDate.Year, productionDate.Month, productionDate.Day).AddDays(-3);
                //var result = input.GroupBy(x => x.F1, (key, g) => g.OrderBy(e => e.F2).First());
                //var query = from player in vfi.ImportFormSX1Detail
                //            group player by player.Machine into team
                //            select team.MaxBy(p => p.PlayerScore);
                var lastProductions = vfi.ImportFormSX1Detail
                        .Where(x => x.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                            && x.ImportFormSX1.MaterialUseDate >= filterDate)
                        .Select(x => new {
                            x.ProductId,
                            x.MachineId,
                            x.Machine1.MachineName,
                            x.Machine1.ProcessingType.TypeName,
                            x.ImportFormSX1.MaterialUseDate,
                            Quantity = x.Number1 + x.Number2,
                            StateId = x.Machine1.StateId ?? 0,
                            StateName = x.Machine1.StateId != null ? x.Machine1.MachineState.NameEN : "",
                            StateColor = x.Machine1.StateId != null ? x.Machine1.MachineState.WarrningColor : "",
                        })
                    //.GroupBy(x => new { x.ProductId, x.MachineName, x.TypeName }, (key, y) => new { MaterialUseDate = y.OrderByDescending(z => z.MaterialUseDate), Quantity = y.Sum(z => z.Quantity) })
                        .GroupBy(x => new { x.ProductId, x.MachineId, x.MachineName, x.TypeName, x.MaterialUseDate, x.StateId, x.StateColor, x.StateName })
                        .Select(x => new {
                            x.Key.ProductId,
                            x.Key.MachineId,
                            x.Key.MachineName,
                            x.Key.TypeName,
                            x.Key.MaterialUseDate,
                            x.Key.StateId,
                            x.Key.StateColor,
                            x.Key.StateName,
                            //MaterialUseDate = x.Max(y => y.MaterialUseDate),
                            Quantity = x.Sum(y => y.Quantity)
                        });
                //var machineIds = lastProductions.Select(x=> x.MachineId).Distinct().ToList();
                var realProductions = vfi.TrackUpMachines.Where(x => x.Status != (byte)MyUtilities.Transaction.Status.Cancel && x.DeliveryDate != null)
                    .Select(x => new {
                        x.MachineId,
                        x.ProductId,
                        x.Machine.MachineName,
                        x.Machine.ProcessingType.TypeName,
                        x.Machine.ProcessingType.Description,
                        StateId = x.Machine.StateId ?? 0,
                        StateName = x.Machine.StateId != null ? x.Machine.MachineState.NameEN : "",
                        StateColor = x.Machine.StateId != null ? x.Machine.MachineState.WarrningColor : "",
                        DeliveryDate = x.DeliveryDate.Value
                    })
                    .GroupBy(x => new { x.MachineId, x.MachineName, x.TypeName, x.Description, x.StateId, x.StateName, x.StateColor })
                    .Select(x => new {
                        //x.Key,
                        x.Key.MachineId,
                        x.Key.MachineName,
                        x.Key.TypeName,
                        x.Key.Description,
                        x.Key.StateId,
                        x.Key.StateColor,
                        x.Key.StateName,
                        ProductId = x.OrderBy(y => y.DeliveryDate).FirstOrDefault().ProductId,
                    })
                    .ToList();
                //var machines = vfi.Machines.Where(x => machineIds.Contains(x.MachineId))
                //    .Select(x => new {
                //        x.MachineId,
                //        x.MachineName,
                //        x.ProcessingType.TypeName,
                //        x.ProcessingType.Description,
                //        StateId = x.StateId ?? 0,
                //        StateName = x.StateId != null ? x.MachineState.NameEN : "",
                //        StateColor = x.StateId != null ? x.MachineState.WarrningColor : "",
                //    })
                //    .ToList();
                var idleStateColor = vfi.MachineStates.FirstOrDefault(x => x.StateId == MyUtilities.Machine.State.OutOfTool).WarrningColor;
                var normalStateColor = vfi.MachineStates.FirstOrDefault(x => x.StateId == MyUtilities.Machine.State.Normal).WarrningColor;
                var doneStateColor = vfi.MachineStates.FirstOrDefault(x => x.StateId == MyUtilities.Machine.State.Done).WarrningColor;
                var productInvs = vfi.ProductInventories
                        .Where(x => productIds.Contains(x.ProductId)
                        && x.TotalQty > 0
                        && x.Warehouse.CanStock)
                        .Select(x => new { x.ProductId, x.TotalQty, x.Warehouse.IsFinish })
                        .GroupBy(x => new { x.ProductId, x.IsFinish })
                        .Select(x => new {
                            ProductId = x.Key.ProductId,
                            IsFinish = x.Key.IsFinish,
                            Quantity = x.Sum(y => y.TotalQty)
                        }).ToList();
                foreach (var orderDetail in orderDetails) {
                    var entity = new DeliverySalesReportModel {
                        OrderDetailId = orderDetail.OrderDetailId,
                        UnitPrice = orderDetail.UnitPrice,
                        ProductId = orderDetail.ProductId,
                        ProductCode = orderDetail.ProductCode,

                        OrderNumber = orderDetail.OrderNumber,
                        OrderQuantity = orderDetail.OrderQty,
                        CustomerPO = orderDetail.PONumber,
                        ProductNumber = orderDetail.DesignNo,
                        OrderDate = orderDetail.OrderDate,
                        DueDate = orderDetail.DueDate,

                        ShipMethod = orderDetail.ShipMethod,
                        CustomerCode = orderDetail.CustomerCode,
                        Status = DeliverySalesReportStatus.Waiting,
                        StatusColor = idleStateColor
                    };
                    var existedProductEntities = model.Where(x => x.ProductCode.Equals(entity.ProductCode)).ToList();
                    if (existedProductEntities.Any()) {
                        var existedProductEntity = existedProductEntities.LastOrDefault();
                        entity.TotalInv = existedProductEntity.TotalInv;
                        entity.FinishInv = existedProductEntity.FinishInv;

                        entity.Productions = existedProductEntity.Productions;
                        entity.ProductionQuantity = existedProductEntity.ProductionQuantity;
                        entity.LastProductionDate = existedProductEntity.LastProductionDate;
                        entity.LastProductionNote = existedProductEntity.LastProductionNote;

                        if (existedProductEntity.Status == DeliverySalesReportStatus.Completed) {
                            existedProductEntity.Productions = new List<ProductionSalesReportDetailModel>();
                            existedProductEntity.ProductionQuantity = 0;
                            existedProductEntity.LastProductionDate = null;
                            existedProductEntity.LastProductionNote = "";
                        }
                        else if (existedProductEntity.Status == DeliverySalesReportStatus.Running 
                            || existedProductEntity.Status == -1) {
                            entity.Status = -1;
                            entity.Productions = new List<ProductionSalesReportDetailModel>();
                            entity.ProductionQuantity = 0;
                            entity.LastProductionDate = null;
                            entity.LastProductionNote = "";
                        }
                    }
                    else {
                        var productInvsById = productInvs.Where(x => x.ProductId == orderDetail.ProductId).ToList();
                        if (productInvsById.Any()) {
                            entity.TotalInv = productInvsById.Sum(x => x.Quantity);
                            entity.FinishInv = productInvsById.Where(x => x.IsFinish).Sum(x => x.Quantity);
                        }
                        var lastProductionsById = lastProductions.Where(x => x.ProductId == orderDetail.ProductId).ToList();
                        var machineByIds = new List<int>();
                        if (lastProductionsById.Any()) {
                            machineByIds = lastProductionsById.Select(x => x.MachineId.Value).ToList();
                            //entity.ProductionQuantity = lastProductionsById.Sum(x => x.Quantity);
                            entity.LastProductionDate = lastProductionsById.Max(x => x.MaterialUseDate);
                            lastProductionsById = lastProductionsById.Where(x => x.MaterialUseDate.Day == entity.LastProductionDate.Value.Day
                               && x.MaterialUseDate.Month == entity.LastProductionDate.Value.Month
                               && x.MaterialUseDate.Year == entity.LastProductionDate.Value.Year).ToList();
                            foreach (var production in lastProductionsById) {
                                var detail = new ProductionSalesReportDetailModel() {
                                    Date = production.MaterialUseDate,
                                    Quantity = production.Quantity,
                                    Machine = production.MachineName + "-" + production.TypeName
                                };
                                entity.Productions.Add(detail);
                                entity.ProductionQuantity += production.Quantity;
                                entity.LastProductionNote += production.MaterialUseDate.ToString("dd/MM/yy")
                                    + "-"
                                    + string.Format("{0:n0}", production.Quantity)
                                    + "(" + production.MachineName + "-" + production.TypeName + ") ";
                                entity.OverideStatus(DeliverySalesReportStatus.Running, normalStateColor);
                                if (production.StateId == MyUtilities.Machine.State.Normal) { }
                                else if (production.StateId == MyUtilities.Machine.State.Setup) {
                                    entity.OverideStatus(DeliverySalesReportStatus.Setup, production.StateColor);
                                }
                                else {
                                    entity.OverideStatus(DeliverySalesReportStatus.Problem, production.StateColor);
                                }
                            }
                        }
                        else {
                            var machines = realProductions.Where(x => orderDetail.ProductId == x.ProductId).ToList();
                            foreach (var machine in machines) {
                                var detail = new ProductionSalesReportDetailModel() {
                                    Quantity = 0,
                                    Machine = machine.MachineName + "-" + machine.TypeName
                                };
                                entity.LastProductionNote += "(" + machine.MachineName + "-" + machine.TypeName + ") ";
                                entity.Productions.Add(detail);
                                if (machine.StateId == MyUtilities.Machine.State.Normal) {
                                    entity.OverideStatus(DeliverySalesReportStatus.Running, normalStateColor);
                                }
                                else if (machine.StateId == MyUtilities.Machine.State.Setup) {
                                    entity.OverideStatus(DeliverySalesReportStatus.Setup, machine.StateColor);
                                }
                                else {
                                    entity.OverideStatus(DeliverySalesReportStatus.Problem, machine.StateColor);
                                }
                            }
                        }
                    }

                    var invoiceDetailsById = invoiceDetails.Where(x => x.OrderDetailId == orderDetail.OrderDetailId).ToList();
                    if (invoiceDetailsById.Any()) {
                        var finishInvoices = invoiceDetailsById.Where(x => x.IsInvoiced).ToList();
                        if (finishInvoices.Any()) {
                            entity.Deliveried = finishInvoices.Sum(x => x.Quantity);
                        }
                        var onShipInvoices = invoiceDetailsById.Where(x => !x.IsInvoiced).ToList();
                        if (onShipInvoices.Any()) {
                            //entity.ShippingQuantity = onShipInvoices.Sum(x => x.Quantity);
                            foreach (var invoice in onShipInvoices) {
                                var detail = new DeliverySalesReportDetailModel {
                                    Quantity = invoice.Quantity,
                                    Date = invoice.ShipmentDate,
                                    Method = orderDetail.ShipMethod
                                };
                                entity.Details.Add(detail);

                                entity.ShippingQuantity += invoice.Quantity;
                                entity.OnShipNote += invoice.ShipmentDate.ToString("dd/MM/yy")
                                    + "-"
                                    + string.Format("{0:n0}", invoice.Quantity)
                                    + "(" + orderDetail.ShipMethod + ") ";
                            }
                        }
                    }
                    if ((existedProductEntities.Sum(x => x.Remaining - x.ShippingQuantity) + (entity.Remaining - entity.ShippingQuantity))
                        <= entity.FinishInv) {
                        entity.OverideStatus(DeliverySalesReportStatus.Completed, doneStateColor);
                        //entity.Productions = new List<ProductionSalesReportDetailModel>();
                    }
                    model.Add(entity);
                }
            }
            return model;
        }

        #endregion

        #region planning

        [GridAction]
        public ActionResult SelectMachineSetupPlan(int customerId, string productCode,
            string fromPoDate, string toPoDate, string invDate,
            bool cames, bool cnc) {
            var model = new List<MachineSetupPlanModel>();
            if (string.IsNullOrWhiteSpace(toPoDate))
                return View(new GridModel(model));
            try {
                model = GetMachineSetupPlan(customerId, productCode, fromPoDate, toPoDate, invDate, cames, cnc);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectMachineSetupPlan", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<MachineSetupPlanModel> GetMachineSetupPlan(int customerId, string productCode,
            string fromPoDate, string toPoDate, string invDate,
            bool cames, bool cnc) {
            var model = new List<MachineSetupPlanModel>();
            if (!cames && !cnc)
                return model;
            try {
                var ci = new CultureInfo("vi-VN");
                var fromdate = string.IsNullOrWhiteSpace(fromPoDate)
                                ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                                : Convert.ToDateTime(fromPoDate, ci);
                var podate = string.IsNullOrWhiteSpace(toPoDate)
                                ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                                : Convert.ToDateTime(toPoDate, ci);
                var invdate = string.IsNullOrWhiteSpace(invDate)
                                ? DateTime.Now
                                : Convert.ToDateTime(invDate, ci);
                using (var vfi = new tammaContext()) {
                    var orderDetails = (from od in vfi.OrderDetails
                                        where
                                            od.Order.DueDate != null &&
                                            od.Order.DueDate <= podate &&
                                            od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                            (customerId == 0 || od.Order.CustomerId == customerId) &&
                                            (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                            od.RequiedNumber > 0
                                        orderby od.Order.DueDate
                                        select new {
                                            od.ProductId,
                                            DueDate = od.Order.DueDate.Value,
                                            od.RequiedNumber,
                                        }).ToList();
                    var startMonth = new DateTime(fromdate.Year, fromdate.Month, 1);
                    var forecast = (from f in vfi.ForecastOrders
                                   where f.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                   f.ForecastDate <= podate &&
                                   f.ForecastDate >= fromdate &&
                                   f.ForecastDate >= startMonth
                                   orderby f.ForecastDate
                                   select new {
                                       f.ProductId,
                                       f.ForecastDate,
                                       f.Quantity
                                   }).ToList();
                    var productIds = orderDetails.Select(od => od.ProductId).Distinct().ToList();
                    var productIds2 = forecast.Select(od => od.ProductId).Distinct().ToList();
                    productIds.AddRange(productIds2);
                    productIds = productIds.Distinct().ToList();
                    var products = (from p in vfi.Products
                                    where p.Active && productIds.Contains(p.ProductId) &&
                                    p.ProcessingDesign != null
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.ProductCode,
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        Productivity = p.Productivity ?? 0,
                                        MillProductivity = p.MillProductivity ?? 0,
                                        p.ProcessingDesign,
                                        p.ProcessingType,
                                        p.MachineFunction,
                                        MaterialId = p.MaterialId ?? 0
                                        //p.id,
                                    }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode)) {
                        products = products.Where(x => x.ProductCode.Contains(productCode.ToUpper())).ToList();
                        productIds = products.Select(x => x.ProductId).ToList();
                    }
                    //if (product.ProcessingType.Description.ToUpper().Contains("CAMES")) {
                    //    processingType = "CAMES";
                    //}
                    //else if (product.ProcessingType.Description.ToUpper().Contains("CNC")) {
                    //    if (product.ProcessingType.Description.ToUpper().Contains("VF2")) {
                    //        processingType = "CNC (VF2)";
                    //    }
                    //    else {
                    //        processingType = "CNC (VF1)";
                    //    }
                    //}
                    var camesDiagram = vfi.SelectDiagram1.Where(x => productIds.Contains(x.ProductId)).ToList();
                    var vf2Diagram = vfi.SelectDiagram3.Where(x => productIds.Contains(x.ProductId)).ToList();
                    var cncDiagram = vfi.SelectDiagram2.Where(x => productIds.Contains(x.ProductId)).ToList();
                    if (cames != cnc) {
                        products = products.Where(p => p.ProcessingDesign != null).ToList();
                        if (cames) {
                            products = products.Where(p => p.ProcessingType.Description.ToUpper().Contains("CAMES")).ToList();
                        }
                        else if (cnc) {
                            products = products.Where(p => p.ProcessingType.Description.ToUpper().Contains("CNC")).ToList();
                        }
                    }
                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity2();
                    var totalInvs = (from pi in vfi.ProductInventories
                                    where productIds.Contains(pi.ProductId) &&
                                          warehouses.Contains(pi.WarehouseId) &&
                                          pi.TotalQty > 0
                                    select new {
                                        pi.ProductId,
                                        pi.WarehouseId,
                                        pi.TotalQty,
                                    }).ToList();

                    // xuat ban trong thang
                    var exports = (from id in vfi.InvoiceDetails
                                  where id.Active &&
                                        id.Invoice.ShipmentDate.Value.Month == startMonth.Month &&
                                        id.Invoice.ShipmentDate.Value.Year == startMonth.Year &&
                                        productIds.Contains(id.ProductId.Value)
                                  //(customerId == 0 || id.Invoice.CustomerId == customerId)
                                  select new {
                                      id.Piece,
                                      id.ProductId
                                  }).ToList();
                    var realTrackUpMachines = vfi.RealProductions.Where(r => productIds.Contains(r.ProductId) 
                                                && !r.Machine.MachineName.Contains("P")).ToList();

                    var materialIds = products.Select(x => x.MaterialId).Distinct().ToList();
                    //var materialInvs = from x in vfi.MaterialInventories
                    //                   where materialIds.Contains(x.MaterialId) && x.TotalQty > 0
                    //                   group by {}
                    //                   select new { 
                    //                        x.MaterialId,
                    //                        x.TotalQty,
                    //                        TotalQtyKg = x.TotalQty * x.UnitWeight
                    //                   };
                    var materialInvs = vfi.MaterialInventories
                        .Where(x => materialIds.Contains(x.MaterialId) && x.TotalQty > 0)
                        .GroupBy(x => new { x.MaterialId, x.Material.MaterialCode })
                        .Select(x => new {
                            MaterialId = x.Key.MaterialId,
                            MaterialCode = x.Key.MaterialCode,
                            Quantity = x.Sum(y => y.TotalQty),
                            QuantityKg = x.Sum(y => y.TotalQty * y.UnitWeight),
                        })
                        .ToList();

                    foreach (var product in products) {
                        //var exist = camesDiagram.Where(cd => cd.ProductId == product.ProductId).Any();
                        //if (exist) continue;
                        //exist = cncDiagram.Where(cd => cd.ProductId == product.ProductId).Any();
                        //if (exist) continue;
                        //exist = vf2Diagram.Where(cd => cd.ProductId == product.ProductId).Any();
                        //if (exist) continue;
                        var entity = new MachineSetupPlanModel {
                            ProductId = product.ProductId,
                            ProductCode = product.ProductCode,
                            CustomerCode = product.CustomerCode,
                            Function = product.MachineFunction
                        };

                        entity.TotalInv = totalInvs.Where(pi => pi.ProductId == entity.ProductId).ToList().Sum(pi => pi.TotalQty);

                        var orderDetailsById = orderDetails.Where(od => od.ProductId == entity.ProductId).ToList();
                        if (orderDetailsById.Any()) {
                            entity.OrderNumber = orderDetailsById.Sum(od => od.RequiedNumber);
                            entity.OrderDate = orderDetailsById.FirstOrDefault().DueDate;
                        }
                        var forecastById = forecast.Where(od => od.ProductId == entity.ProductId).ToList();
                        if (forecastById.Any()) {
                            entity.ForecastNumber = forecastById.Sum(od => od.Quantity);
                            entity.ForecastDate = forecastById.FirstOrDefault().ForecastDate;
                        }

                        if (entity.RequireNumber <= 0)
                            continue;
                        var realTrackUpMachinesById = realTrackUpMachines.Where(r => r.ProductId == entity.ProductId)
                            .OrderBy(r => r.Machine.MachineName);

                        var onDiagrams = camesDiagram.Where(cd => cd.ProductId == product.ProductId).Select(x => x.MachineName).ToList();
                        entity.MachineRunningList.AddRange(onDiagrams);
                        onDiagrams = cncDiagram.Where(cd => cd.ProductId == product.ProductId).Select(x=> x.MachineName).ToList();
                        entity.MachineRunningList.AddRange(onDiagrams);
                        onDiagrams = vf2Diagram.Where(cd => cd.ProductId == product.ProductId).Select(x => x.MachineName).ToList();
                        entity.MachineRunningList.AddRange(onDiagrams);
                        //exist = cncDiagram.Where(cd => cd.ProductId == product.ProductId).Any();
                        //exist = vf2Diagram.Where(cd => cd.ProductId == product.ProductId).Any();
                        foreach (var real in realTrackUpMachinesById) {
                            entity.MachineSetupHistoryList.Add(new MachineSetupHistory {
                                MachineId = real.MachineId.Value,
                                MachineName = real.Machine.MachineName,
                                MachineType = real.Machine.ProcessingType.TypeName,
                                Function = real.Machine.MachineFunction,
                                State = real.Machine.StateId ?? 1,
                            });
                        }
                        if (entity.RequireDate > DateTime.Now) {
                            var days = MyUtilities.Product.GetProductionDay(entity.ProductId, entity.RequireNumber);
                            entity.SetupDate = MyUtilities.Function.FromDate(entity.RequireDate.Value, days);
                            if (entity.SetupDate < DateTime.Now)
                                entity.SetupDate = DateTime.Now;
                        }
                        else {
                            entity.SetupDate = DateTime.Now;
                        }

                        var materialInv = materialInvs.FirstOrDefault(x => x.MaterialId == product.MaterialId);
                        if (materialInv != null) {
                            entity.MaterialCode = materialInv.MaterialCode;
                            entity.MaterialInv = materialInv.Quantity;
                            entity.MaterialInvKg = materialInv.QuantityKg;
                        }
                        model.Add(entity);
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("GetMachineSetupPlan", ex.Message);
            }
            return model;
        }
        
