        List<FactoryProductionProcessModel> GetFactoryProduction2ProcessReport(int customerId, string productCode,
            string fromPoDate, string toPoDate, string endYearForeacast, string toInvDate,
            string fromProductionDate, string toProductionDate,
            bool isGetAll) {
            var model = new List<FactoryProductionProcessModel>();
            var ci = new CultureInfo("vi-VN");
            var fromDate = string.IsNullOrWhiteSpace(fromPoDate)
                            ? DateTime.Now
                            : Convert.ToDateTime(fromPoDate, ci);
            var toDate = string.IsNullOrWhiteSpace(toPoDate)
                            ? DateTime.Now
                            : Convert.ToDateTime(toPoDate, ci);
            var toForecastDate = string.IsNullOrWhiteSpace(endYearForeacast)
                            ? DateTime.Now
                            : Convert.ToDateTime(endYearForeacast, ci);
            var invDate = string.IsNullOrWhiteSpace(toInvDate)
                            ? DateTime.Now
                            : Convert.ToDateTime(toInvDate, ci);
            var fProductionDate = string.IsNullOrWhiteSpace(fromProductionDate)
                            ? DateTime.Now
                            : Convert.ToDateTime(fromProductionDate, ci);
            var tProductionDate = fProductionDate.AddDays(7);
            var startExport = new DateTime(invDate.Year, invDate.Month, 1);
            var expiredTrackingMachine = invDate.AddDays(15);
            using (var vfi = new tammaContext()) {
                var productionProcesses = (from pp in vfi.ProductionProcesses
                                          where pp.IsNecessary && 
                                                pp.WarehouseId == MyUtilities.Warehouse.Production2
                                          orderby pp.ProcessIndex descending
                                          select pp).ToList();
                var productIds = productionProcesses.Select(od => od.ProductId).ToList();
                var orderDetails = (from od in vfi.OrderDetails
                                    where
                                                od.Order.DueDate != null &&
                                                od.Order.DueDate <= toDate &&
                                                (customerId == 0 || od.Order.CustomerId == customerId) &&
                                                (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                                 od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                                od.RequiedNumber > 0 &&
                                                productIds.Contains(od.ProductId)
                                    orderby od.Order.DueDate
                                    select new {
                                        od.ProductId,
                                        DueDate = od.Order.DueDate.Value,
                                        Quantity = od.RequiedNumber
                                    }).ToList();
                var startMonth = new DateTime(fromDate.Year, fromDate.Month, 1);
                var forecasts = (from f in vfi.ForecastOrders
                                where f.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                f.ForecastDate <= toDate &&
                                f.ForecastDate >= fromDate &&
                                (customerId == 0 || f.Product.Customer.CustomerId == customerId) &&
                                productIds.Contains(f.ProductId)
                                orderby f.ForecastDate
                                select new {
                                    f.ProductId,
                                    DueDate = f.ForecastDate,
                                    f.Quantity
                                }).ToList();
                productIds = orderDetails.Select(od => od.ProductId).ToList();
                var productIds2 = forecasts.Select(od => od.ProductId).ToList();
                productIds.AddRange(productIds2);
                productIds = productIds.Distinct().ToList();
                var products = (from p in vfi.Products
                                where p.Active && productIds.Contains(p.ProductId)
                                orderby p.Customer.CustomerCode, p.ProductCode
                                select new {
                                    p.ProductId,
                                    p.ProductCode,
                                    p.CustomerId,
                                    p.Customer.CustomerCode,
                                    Productivity = p.Productivity ?? 0,
                                    MillProductivity = p.MillProductivity ?? 0,
                                    p.ProcessingType,
                                    p.ForecastsQuality
                                }).ToList();
                if (!string.IsNullOrWhiteSpace(productCode))
                    products = products.Where(p => p.ProductCode.Contains(productCode)).ToList();
                productIds = products.Select(p => p.ProductId).ToList();

                var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity2();
                var invPeriods = (from pi in vfi.ProductInventoryPeriods
                                 where productIds.Contains(pi.ProductId) &&
                                       warehouses.Contains(pi.WarehouseId) &&
                                       pi.Quantity > 0 &&
                                       pi.PeriodDate <= invDate
                                 select new {
                                     pi.ProductId,
                                     pi.WarehouseId,
                                     pi.LastPeriodQuantity,
                                     pi.EarlyPeriodQuantity,
                                     pi.PeriodDate,
                                     pi.Transaction.WarehouseIssueId,
                                     pi.Transaction.WarehouseReceiptId,
                                 }).ToList();
                //var productionProcesses = from pp in vfi.ProductionProcesses
                //                          where productIds.Contains(pp.ProductId) &&
                //                                pp.IsNecessary && pp.IsAlert
                //                          orderby pp.ProcessIndex descending
                //                          select pp;
                productionProcesses = productionProcesses.Where(x => productIds.Contains(x.ProcessId)).ToList();
                //var importSx1Details = (from sx in vfi.ImportFormSX1Detail
                //                        where sx.ImportFormSX1.MaterialUseDate >= fProductionDate &&
                //                            sx.ImportFormSX1.MaterialUseDate < tProductionDate &&
                //                             sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                //                             sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                //                             sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                //                                 .Transaction.Status ==
                //                             (byte)MyUtilities.Transaction.Status.Approved &&
                //                              sx.Number1 + sx.Number2 > 0
                                               //&& sx.ImportFormSX1.Status==( byte) MyUtilities.Transaction.Status.Approved
                //                        orderby sx.ImportFormSX1.ImportDate
                //                        select new {
                //                            sx.MachineId,
                //                            sx.ImportFormSX1.MaterialUseDate,
                //                            sx.ProductId,
                //                            Quantity = sx.Number1 + sx.Number2,
                //                        }).ToList();
                var warehouse2Process = MyUtilities.Warehouse.GetWarehouseIdProduction2_PROCESS();
                var importSx1Details = (from sx in invPeriods
                                        where sx.PeriodDate >= fProductionDate &&
                                            sx.PeriodDate <= tProductionDate &&
                                            sx.WarehouseIssueId != null &&
                                            warehouse2Process.Contains(sx.WarehouseIssueId.Value) &&
                                            sx.LastPeriodQuantity > sx.EarlyPeriodQuantity
                                        orderby sx.PeriodDate
                                        select new {
                                            sx.PeriodDate,
                                            sx.ProductId,
                                            Quantity = sx.LastPeriodQuantity - sx.EarlyPeriodQuantity,
                                            sx.WarehouseIssueId,
                                            sx.WarehouseReceiptId,
                                        }).ToList();
                var lastProductionDate = fProductionDate;
                //if (importSx1Details.Any())
                //    lastProductionDate = importSx1Details.Max(x => x.MaterialUseDate);
                // xuat ban trong thang
                var exports = (from id in vfi.InvoiceDetails
                              where id.Active &&
                                    id.Invoice.ShipmentDate >= startExport &&
                                    id.Invoice.ShipmentDate <= invDate &&
                                    productIds.Contains(id.ProductId.Value)
                              select new {
                                  id.ProductId,
                                  Quantity = id.Piece
                              }).ToList();
                var smartProductions = (from sp in vfi.SmartProductions
                                       where productIds.Contains(sp.ProductId.Value) &&
                                       sp.Machine.MachineName.Contains("C") &&
                                       !sp.Machine.MachineName.Contains("CNC")
                                       select sp).ToList();
                var realProductions = (from rp in vfi.RealProductions
                                      where productIds.Contains(rp.ProductId)
                                      select rp).ToList();
                var saved = false;
                var warehouse2 = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                foreach (var product in products) {
                    // 1
                    var entity = new FactoryProductionProcessModel() {
                        CustomerId = product.CustomerId,
                        CustomerCode = product.CustomerCode,
                        ProductId = product.ProductId,
                        ProductCode = product.ProductCode,
                        Productivity = product.Productivity,
                        AfterInvQuantity = 0.0
                    };
                    // 5
                    var invsById = invPeriods.Where(pi => pi.ProductId == entity.ProductId).ToList();
                    var processesById = MyUtilities.Product.GetCalculatedProductionProcess(entity.ProductId);
                    var processes = processesById.FirstOrDefault(pp => pp.WarehouseProcessId == MyUtilities.Warehouse.Production2);
                    var afterInvs = invsById.Where(pi => processes.AfterWarehouseProcessIds.Contains(pi.WarehouseId))
                        .ToList();
                    if (afterInvs.Any())
                        entity.AfterInvQuantity = afterInvs.Sum(pi => pi.LastPeriodQuantity - pi.EarlyPeriodQuantity);
                    afterInvs = invsById.Where(pi => warehouse2.Contains(pi.WarehouseId))
                        .ToList();
                    if (afterInvs.Any())
                        entity.InvQuantity = afterInvs.Sum(pi => pi.LastPeriodQuantity - pi.EarlyPeriodQuantity);
                    // 2
                    var orderDetailsById = orderDetails.Where(od => od.ProductId == entity.ProductId).ToList();
                    entity.OrderQuantity = orderDetailsById.Sum(x => x.Quantity);
                    var calculateAfterInv = entity.AfterInvQuantity;
                    foreach (var detail in orderDetailsById) {
                        var quantity = (double)detail.Quantity;
                        if (quantity > calculateAfterInv) {
                            quantity -= calculateAfterInv;
                            calculateAfterInv = 0;
                        }
                        else {
                            quantity = 0;
                            calculateAfterInv -= quantity;
                        }
                        if (quantity == 0) continue;
                        var dayLeft = MyUtilities.Function.DaysNoSunDay(invDate, detail.DueDate);
                        if (dayLeft > 0) {
                            var max = (double)detail.Quantity / dayLeft;
                            if (max > entity.OrderQuantityPerDay)
                                entity.OrderQuantityPerDay = max; // 9.1
                        }
                        else {
                            var max = detail.Quantity;
                            if (max > entity.OrderQuantityPerDay)
                                entity.OrderQuantityPerDay = max; // 9.1
                        }
                        if (string.IsNullOrWhiteSpace(entity.OrderNote)) {
                            entity.OrderNote = detail.DueDate.ToString("dd/MM") + ":" + string.Format("{0:n0}", detail.Quantity);
                        }
                    }
                    // 4
                    var exportsById = exports.Where(ed => ed.ProductId == entity.ProductId).ToList();
                    entity.ExportQuantity = exportsById.Sum(ed => ed.Quantity);
                    // 3
                    var forecastsById = forecasts.Where(f => f.ProductId == entity.ProductId).ToList();
                    entity.ForecastQuantity = forecastsById.Sum(x => x.Quantity) - entity.ExportQuantity;
                    var exportInMonth = entity.ExportQuantity + entity.AfterInvQuantity;
                    foreach (var detail in forecastsById) {
                        var quantity = detail.Quantity;
                        if (detail.DueDate >= startMonth && detail.DueDate <= invDate) {
                            if (quantity > exportInMonth) {
                                quantity -= exportInMonth;
                                exportInMonth = 0;
                            }
                            else {
                                quantity = 0;
                                exportInMonth -= quantity;
                            }
                        }
                        if (quantity == 0) continue;
                        var dayLeft = MyUtilities.Function.DaysNoSunDay(invDate, detail.DueDate);
                        if (dayLeft > 0) {
                            var max = (double)quantity / dayLeft;
                            if (max > entity.ForecastQuantityPerDay)
                                entity.ForecastQuantityPerDay = max; // 9.2
                        }
                    }

                    // 6 on base
                    if (saved) {

                    }
                    else {

                    }

                    if (!isGetAll) {
                        if (entity.RequireQuantityCalculate < 0)
                            continue;
                    }

                    var smartProductionsById = smartProductions.Where(sp => sp.ProductId == entity.ProductId).ToList();
                    foreach (var smartProduction in smartProductionsById) {
                        entity.MachineCount = 0;
                        var realProductionById = realProductions.FirstOrDefault(rp => rp.ProductId == entity.ProductId
                                                                                && rp.MachineId == smartProduction.MachineId);
                        if (realProductionById != null) {
                            //if (realProductionById.TrackUpMachine.DeliveryDate >= expiredTrackingMachine) {
                            // 7
                            entity.MachineCount++;
                            // 8
                            entity.RealProductivityInDay += MyUtilities.Product.GetProductionRateInFactoryDayTime(
                                                                realProductionById.TrackUpMachine.RealProductivity);
                            //}
                        }
                    }

                    // 9.3 on base
                    // 9.4 on base
                    // 9.5 on base

                    // 10
                    var importSx1DetailsById = importSx1Details.Where(id => id.ProductId == entity.ProductId
                                            && processes.AfterWarehouseProcessIds.Contains(id.WarehouseReceiptId.Value));
                    var causeDate = fProductionDate;
                    for (int i = 1; i <= 7; i++) {
                        var productionDay = new ProductionDay() {
                            ProductionCount = 0,
                            ProductionQuantity = 0,
                            ProductionQuantityCalculate = entity.ProductivityInDayPlan,
                            ProductionQuantitySaved = 0,
                            ProductionDate = causeDate,
                            DayOfWeek = causeDate.DayOfWeek + ""
                        };
                        entity.RealProductions.Add(productionDay);

                        var importSx1DetailsByDate = importSx1DetailsById.Where(id => id.PeriodDate == causeDate);
                        if (importSx1DetailsByDate.Any()) {
                            productionDay.ProductionQuantity = importSx1DetailsByDate.Sum(x => x.Quantity);
                        }
                        if (causeDate.DayOfWeek == DayOfWeek.Sunday) {
                            productionDay.ProductionQuantityCalculate = 0;
                        }
                        causeDate = causeDate.AddDays(1);
                    }

                    //11 on base
                    //12 on base
                    //13 on base

                    model.Add(entity);

                }
            }
            return model;
        }

