        List<FactoryProductionProcessModel> GetFactoryProductionProcessReport(int customerId, string productCode,
            string fromPoDate, string toPoDate, string endYearForeacast, string toInvDate,
            string fromProductionDate, string toProductionDate,
            bool isGetAll) {
            var model = new List<FactoryProductionProcessModel>();
