        [GridAction]
        public ActionResult SelectFactoryCNCProcessReport(int customerId, string productCode,
            string fromPoDate, string toPoDate, string endYearForeacast, string invDate,
            string fromProductionDate, string toProductionDate,
            bool isGetAll) {
            var model = new List<FactoryProductionProcessModel>();
            if (string.IsNullOrWhiteSpace(toPoDate))
                return View(new GridModel(model));
            try {
                model = GetFactoryCNCProcessReport(customerId, productCode,
                    fromPoDate, toPoDate, endYearForeacast, invDate,
                    fromProductionDate, toProductionDate,
                    isGetAll);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectFactoryCNCProcessReport", ex.Message);
            }
            return View(new GridModel(model));
        }

