        [GridAction]
        public ActionResult SelectProductionBalancingPlan(int customerId, string productCode,
            string fromPoDate, string toPoDate, string invDate,
            int type, bool isAllOrder) {
            var model = new List<ProductionBalancingModel>();
            if (string.IsNullOrWhiteSpace(toPoDate))
                return View(new GridModel(model));
            try {
                model = GetProductionBalancingPlan(customerId, productCode, fromPoDate, toPoDate, invDate, type, isAllOrder);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectProductionBalancingPlan", ex.Message);
            }
            return View(new GridModel(model));
        }

        List<ProductionBalancingModel> GetProductionBalancingPlan(int customerId, string productCode,
            string fromPoDate, string toPoDate, string invDate,
            int type, bool isAllOrder) {
            var model = new List<ProductionBalancingModel>();
            try {
                var ci = new CultureInfo("vi-VN");
                var fromdate = string.IsNullOrWhiteSpace(fromPoDate)
                                ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                                : Convert.ToDateTime(fromPoDate, ci);
                var podate = string.IsNullOrWhiteSpace(toPoDate)
                                ? new DateTime(DateTime.Now.Year, DateTime.Now.Month, 1)
                                : Convert.ToDateTime(toPoDate, ci);
                var invdate = string.IsNullOrWhiteSpace(invDate)
                                ? DateTime.Now
                                : Convert.ToDateTime(invDate, ci);
                // binh quan tinh 1 tuan
                var accumulativeFromDate = invdate.AddDays(-7);
                // binh quan tinh tu luy ke san xuat
                //var accumulativeFromDate = new DateTime(invdate.Year, invdate.Month, 26);
                //if (invdate.Day < 26) {
                //    accumulativeFromDate = accumulativeFromDate.AddMonths(-1);
                //}
                using (var vfi = new tammaContext()) {
                    var orderDetails = (from od in vfi.OrderDetails
                                        where
                                            od.Order.DueDate != null &&
                                            od.Order.DueDate <= podate &&
                                            od.Order.DueDate > MyUtilities.Sales.StartOrderDate &&
                                            (customerId == 0 || od.Order.CustomerId == customerId) &&
                                            (od.Order.Status == (byte)MyUtilities.Sales.Status.Waiting ||
                                             od.Order.Status == (byte)MyUtilities.Sales.Status.InProcess) &&
                                            od.RequiedNumber > 0
                                        orderby od.Order.DueDate
                                        select new {
                                            //od.OrderDetailId,
                                            od.ProductId,
                                            //od.Product,
                                            //od.Order,
                                            DueDate = od.Order.DueDate.Value,
                                            //od.OrderQty,
                                            Quantity = od.RequiedNumber * 1.0,
                                            //OrderDate = od.Order.OrderDate < DateTime.Now ? DateTime.Now.Date : od.Order.OrderDate,
                                            //od.Order.OrderDate,
                                        }).ToList();
                    var startMonth = new DateTime(fromdate.Year, fromdate.Month, 1);
                    var forecast = from f in vfi.ForecastOrders
                                   where f.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                   f.ForecastDate <= podate &&
                                   f.ForecastDate >= fromdate &&
                                   f.ForecastDate >= startMonth
                                   orderby f.ForecastDate
                                   select new {
                                       f.ProductId,
                                       DueDate = f.ForecastDate,
                                       f.Quantity
                                   };

                    var productIds = orderDetails.Select(od => od.ProductId).Distinct().ToList();
                    if (type == 2) {
                        productIds = forecast.Select(od => od.ProductId).Distinct().ToList();
                    }

                    var products = (from p in vfi.Products
                                    where p.Active && productIds.Contains(p.ProductId)
                                    orderby p.Customer.CustomerCode, p.ProductCode
                                    select new {
                                        p.ProductId,
                                        p.ProductCode,
                                        p.CustomerId,
                                        p.Customer.CustomerCode,
                                        Productivity = p.Productivity ?? 0,
                                        MillProductivity = p.MillProductivity ?? 0,
                                        p.ProcessingType
                                        //p.id,
                                    }).ToList();
                    if (!string.IsNullOrWhiteSpace(productCode))
                        products = products.Where(p => p.ProductCode.Contains(productCode)).ToList();
                    productIds = products.Select(p => p.ProductId).ToList();

                    var warehouses = MyUtilities.Warehouse.GetWarehouseId_SumTotalQuantity2();
                    var totalInvs = from pi in vfi.ProductInventories
                                    where productIds.Contains(pi.ProductId) &&
                                          warehouses.Contains(pi.WarehouseId) &&
                                          pi.TotalQty > 0
                                    select new {
                                        pi.ProductId,
                                        pi.WarehouseId,
                                        pi.TotalQty,
                                    };
                    var cncInvs = from pi in totalInvs
                                  where productIds.Contains(pi.ProductId) &&
                                        pi.WarehouseId == MyUtilities.Warehouse.Cnc &&
                                        pi.TotalQty > 0
                                  select new {
                                      pi.ProductId,
                                      pi.TotalQty,
                                  };
                    var production2Warehouses = MyUtilities.Warehouse.GetWarehouseIdProduction2_ALL();
                    var production2Invs = from pi in totalInvs
                                          where productIds.Contains(pi.ProductId) &&
                                                production2Warehouses.Contains(pi.WarehouseId) &&
                                                pi.TotalQty > 0
                                          select new {
                                              pi.ProductId,
                                              pi.TotalQty,
                                          };

                    var productionProcesses = from pp in vfi.ProductionProcesses
                                              where productIds.Contains(pp.ProductId) &&
                                                    pp.IsNecessary && pp.IsAlert
                                              select pp;
                    // lay tat ca section 
                    var productionSections = from ps in vfi.ProductionSections
                                             where productIds.Contains(ps.ProductId) &&
                                                   ps.Active &&
                                                   ps.SectionId != MyUtilities.Section.ReProcessSection &&
                                                   ps.Productivity > 0
                                             select ps;

                    var noProcessWarehouse = MyUtilities.Warehouse.GetWarehouseId_NotSumTotalQuantity2();
                    var cncTransactionDetails = from td in vfi.TransactionDetails
                                                where td.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Cnc &&
                                                      !noProcessWarehouse.Contains(td.Transaction.WarehouseReceiptId.Value) &&
                                                      td.Transaction.CreatedDate == invdate &&
                                                      productIds.Contains(td.ReferenceId.Value) &&
                                                      td.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                                select new {
                                                    td.ReferenceId,
                                                    td.Quantity
                                                };

                    var warehouses2_process = MyUtilities.Warehouse.GetWarehouseIdProduction2_PROCESS();
                    var production2TransactionDetails = from td in vfi.TransactionDetails
                                                        where td.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                              td.Transaction.CreatedDate == invdate &&
                                                              productIds.Contains(td.ReferenceId.Value) &&
                                                            (td.Transaction.WarehouseIssueId != null &&
                                                            warehouses2_process.Contains(td.Transaction.WarehouseIssueId.Value)) &&
                                                            (td.Transaction.WarehouseReceiptId != null &&
                                                            !noProcessWarehouse.Contains(td.Transaction.WarehouseIssueId.Value))
                                                        select new {
                                                            td.ReferenceId,
                                                            td.Quantity
                                                        };

                    var importSx1Details = (from sx in vfi.ImportFormSX1Detail
                                            where sx.ImportFormSX1.ImportDate == invdate &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                 sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                     .Transaction.Status ==
                                                 (byte)MyUtilities.Transaction.Status.Approved
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                            select new {
                                                sx.MachineId,
                                                sx.ProductId,
                                                Quantity = sx.Number1 + sx.Number2,
                                            }).ToList();

                    var accumulativeSx1 = (from sx in vfi.ImportFormSX1Detail
                                           where sx.ImportFormSX1.ImportDate >= accumulativeFromDate &&
                                           sx.ImportFormSX1.ImportDate < invdate &&
                                                sx.ImportFormSX1.ImportWorkpieceMaterials.Any() &&
                                                sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault() != null &&
                                                sx.ImportFormSX1.ImportWorkpieceMaterials.FirstOrDefault()
                                                    .Transaction.Status ==
                                                (byte)MyUtilities.Transaction.Status.Approved
                                               && sx.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved
                                           select new {
                                               sx.MachineId,
                                               sx.ProductId,
                                               Quantity = sx.Number1 + sx.Number2,
                                           }).ToList();

                    var accumulativeSx2 = from td in vfi.TransactionDetails
                                          where td.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                td.Transaction.CreatedDate >= accumulativeFromDate &&
                                                td.Transaction.CreatedDate < invdate &&
                                                productIds.Contains(td.ReferenceId.Value) &&
                                              (td.Transaction.WarehouseIssueId != null &&
                                              warehouses2_process.Contains(td.Transaction.WarehouseIssueId.Value)) &&
                                              (td.Transaction.WarehouseReceiptId != null &&
                                              !noProcessWarehouse.Contains(td.Transaction.WarehouseIssueId.Value))
                                          select new {
                                              td.ReferenceId,
                                              td.Quantity
                                          };

                    var accumulativeCnc = from td in vfi.TransactionDetails
                                          where td.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved &&
                                                td.Transaction.CreatedDate >= accumulativeFromDate &&
                                                td.Transaction.CreatedDate < invdate &&
                                                productIds.Contains(td.ReferenceId.Value) &&
                                              td.Transaction.WarehouseIssueId != null &&
                                              td.Transaction.WarehouseIssueId == MyUtilities.Warehouse.Cnc &&
                                              td.Transaction.WarehouseReceiptId != null &&
                                              !noProcessWarehouse.Contains(td.Transaction.WarehouseIssueId.Value)
                                          select new {
                                              td.ReferenceId,
                                              td.Quantity
                                          };
                    var dayCount = MyUtilities.Function.DaysNoSunDay(accumulativeFromDate, invdate);

                    // xuat ban trong thang
                    var exports = from id in vfi.InvoiceDetails
                                  where id.Active &&
                                        id.Invoice.ShipmentDate.Value.Month == startMonth.Month &&
                                        id.Invoice.ShipmentDate.Value.Year == startMonth.Year &&
                                        productIds.Contains(id.ProductId.Value)
                                  //(customerId == 0 || id.Invoice.CustomerId == customerId)
                                  select new {
                                      id.Piece,
                                      id.ProductId
                                  };
                    var qcWarehouses = MyUtilities.Warehouse.GetWarehouseIdQc();
                    var platingWarehouses = MyUtilities.Warehouse.GetWarehouseIds_Plating();
                    var now = DateTime.Now.Date;
                    foreach (var product in products) {
                        // inventory
                        var totalInvById = totalInvs.Where(pi => pi.ProductId == product.ProductId).ToList().Sum(pi => pi.TotalQty);
                        var totalInvByIdAfter = totalInvById;

                        var finishInvById = totalInvs.Where(pi => pi.ProductId == product.ProductId && pi.WarehouseId == MyUtilities.Warehouse.Finish)
                            .ToList().Sum(pi => pi.TotalQty);

                        var packingInvById = totalInvs.Where(pi => pi.ProductId == product.ProductId && pi.WarehouseId == MyUtilities.Warehouse.Packing)
                            .ToList().Sum(pi => pi.TotalQty);

                        var qcInvById = totalInvs.Where(pi => pi.ProductId == product.ProductId && qcWarehouses.Contains(pi.WarehouseId))
                            .ToList().Sum(pi => pi.TotalQty);

                        var platingInvById = totalInvs.Where(pi => pi.ProductId == product.ProductId && platingWarehouses.Contains(pi.WarehouseId))
                            .ToList().Sum(pi => pi.TotalQty);

                        var cncInvById = cncInvs.Where(pi => pi.ProductId == product.ProductId).ToList().Sum(pi => pi.TotalQty);
                        var cncInvByIdAfter = cncInvById;

                        var production2InvById = production2Invs.Where(pi => pi.ProductId == product.ProductId).ToList().Sum(pi => pi.TotalQty);
                        var production2InvByIdAfter = production2InvById;
                        // after production process day
                        var penaltyDay = 5;
                        var process =
                           productionProcesses.FirstOrDefault(
                               pp => pp.ProductId == product.ProductId && pp.WarehouseId == MyUtilities.Warehouse.WaitingPlating);
                        if (process != null) {
                            penaltyDay += 7;
                        }
                        process =
                           productionProcesses.FirstOrDefault(
                               pp => pp.ProductId == product.ProductId && pp.WarehouseId == MyUtilities.Warehouse.HeatTreatment);
                        if (process != null) {
                            penaltyDay += 1;
                        }
                        process =
                           productionProcesses.FirstOrDefault(
                               pp => pp.ProductId == product.ProductId && pp.WarehouseId == MyUtilities.Warehouse.SurfaceTreatment);
                        if (process != null) {
                            penaltyDay += 1;
                        }

                        var afterTotal = -1.0;
                        var afterCnc = -1.0;
                        var afterProduction2 = -1.0;
                        var production1 = -1.0;
                        var productioncnc = -1.0;
                        var production2 = -1.0;
                        var totalRequireQuantity1 = 0.0;
                        var totalRequireQuantityCnc = 0.0;
                        var totalRequireQuantity2 = 0.0;
                        var totalProduction1 = 0.0;
                        var totalProductionCnc = 0.0;
                        var totalProduction2 = 0.0;

                        var orderDetailsById = orderDetails.Where(od => od.ProductId == product.ProductId).ToList();
                        if (type == 2) {
                            orderDetailsById = forecast.Where(f => f.ProductId == product.ProductId).ToList();
                        }
                        var orderDates = orderDetailsById.Select(od => od.DueDate).Distinct().ToList();

                        //var requireQuantity = 0.0;
                        //var afterCnc = -1.0;
                        //var afterProduction2 = -1.0;
                        var processingType = "NULL";
                        if (product.ProcessingType != null) {
                            if (product.ProcessingType.Description.ToUpper().Contains("CAMES")) {
                                processingType = "CAMES";
                            }
                            else if (product.ProcessingType.Description.ToUpper().Contains("CNC")) {
                                if (product.ProcessingType.Description.ToUpper().Contains("VF2")) {
                                    processingType = "CNC (VF2)";
                                }
                                else {
                                    processingType = "CNC (VF1)";
                                }
                            }
                        }

                        var accumulativeSx1ById = accumulativeSx1.Where(a => a.ProductId == product.ProductId)
                                                                .ToList()
                                                                .Sum(a => a.Quantity);
                        var accumulativeSx2ById = accumulativeSx2.Where(a => a.ReferenceId == product.ProductId)
                                                                .ToList()
                                                                .Sum(a => a.Quantity);
                        var accumulativeCncById = accumulativeCnc.Where(a => a.ReferenceId == product.ProductId)
                                                                .ToList()
                                                                .Sum(a => a.Quantity);

                        var flag = "";
                        var list = new List<ProductionBalancingModel>();
                        foreach (var orderDate in orderDates) {
                            var entity = new ProductionBalancingModel() {
                                ProductId = product.ProductId,
                                ProductCode = product.ProductCode,
                                CustomerId = product.CustomerId,
                                CustomerCode = product.CustomerCode,
                                TotalInv = totalInvById,
                                FinishInv = finishInvById,
                                QcInv = qcInvById,
                                PackingInv = packingInvById,
                                PlatingInv = platingInvById,
                                PoDate = orderDate,
                                Type = flag,
                                PenaltyDay = penaltyDay,
                                DayCount = dayCount
                            };
                            var orderDetailsByDate = orderDetailsById.Where(od => od.DueDate == orderDate).ToList();
                            entity.PoQuantity = orderDetailsByDate.Sum(od => od.Quantity);
                            entity.ExportInv = exports.Where(e => e.ProductId == entity.ProductId).ToList().Sum(e => e.Piece);
                            if (type == 2 && orderDate.Month == startMonth.Month && orderDate.Year == startMonth.Year) {
                                // export
                                if (entity.ExportInv > entity.PoQuantity)
                                    continue;
                                entity.PoQuantity -= entity.ExportInv;
                            }
                            //
                            // requireQuantity += (entity.PoQuantity * 1.1);
                            // entity.RequireQuantity = requireQuantity;
                            //
                            //entity.RequireQuantity = entity.PoQuantity * 1.1;
                            entity.RequireQuantity = entity.PoQuantity;

                            #region production 2
                            process =
                               productionProcesses.FirstOrDefault(
                                   pp => pp.ProductId == entity.ProductId && pp.WarehouseId == MyUtilities.Warehouse.Production2);
                            if (process != null) {
                                entity.Production2.InvQuantity = production2InvById;
                                if (production2 < 0) {
                                    production2 = production2TransactionDetails.Where(td => td.ReferenceId == entity.ProductId)
                                                                                                       .ToList()
                                                                                                       .Sum(td => td.Quantity);
                                    totalProduction2 = production2;
                                }
                                entity.Production2.ProductionQuantity = production2;
                                entity.Production2.TotalProductionQuantity = totalProduction2;
                                var processAfter = productionProcesses.Where(pp => pp.ProductId == entity.ProductId &&
                                                                                        pp.ProcessIndex > process.ProcessIndex);
                                var warehouseIds = processAfter.Select(pp => pp.WarehouseId).ToList();
                                if (!warehouseIds.Any())
                                    goto cnc;
                                if (afterProduction2 < 0) {
                                    if (warehouseIds.Contains(MyUtilities.Warehouse.QcA) || warehouseIds.Contains(MyUtilities.Warehouse.QcB)) {
                                        warehouseIds.AddRange(qcWarehouses);
                                    }
                                    if (warehouseIds.Contains(MyUtilities.Warehouse.WaitingPlating)) {
                                        warehouseIds.AddRange(platingWarehouses);
                                    }
                                    warehouseIds = warehouseIds.Distinct().ToList();
                                    afterProduction2 = totalInvs.Where(pi => pi.ProductId == entity.ProductId && warehouseIds.Contains(pi.WarehouseId))
                                                                                    .ToList()
                                                                                    .Sum(pi => pi.TotalQty);
                                }
                                entity.Production2.AfterInvQuantity = afterProduction2;
                                entity.Production2.RequireQuantity = entity.RequireQuantity - entity.Production2.AfterInvQuantity;
                                if (entity.Production2.RequireQuantity <= 0) {
                                    entity.Production2.RequireQuantity = 0;
                                    afterProduction2 -= entity.RequireQuantity;
                                    //continue;
                                }
                                else {
                                    afterProduction2 = 0;
                                    totalRequireQuantity2 += entity.Production2.RequireQuantity;
                                    entity.Production2.TotalRequireQuantity = totalRequireQuantity2;
                                    entity.Production2.Process = 1;
                                    var productionSectionsById = productionSections.Where(ps => ps.ProductId == entity.ProductId).ToList();
                                    if (productionSectionsById.Any()) {
                                        entity.Production2.Productivity = productionSectionsById.Max(ps => ps.Productivity);
                                        entity.Production2.Process = productionSectionsById.Count();
                                    }
                                    if (entity.Production2.Productivity > 0) {
                                        entity.Production2.ProductionRatePerDay =
                                            MyUtilities.Product.GetProductionRateInDayTime(entity.Production2.Productivity);
                                    }
                                    entity.Production2.PlanProductionDay = entity.PlanProductionDay;
                                }
                                // sản xuất 2 sản lượng thấp hơn yêu cầu
                                //if (entity.Production2.RequireProduction < 0 && string.IsNullOrWhiteSpace(entity.Type)) {
                                //    entity.Type = "SX2";
                                //    flag = entity.Type;
                                //}
                                // sản xuất 2 có yêu cầu sản xuất
                                if (totalRequireQuantity2 > 0 && string.IsNullOrWhiteSpace(entity.Type)) {
                                    entity.Type = "SX2";
                                    flag = entity.Type;
                                }
                                if (production2 > entity.Production2.RequirePerDay)
                                    production2 -= entity.Production2.RequirePerDay;
                                else
                                    production2 = 0;
                            }
                            #endregion
                        cnc:
                            #region cnc
                            // cnc case
                            process =
                               productionProcesses.FirstOrDefault(
                                   pp => pp.ProductId == entity.ProductId && pp.WarehouseId == MyUtilities.Warehouse.Cnc);
                            if (process != null) {
                                entity.Cnc.InvQuantity = cncInvById;
                                if (productioncnc < 0) {
                                    productioncnc = cncTransactionDetails.Where(td => td.ReferenceId == entity.ProductId)
                                                                                   .ToList()
                                                                                   .Sum(td => td.Quantity);
                                    totalProductionCnc = productioncnc;
                                }
                                entity.Cnc.ProductionQuantity = productioncnc;
                                entity.Cnc.TotalProductionQuantity = totalProductionCnc;
                                var processAfter = productionProcesses.Where(pp => pp.ProductId == entity.ProductId &&
                                                                                        pp.ProcessIndex > process.ProcessIndex);
                                var warehouseIds = processAfter.Select(pp => pp.WarehouseId).ToList();
                                if (!warehouseIds.Any())
                                    goto production1;
                                if (afterCnc < 0) {
                                    if (warehouseIds.Contains(MyUtilities.Warehouse.QcA) || warehouseIds.Contains(MyUtilities.Warehouse.QcB)) {
                                        warehouseIds.AddRange(qcWarehouses);
                                    }
                                    if (warehouseIds.Contains(MyUtilities.Warehouse.WaitingPlating)) {
                                        warehouseIds.AddRange(platingWarehouses);
                                    }
                                    if (warehouseIds.Contains(MyUtilities.Warehouse.Production2)) {
                                        warehouseIds.AddRange(production2Warehouses);
                                    }
                                    warehouseIds = warehouseIds.Distinct().ToList();
                                    afterCnc = totalInvs.Where(pi => pi.ProductId == entity.ProductId && warehouseIds.Contains(pi.WarehouseId))
                                                                .ToList()
                                                                .Sum(pi => pi.TotalQty);
                                }
                                entity.Cnc.AfterInvQuantity = afterCnc;
                                entity.Cnc.RequireQuantity = entity.RequireQuantity - entity.Cnc.AfterInvQuantity;
                                if (entity.Cnc.RequireQuantity <= 0) {
                                    afterCnc -= entity.RequireQuantity;
                                    entity.Cnc.RequireQuantity = 0;
                                    //if (entity.Production2.Process > 0)
                                    //    goto add;
                                    //else continue;
                                }
                                else {
                                    afterCnc = 0;
                                    totalRequireQuantityCnc += entity.Cnc.RequireQuantity;
                                    entity.Cnc.TotalRequireQuantity = totalRequireQuantityCnc;
                                    entity.Cnc.Process = 1;
                                    if (product.MillProductivity > 0) {
                                        entity.Cnc.Productivity = product.MillProductivity;
                                        entity.Cnc.ProductionRatePerDay =
                                            MyUtilities.Product.GetProductionRateInFactoryDayTime(product.MillProductivity);
                                    }
                                    entity.Cnc.PlanProductionDay = entity.PlanProductionDay;
                                    if (entity.Cnc.PlanProductionDay > entity.Production2.Process) {
                                        entity.Cnc.PlanProductionDay -= (entity.Production2.Process);
                                    }
                                }
                                // cnc sản lượng thấp hơn yêu cầu
                                //if (entity.Cnc.RequireProduction < 0
                                //    && (flag.Equals("SX2") || string.IsNullOrWhiteSpace(flag))
                                //    ) {
                                //    entity.Type = "CNC Phay";
                                //    flag = entity.Type;
                                //}
                                // cnc sản lượng thấp hơn yêu cầu
                                if (totalRequireQuantityCnc > 0 &&
                                    (flag.Equals("SX2") || string.IsNullOrWhiteSpace(flag))
                                    ) {
                                    entity.Type = "CNC Phay";
                                    flag = entity.Type;
                                }
                                if (productioncnc > entity.Cnc.RequirePerDay)
                                    productioncnc -= entity.Cnc.RequirePerDay;
                                else
                                    productioncnc = 0;
                            }
                            #endregion
                        production1:
                            #region production 1
                            // production 1 case
                            if (afterTotal < 0) {
                                afterTotal = entity.TotalInv;
                            }
                            if (production1 < 0) {
                                production1 = importSx1Details.Where(td => td.ProductId == entity.ProductId)
                                                                                        .ToList()
                                                                                        .Sum(td => td.Quantity);
                                totalProduction1 = production1;
                            }
                            entity.Production1.ProductionQuantity = production1;
                            entity.Production1.TotalProductionQuantity = totalProduction1;
                            entity.Production1.AfterInvQuantity = afterTotal;
                            entity.Production1.RequireQuantity = entity.RequireQuantity - entity.Production1.AfterInvQuantity;
                            if (entity.Production1.RequireQuantity <= 0) {
                                entity.Production1.RequireQuantity = 0;
                                afterTotal -= entity.RequireQuantity;
                                //goto add;
                            }
                            else {
                                afterTotal = 0;
                                totalRequireQuantity1 += entity.Production1.RequireQuantity;
                                entity.Production1.TotalRequireQuantity = totalRequireQuantity1;
                                entity.Production1.Process = 1;
                                if (product.Productivity > 0) {
                                    entity.Production1.Productivity = product.Productivity;
                                    entity.Production1.ProductionRatePerDay =
                                        MyUtilities.Product.GetProductionRateInFactoryDayTime(product.Productivity);
                                }
                                entity.Production1.PlanProductionDay = entity.PlanProductionDay;

                                if (entity.Production1.PlanProductionDay > entity.Cnc.Process + entity.Production2.Process) {
                                    entity.Production1.PlanProductionDay -= (entity.Cnc.Process + entity.Production2.Process);
                                }
                                else {
                                    entity.Production1.PlanProductionDay = 1;
                                }
                            }
                            //if (entity.Production1.RequireProduction < 0) {
                            //    entity.Type = processingType;
                            //    flag = entity.Type;
                            //}
                            if (totalRequireQuantity1 > 0) {
                                entity.Type = processingType;
                                flag = entity.Type;
                            }
                            if (production1 > entity.Production1.RequirePerDay)
                                production1 -= entity.Production1.RequirePerDay;
                            else
                                production1 = 0;
                            #endregion

                        add:
                            var maxProductionDay = Math.Max(entity.Production1.ProductionDay, Math.Max(entity.Cnc.ProductionDay, entity.Production2.ProductionDay));
                            if (maxProductionDay > 0)
                                entity.ProductionDay = MyUtilities.Function.RoundUp((maxProductionDay + entity.Production1.Process + entity.Cnc.Process + entity.Production2.Process) * 6 / 7);

                            //if (!string.IsNullOrWhiteSpace(entity.Type))
                            if (entity.Production1.AfterInvQuantity < 0) entity.Production1.AfterInvQuantity = 0;
                            if (entity.Cnc.AfterInvQuantity < 0) entity.Cnc.AfterInvQuantity = 0;
                            if (entity.Production2.AfterInvQuantity < 0) entity.Production2.AfterInvQuantity = 0;
                            if (dayCount > 0) {
                                entity.AvgProduction1 = accumulativeSx1ById / dayCount;
                                entity.AvgProduction2 = accumulativeSx2ById / dayCount;
                                entity.AvgCnc = accumulativeCncById / dayCount;
                            }
                            list.Add(entity);
                            // next order
                        }
                        if (isAllOrder) {
                            model.AddRange(list);
                        }
                        else if (list.Any(l => !string.IsNullOrWhiteSpace(l.Type))) {
                            model.AddRange(list);
                        }
                        //if (list.Count > 1) {

                        //}

                        // next product
                    }
                }
            }
            catch (Exception ex) {
                ModelState.AddModelError("GetProductionBalancingPlan", ex.Message);
            }
            //var qry = from cust in model
            //      group cust by cust.Country
            //      into grp
            //      select new
            //      {
            //          Country = grp.Key,
            //          Count = grp.Select(x => x.City).Distinct().Count()
            //      };
            var conditions = (from m in model
                              group m by new { m.ProductId }
                                  into grp
                                  select new {
                                      ProductId = grp.Key.ProductId,
                                      FirstType = grp.ToList().FirstOrDefault().Type,
                                      LastType = grp.ToList().LastOrDefault().Type,
                                      CountType = grp.Select(x => x.Type).Distinct().Count()
                                  }).ToList();
            conditions = conditions.Where(c => c.CountType > 1).ToList();

            foreach (var condition in conditions) {
                model
                  .Where(x => x.ProductId == condition.ProductId)
                  .ToList()
                  .ForEach(a => a.Type = condition.LastType);

            }
            return model.OrderBy(m => m.Type).ThenBy(m => m.CustomerCode).ThenBy(m => m.ProductCode).ToList();
        }


