                                if (product.ProcessingType.Description.ToUpper().Contains("VF2")) {
                                    processingType = "CNC (VF2)";
                                }
                                else {
                                    processingType = "CNC (VF1)";
                                }
                            }
                        }

                        //var process =
                        //   productionProcesses.FirstOrDefault(
                        //       pp => pp.ProductId == entity.ProductId && pp.WarehouseId == MyUtilities.Warehouse.Production2);
                        //if (process != null) {
                        //    entity.Production2.InvQuantity = production2InvById;
                        //    entity.Production2.ProductionQuantity = production2TransactionDetails.Where(td => td.ReferenceId == entity.ProductId)
                        //                                                                           .ToList()
                        //                                                                           .Sum(td => td.Quantity);
                        //    entity.Production2.TotalProductionQuantity = entity.Production2.ProductionQuantity;
                        //    var processAfter = productionProcesses.Where(pp => pp.ProductId == entity.ProductId &&
