        List<ExpectedSalesModel> GetExpectedSales2(int month, int year) {
            var model = new List<ExpectedSalesModel>();
            using (var vfi = new tammaContext()) {
                var forecasts =
                    vfi.ForecastOrders.Where(
                        fo => fo.ForecastDate.Month == month && fo.ForecastDate.Year == year && fo.IsSelling);
                int i = 0;
                foreach (var forecast in forecasts) {
                    var entity = new ExpectedSalesModel {
                        Index = ++i,
                        ProductId = forecast.Product.ProductId,
                        ProductCustomerCode = forecast.Product.DesignNo,
                        ProductName = forecast.Product.ProductName,
                        ProductCode = forecast.Product.ProductCode,
                        AvgOrderQuantity = 0,
                        ProductTotalInventory = 0,
                        FinishInventory = 0,
                        MonthOrder = "",
                        ExpectedSalesQuantity = 0,
                        ForecastProduction = 0,
                        MonthCount = 0,
                        ForeCastNext2Month = 0,
                        ForeCastNext3Month = 0,
                        MaxOrderQuantityInMonth = 0,
                        InventoryAlarmColor = 0,
                        InvQuantityNeed = 0,
                        InvQuantityNeedProcessing = 0,
                        InvQuantityNeedProduction = 0,
                        DateNeedProcessing = null,
                        DateNeedProduction = null,
                        DayNeedProcessing = 0,
                        DiffRequestInv = 0,
                        ForeCastDate = forecast.ForecastDate
                    };
                    model.Add(entity);
                }
            }
            return model;
        }
        [GridAction]
        public ActionResult InsertExpectedSales2(ExpectedSalesModel inserted) {
            var toDatetime = DateTime.Now;
            try {
                if (!Request.IsAuthenticated)
                    ModelState.AddModelError("UpdateExpectedSales",
                                             @"Vui lòng đang nhập lại hệ thống. (IsAuthenticated) ");
                ModelState.Clear();
                using (var vfi = new tammaContext()) {

                    var product = vfi.Products.FirstOrDefault(p => p.ProductId == inserted.ProductId);
                    if (product == null)
                        throw new AggregateException("Không tìm thấy sản phẩm ! Liên hệ admin " +
                                                     inserted.ProductCode);
                    var forecastOrder =
                        vfi.ForecastOrders.FirstOrDefault(
                            fo =>
                            fo.ProductId == product.ProductId &&
                            fo.ForecastDate == inserted.ForeCastDate.Value);
                    if (forecastOrder == null) {
                        //if (!expectedNew.IsSelling) continue;
                        forecastOrder = new ForecastOrder {
                            ProductId = inserted.ProductId,
                            ForecastDate = inserted.ForeCastDate.Value,
                            Quantity = inserted.ExpectedSalesQuantity,
                            ModifiedDate = DateTime.Now,
                            ModifiedUser = HttpContext.User.Identity.Name,
                            IsSelling = true,
                            Status = (byte)MyUtilities.Sales.Status.Waiting,
                        };
                        vfi.ForecastOrders.Add(forecastOrder);
                    }
                    else {
                        if (forecastOrder.IsSelling) {
                            forecastOrder = new ForecastOrder {
                                ProductId = inserted.ProductId,
                                ForecastDate = inserted.ForeCastDate.Value,
                                Quantity = inserted.ExpectedSalesQuantity,
                                ModifiedDate = DateTime.Now,
                                ModifiedUser = HttpContext.User.Identity.Name,
                                IsSelling = true,
                                Status = (byte)MyUtilities.Sales.Status.Waiting,
                            };
                            vfi.ForecastOrders.Add(forecastOrder);
                        }
                        else {
                            forecastOrder.Quantity = inserted.ExpectedSalesQuantity;
                            forecastOrder.IsSelling = true;
                            forecastOrder.Status = (byte)MyUtilities.Sales.Status.Waiting;
                        }
                        //product.IsSelling = expectedNew.IsSelling;
                    }
                    vfi.SaveChanges();
                }

            }
            catch (Exception ex) {
                ModelState.AddModelError("InsertExpectedSales2", ex.Message);
            }
            return View(new GridModel(GetExpectedSales2(toDatetime.Month, toDatetime.Year)));
        }

        [GridAction]
        public ActionResult UpdateExpectedSales2(ExpectedSalesModel updated) {
            var toDatetime = DateTime.Now;
            try {
                if (!Request.IsAuthenticated)
                    ModelState.AddModelError("UpdateExpectedSales",
                                             @"Vui lòng đang nhập lại hệ thống. (IsAuthenticated) ");
                ModelState.Clear();
                using (var vfi = new tammaContext()) {
                    var product = vfi.Products.FirstOrDefault(p => p.ProductId == updated.ProductId);
                    if (product == null)
                        throw new AggregateException("Không tìm thấy sản phẩm ! Liên hệ admin " +
                                                     updated.ProductCode);
                    var forecastOrder =
                        vfi.ForecastOrders.FirstOrDefault(
                            fo => fo.ForecastOrderId == updated.ForecastId);
                    if (forecastOrder == null) {
                        //if (!expectedNew.IsSelling) continue;
                        forecastOrder = new ForecastOrder {
                            ProductId = updated.ProductId,
                            ForecastDate = updated.ForeCastDate.Value,
                            Quantity = updated.ExpectedSalesQuantity,
                            ModifiedDate = DateTime.Now,
                            ModifiedUser = HttpContext.User.Identity.Name,
                            IsSelling = true
                        };
                        vfi.ForecastOrders.Add(forecastOrder);
                    }
                    else {
                        toDatetime = forecastOrder.ForecastDate;
                        if (forecastOrder.ForecastDate != updated.ForeCastDate.Value) {
                            forecastOrder = new ForecastOrder {
                                ProductId = updated.ProductId,
                                ForecastDate = updated.ForeCastDate.Value,
                                Quantity = updated.ExpectedSalesQuantity,
                                ModifiedDate = DateTime.Now,
                                ModifiedUser = HttpContext.User.Identity.Name,
                                IsSelling = true
                            };
                            vfi.ForecastOrders.Add(forecastOrder);
                        }
                        else {
                            forecastOrder.IsSelling = updated.IsSelling;
                            forecastOrder.Quantity = updated.ExpectedSalesQuantity;
                        }
                    }
                    vfi.SaveChanges();
                }

            }
            catch (Exception ex) {
                ModelState.AddModelError("UpdateExpectedSales2", ex.Message);
            }
            return View(new GridModel(GetExpectedSales2(toDatetime.Month, toDatetime.Year)));
        }
