        public ActionResult SelectPurchasesChartReport(string fromDate, string toDate) {
            return Json(GetPurchasesReport(fromDate, toDate));
        }

        List<PurchasesReportModel> GetPurchasesReport(string fromDate, string toDate) {
            var model = new List<PurchasesReportModel>();
            if (string.IsNullOrWhiteSpace(fromDate)) return model;
            var fDate = MyUtilities.Function.ParseDate(fromDate);
            var tDate = MyUtilities.Function.ParseLastMonthTime(toDate);
            if (fDate.AddMonths(13) < tDate) {
                tDate = fDate.AddYears(1).AddSeconds(-1);
            }
            using (var vfi = new tammaContext()) {
                var purchases = vfi.PurchaseOrderDetails
                            .Where(x => x.PurchaseOrder.Status != (byte)MyUtilities.Sales.Status.Cancel
                                && x.PurchaseOrder.OrderDate >= fDate
                                && x.PurchaseOrder.OrderDate < tDate
                                && x.OrderQty > 0)
                            .Select(x => new {
                                x.PurchaseOrder.OrderDate.Month,
                                x.PurchaseOrder.OrderDate.Year,
                                x.PurchaseOrder.MaterialClassifiedId,
                                x.PurchaseOrderId,
                                x.ReferenceId,
                                x.OrderQty
                            })
                            .GroupBy(x => new { x.Month, x.Year, x.MaterialClassifiedId, x.PurchaseOrderId, })
                            .Select(x => new {
                                x.Key.Month,
                                x.Key.Year,
                                x.Key.MaterialClassifiedId,
                                x.Key.PurchaseOrderId,
                                //x.Key.ReferenceId,
                                Quantity = x.Sum(y => y.OrderQty),
                            })
                            .ToList();
                var poIds = purchases.Select(x=> x.PurchaseOrderId).Distinct().ToList();

                var importMaterials = vfi.ImportPurchaseOrderDetails
                                    .Where(x => x.ImportPurchaseOrder.PurchaseOrderId!=null 
                                        && poIds.Contains(x.ImportPurchaseOrder.PurchaseOrderId.Value)
                                        && x.ImportPurchaseOrder.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved)
                                        .Select(x => new {
                                            PoId = x.ImportPurchaseOrder.PurchaseOrderId.Value,
                                            MaterialId = x.MaterialId ?? 0,
                                            Quantity = x.QuantityKg
                                        })
                                        .GroupBy(x => new { x.PoId, x.MaterialId, })
                                        .Select(x => new {
                                            x.Key.PoId,
                                            x.Key.MaterialId,
                                            Quantity = x.Sum(y => y.Quantity)
                                        })
                                    .ToList();
                var importFuelsAndTools = vfi.TransactionFptDetails
                                    .Where(x => x.TransactionFpt.Status == (byte)MyUtilities.Transaction.Status.Approved
                                        && x.TransactionFpt.EoI == (int)MyUtilities.PurchaseOrder.EoILot.Import
                                        && x.TransactionFpt.PoId != null
                                        && poIds.Contains(x.TransactionFpt.PoId.Value))
                                    .Select(x => new {
                                        PoId = x.TransactionFpt.PoId.Value,
                                        x.FptId,
                                        Fpt = x.TransactionFpt.Fpt,
                                        Quantity = x.Quantity
                                    })
                                    .GroupBy(x => new { x.PoId, x.Fpt, x.FptId, })
                                    .Select(x => new {
                                        x.Key.PoId,
                                        x.Key.Fpt,
                                        x.Key.FptId,
                                        Quantity = x.Sum(y => y.Quantity)
                                    })
                                    .ToList();

                var importProducts = vfi.TransactionDetails
                    .Where(x => x.Transaction.PoId != null
                        && poIds.Contains(x.Transaction.PoId.Value)
                        && x.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved)
                                    .Select(x => new {
                                        PoId = x.Transaction.PoId.Value,
                                        ProductId = x.ReferenceId.Value,
                                        Quantity = x.Quantity
                                    })
                                    .GroupBy(x => new { x.PoId, x.ProductId, })
                                    .Select(x => new {
                                        x.Key.PoId,
                                        x.Key.ProductId,
                                        Quantity = x.Sum(y => y.Quantity)
                                    })
                                    .ToList();

                var dateLoop = fDate;
                while (dateLoop < tDate) {
                    var entity = new PurchasesReportModel {
                        Month = dateLoop.Month + "-" + dateLoop.Year,
                    };
                    var purchasesById = purchases.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year).ToList();
                    if (purchasesById.Any()) {
                        entity.PurchasesQuantity = purchasesById.Sum(x => x.Quantity);

                        var poIdsById = purchasesById.Select(x => x.PurchaseOrderId).Distinct().ToList();
                        var importMaterialsById = importMaterials.Where(x => poIdsById.Contains(x.PoId)).ToList();
                        if (importMaterialsById.Any()) {
                            entity.ImportMaterial = importMaterialsById.Sum(x => x.Quantity);
                            entity.ImportMaterialCount = importMaterialsById.Select(x => x.MaterialId).Distinct().Count();
                        }

                        var importFuelsAndToolsById = importFuelsAndTools.Where(x => poIdsById.Contains(x.PoId)
                            && x.Fpt == (int)MyUtilities.PurchaseOrder.FptLot.Fuel).ToList();
                        if (importFuelsAndToolsById.Any()) {
                            entity.ImportFuel = importFuelsAndToolsById.Sum(x => x.Quantity);
                            entity.ImportFuelCount = importFuelsAndToolsById.Select(x => x.FptId).Distinct().Count();
                        }
                        importFuelsAndToolsById = importFuelsAndTools.Where(x => poIdsById.Contains(x.PoId)
                            && x.Fpt == (int)MyUtilities.PurchaseOrder.FptLot.Tool).ToList();
                        if (importFuelsAndToolsById.Any()) {
                            entity.ImportTool = importFuelsAndToolsById.Sum(x => x.Quantity);
                            entity.ImportToolCount = importFuelsAndToolsById.Select(x => x.FptId).Distinct().Count();
                        }

                        var importProductsById = importProducts.Where(x => poIdsById.Contains(x.PoId)).ToList();
                        if (importMaterialsById.Any()) {
                            entity.ImportProduct = importProductsById.Sum(x => x.Quantity);
                            entity.ImportProductCount = importProductsById.Select(x => x.ProductId).Distinct().Count();
                        }
                    }
                    //var returnSalesById = returnSales.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year).ToList();
                    //if (returnSalesById.Any()) {
                    //    entity.ReturnQuantity = returnSalesById.Sum(x => x.Quantity);
                    //    entity.ReturnCount = returnSalesById.Sum(x => x.Count);
                    //}
                    //var forecastsById = forecasts.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year).ToList();
                    //if (forecastsById.Any()) {
                    //    entity.ForecastQuantity = forecastsById.Sum(x => x.Quantity);
                    //}
                    model.Add(entity);
                    dateLoop = dateLoop.AddMonths(1);
                }
            }
            return model;
        }
        
        [GridAction]
        public ActionResult SelectResourcesReport(string fromDate, string toDate) {
            var model = new List<ResourcesReportModel>();
            if (string.IsNullOrWhiteSpace(fromDate)) return View(new GridModel(model));
            try {
                model = GetResourcesReport(fromDate, toDate);
            }
            catch (Exception ex) {
                ModelState.AddModelError("SelectResourcesReport", ex.Message);
            }
            return View(new GridModel(model));
        }

        public ActionResult SelectResourcesChartReport(string fromDate, string toDate) {
            return Json(GetResourcesReport(fromDate, toDate));
        }

        List<ResourcesReportModel> GetResourcesReport(string fromDate, string toDate) {
            var model = new List<ResourcesReportModel>();
            if (string.IsNullOrWhiteSpace(fromDate)) return model;
            var fDate = MyUtilities.Function.ParseDate(fromDate);
            var tDate = MyUtilities.Function.ParseLastMonthTime(toDate);
            if (fDate.AddMonths(13) < tDate) {
                tDate = fDate.AddYears(1).AddSeconds(-1);
            }
            var exchangeRate = MyUtilities.Monitor.GetParameterValue(MyUtilities.Monitor.ExchangeToVndRate);
            var productionPriceRate = 0.6;
            var cncPriceRate = 0.15;
            var production2PriceRate = 0.15;
            var minVND = MyUtilities.Product.MinVndPrice;
            using (var vfi = new tammaContext()) {
                var productions = vfi.ImportFormSX1Detail
                            .Where(x => x.ImportFormSX1.MaterialUseDate >= fDate
                                && x.ImportFormSX1.MaterialUseDate < tDate
                                && x.ImportFormSX1.Status == (byte)MyUtilities.Transaction.Status.Approved)
                            .Select(x => new {
                                x.ImportFormSX1.MaterialUseDate.Month,
                                x.ImportFormSX1.MaterialUseDate.Year,
                                MaterialUse = (x.MaterialUse1 + x.MaterialUse2) * x.MaterialInventory.UnitWeight,
                                MaterialUsePrice = (x.MaterialUse1 + x.MaterialUse2) * x.MaterialInventory.UnitWeight * x.MaterialInventory.UnitPrice,
                                MaxQuantity = (x.MaterialUse1 + x.MaterialUse2) * x.ProductionRate,
                                ProductionQuantity = x.Number1 + x.Number2,
                                ProductPrice = x.Product.UnitPrice <= MyUtilities.Product.MinVndPrice
                                                    ? (x.Product.UnitPrice ?? 0) * exchangeRate * productionPriceRate
                                                    : Math.Round(x.Product.UnitPrice ?? 0, 4) - Math.Round(x.Product.UnitPrice ?? 0, 0) == 0
                                                        ? (x.Product.UnitPrice ?? 0) * productionPriceRate
                                                        : (x.Product.UnitPrice ?? 0) * exchangeRate * productionPriceRate
                            })
                            .GroupBy(x => new { x.Year, x.Month })
                            .OrderBy(x => x.Key)
                            .Select(x => new {
                                x.Key.Month,
                                x.Key.Year,
                                MaterialUse = x.Sum(y => y.MaterialUse),
                                MaterialUsePrice = x.Sum(y => y.MaterialUsePrice),
                                MaxQuantity = x.Sum(y => y.MaxQuantity),
                                ProductionQuantity = x.Sum(y => y.ProductionQuantity),
                                ProductionPrice = x.Sum(y => y.ProductionQuantity * y.ProductPrice),
                            })
                            .ToList();
                var approvedCncs = vfi.Transactions.Where(x => x.WarehouseIssueId != null 
                    && x.Warehouse.IsCncMilling 
                    && x.Status == (byte)MyUtilities.Transaction.Status.Approved).Select(x => x.TransactionCode)
                    .ToList();
                var cncs = vfi.ImportFormCncDetails
                            .Where(x => x.ImportFormCnc.MaterialUseDate >= fDate
                                && x.ImportFormCnc.MaterialUseDate < tDate
                                && approvedCncs.Contains(x.ImportFormCnc.TransactionCode))
                            .Select(x => new {
                                x.ImportFormCnc.MaterialUseDate.Month,
                                x.ImportFormCnc.MaterialUseDate.Year,
                                ProductionQuantity = x.Number1 + x.Number2,
                                ProductPrice = x.Product.UnitPrice <= MyUtilities.Product.MinVndPrice
                                    ? (x.Product.UnitPrice ?? 0) * exchangeRate * cncPriceRate
                                    : Math.Round(x.Product.UnitPrice ?? 0, 4) - Math.Round(x.Product.UnitPrice ?? 0, 0) == 0
                                    ? (x.Product.UnitPrice ?? 0) * cncPriceRate
                                    : (x.Product.UnitPrice ?? 0) * exchangeRate * cncPriceRate
                            })
                            .GroupBy(x => new { x.Year, x.Month, })
                            .OrderBy(x => x.Key)
                            .Select(x => new {
                                x.Key.Month,
                                x.Key.Year,
                                ProductionQuantity = x.Sum(y => y.ProductionQuantity),
                                ProductionPrice = x.Sum(y => y.ProductionQuantity * y.ProductPrice),
                            })
                            .ToList();
                var production2s = vfi.TransactionDetails
                            .Where(x => x.Transaction.CreatedDate >= fDate
                                && x.Transaction.CreatedDate < tDate
                                && x.Transaction.Status == (byte)MyUtilities.Transaction.Status.Approved
                                && x.Transaction.WarehouseIssueId != null
                                && x.Transaction.WarehouseReceiptId != null
                                && x.Transaction.Warehouse.IsProduction2
                                && !x.Transaction.Warehouse1.IsProduction2)
                            .Select(x => new {
                                x.Transaction.CreatedDate.Month,
                                x.Transaction.CreatedDate.Year,
                                ProductionQuantity = x.Quantity,
                                ProductPrice = x.Product.UnitPrice <= MyUtilities.Product.MinVndPrice
                                    ? (x.Product.UnitPrice ?? 0) * exchangeRate * production2PriceRate
                                    : Math.Round(x.Product.UnitPrice ?? 0, 4) - Math.Round(x.Product.UnitPrice ?? 0, 0) == 0
                                    ? (x.Product.UnitPrice ?? 0) * production2PriceRate
                                    : (x.Product.UnitPrice ?? 0) * exchangeRate * production2PriceRate
                            })
                            .GroupBy(x => new { x.Year, x.Month, })
                            .Select(x => new {
                                x.Key.Month,
                                x.Key.Year,
                                ProductionQuantity = x.Sum(y => y.ProductionQuantity),
                                ProductionPrice = x.Sum(y => y.ProductionQuantity * y.ProductPrice),
                            })
                            .ToList();

                var exportFuelsAndTools = vfi.TransactionFptDetails
                                    .Where(x => x.TransactionFpt.Status == (byte)MyUtilities.Transaction.Status.Approved
                                        && x.IsInternal != true
                                        && x.TransactionFpt.EoI == (int)MyUtilities.PurchaseOrder.EoILot.Export)
                                    .Select(x => new {
                                        x.TransactionFpt.TransactionDate.Month,
                                        x.TransactionFpt.TransactionDate.Year,
                                        Fpt = x.TransactionFpt.Fpt,
                                        Quantity = x.Quantity,
                                        Price = x.Quantity * x.UnitPrice
                                    })
                                    .GroupBy(x => new { x.Month, x.Year, x.Fpt, })
                                    .Select(x => new {
                                        x.Key.Month,
                                        x.Key.Year,
                                        x.Key.Fpt,
                                        Quantity = x.Sum(y => y.Quantity),
                                        Price = x.Sum(y => y.Price),
                                    })
                                    .ToList();
                var dateLoop = fDate;
                while (dateLoop < tDate) {
                    var entity = new ResourcesReportModel {
                        Month = dateLoop.Month + "-" + dateLoop.Year,
                    };
                    var productionsById = productions.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year).ToList();
                    if (productionsById.Any()) {
                        entity.MaterialUse = productionsById.Sum(x => x.MaterialUse);
                        entity.MaterialUsePrice = productionsById.Sum(x => x.MaterialUsePrice);
                        entity.ProductionQuantityMax = productionsById.Sum(x => x.MaxQuantity);
                        entity.ProductionQuantity = productionsById.Sum(x => x.ProductionQuantity);
                        entity.ProductionPrice = productionsById.Sum(x => x.ProductionPrice);
                    }
                    var cncsById = cncs.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year).ToList();
                    if (cncsById.Any()) {
                        entity.ProductionCNC = cncsById.Sum(x => x.ProductionQuantity);
                        entity.ProductionCNCPrice = cncsById.Sum(x => x.ProductionPrice);
                    }
                    var production2sById = production2s.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year).ToList();
                    if (production2sById.Any()) {
                        entity.Production2 = production2sById.Sum(x => x.ProductionQuantity);
                        entity.Production2Price = production2sById.Sum(x => x.ProductionPrice);
                    }
                    var exportsById = exportFuelsAndTools.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year
                        && x.Fpt == (int)MyUtilities.PurchaseOrder.FptLot.Fuel).ToList();
                    if (exportsById.Any()) {
                        entity.FuelExport = exportsById.Sum(x => x.Quantity);
                        entity.FuelExportPrice = exportsById.Sum(x => x.Price);
                    }
                    exportsById = exportFuelsAndTools.Where(x => x.Month == dateLoop.Month && x.Year == dateLoop.Year
                        && x.Fpt == (int)MyUtilities.PurchaseOrder.FptLot.Tool).ToList();
                    if (exportsById.Any()) {
                        entity.ToolExport = exportsById.Sum(x => x.Quantity);
                        entity.ToolExportPrice = exportsById.Sum(x => x.Price);
                    }
                    model.Add(entity);
                    dateLoop = dateLoop.AddMonths(1);
                }
            }
            return model;
        }
        #endregion

